INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39006, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "草の根", "is_correct": true, "explanation": "「大きな団体ではなく草の根の小さな集まり」は、市民が自分で始めた集まりという意味で自然。"}, {"text": "寝不足", "is_correct": false, "explanation": "「寝不足」は体の状態で、集まりの性質を表せない。"}, {"text": "夕立", "is_correct": false, "explanation": "「夕立」は天気の現象で、集まりの性質にはならない。"}, {"text": "腹痛", "is_correct": false, "explanation": "「腹痛」は体の症状で、集まりの性質を表せない。"}], "explanations": {"草の根": "「大きな団体ではなく草の根の小さな集まり」は、市民が自分で始めた集まりという意味で自然。", "寝不足": "「寝不足」は体の状態で、集まりの性質を表せない。", "夕立": "「夕立」は天気の現象で、集まりの性質にはならない。", "腹痛": "「腹痛」は体の症状で、集まりの性質を表せない。"}, "sentence_index": 6, "correct_answer": "草の根"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府の草の根の指示で、町の制度が決まった。", "explanation": "ここは〈政府〉が指示する上からの決定の意味。草の根は市民が自分で始める活動で、指示には使わない。"}, {"text": "国家の草の根の計画で、学校が新しくなった。", "explanation": "ここは〈国家〉が立てる計画の意味。草の根は市民の自発的な活動なので、国の計画とは合わない。"}, {"text": "大組織の草の根の方針で、町の祭りが中止になった。", "explanation": "ここは〈大組織〉が決める方針の意味。草の根は市民が自分で始める活動なので、組織の方針には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39006, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草の根を始まった小さな清掃活動が、町の人たちを変えた。", "corrected_sentence": "草の根で始まった小さな清掃活動が、町の人たちを変えた。", "error_description": "「草の根」の後は「で」（起点）が必要。「を」は誤りで、正しくは「で始まった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39006, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大きな組織ではなく、草の根な小さな集まりだ。", "corrected_sentence": "大きな組織ではなく、草の根の小さな集まりだ。", "error_description": "「草の根」は名詞なので、「な」ではなく「の」で続ける。「草の根な」は誤りで、正しくは「草の根の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39007, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「草の根の活動」と名詞を続ける形で、ここに入る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、名詞を修飾する位置には合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示すので、この位置では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、名詞を修飾する位置には合わない。"}], "correct_answer": "の", "explanations": {"の": "「草の根の活動」と名詞を続ける形で、ここに入る。", "を": "「を」は目的語を示すので、名詞を修飾する位置には合わない。", "に": "「に」は位置や相手を示すので、この位置では意味が通らない。", "へ": "「へ」は方向を示すので、名詞を修飾する位置には合わない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39007, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「草の根の活動は」と名詞を続ける形で、ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、名詞を修飾する位置には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、この位置には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、名詞を修飾する位置には合わない。"}], "correct_answer": "の", "explanations": {"の": "「草の根の活動は」と名詞を続ける形で、ここに入る。", "が": "「が」は主語を示すので、名詞を修飾する位置には合わない。", "より": "「より」は比較を示すので、この位置には合わない。", "から": "「から」は起点を示すので、名詞を修飾する位置には合わない。"}, "error_tags": {"が": "主語", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39007, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一般の人々が地域や社会の問題を解決するために、自発的に行う運動や活動。", "primary_collocate": null, "pronunciation": "くさのね", "ipa": "kɯsanone", "syllable_count": 4, "sentences": [{"text": "環境問題を解決するため、草の根の運動が各地で始まった。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "環境[かんきょう]問題[もんだい]を解決[かいけつ]するため、草[くさ]の根[ね]の運動[うんどう]が各地[かくち]で始[はじ]まった。", "sentence_source": "generated"}, {"text": "草の根の活動が、地域の貧困問題を少しずつ減らしている。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "草[くさ]の根[ね]の活動[かつどう]が、地域[ちいき]の貧困[ひんこん]問題[もんだい]を少[すこ]しずつ減[へ]らしている。", "sentence_source": "generated"}, {"text": "政治家ではなく一般の人々による草の根の取り組みが、法律を変えた。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "政治家[せいじか]ではなく一般[いっぱん]の人々[ひとびと]による草[くさ]の根[ね]の取[と]り組[く]みが、法律[ほうりつ]を変[か]えた。", "sentence_source": "generated"}, {"text": "草の根の支援のおかげで、被災地の復興は早く進んだ。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "草[くさ]の根[ね]の支援[しえん]のおかげで、被災地[ひさいち]の復興[ふっこう]は早[はや]く進[すす]んだ。", "sentence_source": "generated"}, {"text": "彼は、草の根の活動で社会を変えようと考えている。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "彼[かれ]は、草[くさ]の根[ね]の活動[かつどう]で社会[しゃかい]を変[か]えようと考[かんが]えている。", "sentence_source": "generated"}, {"text": "ごみ問題を考える市民が、草の根で署名を集めた。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "ごみ問題[もんだい]を考[かんが]える市民[しみん]が、草[くさ]の根[ね]で署名[しょめい]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "草の根の努力が実り、町の交通事故が減った。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "草[くさ]の根[ね]の努力[どりょく]が実[みの]り、町[まち]の交通[こうつう]事故[じこ]が減[へ]った。", "sentence_source": "generated"}, {"text": "大きな組織がなくても、草の根の活動は社会を動かせる。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "大[おお]きな組織[そしき]がなくても、草[くさ]の根[ね]の活動[かつどう]は社会[しゃかい]を動[うご]かせる。", "sentence_source": "generated"}, {"text": "この団体は、草の根の力で地域の教育問題に取り組んでいる。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "この団体[だんたい]は、草[くさ]の根[ね]の力[ちから]で地域[ちいき]の教育[きょういく]問題[もんだい]に取[と]り組[く]んでいる。", "sentence_source": "generated"}, {"text": "草の根の声が政府に届き、新しい制度ができた。", "target_word": "草の根", "complexity_tier": "T3", "furigana": "草[くさ]の根[ね]の声[こえ]が政府[せいふ]に届[とど]き、新[あたら]しい制度[せいど]ができた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "草の根", "label": "基本形"}, {"form": "草の根の", "label": "連体修飾形"}], "register": "中立", "sense_fingerprint": "市民が社会の問題を解決するために自発的に行う運動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b805d309-ed0d-4afe-a0c9-16e05b3d5c5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39007, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "草の根", "is_correct": true, "explanation": "「草の根の運動」は一般の人々が自発的に行う運動という意味で、この文に合う。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気」は体の感覚で、運動の主体にはならない。"}, {"text": "空腹", "is_correct": false, "explanation": "「空腹」は体の状態で、運動とは結びつかない。"}, {"text": "心配", "is_correct": false, "explanation": "「心配」は気持ちを表す語で、運動の主体にはならない。"}], "explanations": {"草の根": "「草の根の運動」は一般の人々が自発的に行う運動という意味で、この文に合う。", "眠気": "「眠気」は体の感覚で、運動の主体にはならない。", "空腹": "「空腹」は体の状態で、運動とは結びつかない。", "心配": "「心配」は気持ちを表す語で、運動の主体にはならない。"}, "sentence_index": 0, "correct_answer": "草の根"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "裁判所の草の根の判断で、制度が変わった。", "explanation": "ここは〈裁判所〉が下す判断の意味。草の根は一般の人々が自発的に行う運動なので、裁判所の判断とは合わない。"}, {"text": "政府の草の根の支援で、被災地の復興は早く進んだ。", "explanation": "ここは〈政府〉が行う上からの支援の意味。草の根は一般の人々の自発的な運動なので、政府の支援には使えない。"}, {"text": "中央の草の根の計画で、町の道路が整備された。", "explanation": "ここは〈中央〉が立てる計画の意味。草の根は下から始まる運動なので、中央の計画とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39007, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "草の根", "is_correct": true, "explanation": "「草の根の努力が実り」は、市民が自発的に行った努力という意味で自然。"}, {"text": "夕立", "is_correct": false, "explanation": "「夕立」は天気の現象で、努力の主体にはならない。"}, {"text": "寝不足", "is_correct": false, "explanation": "「寝不足」は体の状態で、努力の主体にはならない。"}, {"text": "腹痛", "is_correct": false, "explanation": "「腹痛」は体の症状で、努力とは結びつかない。"}], "explanations": {"草の根": "「草の根の努力が実り」は、市民が自発的に行った努力という意味で自然。", "夕立": "「夕立」は天気の現象で、努力の主体にはならない。", "寝不足": "「寝不足」は体の状態で、努力の主体にはならない。", "腹痛": "「腹痛」は体の症状で、努力とは結びつかない。"}, "sentence_index": 6, "correct_answer": "草の根"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "業界団体の草の根の方針で、新しい規則が決まった。", "explanation": "ここは〈業界団体〉が決める方針の意味。草の根は一般の人々が自発的に始める運動なので、団体の方針とは合わない。"}, {"text": "国家の草の根の計画で、学校が新しくなった。", "explanation": "ここは〈国家〉が立てる計画の意味。草の根は市民の自発的な運動なので、国の計画には使わない。"}, {"text": "役所の草の根の指示で、町の道が整備された。", "explanation": "ここは〈役所〉が出す指示の意味。草の根は下から始まる運動なので、役所の指示とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39007, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の人々が、草の根を運動を各地で始めた。", "corrected_sentence": "町の人々が、草の根の運動を各地で始めた。", "error_description": "「草の根」の後は「の」で運動に続く。「を」は誤りで、正しくは「草の根の運動」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39007, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "草の根を努力が実って、町の交通事故が減った。", "corrected_sentence": "草の根の努力が実って、町の交通事故が減った。", "error_description": "「草の根」の後は「の」で努力に続く。「を」は誤りで、正しくは「草の根の努力」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
