INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39010, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "北アメリカのことを言う言葉です。", "primary_collocate": null, "pronunciation": "ほくべい", "ipa": "hokɯbeː", "syllable_count": 4, "sentences": [{"text": "夏休みに、家族でホクベイを旅行する予定です。", "target_word": "ホクベイ", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、家族[かぞく]でホクベイを旅行[りょこう]する予定[よてい]です。", "sentence_source": "generated"}, {"text": "ホクベイにはカナダやアメリカ、メキシコなどの国があります。", "target_word": "ホクベイ", "complexity_tier": "T3", "furigana": "ホクベイにはカナダやアメリカ、メキシコなどの国[くに]があります。", "sentence_source": "generated"}, {"text": "この鳥は冬になると、ホクベイから南へ飛んでいきます。", "target_word": "ホクベイ", "complexity_tier": "T3", "furigana": "この鳥[とり]は冬[ふゆ]になると、ホクベイから南[みなみ]へ飛[と]んでいきます。", "sentence_source": "generated"}, {"text": "ホクベイでは、多くの人が車で通勤します。", "target_word": "ホクベイ", "complexity_tier": "T3", "furigana": "ホクベイでは、多[おお]くの人[ひと]が車[くるま]で通勤[つうきん]します。", "sentence_source": "generated"}, {"text": "兄は大学を出てから、ホクベイの会社で働いています。", "target_word": "ホクベイ", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]を出[で]てから、ホクベイの会社[かいしゃ]で働[はたら]いています。", "sentence_source": "generated"}, {"text": "ホクベイは広いので、国によって気候がちがいます。", "target_word": "ホクベイ", "complexity_tier": "T3", "furigana": "ホクベイは広[ひろ]いので、国[くに]によって気候[きこう]がちがいます。", "sentence_source": "generated"}, {"text": "この映画はホクベイで公開されたあと、日本でも人気になりました。", "target_word": "ホクベイ", "complexity_tier": "T3", "furigana": "この映画[えいが]はホクベイで公開[こうかい]されたあと、日本[にほん]でも人気[にんき]になりました。", "sentence_source": "generated"}, {"text": "ホクベイの大きな自然公園を見に行くのが、私の夢です。", "target_word": "ホクベイ", "complexity_tier": "T3", "furigana": "ホクベイの大[おお]きな自然公園[しぜんこうえん]を見[み]に行[い]くのが、私[わたし]の夢[ゆめ]です。", "sentence_source": "generated"}, {"text": "ホクベイとヨーロッパでは、食事の時間が少しちがいます。", "target_word": "ホクベイ", "complexity_tier": "T3", "furigana": "ホクベイとヨーロッパでは、食事[しょくじ]の時間[じかん]が少[すこ]しちがいます。", "sentence_source": "generated"}, {"text": "先生は地図を見せて、ホクベイの場所を教えてくれました。", "target_word": "ホクベイ", "complexity_tier": "T3", "furigana": "先生[せんせい]は地図[ちず]を見[み]せて、ホクベイの場所[ばしょ]を教[おし]えてくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ホクベイ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ホクベイ: 北アメリカ地域を指す名詞(カナダ・アメリカなどを含む広い地域)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ac41b1-bf6a-4b52-9986-43adaca85130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39010, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ホクベイ", "is_correct": true, "explanation": "正解。北アメリカ地域を指す名詞で、「家族で旅行する」の行き先として自然に入る。"}, {"text": "テーブル", "is_correct": false, "explanation": "テーブルは家具で、「家族で旅行する」の対象にならないので文が成り立たない。"}, {"text": "ラーメン", "is_correct": false, "explanation": "ラーメンは料理で、旅行する対象にはならないので文の意味が通らない。"}, {"text": "ボール", "is_correct": false, "explanation": "ボールは遊び道具で、家族で旅行する対象にはならないので合わない。"}], "explanations": {"ホクベイ": "正解。北アメリカ地域を指す名詞で、「家族で旅行する」の行き先として自然に入る。", "テーブル": "テーブルは家具で、「家族で旅行する」の対象にならないので文が成り立たない。", "ラーメン": "ラーメンは料理で、旅行する対象にはならないので文の意味が通らない。", "ボール": "ボールは遊び道具で、家族で旅行する対象にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "ホクベイ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ホクベイは一つの国で、首都はワシントンです。", "explanation": "ここは〈アメリカ〉の意味。ホクベイは一つの国ではなく、複数の国を含む広い地域を指すので合わない。"}, {"text": "ホクベイは大きな都市で、夜も明るい店が多いです。", "explanation": "ここは〈街〉の意味。ホクベイは地域の名前で、夜に明かりが灯る街の名前にはならないので合わない。"}, {"text": "ホクベイは日本の一つの道で、道庁があります。", "explanation": "ここは〈北海道〉の意味。ホクベイは日本の行政区画ではないので、道として道庁を持つとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39010, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ホクベイ", "is_correct": true, "explanation": "正解。地域名として「で公開された」と続き、映画の公開場所として自然に入る。"}, {"text": "ケーキ", "is_correct": false, "explanation": "ケーキは食べ物で、「で公開された」とは続かないので文が成り立たない。"}, {"text": "カバン", "is_correct": false, "explanation": "カバンは持ち物で、映画の公開の場所や手段にはならないので合わない。"}, {"text": "ピアノ", "is_correct": false, "explanation": "ピアノは楽器で、「で公開された」の場所としては意味が通らない。"}], "explanations": {"ホクベイ": "正解。地域名として「で公開された」と続き、映画の公開場所として自然に入る。", "ケーキ": "ケーキは食べ物で、「で公開された」とは続かないので文が成り立たない。", "カバン": "カバンは持ち物で、映画の公開の場所や手段にはならないので合わない。", "ピアノ": "ピアノは楽器で、「で公開された」の場所としては意味が通らない。"}, "sentence_index": 6, "correct_answer": "ホクベイ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ホクベイは毎朝六時に起きて、会社へ行きます。", "explanation": "ここは〈人〉の意味。ホクベイは場所の名前なので、起きたり会社へ行ったりする主語にはならない。"}, {"text": "ホクベイは小さな公園なので、歩いて一周できます。", "explanation": "ここは〈広場〉の意味。ホクベイは大陸規模の広い地域の名前なので、歩いて一周できる広場の意味では使えず合わない。"}, {"text": "ホクベイを一時間で読み終えました。", "explanation": "ここは〈本〉の意味。ホクベイは読める文書ではないので、「読み終える」の対象にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39010, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来年の春、家族でホクベイが旅行する計画があります。", "corrected_sentence": "来年の春、家族でホクベイを旅行する計画があります。", "error_description": "正しくは「ホクベイを旅行する」。旅行は行く対象を「を」で示すので、「が」だとホクベイが旅行する主語になり意味が合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39010, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友達とホクベイが映画を見て、感想を話しました。", "corrected_sentence": "友達とホクベイの映画を見て、感想を話しました。", "error_description": "正しくは「ホクベイの映画」（の）。「ホクベイが映画を見て」では場所の名前が映画を見る主語になってしまい、不自然で意味が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39012, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39012, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。『連邦に入った』で、入る先を示す到達点の格助詞。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す。『連邦で入った』は入る先を示せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。入る先を示すことはできず文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示す。『連邦の入った国』は成り立たず、入る先を示せない。"}], "correct_answer": "に", "explanations": {"に": "正解。『連邦に入った』で、入る先を示す到達点の格助詞。", "で": "手段を示す。『連邦で入った』は入る先を示せず不自然。", "より": "比較を示す。入る先を示すことはできず文が成り立たない。", "の": "連体修飾を示す。『連邦の入った国』は成り立たず、入る先を示せない。"}, "error_tags": {"で": "手段", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39012, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いくつかの国や地域が一緒になって作った一つの大きなまとまり。", "primary_collocate": null, "pronunciation": "れんぽう", "ipa": "reɴpoː", "syllable_count": 4, "sentences": [{"text": "いくつかの国が連邦を作り、外交を一緒に行うことにした。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "いくつかの国[くに]が連邦[れんぽう]を作[つく]り、外交[がいこう]を一緒[いっしょ]に行[おこな]うことにした。", "sentence_source": "generated"}, {"text": "ドイツは十六の州からなる連邦だ。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "ドイツは十六[じゅうろく]の州[しゅう]からなる連邦[れんぽう]だ。", "sentence_source": "generated"}, {"text": "小さな国々は、力を合わせるために連邦を組んだ。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "小[ちい]さな国々[くにぐに]は、力[ちから]を合[あ]わせるために連邦[れんぽう]を組[く]んだ。", "sentence_source": "generated"}, {"text": "連邦の中の各地域は、それぞれ自分たちの法律を持っている。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "連邦[れんぽう]の中[なか]の各地域[かくちいき]は、それぞれ自分[じぶん]たちの法律[ほうりつ]を持[も]っている。", "sentence_source": "generated"}, {"text": "彼は歴史の授業で、連邦ができた理由を発表した。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "彼[かれ]は歴史[れきし]の授業[じゅぎょう]で、連邦[れんぽう]ができた理由[りゆう]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "二つの国が一つの連邦になれば、国境で検査を受けなくてよくなる。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]が一[ひと]つの連邦[れんぽう]になれば、国境[こっきょう]で検査[けんさ]を受[う]けなくてよくなる。", "sentence_source": "generated"}, {"text": "この連邦には言葉の違う民族が一緒に暮らしている。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "この連邦[れんぽう]には言葉[ことば]の違[ちが]う民族[みんぞく]が一緒[いっしょ]に暮[く]らしている。", "sentence_source": "generated"}, {"text": "連邦に入った国は、お金や軍隊の一部を共同で管理する。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "連邦[れんぽう]に入[はい]った国[くに]は、お金[かね]や軍隊[ぐんたい]の一部[いちぶ]を共同[きょうどう]で管理[かんり]する。", "sentence_source": "generated"}, {"text": "連邦が大きくなりすぎて、各地域の意見をまとめるのが難しくなった。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "連邦[れんぽう]が大[おお]きくなりすぎて、各地域[かくちいき]の意見[いけん]をまとめるのが難[むずか]しくなった。", "sentence_source": "generated"}, {"text": "昔、この地域の小さな国々は連邦を作って外敵と戦った。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "昔[むかし]、この地域[ちいき]の小[ちい]さな国々[くにぐに]は連邦[れんぽう]を作[つく]って外敵[がいてき]と戦[たたか]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連邦", "label": "基本形"}], "register": "formal", "sense_fingerprint": "複数の国や地域が結びついてできた大きな連合体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be61a4f4-a23f-4ede-b4c0-325ba41986c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39012, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連邦", "is_correct": true, "explanation": "正解。複数の国が一つの大きなまとまりを作る、という文脈に合う。"}, {"text": "大統領", "is_correct": false, "explanation": "人を指す語で、作るものではない。「大統領を作り」は意味が通らない。"}, {"text": "選挙", "is_correct": false, "explanation": "投票の行為を指し、国が作る対象にはならない。"}, {"text": "議席", "is_correct": false, "explanation": "議会の席を指し、国が作るものとしては成り立たない。"}], "explanations": {"連邦": "正解。複数の国が一つの大きなまとまりを作る、という文脈に合う。", "大統領": "人を指す語で、作るものではない。「大統領を作り」は意味が通らない。", "選挙": "投票の行為を指し、国が作る対象にはならない。", "議席": "議会の席を指し、国が作るものとしては成り立たない。"}, "sentence_index": 0, "correct_answer": "連邦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "連邦の大会で、二人の選手が優勝した。", "explanation": "ここは〈連盟〉の意味。競技の団体を指し、国や地域が一つにまとまった連邦とは違う。"}, {"text": "アメリカは連邦ごとに、独自の税金を決めている。", "explanation": "ここは〈州〉の意味。州ごとに独自の税を決める文脈で、連邦全体を単位にするのは合わない。"}, {"text": "その連邦は、毎年サッカーの試合の日程を決めている。", "explanation": "ここは〈連盟〉の意味。連盟は競技の運営を担う団体を指し、国や地域が一つにまとまった体制の連邦とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39012, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連邦", "is_correct": true, "explanation": "正解。複数の州や国がまとまった単位を指し、民族が暮らす文脈に合う。"}, {"text": "首相", "is_correct": false, "explanation": "人を指す語で、民族が暮らす場所としての文脈に合わない。"}, {"text": "議事堂", "is_correct": false, "explanation": "議会の建物を指し、人が暮らす場所としては合わない。"}, {"text": "外務省", "is_correct": false, "explanation": "行政機関の名で、民族が暮らす場所ではない。"}], "explanations": {"連邦": "正解。複数の州や国がまとまった単位を指し、民族が暮らす文脈に合う。", "首相": "人を指す語で、民族が暮らす場所としての文脈に合わない。", "議事堂": "議会の建物を指し、人が暮らす場所としては合わない。", "外務省": "行政機関の名で、民族が暮らす場所ではない。"}, "sentence_index": 6, "correct_answer": "連邦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "連邦では、王様が中央の政府を率いている。", "explanation": "ここは〈王国〉の意味。王が統治する国の形を述べる文で、複数の州が集まる連邦では王が統治しないので合わない。"}, {"text": "その連邦は、毎週日曜に家族そろって食事をする。", "explanation": "ここは〈家族〉の意味。連邦は国や地域が一つにまとまった体制を指し、家族の集まりには使わない。"}, {"text": "連邦は、組合員の給料を交渉する。", "explanation": "ここは〈組合〉の意味。労働者が給料を交渉する団体の文で、国家の体制を表す連邦とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39012, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの州が連邦に組んで、新しい政府を作った。", "corrected_sentence": "二つの州が連邦を組んで、新しい政府を作った。", "error_description": "『組む』は『〜を組む』の形で、目的語に『を』を取る。『連邦に組む』は格助詞が誤り。正しくは『連邦を組む』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39012, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三つの州が連邦な体制を作り、共通の軍隊を持つことにした。", "corrected_sentence": "三つの州が連邦的な体制を作り、共通の軍隊を持つことにした。", "error_description": "『連邦』は名詞なので、形容する場合は『連邦的な』とする。『連邦な体制』は誤り。正しくは『連邦的な体制』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39013, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "正解。『からなる』で、連邦を構成する単位である州を示す。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。『州でなる』とは続かず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示す。『州のなる』とは続かず、構成を表せない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。『州がなる』は成り立たず、文が不自然になる。"}], "correct_answer": "から", "explanations": {"から": "正解。『からなる』で、連邦を構成する単位である州を示す。", "で": "手段や場所を示す。『州でなる』とは続かず、文が成り立たない。", "の": "連体修飾を示す。『州のなる』とは続かず、構成を表せない。", "が": "主語を示す。『州がなる』は成り立たず、文が不自然になる。"}, "error_tags": {"で": "手段・場所", "の": "連体修飾", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39013, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。『連邦に加わる』で、加わる先を示す到達点の格助詞。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。『連邦を加わる』は『加わる』が取れず誤り。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す。『連邦で加わる』は加わる先を示せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。加わる先を示すことはできず文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "正解。『連邦に加わる』で、加わる先を示す到達点の格助詞。", "を": "目的語を示す。『連邦を加わる』は『加わる』が取れず誤り。", "で": "手段を示す。『連邦で加わる』は加わる先を示せず不自然。", "より": "比較を示す。加わる先を示すことはできず文が成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39013, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の州や国などが集まって作られた、一つの統一された国家や政治組織。", "primary_collocate": null, "pronunciation": "れんぽう", "ipa": "reɴpoː", "syllable_count": 4, "sentences": [{"text": "アメリカは五十の州が集まってできた連邦で、州ごとに法律が違う。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "アメリカは五十[ごじゅう]の州[しゅう]が集[あつ]まってできた連邦[れんぽう]で、州[しゅう]ごとに法律[ほうりつ]が違[ちが]う。", "sentence_source": "generated"}, {"text": "スイスは二十六の州からなる連邦で、州の自治が強い。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "スイスは二十六[にじゅうろく]の州[しゅう]からなる連邦[れんぽう]で、州[しゅう]の自治[じち]が強[つよ]い。", "sentence_source": "generated"}, {"text": "連邦の政府と州の政府は、仕事を分け合っている。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "連邦[れんぽう]の政府[せいふ]と州[しゅう]の政府[せいふ]は、仕事[しごと]を分[わ]け合[あ]っている。", "sentence_source": "generated"}, {"text": "その国は一つの連邦として、外国と条約を結んだ。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "その国[くに]は一[ひと]つの連邦[れんぽう]として、外国[がいこく]と条約[じょうやく]を結[むす]んだ。", "sentence_source": "generated"}, {"text": "連邦の議会では、各州の代表が話し合って法案を決める。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "連邦[れんぽう]の議会[ぎかい]では、各州[かくしゅう]の代表[だいひょう]が話[はな]し合[あ]って法案[ほうあん]を決[き]める。", "sentence_source": "generated"}, {"text": "国民は、州の市民であると同時に連邦の市民でもある。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "国民[こくみん]は、州[しゅう]の市民[しみん]であると同時[どうじ]に連邦[れんぽう]の市民[しみん]でもある。", "sentence_source": "generated"}, {"text": "オーストラリアは、六つの州が連邦を作って生まれた国だ。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "オーストラリアは、六[むっ]つの州[しゅう]が連邦[れんぽう]を作[つく]って生[う]まれた国[くに]だ。", "sentence_source": "generated"}, {"text": "連邦に加わると、州は外国と勝手に戦争をする権利を失う。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "連邦[れんぽう]に加[くわ]わると、州[しゅう]は外国[がいこく]と勝手[かって]に戦争[せんそう]をする権利[けんり]を失[うしな]う。", "sentence_source": "generated"}, {"text": "連邦を作る目的は、小さな地域が力を合わせて安全を守ることだ。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "連邦[れんぽう]を作[つく]る目的[もくてき]は、小[ちい]さな地域[ちいき]が力[ちから]を合[あ]わせて安全[あんぜん]を守[まも]ることだ。", "sentence_source": "generated"}, {"text": "連邦の首都は、どの州にも属さない特別な地域に置かれている。", "target_word": "連邦", "complexity_tier": "T3", "furigana": "連邦[れんぽう]の首都[しゅと]は、どの州[しゅう]にも属[ぞく]さない特別[とくべつ]な地域[ちいき]に置[お]かれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連邦", "label": "基本形"}], "register": "formal", "sense_fingerprint": "複数の州が集まり中央政府を持つ統一国家（連邦制）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be61a4f4-a23f-4ede-b4c0-325ba41986c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39013, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連邦", "is_correct": true, "explanation": "正解。州が集まって一つの統一国家になった、という文脈に合う。"}, {"text": "税金", "is_correct": false, "explanation": "納める金銭を指し、州が集まってできたものとしては合わない。"}, {"text": "選挙", "is_correct": false, "explanation": "投票の行為を指し、国の構成を表す語ではない。"}, {"text": "議席", "is_correct": false, "explanation": "議会の席を指し、州が集まって生まれた国家を表さない。"}], "explanations": {"連邦": "正解。州が集まって一つの統一国家になった、という文脈に合う。", "税金": "納める金銭を指し、州が集まってできたものとしては合わない。", "選挙": "投票の行為を指し、国の構成を表す語ではない。", "議席": "議会の席を指し、州が集まって生まれた国家を表さない。"}, "sentence_index": 0, "correct_answer": "連邦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その国は連邦を結び、外国と軍事の協定を結んだ。", "explanation": "ここは〈同盟〉の意味。協定を結んで協力する意味で、連邦は統一された国家の体制を指すので結ぶ対象にはならない。"}, {"text": "その連邦は、組合員の給料を交渉した。", "explanation": "ここは〈組合〉の意味。労働者が給料を交渉する団体の文で、国家の体制を表す連邦とは合わない。"}, {"text": "その連邦は王様が統治し、外国と条約を結んだ。", "explanation": "ここは〈王国〉の意味。王が国を統治する文で、複数の州が集まってできた連邦とは体制が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39013, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連邦", "is_correct": true, "explanation": "正解。六つの州が集まって国を作った、という文脈に合う。"}, {"text": "歳入", "is_correct": false, "explanation": "国が得る収入を指し、作るものではない。"}, {"text": "納税", "is_correct": false, "explanation": "税金を納める行為で、国の構成を表す語ではない。"}, {"text": "汚職", "is_correct": false, "explanation": "不正な行為を指し、国を作る対象にはならない。"}], "explanations": {"連邦": "正解。六つの州が集まって国を作った、という文脈に合う。", "歳入": "国が得る収入を指し、作るものではない。", "納税": "税金を納める行為で、国の構成を表す語ではない。", "汚職": "不正な行為を指し、国を作る対象にはならない。"}, "sentence_index": 6, "correct_answer": "連邦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その連邦は、昔から温泉で有名な地域だ。", "explanation": "ここは〈地域〉の意味。連邦は複数の州や国が集まった国家の体制を指し、特定の土地の名所を表す語ではない。"}, {"text": "その連邦は、三百人の社員を抱える大企業だ。", "explanation": "ここは〈会社〉の意味。連邦は国家や政治組織の体制を指し、社員数で規模を表す企業の語ではない。"}, {"text": "連邦は本国に税金を納めていた。", "explanation": "ここは〈植民地〉の意味。本国に税を納める従属関係の文で、対等な州が集まった連邦の体制には当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39013, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "カナダは州が集まって連邦した国で、外交は連邦政府が担っている。", "corrected_sentence": "カナダは州が集まって連邦になった国で、外交は連邦政府が担っている。", "error_description": "「連邦」は名詞なので「連邦した」とは言えず、「連邦になった」と言う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39013, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一部の州は、連邦を加わるかどうかを住民投票で決めた。", "corrected_sentence": "一部の州は、連邦に加わるかどうかを住民投票で決めた。", "error_description": "『加わる』は『〜に加わる』と、加わる先を『に』で示す。『連邦を加わる』は格助詞が誤り。正しくは『連邦に加わる』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39014, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。ルールが制定の対象であることを示す目的語の格助詞。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。ルールが制定する主体になり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "相手や位置を示す。制定の対象を示すことができず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。制定の対象を示すことはできない。"}], "correct_answer": "を", "explanations": {"を": "正解。ルールが制定の対象であることを示す目的語の格助詞。", "が": "主語を示す。ルールが制定する主体になり、文が成り立たない。", "に": "相手や位置を示す。制定の対象を示すことができず不自然。", "へ": "方向を示す。制定の対象を示すことはできない。"}, "error_tags": {"が": "主語", "に": "相手・位置", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "廃止", "is_correct": true, "explanation": "正解。正式に決めたきまりを取りやめる意味で、制定の対義語。"}, {"text": "延期", "is_correct": false, "explanation": "予定を後ろにずらす意味で、制定の対義語ではない。"}, {"text": "相談", "is_correct": false, "explanation": "話し合う意味で、制定とは対義の関係にない。"}, {"text": "検討", "is_correct": false, "explanation": "よく考えて判断する意味で、制定とは対義の関係にない。"}], "correct_answer": "廃止", "explanations": {"廃止": "正解。正式に決めたきまりを取りやめる意味で、制定の対義語。", "延期": "予定を後ろにずらす意味で、制定の対義語ではない。", "相談": "話し合う意味で、制定とは対義の関係にない。", "検討": "よく考えて判断する意味で、制定とは対義の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39014, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。規則が制定の対象であることを示す目的語の格助詞。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。制定の対象を示すことはできず文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示す。『規則の制定する』とは続かず、目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す。『規則で制定する』は手段の意味になり、対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。規則が制定の対象であることを示す目的語の格助詞。", "より": "比較を示す。制定の対象を示すことはできず文が成り立たない。", "の": "連体修飾を示す。『規則の制定する』とは続かず、目的語にならない。", "で": "手段を示す。『規則で制定する』は手段の意味になり、対象を示せない。"}, "error_tags": {"より": "比較", "の": "連体修飾", "で": "手段"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "廃止", "is_correct": true, "explanation": "正解。正式に決めたきまりを取りやめる意味で、制定の対義語。"}, {"text": "改築", "is_correct": false, "explanation": "建物を建て直す意味で、制定の対義語ではない。"}, {"text": "購入", "is_correct": false, "explanation": "物を買い入れる意味で、制定とは対義の関係にない。"}, {"text": "記録", "is_correct": false, "explanation": "事実を書き残す意味で、制定とは対義の関係にない。"}], "correct_answer": "廃止", "explanations": {"廃止": "正解。正式に決めたきまりを取りやめる意味で、制定の対義語。", "改築": "建物を建て直す意味で、制定の対義語ではない。", "購入": "物を買い入れる意味で、制定とは対義の関係にない。", "記録": "事実を書き残す意味で、制定とは対義の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39014, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "きまりやルールを、国や会社などが正式に決めること。", "primary_collocate": null, "pronunciation": "せいてい", "ipa": "seːteː", "syllable_count": 4, "sentences": [{"text": "会社は社員の安全のために、新しい社則を制定した。", "target_word": "制定", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は社員[しゃいん]の安全[あんぜん]のために、新[あたら]しい社則[しゃそく]を制定[せいてい]した。", "sentence_source": "generated"}, {"text": "町内会は、ごみの出し方について新しいルールを制定した。", "target_word": "制定", "complexity_tier": "T3", "furigana": "町内会[ちょうないかい]は、ごみの出[だ]し方[かた]について新[あたら]しいルールを制定[せいてい]した。", "sentence_source": "generated"}, {"text": "学校の部活動の決まりは、先生たちが話し合って制定した。", "target_word": "制定", "complexity_tier": "T3", "furigana": "学校[がっこう]の部活動[ぶかつどう]の決[き]まりは、先生[せんせい]たちが話[はな]し合[あ]って制定[せいてい]した。", "sentence_source": "generated"}, {"text": "制定されたばかりのルールなので、まだ知らない人が多い。", "target_word": "制定", "complexity_tier": "T3", "furigana": "制定[せいてい]されたばかりのルールなので、まだ知[し]らない人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "市は夜の騒音を減らすため、新しいきまりを制定した。", "target_word": "制定", "complexity_tier": "T3", "furigana": "市[し]は夜[よる]の騒音[そうおん]を減[へ]らすため、新[あたら]しいきまりを制定[せいてい]した。", "sentence_source": "generated"}, {"text": "国は、全員が守るべき基本のきまりを制定する責任がある。", "target_word": "制定", "complexity_tier": "T3", "furigana": "国[くに]は、全員[ぜんいん]が守[まも]るべき基本[きほん]のきまりを制定[せいてい]する責任[せきにん]がある。", "sentence_source": "generated"}, {"text": "組合は、休みの取り方に関する規則を制定し、全員に配った。", "target_word": "制定", "complexity_tier": "T3", "furigana": "組合[くみあい]は、休[やす]みの取[と]り方[かた]に関[かん]する規則[きそく]を制定[せいてい]し、全員[ぜんいん]に配[くば]った。", "sentence_source": "generated"}, {"text": "新しい規則を制定する前に、社員の意見を集めた。", "target_word": "制定", "complexity_tier": "T3", "furigana": "新[あたら]しい規則[きそく]を制定[せいてい]する前[まえ]に、社員[しゃいん]の意見[いけん]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "クラブは会員の増加にあわせて、使用のきまりを制定した。", "target_word": "制定", "complexity_tier": "T3", "furigana": "クラブは会員[かいいん]の増加[ぞうか]にあわせて、使用[しよう]のきまりを制定[せいてい]した。", "sentence_source": "generated"}, {"text": "工場では、事故が起きた後に安全のきまりが制定された。", "target_word": "制定", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、事故[じこ]が起[お]きた後[あと]に安全[あんぜん]のきまりが制定[せいてい]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "制定する", "label": "終止形"}, {"form": "制定した", "label": "過去形"}, {"form": "制定される", "label": "受身形"}, {"form": "制定して", "label": "て形"}, {"form": "制定された", "label": "受身過去形"}], "register": "formal", "sense_fingerprint": "組織が規則やルールを正式に決めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 社則 (Zipf 1.52)']::text[], 'be61a4f4-a23f-4ede-b4c0-325ba41986c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39014, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制定", "is_correct": true, "explanation": "正解。会社が社則を正式に決める、という文脈に合う。"}, {"text": "点呼", "is_correct": false, "explanation": "人を一人ずつ呼んで確認する行為で、社則を対象にできない。"}, {"text": "施錠", "is_correct": false, "explanation": "鍵をかける行為で、社則には使わない。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点数をつける行為で、社則には当てはまらない。"}], "explanations": {"制定": "正解。会社が社則を正式に決める、という文脈に合う。", "点呼": "人を一人ずつ呼んで確認する行為で、社則を対象にできない。", "施錠": "鍵をかける行為で、社則には使わない。", "採点": "答案などに点数をつける行為で、社則には当てはまらない。"}, "sentence_index": 0, "correct_answer": "制定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は来週の試験問題を制定した。", "explanation": "ここは〈作成〉の意味。試験問題は作るものなので、きまりを正式に定める〈制定〉とは合わない。"}, {"text": "市は三年間の計画を制定した。", "explanation": "ここは〈策定〉の意味。計画は立てるもので、きまりを定める〈制定〉の対象にはならない。"}, {"text": "作曲家は新しい曲を制定した。", "explanation": "ここは〈作曲〉の意味。曲は作るもので、きまりを正式に決める〈制定〉の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39014, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制定", "is_correct": true, "explanation": "正解。組合が休みに関する規則を正式に決めて配る、という文脈に合う。"}, {"text": "撮影", "is_correct": false, "explanation": "写真や映像を撮る行為で、規則を対象にはできない。"}, {"text": "演奏", "is_correct": false, "explanation": "楽器などで音楽を奏でる行為で、規則には使わない。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の資源を掘り出す行為で、規則には当てはまらない。"}], "explanations": {"制定": "正解。組合が休みに関する規則を正式に決めて配る、という文脈に合う。", "撮影": "写真や映像を撮る行為で、規則を対象にはできない。", "演奏": "楽器などで音楽を奏でる行為で、規則には使わない。", "採掘": "地下の資源を掘り出す行為で、規則には当てはまらない。"}, "sentence_index": 6, "correct_answer": "制定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作家は外国の小説を制定した。", "explanation": "ここは〈翻訳〉の意味。小説は訳すもので、きまりを定める〈制定〉の意味では使わない。"}, {"text": "係の人が投票の結果を制定した。", "explanation": "ここは〈集計〉の意味。結果は数えてまとめるもので、きまりを正式に定める〈制定〉とは合わない。"}, {"text": "職人は壊れた時計を制定した。", "explanation": "ここは〈修理〉の意味。壊れた物は直すもので、きまりを定める〈制定〉の対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39014, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この決まりは、先月制定られた。", "corrected_sentence": "この決まりは、先月制定された。", "error_description": "『制定』はサ変動詞なので、受身の過去形は『制定された』となる。『制定られた』は活用が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39014, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は、夜間の騒音を減らすための規則に制定した。", "corrected_sentence": "町は、夜間の騒音を減らすための規則を制定した。", "error_description": "『制定』は『規則を制定する』の形で、対象は『を』で示す。『規則に』は格助詞が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39015, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「制定」は「憲法を制定する」の形で目的語を取るので、ここは「を」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「憲法に制定する」とは言えず、制定の対象を示すには「を」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、制定の対象を示す格としては使えない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表すので、憲法を定める行為には合わない。"}], "correct_answer": "を", "explanations": {"を": "「制定」は「憲法を制定する」の形で目的語を取るので、ここは「を」が正しい。", "に": "「憲法に制定する」とは言えず、制定の対象を示すには「を」が必要。", "へ": "「へ」は方向を表すので、制定の対象を示す格としては使えない。", "と": "「と」は相手や並列を表すので、憲法を定める行為には合わない。"}, "error_tags": {"に": "対象を示す格ではない", "へ": "方向を表す", "と": "相手・並列を表す"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "廃止", "is_correct": true, "explanation": "法律を正式に取り消すことで、制定の対義語として辞書にも並ぶ。"}, {"text": "承認", "is_correct": false, "explanation": "承認は内容を認めることで、法律を定める行為の反対語ではない。"}, {"text": "解散", "is_correct": false, "explanation": "解散は組織や集まりを解くことで、法律を対象にはできず反対語でもない。"}, {"text": "放棄", "is_correct": false, "explanation": "放棄は権利や物を手放すことで、制定の反対語とは言えない。"}], "correct_answer": "廃止", "explanations": {"廃止": "法律を正式に取り消すことで、制定の対義語として辞書にも並ぶ。", "承認": "承認は内容を認めることで、法律を定める行為の反対語ではない。", "解散": "解散は組織や集まりを解くことで、法律を対象にはできず反対語でもない。", "放棄": "放棄は権利や物を手放すことで、制定の反対語とは言えない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39015, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「法律の制定」の「の」は名詞どうしを結び、制定が法律に関わることを示すので、ここに合う。"}, {"text": "が", "is_correct": false, "explanation": "「法律が制定を求める」は主語を示す形になり、名詞を結ぶ位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すので、名詞どうしを結ぶ位置では使えない。"}, {"text": "を", "is_correct": false, "explanation": "「法律を制定を求める」と目的語が二つ並んで不自然になる。"}], "correct_answer": "の", "explanations": {"の": "「法律の制定」の「の」は名詞どうしを結び、制定が法律に関わることを示すので、ここに合う。", "が": "「法律が制定を求める」は主語を示す形になり、名詞を結ぶ位置には合わない。", "で": "「で」は手段や場所を表すので、名詞どうしを結ぶ位置では使えない。", "を": "「法律を制定を求める」と目的語が二つ並んで不自然になる。"}, "error_tags": {"が": "主語を示す格", "で": "手段・場所を示す", "を": "目的語を示す格"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "廃止", "is_correct": true, "explanation": "法律を正式に取り消すことで、制定の対義語として辞書にも並ぶ。"}, {"text": "点検", "is_correct": false, "explanation": "調べて状態を確かめる意味で、制定とは対義の関係にない。"}, {"text": "中止", "is_correct": false, "explanation": "中止は途中でやめることで、法律を定める行為の反対語とは言えない。"}, {"text": "解除", "is_correct": false, "explanation": "解除は禁止や契約などを解くことで、制定と対になる語ではない。"}], "correct_answer": "廃止", "explanations": {"廃止": "法律を正式に取り消すことで、制定の対義語として辞書にも並ぶ。", "点検": "調べて状態を確かめる意味で、制定とは対義の関係にない。", "中止": "中止は途中でやめることで、法律を定める行為の反対語とは言えない。", "解除": "解除は禁止や契約などを解くことで、制定と対になる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39015, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "法律や規則などを、正式な手続きを経て決めること。", "primary_collocate": null, "pronunciation": "せいてい", "ipa": "seːteː", "syllable_count": 4, "sentences": [{"text": "国会は、長い議論の後で新しい法律を制定した。", "target_word": "制定", "complexity_tier": "T3", "furigana": "国会[こっかい]は、長[なが]い議論[ぎろん]の後[あと]で新[あたら]しい法律[ほうりつ]を制定[せいてい]した。", "sentence_source": "generated"}, {"text": "国民の代表が集まって憲法を制定した。", "target_word": "制定", "complexity_tier": "T3", "furigana": "国民[こくみん]の代表[だいひょう]が集[あつ]まって憲法[けんぽう]を制定[せいてい]した。", "sentence_source": "generated"}, {"text": "その条例は、住民の投票を経て制定された。", "target_word": "制定", "complexity_tier": "T3", "furigana": "その条例[じょうれい]は、住民[じゅうみん]の投票[とうひょう]を経[へ]て制定[せいてい]された。", "sentence_source": "generated"}, {"text": "法律を制定するには、国会で多くの議員の賛成が必要だ。", "target_word": "制定", "complexity_tier": "T3", "furigana": "法律[ほうりつ]を制定[せいてい]するには、国会[こっかい]で多[おお]くの議員[ぎいん]の賛成[さんせい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "戦後、日本では新しい憲法が制定された。", "target_word": "制定", "complexity_tier": "T3", "furigana": "戦後[せんご]、日本[にほん]では新[あたら]しい憲法[けんぽう]が制定[せいてい]された。", "sentence_source": "generated"}, {"text": "市議会は、禁煙を進める条例を制定した。", "target_word": "制定", "complexity_tier": "T3", "furigana": "市議会[しぎかい]は、禁煙[きんえん]を進[すす]める条例[じょうれい]を制定[せいてい]した。", "sentence_source": "generated"}, {"text": "制定から五十年たった法律を、今の時代に合うように変える。", "target_word": "制定", "complexity_tier": "T3", "furigana": "制定[せいてい]から五十年[ごじゅうねん]たった法律[ほうりつ]を、今[いま]の時代[じだい]に合[あ]うように変[か]える。", "sentence_source": "generated"}, {"text": "議員たちは、環境を守る法律の制定を求めている。", "target_word": "制定", "complexity_tier": "T3", "furigana": "議員[ぎいん]たちは、環境[かんきょう]を守[まも]る法律[ほうりつ]の制定[せいてい]を求[もと]めている。", "sentence_source": "generated"}, {"text": "法案が正式に制定されるまでには、いくつもの手続きがある。", "target_word": "制定", "complexity_tier": "T3", "furigana": "法案[ほうあん]が正式[せいしき]に制定[せいてい]されるまでには、いくつもの手続[てつづ]きがある。", "sentence_source": "generated"}, {"text": "外国の例を参考にして、個人情報を守る法律が制定された。", "target_word": "制定", "complexity_tier": "T3", "furigana": "外国[がいこく]の例[れい]を参考[さんこう]にして、個人情報[こじんじょうほう]を守[まも]る法律[ほうりつ]が制定[せいてい]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "制定する", "label": "終止形"}, {"form": "制定した", "label": "過去形"}, {"form": "制定される", "label": "受身形"}, {"form": "制定して", "label": "て形"}, {"form": "制定された", "label": "受身過去形"}], "register": "formal", "sense_fingerprint": "法律・条例などを正式な手続きで定めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be61a4f4-a23f-4ede-b4c0-325ba41986c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39015, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制定", "is_correct": true, "explanation": "法律を正式な手続きで定める意味で、「新しい法律を制定した」が成り立つ。"}, {"text": "販売", "is_correct": false, "explanation": "法律は売買の対象ではないので、「法律を販売した」とは言えない。"}, {"text": "撮影", "is_correct": false, "explanation": "撮影は映像を撮る行為なので、法律を対象にすることはできない。"}, {"text": "注文", "is_correct": false, "explanation": "注文は品物などを頼む行為で、法律を注文するという言い方は成り立たない。"}], "explanations": {"制定": "法律を正式な手続きで定める意味で、「新しい法律を制定した」が成り立つ。", "販売": "法律は売買の対象ではないので、「法律を販売した」とは言えない。", "撮影": "撮影は映像を撮る行為なので、法律を対象にすることはできない。", "注文": "注文は品物などを頼む行為で、法律を注文するという言い方は成り立たない。"}, "sentence_index": 0, "correct_answer": "制定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議で来月の旅行先を制定した。", "explanation": "ここは〈決定〉の意味。制定は法律や規則を正式に定めることで、旅行先には使わない。"}, {"text": "そのアニメ映画は、五年かけて制定された。", "explanation": "ここは〈制作〉の意味。制定は規則を定めることで、映画は制作するものなので合わない。"}, {"text": "新しい町づくりの計画を制定した。", "explanation": "ここは〈策定〉の意味。計画は策定するもので、制定は法律や規則に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39015, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制定", "is_correct": true, "explanation": "「制定から五十年」は法律が正式に定められた時点を表し、ここに合う。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩くことなので、「散歩から五十年たった法律」は意味をなさない。"}, {"text": "調理", "is_correct": false, "explanation": "調理は料理をすることなので、法律の時点を表す言葉としては合わない。"}, {"text": "購入", "is_correct": false, "explanation": "購入は品物を買うことで、法律は買えないので「購入から五十年」は不自然。"}], "explanations": {"制定": "「制定から五十年」は法律が正式に定められた時点を表し、ここに合う。", "散歩": "散歩は歩くことなので、「散歩から五十年たった法律」は意味をなさない。", "調理": "調理は料理をすることなので、法律の時点を表す言葉としては合わない。", "購入": "購入は品物を買うことで、法律は買えないので「購入から五十年」は不自然。"}, "sentence_index": 6, "correct_answer": "制定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験に合格した人を、正式な指導員として制定した。", "explanation": "ここは〈認定〉の意味。人を資格や身分として公式に認めることで、制定は法律や規則を定める語なので合わない。"}, {"text": "新しい会社を五年前に制定した。", "explanation": "ここは〈設立〉の意味。会社は設立するもので、制定は法律や規則に使う。"}, {"text": "完成した作品を、来週ネットに制定する予定だ。", "explanation": "ここは〈公開〉の意味。作品は公開するもので、制定は法律や規則を定める語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39015, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "住民たちは、新しい条例の制定と求めている。", "corrected_sentence": "住民たちは、新しい条例の制定を求めている。", "error_description": "「求める」は求める対象を「を」で示すが、「と」を使っている。正しくは「制定を求める」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39015, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法律の制定を三年がたった。", "corrected_sentence": "法律の制定から三年がたった。", "error_description": "「三年がたった」は起点を示す「から」が必要。「を」は目的語を示すので、ここでは誤り。正しくは「制定から」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ced742a-11f3-4aaa-a0e2-086feaf2a012') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39016, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この州は」と主題を示す。「この州は広くて」と続けるのに合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「この州を広くて」では、州が広いと述べる文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は存在や到着の場所を示す。「この州に広くて」は文の形にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「この州へ広くて」は「広い」と続かない。"}], "correct_answer": "は", "explanations": {"は": "「この州は」と主題を示す。「この州は広くて」と続けるのに合う。", "を": "「を」は目的語を示す。「この州を広くて」では、州が広いと述べる文が成り立たない。", "に": "「に」は存在や到着の場所を示す。「この州に広くて」は文の形にならない。", "へ": "「へ」は方向を示す。「この州へ広くて」は「広い」と続かない。"}, "error_tags": {"を": "目的語（対象）", "に": "存在・到着点", "へ": "方向・行き先"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39016, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「その州の中心」と、州が中心を修飾する「の」。「その州の中心にある町」の形になる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示す。「その州で中心にある町」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「その州より中心にある町」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「その州から中心にある町」は文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「その州の中心」と、州が中心を修飾する「の」。「その州の中心にある町」の形になる。", "で": "「で」は場所や手段を示す。「その州で中心にある町」は成り立たない。", "より": "「より」は比較を示す。「その州より中心にある町」は意味が通らない。", "から": "「から」は起点を示す。「その州から中心にある町」は文が成り立たない。"}, "error_tags": {"で": "場所・手段", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39016, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "国の中の、いくつかに分けられた大きな区域のことです。", "primary_collocate": null, "pronunciation": "しゅう", "ipa": "ɕɯː", "syllable_count": 2, "sentences": [{"text": "国は十の州に分けられ、それぞれに大きな町がある。", "target_word": "州", "complexity_tier": "T3", "furigana": "国[くに]は十[じゅう]の州[しゅう]に分[わ]けられ、それぞれに大[おお]きな町[まち]がある。", "sentence_source": "generated"}, {"text": "この州は広くて、端から端まで車で一日かかる。", "target_word": "州", "complexity_tier": "T3", "furigana": "この州[しゅう]は広[ひろ]くて、端[はし]から端[はし]まで車[くるま]で一日[いちにち]かかる。", "sentence_source": "generated"}, {"text": "北の州は雪が多く、南の州は一年中暖かい。", "target_word": "州", "complexity_tier": "T3", "furigana": "北[きた]の州[しゅう]は雪[ゆき]が多[おお]く、南[みなみ]の州[しゅう]は一年中[いちねんじゅう]暖[あたた]かい。", "sentence_source": "generated"}, {"text": "州ごとに天気が違うので、旅行の前に調べておく。", "target_word": "州", "complexity_tier": "T3", "furigana": "州[しゅう]ごとに天気[てんき]が違[ちが]うので、旅行[りょこう]の前[まえ]に調[しら]べておく。", "sentence_source": "generated"}, {"text": "私が生まれた州には、大きな山と湖がある。", "target_word": "州", "complexity_tier": "T3", "furigana": "私[わたし]が生[う]まれた州[しゅう]には、大[おお]きな山[やま]と湖[みずうみ]がある。", "sentence_source": "generated"}, {"text": "国の中のどの州にも、小さな村がたくさんある。", "target_word": "州", "complexity_tier": "T3", "furigana": "国[くに]の中[なか]のどの州[しゅう]にも、小[ちい]さな村[むら]がたくさんある。", "sentence_source": "generated"}, {"text": "昔の地図には、国がいくつかの州に分かれて描かれている。", "target_word": "州", "complexity_tier": "T3", "furigana": "昔[むかし]の地図[ちず]には、国[くに]がいくつかの州[しゅう]に分[わ]かれて描[えが]かれている。", "sentence_source": "generated"}, {"text": "その州の中心にある町は、市場でにぎわっている。", "target_word": "州", "complexity_tier": "T3", "furigana": "その州[しゅう]の中心[ちゅうしん]にある町[まち]は、市場[いちば]でにぎわっている。", "sentence_source": "generated"}, {"text": "隣の州へ行くには、橋を渡らなければならない。", "target_word": "州", "complexity_tier": "T3", "furigana": "隣[となり]の州[しゅう]へ行[い]くには、橋[はし]を渡[わた]らなければならない。", "sentence_source": "generated"}, {"text": "この州で取れる果物は、国中に送られる。", "target_word": "州", "complexity_tier": "T3", "furigana": "この州[しゅう]で取[と]れる果物[くだもの]は、国中[くにじゅう]に送[おく]られる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "州", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "国をいくつかに分けた大きな地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44bb0fd-3452-43af-b204-23fdee287513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39016, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "州", "is_correct": true, "explanation": "〈州〉は国の中の区域なので、「十の州に分けられ」に合う。"}, {"text": "大陸", "is_correct": false, "explanation": "国を大陸に分けるとは言えず、文の意味が通らない。"}, {"text": "半島", "is_correct": false, "explanation": "半島は陸地の形の名前で、国を十の半島に分けるという文にはならない。"}, {"text": "山脈", "is_correct": false, "explanation": "山脈は連なった山の地形で、国を山脈に分けるとは言わない。"}], "explanations": {"州": "〈州〉は国の中の区域なので、「十の州に分けられ」に合う。", "大陸": "国を大陸に分けるとは言えず、文の意味が通らない。", "半島": "半島は陸地の形の名前で、国を十の半島に分けるという文にはならない。", "山脈": "山脈は連なった山の地形で、国を山脈に分けるとは言わない。"}, "sentence_index": 0, "correct_answer": "州"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この州は国連に加盟している。", "explanation": "ここは〈国家〉の意味。州は国の中の区画なので、独立した国家として国連に加盟することはない。"}, {"text": "この州は国の首都で、政府の建物が集まっている。", "explanation": "ここは国の政治の中心となる地（政府の所在地）の意味。州は国の中の区域なので、国全体の中心地にはならず合わない。"}, {"text": "この州には窓が三つあり、ベッドが二つ置いてある。", "explanation": "ここは〈部屋〉の意味。州は区域を指すので、窓やベッドのある空間の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39016, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "州", "is_correct": true, "explanation": "地図に国の中の区域として描かれるので、〈州〉が入る。"}, {"text": "海岸", "is_correct": false, "explanation": "海岸は海に接する線状の地形で、国を海岸に分けて描くとは言わない。"}, {"text": "砂漠", "is_correct": false, "explanation": "砂漠は乾燥した地域の名前で、国が砂漠に分かれて描かれるという文にはならない。"}, {"text": "湾", "is_correct": false, "explanation": "湾は海が陸に入り込んだ所で、国を湾に分けて描くのは意味が通らない。"}], "explanations": {"州": "地図に国の中の区域として描かれるので、〈州〉が入る。", "海岸": "海岸は海に接する線状の地形で、国を海岸に分けて描くとは言わない。", "砂漠": "砂漠は乾燥した地域の名前で、国が砂漠に分かれて描かれるという文にはならない。", "湾": "湾は海が陸に入り込んだ所で、国を湾に分けて描くのは意味が通らない。"}, "sentence_index": 6, "correct_answer": "州"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この池は州が十キロあり、歩いて一周すると一時間かかる。", "explanation": "ここは「まわりの長さ」の意味。州は区域の意味なので、池のまわりの長さは表せない。"}, {"text": "ジムには州に三回通っている。", "explanation": "ここは同音の〈週〉の意味。州は区域なので、回数の単位としては使えない。"}, {"text": "州は太陽のまわりを一年かけて回っている。", "explanation": "ここは〈地球〉の意味。州は国の中の区域で、天体ではないので太陽のまわりを回らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39016, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "南の州で行くには、飛行機が便利だ。", "corrected_sentence": "南の州へ行くには、飛行機が便利だ。", "error_description": "「州へ行く」の「へ」を「で」にしている。行き先は「へ」で表すので、「州で行く」は成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39016, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "州が作られた酒は、国中で人気がある。", "corrected_sentence": "州で作られた酒は、国中で人気がある。", "error_description": "「州で作られた」の「で」を「が」にしている。作られる場所は「で」で示すので、「州が作られた」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39017, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「その州の知事」と、州が知事を修飾する「の」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「その州を知事は」は文の形にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「その州へ知事は」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「その州より知事は」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「その州の知事」と、州が知事を修飾する「の」が入る。", "を": "「を」は目的語を示す。「その州を知事は」は文の形にならない。", "へ": "「へ」は方向を示す。「その州へ知事は」は意味が通らない。", "より": "「より」は比較を示す。「その州より知事は」は成り立たない。"}, "error_tags": {"を": "目的語（対象）", "へ": "方向・行き先", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39017, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「州の警察」と、州が警察を修飾する「の」が入る。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所を示す。「州で警察は」では文の骨組みが合わない。"}, {"text": "を", "is_correct": false, "explanation": "「州を警察は」では州が目的語になり、警察の主語として成り立たず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「州から警察は」では州の警察という意味にならない。"}], "correct_answer": "の", "explanations": {"の": "「州の警察」と、州が警察を修飾する「の」が入る。", "で": "「で」は場所を示す。「州で警察は」では文の骨組みが合わない。", "を": "「州を警察は」では州が目的語になり、警察の主語として成り立たず不自然。", "から": "「から」は起点を示す。「州から警察は」では州の警察という意味にならない。"}, "error_tags": {"で": "場所・手段", "を": "目的語", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39017, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国家を構成する行政区画の一つ。連邦制国家では、独自の法律や政府を持つ行政単位を指す。", "primary_collocate": null, "pronunciation": "しゅう", "ipa": "ɕɯː", "syllable_count": 2, "sentences": [{"text": "アメリカでは、州によって法律が違う。", "target_word": "州", "complexity_tier": "T3", "furigana": "アメリカでは、州[しゅう]によって法律[ほうりつ]が違[ちが]う。", "sentence_source": "generated"}, {"text": "その州の知事は、来月の選挙で決まる。", "target_word": "州", "complexity_tier": "T3", "furigana": "その州[しゅう]の知事[ちじ]は、来月[らいげつ]の選挙[せんきょ]で決[き]まる。", "sentence_source": "generated"}, {"text": "州が独自に決めた税金に、住民は不満を持っている。", "target_word": "州", "complexity_tier": "T3", "furigana": "州[しゅう]が独自[どくじ]に決[き]めた税金[ぜいきん]に、住民[じゅうみん]は不満[ふまん]を持[も]っている。", "sentence_source": "generated"}, {"text": "連邦政府と州の意見が分かれ、裁判になった。", "target_word": "州", "complexity_tier": "T3", "furigana": "連邦政府[れんぽうせいふ]と州[しゅう]の意見[いけん]が分[わ]かれ、裁判[さいばん]になった。", "sentence_source": "generated"}, {"text": "この州では、車を運転できる年齢が十六歳だ。", "target_word": "州", "complexity_tier": "T3", "furigana": "この州[しゅう]では、車[くるま]を運転[うんてん]できる年齢[ねんれい]が十六歳[じゅうろくさい]だ。", "sentence_source": "generated"}, {"text": "州の議会は、新しい教育の法律を認めた。", "target_word": "州", "complexity_tier": "T3", "furigana": "州[しゅう]の議会[ぎかい]は、新[あたら]しい教育[きょういく]の法律[ほうりつ]を認[みと]めた。", "sentence_source": "generated"}, {"text": "ドイツには十六の州があり、それぞれが政府を持つ。", "target_word": "州", "complexity_tier": "T3", "furigana": "ドイツには十六[じゅうろく]の州[しゅう]があり、それぞれが政府[せいふ]を持[も]つ。", "sentence_source": "generated"}, {"text": "州の警察は、国の警察とは別の組織だ。", "target_word": "州", "complexity_tier": "T3", "furigana": "州[しゅう]の警察[けいさつ]は、国[くに]の警察[けいさつ]とは別[べつ]の組織[そしき]だ。", "sentence_source": "generated"}, {"text": "兄は州の職員として、道路の管理をしている。", "target_word": "州", "complexity_tier": "T3", "furigana": "兄[あに]は州[しゅう]の職員[しょくいん]として、道路[どうろ]の管理[かんり]をしている。", "sentence_source": "generated"}, {"text": "州ごとに最低賃金が決められている国もある。", "target_word": "州", "complexity_tier": "T3", "furigana": "州[しゅう]ごとに最低賃金[さいていちんぎん]が決[き]められている国[くに]もある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "州", "label": "基本形"}], "register": "formal", "sense_fingerprint": "連邦国家で独自の法律と政府を持つ行政区画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44bb0fd-3452-43af-b204-23fdee287513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39017, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "州", "is_correct": true, "explanation": "アメリカでは州ごとに法律が違うので、〈州〉が入る。"}, {"text": "大陸", "is_correct": false, "explanation": "法律の違いは州という行政単位で決まり、大陸によって違うとは言えない。"}, {"text": "半島", "is_correct": false, "explanation": "半島の地形によって法律が違うという文にはならない。"}, {"text": "盆地", "is_correct": false, "explanation": "盆地によって法律が違うとは言えず、文の意味が通らない。"}], "explanations": {"州": "アメリカでは州ごとに法律が違うので、〈州〉が入る。", "大陸": "法律の違いは州という行政単位で決まり、大陸によって違うとは言えない。", "半島": "半島の地形によって法律が違うという文にはならない。", "盆地": "盆地によって法律が違うとは言えず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "州"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一年で一番好きな季節は州だ。", "explanation": "ここは〈季節〉の意味。州は区域を指すので、季節の名前としては使えない。"}, {"text": "州は国会で選ばれ、国の政策を決める。", "explanation": "ここは国の代表者の意味。州は国の中の区域なので、国会で選ばれて政策を決める立場にはならない。"}, {"text": "この湖は州が五キロあり、歩いて一周すると二時間かかる。", "explanation": "ここは「まわりの長さ」の意味。州は区域の意味なので、湖のまわりの長さは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39017, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "州", "is_correct": true, "explanation": "ドイツの連邦制で、政府を持つ行政区画として〈州〉が入る。"}, {"text": "海峡", "is_correct": false, "explanation": "海峡は海の狭い道で、政府を持つ単位ではないので文が成り立たない。"}, {"text": "砂漠", "is_correct": false, "explanation": "砂漠は政府を持つ行政単位ではなく、「それぞれが政府を持つ」と合わない。"}, {"text": "湾", "is_correct": false, "explanation": "湾は政府を持つ行政単位ではなく、この文の意味に合わない。"}], "explanations": {"州": "ドイツの連邦制で、政府を持つ行政区画として〈州〉が入る。", "海峡": "海峡は海の狭い道で、政府を持つ単位ではないので文が成り立たない。", "砂漠": "砂漠は政府を持つ行政単位ではなく、「それぞれが政府を持つ」と合わない。", "湾": "湾は政府を持つ行政単位ではなく、この文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "州"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この州には窓が三つあり、朝は日がよく入る。", "explanation": "ここは〈部屋〉の意味。州は区域を指すので、窓のある空間の意味では使えない。"}, {"text": "州は地球のまわりを回っていて、夜になると見える。", "explanation": "ここは〈月〉の意味。州は地上の区域で、夜空に見える天体ではない。"}, {"text": "州は七日間で、日曜日が最後に来る。", "explanation": "ここは同音の〈週〉の意味。州は一週間の単位ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39017, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "州を知事は、州民の投票で選ばれる。", "corrected_sentence": "州の知事は、州民の投票で選ばれる。", "error_description": "「州の知事」の「の」を「を」にしている。名詞を修飾するには「の」が必要で、「州を知事」は成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
