INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39020, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを広げて、だんだん大きくなったり広がったりすること。", "primary_collocate": null, "pronunciation": "てんかい", "ipa": "teŋkai", "syllable_count": 4, "sentences": [{"text": "その会社は新しい店を全国に展開する計画だ。", "target_word": "展開", "complexity_tier": "T3", "furigana": "その会社[かいしゃ]は新[あたら]しい店[みせ]を全国[ぜんこく]に展開[てんかい]する計画[けいかく]だ。", "sentence_source": "generated"}, {"text": "私たちは海外にも事業を展開していきたい。", "target_word": "展開", "complexity_tier": "T3", "furigana": "私[わたし]たちは海外[かいがい]にも事業[じぎょう]を展開[てんかい]していきたい。", "sentence_source": "generated"}, {"text": "警察は駅の周辺に多くの警官を展開して、警戒を強めた。", "target_word": "展開", "complexity_tier": "T4", "furigana": "警察[けいさつ]は駅[えき]の周辺[しゅうへん]に多[おお]くの警官[けいかん]を展開[てんかい]して、警戒[けいかい]を強[つよ]めた。", "sentence_source": "generated"}, {"text": "山道を登りきると、目の前に雄大な景色が展開していた。", "target_word": "展開", "complexity_tier": "T4", "furigana": "山道[やまみち]を登[のぼ]りきると、目[め]の前[まえ]に雄大[ゆうだい]な景色[けしき]が展開[てんかい]していた。", "sentence_source": "generated"}, {"text": "この店はコーヒーを中心に、さまざまな商品を展開している。", "target_word": "展開", "complexity_tier": "T3", "furigana": "この店[みせ]はコーヒーを中心[ちゅうしん]に、さまざまな商品[しょうひん]を展開[てんかい]している。", "sentence_source": "generated"}, {"text": "この折りたたみ式のテーブルは、一瞬で展開できて便利だ。", "target_word": "展開", "complexity_tier": "T3", "furigana": "この折[お]りたたみ式[しき]のテーブルは、一瞬[いっしゅん]で展開[てんかい]できて便利[べんり]だ。", "sentence_source": "generated"}, {"text": "会社は来年から東南アジアでの展開を始める。", "target_word": "展開", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は来年[らいねん]から東南[とうなん]アジアでの展開[てんかい]を始[はじ]める。", "sentence_source": "generated"}, {"text": "彼女は小さなパン屋から、十年で十店舗まで展開した。", "target_word": "展開", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は小[ちい]さなパン屋[や]から、十年[じゅうねん]で十店舗[じゅってんぽ]まで展開[てんかい]した。", "sentence_source": "generated"}, {"text": "新しいアプリは、まず東京でサービスを始め、その後ほかの町にも展開する予定だ。", "target_word": "展開", "complexity_tier": "T3", "furigana": "新[あたら]しいアプリは、まず東京[とうきょう]でサービスを始[はじ]め、その後[ご]ほかの町[まち]にも展開[てんかい]する予定[よてい]だ。", "sentence_source": "generated"}, {"text": "兵士たちは川に沿って展開し、橋を守った。", "target_word": "展開", "complexity_tier": "T4", "furigana": "兵士[へいし]たちは川[かわ]に沿[そ]って展開[てんかい]し、橋[はし]を守[まも]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "展開", "label": "基本形"}, {"form": "展開する", "label": "サ変動詞"}, {"form": "展開している", "label": "進行形"}], "register": "neutral", "sense_fingerprint": "店・事業・部隊などを広い範囲に広げて配置すること、物を開いて広げること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 4 words above tier T1 (max 2): 山道 (Zipf 3.31), 登り (Zipf 3.72), きる (Zipf 3.7), 雄大 (Zipf 3.51)']::text[], '84e0df04-93ce-41d8-b3b1-6e849a052392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39020, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "展開", "is_correct": true, "explanation": "「展開する」は店を広い範囲に広げて配置する意味で、「全国に」と「計画」の文に合う。"}, {"text": "店舗", "is_correct": false, "explanation": "店舗は店そのものを指す名詞で、「店舗する」とは動詞として続かない。"}, {"text": "看板", "is_correct": false, "explanation": "看板は掲示物を指す名詞で、「看板する」は成り立たない。"}, {"text": "在庫", "is_correct": false, "explanation": "在庫は商品の手持ちを指す名詞で、「新しい店を在庫する」は文に合わない。"}], "explanations": {"展開": "「展開する」は店を広い範囲に広げて配置する意味で、「全国に」と「計画」の文に合う。", "店舗": "店舗は店そのものを指す名詞で、「店舗する」とは動詞として続かない。", "看板": "看板は掲示物を指す名詞で、「看板する」は成り立たない。", "在庫": "在庫は商品の手持ちを指す名詞で、「新しい店を在庫する」は文に合わない。"}, "sentence_index": 0, "correct_answer": "展開"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は赤字のため、社員を展開した。", "explanation": "ここは〈解雇〉の意味。展開は広げて配置する意味で、人を辞めさせることには使わない。"}, {"text": "夜が来て、ランプを展開した。", "explanation": "ここは〈点灯〉の意味。展開は広げて配置する意味で、灯りをともす意味にはならない。"}, {"text": "食べ残しは、そのまま展開した。", "explanation": "ここは〈廃棄〉の意味。展開は広げて並べる意味で、食べ残しを捨てる意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39020, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "展開", "is_correct": true, "explanation": "「展開を始める」は事業を広げ始める意味で、「東南アジアでの」に合う。"}, {"text": "名刺", "is_correct": false, "explanation": "名刺は連絡先を書いた紙で、「東南アジアでの名刺を始める」は意味をなさない。"}, {"text": "布団", "is_correct": false, "explanation": "布団は寝具の名で、「布団を始める」は文に合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は眠たさを指す名詞で、「東南アジアでの眠気を始める」は意味をなさない。"}], "explanations": {"展開": "「展開を始める」は事業を広げ始める意味で、「東南アジアでの」に合う。", "名刺": "名刺は連絡先を書いた紙で、「東南アジアでの名刺を始める」は意味をなさない。", "布団": "布団は寝具の名で、「布団を始める」は文に合わない。", "眠気": "眠気は眠たさを指す名詞で、「東南アジアでの眠気を始める」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "展開"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秋になり、畑のりんごを展開した。", "explanation": "ここは〈収穫〉の意味。展開は広げて配置する意味で、実を取り入れる意味にはならない。"}, {"text": "ひびの入った壁を展開した。", "explanation": "ここは〈修復〉の意味。展開は広げる意味で、壊れたものを直す意味にはならない。"}, {"text": "会議の途中で、彼は展開して部屋を出た。", "explanation": "ここは〈退席〉の意味。展開は広げる・広がる意味で、会議を抜ける意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39020, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その会社は地方にも店舗を展開で方針だ。", "corrected_sentence": "その会社は地方にも店舗を展開する方針だ。", "error_description": "「展開する方針」が正しい。「する」を「で」に替えると「展開で方針」となり、名詞「方針」を修飾できない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39020, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼らは島に拠点を展開られ、物資を運んだ。", "corrected_sentence": "彼らは島に拠点を展開し、物資を運んだ。", "error_description": "「展開する」は連用形「展開し」で続ける。「られ」は受身の形で、サ変動詞の「展開」には付けられない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39021, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「展開が早くて」で、展開を主語にして「早い」と述べる形。"}, {"text": "を", "is_correct": false, "explanation": "「展開を早くて」は「早い」の主語にならず、目的語としても成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「展開で早くて」は手段や場所の意味にならず、主語にもならない。"}, {"text": "に", "is_correct": false, "explanation": "「展開に早くて」は方向や位置を示さず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「展開が早くて」で、展開を主語にして「早い」と述べる形。", "を": "「展開を早くて」は「早い」の主語にならず、目的語としても成り立たない。", "で": "「展開で早くて」は手段や場所の意味にならず、主語にもならない。", "に": "「展開に早くて」は方向や位置を示さず、文が成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "に": "方向・位置"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
