INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39021, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を広く行き渡らせたり、詳しく述べたりすること。また、ある状態が広がって進むこと。", "primary_collocate": null, "pronunciation": "てんかい", "ipa": "teŋkai", "syllable_count": 4, "sentences": [{"text": "熟練したソムリエは、グラス内で展開される鉱物的な輪郭や土壌由来の複雑な香気構造を解読し、視覚や嗅覚を超えた土地的コンテキストを味覚的に再構成する。", "target_word": "展開", "complexity_tier": "T5", "furigana": "熟練[じゅくれん]したソムリエは、グラス内[ない]で展開[てんかい]される鉱物的[こうぶつてき]な輪郭[りんかく]や土壌[どじょう]由来[ゆらい]の複雑[ふくざつ]な香気[こうき]構造[こうぞう]を解読[かいどく]し、視覚[しかく]や嗅覚[きゅうかく]を超[こ]えた土地的[とちてき]コンテキストを味覚的[みかくてき]に再構成[さいこうせい]する。", "sentence_source": "mined"}, {"text": "この映画は後半の展開が早くて、最後まで目が離せなかった。", "target_word": "展開", "complexity_tier": "T3", "furigana": "この映画[えいが]は後半[こうはん]の展開[てんかい]が早[はや]くて、最後[さいご]まで目[め]が離[はな]せなかった。", "sentence_source": "generated"}, {"text": "予想外の展開に、会場の誰もが言葉を失った。", "target_word": "展開", "complexity_tier": "T3", "furigana": "予想外[よそうがい]の展開[てんかい]に、会場[かいじょう]の誰[だれ]もが言葉[ことば]を失[うしな]った。", "sentence_source": "generated"}, {"text": "先生は黒板を使って、自分の考えを順序立てて展開した。", "target_word": "展開", "complexity_tier": "T4", "furigana": "先生[せんせい]は黒板[こくばん]を使[つか]って、自分[じぶん]の考[かんが]えを順序立[じゅんじょだ]てて展開[てんかい]した。", "sentence_source": "generated"}, {"text": "試合は延長戦へと展開し、観客は大いに盛り上がった。", "target_word": "展開", "complexity_tier": "T4", "furigana": "試合[しあい]は延長戦[えんちょうせん]へと展開[てんかい]し、観客[かんきゃく]は大[おお]いに盛[も]り上[あ]がった。", "sentence_source": "generated"}, {"text": "小説の展開が単調なので、途中で読むのをやめてしまった。", "target_word": "展開", "complexity_tier": "T3", "furigana": "小説[しょうせつ]の展開[てんかい]が単調[たんちょう]なので、途中[とちゅう]で読[よ]むのをやめてしまった。", "sentence_source": "generated"}, {"text": "話し合いが思わぬ方向に展開して、結論が出なくなった。", "target_word": "展開", "complexity_tier": "T4", "furigana": "話[はな]し合[あ]いが思[おも]わぬ方向[ほうこう]に展開[てんかい]して、結論[けつろん]が出[で]なくなった。", "sentence_source": "generated"}, {"text": "彼は論文の中で、独自の理論を展開している。", "target_word": "展開", "complexity_tier": "T4", "furigana": "彼[かれ]は論文[ろんぶん]の中[なか]で、独自[どくじ]の理論[りろん]を展開[てんかい]している。", "sentence_source": "generated"}, {"text": "事件はその後、誰も予想しなかった展開を見せた。", "target_word": "展開", "complexity_tier": "T3", "furigana": "事件[じけん]はその後[ご]、誰[だれ]も予想[よそう]しなかった展開[てんかい]を見[み]せた。", "sentence_source": "generated"}, {"text": "議論がどう展開するか分からないので、資料を多めに用意した。", "target_word": "展開", "complexity_tier": "T4", "furigana": "議論[ぎろん]がどう展開[てんかい]するか分[わ]からないので、資料[しりょう]を多[おお]めに用意[ようい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "展開", "label": "基本形"}, {"form": "展開する", "label": "サ変動詞"}, {"form": "展開される", "label": "受身"}], "register": "neutral", "sense_fingerprint": "話・出来事・議論などが進んでいく様子、または考えを詳しく述べること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 香気 (Zipf 2.11)']::text[], '84e0df04-93ce-41d8-b3b1-6e849a052392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39021, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "展開", "is_correct": true, "explanation": "「展開される」は香りや風味が広がって現れる受身で、この文の「広がる・行き渡る」意味に合う。"}, {"text": "樽", "is_correct": false, "explanation": "樽は熟成に使う容器の名詞で、「樽される」は受身として成り立たない。"}, {"text": "酸味", "is_correct": false, "explanation": "酸味は味の一つを指す名詞で、「酸味される」とは言えない。"}, {"text": "芳香", "is_correct": false, "explanation": "芳香は香りを表す名詞で、「芳香される」は文の意味に合わない。"}], "explanations": {"展開": "「展開される」は香りや風味が広がって現れる受身で、この文の「広がる・行き渡る」意味に合う。", "樽": "樽は熟成に使う容器の名詞で、「樽される」は受身として成り立たない。", "酸味": "酸味は味の一つを指す名詞で、「酸味される」とは言えない。", "芳香": "芳香は香りを表す名詞で、「芳香される」は文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "展開"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い校舎を展開して、新しいビルを建てた。", "explanation": "ここは〈解体〉の意味。展開は広げて進める意味で、建物を壊すことには使わない。"}, {"text": "渋滞を展開して、道がすいた。", "explanation": "ここは〈解消〉の意味。展開は広がって進む意味で、渋滞をなくす意味にはならない。"}, {"text": "夜になったので、ドアを展開した。", "explanation": "ここは〈施錠〉の意味。展開は広げる意味で、鍵をかける意味は持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39021, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "展開", "is_correct": true, "explanation": "「展開して」は話や議論が進んでいく様子を表し、文の「思わぬ方向に」に合う。"}, {"text": "議題", "is_correct": false, "explanation": "議題は話し合う題目を指す名詞で、「思わぬ方向に議題して」とは続かない。"}, {"text": "資料", "is_correct": false, "explanation": "資料は参考になる書類で、「資料して」は動詞として成り立たない。"}, {"text": "日程", "is_correct": false, "explanation": "日程は予定の並びを指し、「思わぬ方向に日程して」は意味をなさない。"}], "explanations": {"展開": "「展開して」は話や議論が進んでいく様子を表し、文の「思わぬ方向に」に合う。", "議題": "議題は話し合う題目を指す名詞で、「思わぬ方向に議題して」とは続かない。", "資料": "資料は参考になる書類で、「資料して」は動詞として成り立たない。", "日程": "日程は予定の並びを指し、「思わぬ方向に日程して」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "展開"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "信号が展開して、車が止まった。", "explanation": "ここは〈点滅〉の意味。展開は広がって進む意味で、光が明滅する様子には使わない。"}, {"text": "試合を延期して、来週に展開した。", "explanation": "ここは〈延期〉の意味。展開は広がる・進む意味で、日時を先に送る意味にはならない。"}, {"text": "その国は外国人の入国を展開した。", "explanation": "ここは〈禁止〉の意味。展開は広げて進む意味で、入国を止める意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39021, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作者は第二章で、人物の過去を丁寧に展開するている。", "corrected_sentence": "作者は第二章で、人物の過去を丁寧に展開している。", "error_description": "「展開している」が正しい。「する」に「ている」を重ねた「展開するている」は文法的に成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39021, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ドラマは驚きの展開が見せて、視聴者を引きつけた。", "corrected_sentence": "ドラマは驚きの展開を見せて、視聴者を引きつけた。", "error_description": "「見せる」は他動詞なので目的語の「を」が必要。「展開が見せて」では主語と動詞が対応せず、不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39022, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無料", "is_correct": true, "explanation": "利用に料金がかからないことを表し、有料の対義語として辞書にも並ぶ。"}, {"text": "有名", "is_correct": false, "explanation": "世間によく知られていること。料金の有無とは関係がなく、対義語ではない。"}, {"text": "有益", "is_correct": false, "explanation": "役に立つこと。料金の有無とは別の概念で、対義語ではない。"}, {"text": "有力", "is_correct": false, "explanation": "勢いや影響力があること。料金の性質とは関係がなく、対義語ではない。"}], "correct_answer": "無料", "explanations": {"無料": "利用に料金がかからないことを表し、有料の対義語として辞書にも並ぶ。", "有名": "世間によく知られていること。料金の有無とは関係がなく、対義語ではない。", "有益": "役に立つこと。料金の有無とは別の概念で、対義語ではない。", "有力": "勢いや影響力があること。料金の性質とは関係がなく、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39022, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無料", "is_correct": true, "explanation": "利用に料金がかからないことで、有料の対義語として辞書にも並ぶ。"}, {"text": "有効", "is_correct": false, "explanation": "効き目があること。料金の有無とは関係がなく、対義語ではない。"}, {"text": "有能", "is_correct": false, "explanation": "仕事をうまくこなせる能力があること。料金とは無関係で、対義語ではない。"}, {"text": "有限", "is_correct": false, "explanation": "限りがあること。料金の性質とは別の概念で、対義語ではない。"}], "correct_answer": "無料", "explanations": {"無料": "利用に料金がかからないことで、有料の対義語として辞書にも並ぶ。", "有効": "効き目があること。料金の有無とは関係がなく、対義語ではない。", "有能": "仕事をうまくこなせる能力があること。料金とは無関係で、対義語ではない。", "有限": "限りがあること。料金の性質とは別の概念で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39022, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "お金を払わなければならないこと。", "primary_collocate": null, "pronunciation": "ゆうりょう", "ipa": "jɯːɾʲoː", "syllable_count": 4, "sentences": [{"text": "この駐車場は有料です。", "target_word": "有料", "complexity_tier": "T3", "furigana": "この駐車場[ちゅうしゃじょう]は有料[ゆうりょう]です。", "sentence_source": "generated"}, {"text": "スーパーのレジ袋は有料なので、自分の袋を持っていく。", "target_word": "有料", "complexity_tier": "T3", "furigana": "スーパーのレジ袋[ぶくろ]は有料[ゆうりょう]なので、自分[じぶん]の袋[ふくろ]を持[も]っていく。", "sentence_source": "generated"}, {"text": "無料だと思ったら、有料だったので驚いた。", "target_word": "有料", "complexity_tier": "T3", "furigana": "無料[むりょう]だと思[おも]ったら、有料[ゆうりょう]だったので驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "この展覧会は有料だが、学生は安く入れる。", "target_word": "有料", "complexity_tier": "T3", "furigana": "この展覧会[てんらんかい]は有料[ゆうりょう]だが、学生[がくせい]は安[やす]く入[はい]れる。", "sentence_source": "generated"}, {"text": "トイレが有料の駅もあるので、小銭を用意しておく。", "target_word": "有料", "complexity_tier": "T3", "furigana": "トイレが有料[ゆうりょう]の駅[えき]もあるので、小銭[こぜに]を用意[ようい]しておく。", "sentence_source": "generated"}, {"text": "海の近くの駐車場はどこも有料で、安い所を探すのが大変だった。", "target_word": "有料", "complexity_tier": "T3", "furigana": "海[うみ]の近[ちか]くの駐車場[ちゅうしゃじょう]はどこも有料[ゆうりょう]で、安[やす]い所[ところ]を探[さが]すのが大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "試食は無料ですが、持ち帰りは有料です。", "target_word": "有料", "complexity_tier": "T3", "furigana": "試食[ししょく]は無料[むりょう]ですが、持[も]ち帰[かえ]りは有料[ゆうりょう]です。", "sentence_source": "generated"}, {"text": "有料かどうか、入る前に係の人に聞いた。", "target_word": "有料", "complexity_tier": "T3", "furigana": "有料[ゆうりょう]かどうか、入[はい]る前[まえ]に係[かかり]の人[ひと]に聞[き]いた。", "sentence_source": "generated"}, {"text": "公園のシャワーは有料で、五分で百円かかる。", "target_word": "有料", "complexity_tier": "T3", "furigana": "公園[こうえん]のシャワーは有料[ゆうりょう]で、五分[ごふん]で百円[ひゃくえん]かかる。", "sentence_source": "generated"}, {"text": "来月から、この道路では駐車が有料になる。", "target_word": "有料", "complexity_tier": "T3", "furigana": "来月[らいげつ]から、この道路[どうろ]では駐車[ちゅうしゃ]が有料[ゆうりょう]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "有料", "label": "基本形"}, {"form": "有料の", "label": "連体形"}, {"form": "有料だ", "label": "断定形"}], "register": "一般", "sense_fingerprint": "利用や持ち帰りなどに料金がかかる状態（無料の反対）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f54bc903-95d5-40b4-bd35-efc729115735') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39022, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有料", "is_correct": true, "explanation": "料金がかかる駐車場の性質を表す語で、「この駐車場は＿です」の空欄に自然に入る。"}, {"text": "駐車", "is_correct": false, "explanation": "車を止める行為の名詞。「この駐車場は駐車です」は駐車場の性質を述べる文として成り立たない。"}, {"text": "出口", "is_correct": false, "explanation": "場所の名詞だが、「この駐車場は出口です」は意味が通らず、料金の性質の説明にもならない。"}, {"text": "通行", "is_correct": false, "explanation": "通ること。駐車場の性質を述べる空欄には合わない。"}], "explanations": {"有料": "料金がかかる駐車場の性質を表す語で、「この駐車場は＿です」の空欄に自然に入る。", "駐車": "車を止める行為の名詞。「この駐車場は駐車です」は駐車場の性質を述べる文として成り立たない。", "出口": "場所の名詞だが、「この駐車場は出口です」は意味が通らず、料金の性質の説明にもならない。", "通行": "通ること。駐車場の性質を述べる空欄には合わない。"}, "sentence_index": 0, "correct_answer": "有料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週は有料をとって、家族と旅行に行くつもりだ。", "explanation": "ここは〈有給〉の意味。有料は料金がかかることで、休暇をとる文には合わない。"}, {"text": "彼は週末、有料のボランティアとして病院で働いた。", "explanation": "ここは〈有償〉の意味。有料は利用に料金がかかることで、報酬を伴う活動には使わない。"}, {"text": "振込には有料がかかるので、窓口で確認した。", "explanation": "ここは〈手数料〉の意味。有料は料金がかかる状態を表す語で、かかる金額そのものを指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39022, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有料", "is_correct": true, "explanation": "「試食は無料ですが」と対比されており、持ち帰りに料金がかかることを表す語として入る。"}, {"text": "店内", "is_correct": false, "explanation": "店の中という場所の名詞。持ち帰りの性質を表す空欄には入らない。"}, {"text": "包装", "is_correct": false, "explanation": "包むこと。持ち帰りの料金の話をしている文には合わない。"}, {"text": "配達", "is_correct": false, "explanation": "届けること。持ち帰りの説明にはならず、対比の文脈とも合わない。"}], "explanations": {"有料": "「試食は無料ですが」と対比されており、持ち帰りに料金がかかることを表す語として入る。", "店内": "店の中という場所の名詞。持ち帰りの性質を表す空欄には入らない。", "包装": "包むこと。持ち帰りの料金の話をしている文には合わない。", "配達": "届けること。持ち帰りの説明にはならず、対比の文脈とも合わない。"}, "sentence_index": 6, "correct_answer": "有料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会員なら、この店で有料が受けられる。", "explanation": "ここは〈割引〉の意味。有料は料金がかかる状態を表し、受けられるものではない。"}, {"text": "会員証を出すと、この店で有料をもらえる。", "explanation": "ここは〈特典〉の意味。有料は得られる物ではなく、料金がかかることを表す。"}, {"text": "事故の有料を受けるには、書類が必要だ。", "explanation": "ここは〈補償〉の意味。有料は受け取るものではないので、補償の文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39022, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅前には有料を駐車場が多い。", "corrected_sentence": "駅前には有料の駐車場が多い。", "error_description": "『有料』は名詞で、後ろの名詞を修飾するときは『の』で続ける。『有料を駐車場』の『を』は誤りで、正しくは『有料の駐車場』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39022, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜のプールは有料を入れます。", "corrected_sentence": "夜のプールは有料で入れます。", "error_description": "料金を払って入る意味では『有料で入る』。『有料を入る』の『を』は誤りで、手段を表す『で』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39023, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無料", "is_correct": true, "explanation": "アプリやサービスを料金なしで使えることで、有料の対義語として並ぶ。"}, {"text": "有名", "is_correct": false, "explanation": "よく知られていること。料金の有無とは無関係で、対義語ではない。"}, {"text": "有益", "is_correct": false, "explanation": "役に立つこと。料金の有無とは別の概念で、対義語ではない。"}, {"text": "有力", "is_correct": false, "explanation": "勢いや影響力があること。料金の性質とは関係がなく、対義語ではない。"}], "correct_answer": "無料", "explanations": {"無料": "アプリやサービスを料金なしで使えることで、有料の対義語として並ぶ。", "有名": "よく知られていること。料金の有無とは無関係で、対義語ではない。", "有益": "役に立つこと。料金の有無とは別の概念で、対義語ではない。", "有力": "勢いや影響力があること。料金の性質とは関係がなく、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39023, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無料", "is_correct": true, "explanation": "料金がかからないことで、有料の対義語として辞書にも並ぶ。"}, {"text": "有効", "is_correct": false, "explanation": "効き目があること。料金の有無とは関係がなく、対義語ではない。"}, {"text": "有能", "is_correct": false, "explanation": "仕事をうまくこなせる能力があること。料金とは無関係で、対義語ではない。"}, {"text": "有限", "is_correct": false, "explanation": "限りがあること。料金の性質とは別の概念で、対義語ではない。"}], "correct_answer": "無料", "explanations": {"無料": "料金がかからないことで、有料の対義語として辞書にも並ぶ。", "有効": "効き目があること。料金の有無とは関係がなく、対義語ではない。", "有能": "仕事をうまくこなせる能力があること。料金とは無関係で、対義語ではない。", "有限": "限りがあること。料金の性質とは別の概念で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39023, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "利用するためにお金を支払う必要があること。", "primary_collocate": null, "pronunciation": "ゆうりょう", "ipa": "jɯːɾʲoː", "syllable_count": 4, "sentences": [{"text": "このアプリは、広告を消すには有料のプランに入る必要がある。", "target_word": "有料", "complexity_tier": "T3", "furigana": "このアプリは、広告[こうこく]を消[け]すには有料[ゆうりょう]のプランに入[はい]る必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "このサイトには、無料のコースと有料のコースがある。", "target_word": "有料", "complexity_tier": "T3", "furigana": "このサイトには、無料[むりょう]のコースと有料[ゆうりょう]のコースがある。", "sentence_source": "generated"}, {"text": "有料の会員になると、動画が見放題だ。", "target_word": "有料", "complexity_tier": "T3", "furigana": "有料[ゆうりょう]の会員[かいいん]になると、動画[どうが]が見放題[みほうだい]だ。", "sentence_source": "generated"}, {"text": "有料のサービスは便利だが、毎月お金がかかる。", "target_word": "有料", "complexity_tier": "T3", "furigana": "有料[ゆうりょう]のサービスは便利[べんり]だが、毎月[まいつき]お金[かね]がかかる。", "sentence_source": "generated"}, {"text": "ニュースの続きを読むには登録が必要ですが、その登録は有料です。", "target_word": "有料", "complexity_tier": "T3", "furigana": "ニュースの続[つづ]きを読[よ]むには登録[とうろく]が必要[ひつよう]ですが、その登録[とうろく]は有料[ゆうりょう]です。", "sentence_source": "generated"}, {"text": "この辞書アプリは有料だが、その分、機能が多い。", "target_word": "有料", "complexity_tier": "T3", "furigana": "この辞書[じしょ]アプリは有料[ゆうりょう]だが、その分[ぶん]、機能[きのう]が多[おお]い。", "sentence_source": "generated"}, {"text": "無料で試したあと、有料に変えるか考えている。", "target_word": "有料", "complexity_tier": "T3", "furigana": "無料[むりょう]で試[ため]したあと、有料[ゆうりょう]に変[か]えるか考[かんが]えている。", "sentence_source": "generated"}, {"text": "無線LANは、ホテルによって有料のところもある。", "target_word": "有料", "complexity_tier": "T3", "furigana": "無線LAN[むせんラン]は、ホテルによって有料[ゆうりょう]のところもある。", "sentence_source": "generated"}, {"text": "有料の相談サービスを使ったら、すぐに答えがもらえた。", "target_word": "有料", "complexity_tier": "T3", "furigana": "有料[ゆうりょう]の相談[そうだん]サービスを使[つか]ったら、すぐに答[こた]えがもらえた。", "sentence_source": "generated"}, {"text": "このゲームは基本は無料だが、一部の機能は有料だ。", "target_word": "有料", "complexity_tier": "T3", "furigana": "このゲームは基本[きほん]は無料[むりょう]だが、一部[いちぶ]の機能[きのう]は有料[ゆうりょう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "有料", "label": "基本形"}, {"form": "有料の", "label": "連体形"}, {"form": "有料だ", "label": "断定形"}], "register": "一般", "sense_fingerprint": "アプリ・サイト・サービスなどの利用に支払いが必要な状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f54bc903-95d5-40b4-bd35-efc729115735') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39023, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有料", "is_correct": true, "explanation": "利用に料金がかかるプランを指し、広告を消すために入るプランとして自然に入る。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のこと。「広告を消すには天気のプランに入る」は意味が通らない。"}, {"text": "音声", "is_correct": false, "explanation": "声や音のこと。「音声のプラン」は文脈に合わない。"}, {"text": "写真", "is_correct": false, "explanation": "写真のこと。「写真のプラン」は広告を消す文脈と合わない。"}], "explanations": {"有料": "利用に料金がかかるプランを指し、広告を消すために入るプランとして自然に入る。", "天気": "空模様のこと。「広告を消すには天気のプランに入る」は意味が通らない。", "音声": "声や音のこと。「音声のプラン」は文脈に合わない。", "写真": "写真のこと。「写真のプラン」は広告を消す文脈と合わない。"}, "sentence_index": 0, "correct_answer": "有料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このアプリは有料を一括で払うと、一年間使える。", "explanation": "ここは〈料金〉の意味。有料は料金がかかる状態を表す語で、払うお金そのものは指さない。"}, {"text": "このクーポンは有料期限が来月までだ。", "explanation": "ここは〈有効〉の意味。有料は料金に関する状態で、期限を表す語ではない。"}, {"text": "この本は内容が有料で、何度も読み返したい。", "explanation": "ここは〈有益〉の意味。有料は料金がかかる状態を表す語で、内容の価値を評価する文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39023, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有料", "is_correct": true, "explanation": "無料で試したあとに切り替える先として、料金のかかるプランを表す語が入る。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物を作ること。無料で試したあとに切り替える先としては成り立たない。"}, {"text": "手順", "is_correct": false, "explanation": "物事を行うやり方の順序。無料で試したあとに切り替える先としては意味が合わない。"}, {"text": "散髪", "is_correct": false, "explanation": "髪を切ること。料金の状態を切り替える空欄には入らない。"}], "explanations": {"有料": "無料で試したあとに切り替える先として、料金のかかるプランを表す語が入る。", "料理": "食べ物を作ること。無料で試したあとに切り替える先としては成り立たない。", "手順": "物事を行うやり方の順序。無料で試したあとに切り替える先としては意味が合わない。", "散髪": "髪を切ること。料金の状態を切り替える空欄には入らない。"}, "sentence_index": 6, "correct_answer": "有料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学割が使えるなら、このアプリで有料が受けられる。", "explanation": "ここは〈割引〉の意味。有料は料金がかかる状態を表し、受けられる物ではない。"}, {"text": "通知を受け取る設定にすると、有料も届く。", "explanation": "ここは〈お知らせ〉の意味。有料は情報として送られるものではなく、料金がかかる状態を表す語なので、この文には合わない。"}, {"text": "広告を消すには、有料を消す必要がある。", "explanation": "ここは〈削除〉の意味。有料は取り除くものではなく、料金がかかる状態を表す語なので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39023, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このサイトは有料に利用できる。", "corrected_sentence": "このサイトは有料で利用できる。", "error_description": "『料金を払って利用する』の意味では『有料で利用』。『有料に』の『に』は誤りで、手段を表す『で』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
