INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39024, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「義務がある」の主語を示す格助詞。存在を表す文型に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「義務をある」は存在の文型が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "場所や帰着を示す。「義務にある」は義務を場所のように扱う不自然な文になる。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。文が終わらず、述語にならない。"}], "correct_answer": "が", "explanations": {"が": "「義務がある」の主語を示す格助詞。存在を表す文型に合う。", "を": "目的語を示す。「義務をある」は存在の文型が成り立たない。", "に": "場所や帰着を示す。「義務にある」は義務を場所のように扱う不自然な文になる。", "の": "連体修飾の「の」。文が終わらず、述語にならない。"}, "error_tags": {"を": "object marker, no transitive verb here", "に": "location or destination", "の": "modifier, no predicate"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "権利", "is_correct": true, "explanation": "義務と対になる語で、主張できる資格を表す。義務の対義語として辞書にも並ぶ。"}, {"text": "責任", "is_correct": false, "explanation": "義務と似た語だが、対義語ではない。"}, {"text": "義理", "is_correct": false, "explanation": "人間関係上の筋として果たすべきこと。対義語ではない。"}, {"text": "使命", "is_correct": false, "explanation": "与えられた重大な任務。対義語ではない。"}], "correct_answer": "権利", "explanations": {"権利": "義務と対になる語で、主張できる資格を表す。義務の対義語として辞書にも並ぶ。", "責任": "義務と似た語だが、対義語ではない。", "義理": "人間関係上の筋として果たすべきこと。対義語ではない。", "使命": "与えられた重大な任務。対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
