INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39024, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "しなければならないこと、やらなくてはいけないこと。", "primary_collocate": null, "pronunciation": "ぎむ", "ipa": "ɡimɯ", "syllable_count": 2, "sentences": [{"text": "子どもを育てるのは親の義務だと思う。", "target_word": "義務", "complexity_tier": "T3", "furigana": "子[こ]どもを育[そだ]てるのは親[おや]の義務[ぎむ]だと思[おも]う。", "sentence_source": "generated"}, {"text": "借りた本は期限までに返す義務がある。", "target_word": "義務", "complexity_tier": "T3", "furigana": "借[か]りた本[ほん]は期限[きげん]までに返[かえ]す義務[ぎむ]がある。", "sentence_source": "generated"}, {"text": "彼は私に説明する義務はないと言って、帰ってしまった。", "target_word": "義務", "complexity_tier": "T3", "furigana": "彼[かれ]は私[わたし]に説明[せつめい]する義務[ぎむ]はないと言[い]って、帰[かえ]ってしまった。", "sentence_source": "generated"}, {"text": "権利ばかり言わずに、義務も果たしなさい。", "target_word": "義務", "complexity_tier": "T3", "furigana": "権利[けんり]ばかり言[い]わずに、義務[ぎむ]も果[は]たしなさい。", "sentence_source": "generated"}, {"text": "当番の日は、教室をそうじする義務がある。", "target_word": "義務", "complexity_tier": "T3", "furigana": "当番[とうばん]の日[ひ]は、教室[きょうしつ]をそうじする義務[ぎむ]がある。", "sentence_source": "generated"}, {"text": "先輩だからといって、おごる義務はない。", "target_word": "義務", "complexity_tier": "T3", "furigana": "先輩[せんぱい]だからといって、おごる義務[ぎむ]はない。", "sentence_source": "generated"}, {"text": "私には、この秘密を守る義務がある。", "target_word": "義務", "complexity_tier": "T3", "furigana": "私[わたし]には、この秘密[ひみつ]を守[まも]る義務[ぎむ]がある。", "sentence_source": "generated"}, {"text": "人を助けるのは義務ではなく、気持ちの問題だ。", "target_word": "義務", "complexity_tier": "T3", "furigana": "人[ひと]を助[たす]けるのは義務[ぎむ]ではなく、気持[きも]ちの問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "会社に勤める以上、約束の時間に来る義務がある。", "target_word": "義務", "complexity_tier": "T3", "furigana": "会社[かいしゃ]に勤[つと]める以上[いじょう]、約束[やくそく]の時間[じかん]に来[く]る義務[ぎむ]がある。", "sentence_source": "generated"}, {"text": "義務だと思うと、勉強がつまらなくなる。", "target_word": "義務", "complexity_tier": "T3", "furigana": "義務[ぎむ]だと思[おも]うと、勉強[べんきょう]がつまらなくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "義務", "label": "基本形"}, {"form": "義務の", "label": "連体形"}, {"form": "義務だ", "label": "断定形"}], "register": "一般", "sense_fingerprint": "人として・立場上しなければならないこと（道徳的・役割上の務め）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: じする (Zipf 1.05)']::text[], 'f54bc903-95d5-40b4-bd35-efc729115735') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39024, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "義務", "is_correct": true, "explanation": "しなければならない務めを表し、親が育てることの位置づけとして自然に入る。"}, {"text": "季節", "is_correct": false, "explanation": "一年の区分。「育てるのは親の季節だと思う」は文として成り立たない。"}, {"text": "食事", "is_correct": false, "explanation": "食べること。「育てるのは親の食事だと思う」は意味が通らない。"}, {"text": "遊び", "is_correct": false, "explanation": "遊ぶこと。「育てるのは親の遊びだと思う」は意味が合わない。"}], "explanations": {"義務": "しなければならない務めを表し、親が育てることの位置づけとして自然に入る。", "季節": "一年の区分。「育てるのは親の季節だと思う」は文として成り立たない。", "食事": "食べること。「育てるのは親の食事だと思う」は意味が通らない。", "遊び": "遊ぶこと。「育てるのは親の遊びだと思う」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "義務"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事故の義務を取って、謝った。", "explanation": "ここは〈責任〉の意味。義務は果たすものであり、事故の後始末として取るものではない。"}, {"text": "お世話になった先生に、義務を伝えた。", "explanation": "ここは〈感謝〉の意味。義務は伝える気持ちではなく、しなければならない務めを表す。"}, {"text": "助けてもらった恩を、義務で返す。", "explanation": "ここは〈お礼〉の意味。義務は受けた親切に報いる行為を表さず、しなければならない務めを表す語で、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39024, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "義務", "is_correct": true, "explanation": "「この秘密を守る」に続き、守るべき務めを表す語として入る。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のこと。「この秘密を守る天気がある」は意味が通らない。"}, {"text": "散歩", "is_correct": false, "explanation": "歩いて回ること。秘密を守る文脈には入らない。"}, {"text": "食事", "is_correct": false, "explanation": "食べること。「この秘密を守る食事がある」は成り立たない。"}], "explanations": {"義務": "「この秘密を守る」に続き、守るべき務めを表す語として入る。", "天気": "空模様のこと。「この秘密を守る天気がある」は意味が通らない。", "散歩": "歩いて回ること。秘密を守る文脈には入らない。", "食事": "食べること。「この秘密を守る食事がある」は成り立たない。"}, "sentence_index": 6, "correct_answer": "義務"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもに義務を注ぐのは大切だ。", "explanation": "ここは〈愛情〉の意味。義務は注ぐものではなく、しなければならない務めを表すので、愛情を与える文には合わない。"}, {"text": "彼は母に義務を贈った。", "explanation": "ここは〈贈り物〉の意味。義務は贈るものではなく、しなければならない務めを表すので、物を渡す文には合わない。"}, {"text": "彼女は、会ったばかりの相手に義務を抱いた。", "explanation": "ここは〈好意〉の意味。義務は抱く感情ではなく、しなければならない務めを表すので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39024, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先輩には後輩を導く義務のある。", "corrected_sentence": "先輩には後輩を導く義務がある。", "error_description": "『義務がある』の文型では『が』が正しい。『義務のある』は文の述語にならず、『の』が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39024, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社の規則では、遅刻しない義務にある。", "corrected_sentence": "会社の規則では、遅刻しない義務がある。", "error_description": "存在を表す文型では『義務がある』。『義務に』の『に』は誤りで、『が』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39025, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「義務がある」の主語を示す格助詞。存在を表す文型に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「義務をある」は存在の文型が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "場所や帰着を示す。「義務にある」は義務を場所のように扱う不自然な文になる。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。文が終わらず、述語にならない。"}], "correct_answer": "が", "explanations": {"が": "「義務がある」の主語を示す格助詞。存在を表す文型に合う。", "を": "目的語を示す。「義務をある」は存在の文型が成り立たない。", "に": "場所や帰着を示す。「義務にある」は義務を場所のように扱う不自然な文になる。", "の": "連体修飾の「の」。文が終わらず、述語にならない。"}, "error_tags": {"を": "object marker", "に": "location or destination", "の": "modifier, no predicate"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "権利", "is_correct": true, "explanation": "法律上、義務と対になる語で、行使できる資格を表す。対義語として辞書にも並ぶ。"}, {"text": "規定", "is_correct": false, "explanation": "決められた取り決め。義務と関係は深いが、対義語ではない。"}, {"text": "罰則", "is_correct": false, "explanation": "違反への罰の定め。対義語ではない。"}, {"text": "制度", "is_correct": false, "explanation": "社会の仕組み。対義語ではない。"}], "correct_answer": "権利", "explanations": {"権利": "法律上、義務と対になる語で、行使できる資格を表す。対義語として辞書にも並ぶ。", "規定": "決められた取り決め。義務と関係は深いが、対義語ではない。", "罰則": "違反への罰の定め。対義語ではない。", "制度": "社会の仕組み。対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39025, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「義務を守る」の目的語を示す格助詞。守る対象として自然に入る。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「義務が守らない」は主語と動詞が合わない。"}, {"text": "に", "is_correct": false, "explanation": "方向や対象を示す。「義務に守る」は文型が合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を示す。「義務と守らない」は不自然で成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「義務を守る」の目的語を示す格助詞。守る対象として自然に入る。", "が": "主語を示す。「義務が守らない」は主語と動詞が合わない。", "に": "方向や対象を示す。「義務に守る」は文型が合わない。", "と": "相手や引用を示す。「義務と守らない」は不自然で成り立たない。"}, "error_tags": {"が": "subject marker", "に": "target or location", "と": "partner or quotation"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "権利", "is_correct": true, "explanation": "義務と対になる語で、主張できる資格を表す。対義語として辞書にも並ぶ。"}, {"text": "責任", "is_correct": false, "explanation": "引き受けるべき務め。義務と似た語だが、対義語ではない。"}, {"text": "役割", "is_correct": false, "explanation": "立場に応じて担う働き。対義語ではない。"}, {"text": "負担", "is_correct": false, "explanation": "身に負うこと。対義語ではない。"}], "correct_answer": "権利", "explanations": {"権利": "義務と対になる語で、主張できる資格を表す。対義語として辞書にも並ぶ。", "責任": "引き受けるべき務め。義務と似た語だが、対義語ではない。", "役割": "立場に応じて担う働き。対義語ではない。", "負担": "身に負うこと。対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39025, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "法律や規則などで、必ずしなければならないと決められていること。", "primary_collocate": null, "pronunciation": "ぎむ", "ipa": "ɡimɯ", "syllable_count": 2, "sentences": [{"text": "法律で、車に乗る人はシートベルトをつける義務がある。", "target_word": "義務", "complexity_tier": "T3", "furigana": "法律[ほうりつ]で、車[くるま]に乗[の]る人[ひと]はシートベルトをつける義務[ぎむ]がある。", "sentence_source": "generated"}, {"text": "日本では、親は子どもに九年間の教育を受けさせる義務がある。", "target_word": "義務", "complexity_tier": "T3", "furigana": "日本[にほん]では、親[おや]は子[こ]どもに九年間[きゅうねんかん]の教育[きょういく]を受[う]けさせる義務[ぎむ]がある。", "sentence_source": "generated"}, {"text": "会社は、社員の健康診断を行う義務がある。", "target_word": "義務", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、社員[しゃいん]の健康診断[けんこうしんだん]を行[おこな]う義務[ぎむ]がある。", "sentence_source": "generated"}, {"text": "国民には、税金を納める義務がある。", "target_word": "義務", "complexity_tier": "T3", "furigana": "国民[こくみん]には、税金[ぜいきん]を納[おさ]める義務[ぎむ]がある。", "sentence_source": "generated"}, {"text": "事故を起こした人は、警察に知らせる義務がある。", "target_word": "義務", "complexity_tier": "T3", "furigana": "事故[じこ]を起[お]こした人[ひと]は、警察[けいさつ]に知[し]らせる義務[ぎむ]がある。", "sentence_source": "generated"}, {"text": "規則で、工場の作業員はヘルメットをかぶる義務がある。", "target_word": "義務", "complexity_tier": "T3", "furigana": "規則[きそく]で、工場[こうじょう]の作業員[さぎょういん]はヘルメットをかぶる義務[ぎむ]がある。", "sentence_source": "generated"}, {"text": "店は、食品に原材料を表示する義務がある。", "target_word": "義務", "complexity_tier": "T3", "furigana": "店[みせ]は、食品[しょくひん]に原材料[げんざいりょう]を表示[ひょうじ]する義務[ぎむ]がある。", "sentence_source": "generated"}, {"text": "法律で決められた義務を守らないと、罰金を払うことになる。", "target_word": "義務", "complexity_tier": "T3", "furigana": "法律[ほうりつ]で決[き]められた義務[ぎむ]を守[まも]らないと、罰金[ばっきん]を払[はら]うことになる。", "sentence_source": "generated"}, {"text": "選挙で投票するのは権利であって、義務ではない。", "target_word": "義務", "complexity_tier": "T3", "furigana": "選挙[せんきょ]で投票[とうひょう]するのは権利[けんり]であって、義務[ぎむ]ではない。", "sentence_source": "generated"}, {"text": "運転手には、お酒を飲んで運転しない義務がある。", "target_word": "義務", "complexity_tier": "T3", "furigana": "運転手[うんてんしゅ]には、お酒[さけ]を飲[の]んで運転[うんてん]しない義務[ぎむ]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "義務", "label": "基本形"}, {"form": "義務の", "label": "連体形"}, {"form": "義務だ", "label": "断定形"}], "register": "一般", "sense_fingerprint": "法律・規則で定められた、しなければならないこと（法的義務）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f54bc903-95d5-40b4-bd35-efc729115735') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39025, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "義務", "is_correct": true, "explanation": "法律で定められた、しなければならないことを表し、シートベルトをつける文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のこと。「シートベルトをつける天気がある」は意味が通らない。"}, {"text": "季節", "is_correct": false, "explanation": "一年の区分。法律の文脈とは合わず、文が成り立たない。"}, {"text": "愛情", "is_correct": false, "explanation": "気持ちを表す語。法律上の決まりを述べる空欄には入らない。"}], "explanations": {"義務": "法律で定められた、しなければならないことを表し、シートベルトをつける文に合う。", "天気": "空模様のこと。「シートベルトをつける天気がある」は意味が通らない。", "季節": "一年の区分。法律の文脈とは合わず、文が成り立たない。", "愛情": "気持ちを表す語。法律上の決まりを述べる空欄には入らない。"}, "sentence_index": 0, "correct_answer": "義務"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国民は、選挙で投票する義務を行使できる。", "explanation": "ここは〈権利〉の意味。義務は行使するものではなく、しなければならないことを表す。"}, {"text": "市から義務を得て、工事を始めた。", "explanation": "ここは〈許可〉の意味。義務は得るものではなく、課された務めを表すので、工事を始めることを認める文には合わない。"}, {"text": "社長は部下に義務を出した。", "explanation": "ここは〈指示〉の意味。義務は出すものではなく、課せられるものを表すので、部下へ仕事の内容を伝える文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39025, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "義務", "is_correct": true, "explanation": "法律で定められたしなければならないことを表し、表示を行う文に合う。"}, {"text": "旅行", "is_correct": false, "explanation": "出かけて楽しむこと。「表示する旅行がある」は意味が通らない。"}, {"text": "音楽", "is_correct": false, "explanation": "音の芸術。原材料の表示の文脈には合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "歩いて回ること。表示を行う文の空欄には入らない。"}], "explanations": {"義務": "法律で定められたしなければならないことを表し、表示を行う文に合う。", "旅行": "出かけて楽しむこと。「表示する旅行がある」は意味が通らない。", "音楽": "音の芸術。原材料の表示の文脈には合わない。", "散歩": "歩いて回ること。表示を行う文の空欄には入らない。"}, "sentence_index": 6, "correct_answer": "義務"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "違反者は義務を払うことになる。", "explanation": "ここは〈罰金〉の意味。義務は払うお金ではなく、しなければならないことを表す語で、支払う金額の文には合わない。"}, {"text": "書類の不備で、義務を取り下げた。", "explanation": "ここは〈申請〉の意味。義務は取り下げるものではなく、課された務めを表すので、提出した手続きを撤回する文には合わない。"}, {"text": "上司から事故の義務を受けた。", "explanation": "ここは〈報告〉の意味。義務は受け取るものではなく、課された務めを表すので、事故を知らせる内容には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39025, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日の運転は、速度を落とす義務をある。", "corrected_sentence": "雨の日の運転は、速度を落とす義務がある。", "error_description": "存在を表す『義務がある』の『が』が正しい。『義務をある』の『を』は誤りで、主語を示す『が』に直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39025, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事業者には、従業員の安全を守る義務のがある。", "corrected_sentence": "事業者には、従業員の安全を守る義務がある。", "error_description": "『義務』の直後に『の』は不要。存在を示す文型では『義務がある』となる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39026, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「分権」は「進む」の主語になるので、「が」が正しい。"}, {"text": "の", "is_correct": false, "explanation": "「分権の進めば」では名詞がつながるだけで、動詞の主語が立たず文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「分権と進めば」は相手や並列を示す「と」になり、文の意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すため、「分権より進めば」は主語を表せず不自然。"}], "correct_answer": "が", "explanations": {"が": "「分権」は「進む」の主語になるので、「が」が正しい。", "の": "「分権の進めば」では名詞がつながるだけで、動詞の主語が立たず文が成り立たない。", "と": "「分権と進めば」は相手や並列を示す「と」になり、文の意味が通らない。", "より": "「より」は比較を示すため、「分権より進めば」は主語を表せず不自然。"}, "error_tags": {"の": "連体の誤り", "と": "並列・相手の誤り", "より": "比較の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集権", "is_correct": true, "explanation": "権限を一か所に集める考え方を指し、この文の分権と対になる。"}, {"text": "分類", "is_correct": false, "explanation": "種類ごとに分ける意味で、分権の反対概念ではない。"}, {"text": "同調", "is_correct": false, "explanation": "周囲に合わせる意味で、制度の反対語にはならない。"}, {"text": "分岐", "is_correct": false, "explanation": "道や流れが分かれる意味で、分権の反対概念ではない。"}], "correct_answer": "集権", "explanations": {"集権": "権限を一か所に集める考え方を指し、この文の分権と対になる。", "分類": "種類ごとに分ける意味で、分権の反対概念ではない。", "同調": "周囲に合わせる意味で、制度の反対語にはならない。", "分岐": "道や流れが分かれる意味で、分権の反対概念ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39026, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「分権」は「進む」の主語になるので、「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「進んでいて」は自動詞なので、「分権を」と目的語を取ることはできない。"}, {"text": "から", "is_correct": false, "explanation": "「分権から進んでいて」は起点の「から」になり、主語の関係が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「分権の進んでいて」では名詞が続くだけで、動詞の主語が立たず文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「分権」は「進む」の主語になるので、「が」が正しい。", "を": "「進んでいて」は自動詞なので、「分権を」と目的語を取ることはできない。", "から": "「分権から進んでいて」は起点の「から」になり、主語の関係が成り立たない。", "の": "「分権の進んでいて」では名詞が続くだけで、動詞の主語が立たず文が成り立たない。"}, "error_tags": {"を": "目的語の誤り", "から": "起点の誤り", "の": "連体の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集権", "is_correct": true, "explanation": "権限を一か所に集める考え方で、仕事を分けて決める分権と対になる。"}, {"text": "集計", "is_correct": false, "explanation": "数を合わせる意味で、分権の反対概念ではない。"}, {"text": "養成", "is_correct": false, "explanation": "人を育てる意味で、分権の反対概念ではない。"}, {"text": "感謝", "is_correct": false, "explanation": "ありがたく思う気持ちを指し、分権の反対概念ではない。"}], "correct_answer": "集権", "explanations": {"集権": "権限を一か所に集める考え方で、仕事を分けて決める分権と対になる。", "集計": "数を合わせる意味で、分権の反対概念ではない。", "養成": "人を育てる意味で、分権の反対概念ではない。", "感謝": "ありがたく思う気持ちを指し、分権の反対概念ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39026, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国や組織の仕事を、上の人だけが決めるのではなく、いくつかのところに分けて、それぞれで決めること。", "primary_collocate": null, "pronunciation": "ぶんけん", "ipa": "bɯŋkeɴ", "syllable_count": 4, "sentences": [{"text": "国がすべて決めるのをやめて、分権を進める必要がある。", "target_word": "分権", "complexity_tier": "T3", "furigana": "国[くに]がすべて決[き]めるのをやめて、分権[ぶんけん]を進[すす]める必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "分権が進めば、町の問題は町の人が決められる。", "target_word": "分権", "complexity_tier": "T3", "furigana": "分権[ぶんけん]が進[すす]めば、町[まち]の問題[もんだい]は町[まち]の人[ひと]が決[き]められる。", "sentence_source": "generated"}, {"text": "会社でも、社長一人で決めず、各部署に決める力を渡す分権が大切だ。", "target_word": "分権", "complexity_tier": "T3", "furigana": "会社[かいしゃ]でも、社長[しゃちょう]一人[ひとり]で決[き]めず、各部署[かくぶしょ]に決[き]める力[ちから]を渡[わた]す分権[ぶんけん]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "分権の考え方では、現場に近い人が判断する。", "target_word": "分権", "complexity_tier": "T3", "furigana": "分権[ぶんけん]の考[かんが]え方[かた]では、現場[げんば]に近[ちか]い人[ひと]が判断[はんだん]する。", "sentence_source": "generated"}, {"text": "上の人がすべて決める組織は遅いので、分権を取り入れた。", "target_word": "分権", "complexity_tier": "T3", "furigana": "上[うえ]の人[ひと]がすべて決[き]める組織[そしき]は遅[おそ]いので、分権[ぶんけん]を取[と]り入[い]れた。", "sentence_source": "generated"}, {"text": "分権によって、学校ごとにやり方を決められるようになった。", "target_word": "分権", "complexity_tier": "T3", "furigana": "分権[ぶんけん]によって、学校[がっこう]ごとにやり方[かた]を決[き]められるようになった。", "sentence_source": "generated"}, {"text": "分権は、決める人が増えるので、話し合いに時間がかかることもある。", "target_word": "分権", "complexity_tier": "T3", "furigana": "分権[ぶんけん]は、決[き]める人[ひと]が増[ふ]えるので、話[はな]し合[あ]いに時間[じかん]がかかることもある。", "sentence_source": "generated"}, {"text": "この会社は分権が進んでいて、支店長が予算を決めている。", "target_word": "分権", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は分権[ぶんけん]が進[すす]んでいて、支店長[してんちょう]が予算[よさん]を決[き]めている。", "sentence_source": "generated"}, {"text": "一か所で決める体制をやめて、分権に切り替えた。", "target_word": "分権", "complexity_tier": "T3", "furigana": "一[いち]か所[しょ]で決[き]める体制[たいせい]をやめて、分権[ぶんけん]に切[き]り替[か]えた。", "sentence_source": "generated"}, {"text": "先生は、分権とは仕事を分けて決めることだと説明した。", "target_word": "分権", "complexity_tier": "T3", "furigana": "先生[せんせい]は、分権[ぶんけん]とは仕事[しごと]を分[わ]けて決[き]めることだと説明[せつめい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分権", "label": "基本形"}, {"form": "分権の", "label": "連体形"}], "register": "文章語", "sense_fingerprint": "組織の決定を上層だけでなく複数の部署・場所に分けて任せること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f54bc903-95d5-40b4-bd35-efc729115735') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39026, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分権", "is_correct": true, "explanation": "「国が決めるのをやめて」と対になる文脈で、「進める」の目的語として自然に入る。"}, {"text": "友情", "is_correct": false, "explanation": "「友情を進める必要がある」は意味をなさず、決定の仕組みの話にもならない。"}, {"text": "感想", "is_correct": false, "explanation": "感想は「進める」とは結びつかず、国の決め方の話に合わない。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は残る響きや気分を指し、「進める必要がある」とは合わない。"}], "explanations": {"分権": "「国が決めるのをやめて」と対になる文脈で、「進める」の目的語として自然に入る。", "友情": "「友情を進める必要がある」は意味をなさず、決定の仕組みの話にもならない。", "感想": "感想は「進める」とは結びつかず、国の決め方の話に合わない。", "余韻": "余韻は残る響きや気分を指し、「進める必要がある」とは合わない。"}, "sentence_index": 0, "correct_answer": "分権"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕事を三人で分権して、午後には終わらせた。", "explanation": "ここは〈分担〉の意味。分権は権限を複数の場所に分けて決める仕組みを指し、作業を分ける意味では使わない。"}, {"text": "荷物を三つの倉庫に分権して保管した。", "explanation": "ここは〈分散〉の意味。分権は決定の権限を分ける語で、物を各地に散らす意味では使えない。"}, {"text": "会社の方針は社長が決めるので、社長に分権が集まっている。", "explanation": "ここは〈権限〉の意味。分権は権限を分けて渡すことを表し、一人の人に集まる「もの」としては言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39026, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分権", "is_correct": true, "explanation": "決める人が増えて話し合いが長引く、という主題として文が成り立つ。"}, {"text": "共感", "is_correct": false, "explanation": "「共感は決める人が増えるので」では、主題として話の流れにつながらない。"}, {"text": "余裕", "is_correct": false, "explanation": "「余裕は、決める人が増える」は因果関係が成り立たず、話し合いの時間の話にならない。"}, {"text": "感傷", "is_correct": false, "explanation": "感傷は心の動きを指し、決める人の数と話し合いの時間の話には合わない。"}], "explanations": {"分権": "決める人が増えて話し合いが長引く、という主題として文が成り立つ。", "共感": "「共感は決める人が増えるので」では、主題として話の流れにつながらない。", "余裕": "「余裕は、決める人が増える」は因果関係が成り立たず、話し合いの時間の話にならない。", "感傷": "感傷は心の動きを指し、決める人の数と話し合いの時間の話には合わない。"}, "sentence_index": 6, "correct_answer": "分権"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "収穫した米を家族で公平に分権した。", "explanation": "ここは〈分配〉の意味。分権は権限を分ける語で、物を配る意味では使わない。"}, {"text": "古いパソコンを部品ごとに分権して、掃除した。", "explanation": "ここは〈分解〉の意味。分権は権限の分散を表し、機械を部品に解体する意味はない。"}, {"text": "アンケートの結果を年代別に分権した。", "explanation": "ここは〈分析〉の意味。分権は権限に関する語で、データを調べる意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39026, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校でも分権が進むれば、現場が判断できる。", "corrected_sentence": "学校でも分権が進めば、現場が判断できる。", "error_description": "「進む」の仮定形は「進めば」。「進むれば」は活用の誤りで、「分権が」に続く動詞の形が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39026, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府は分権を進むことにして、各地に仕事を任せた。", "corrected_sentence": "政府は分権を進めることにして、各地に仕事を任せた。", "error_description": "「分権」を目的語に取るのは他動詞「進める」。自動詞「進む」を使うと「分権を進む」となり不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39027, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「分権」を話題として取り上げ、その説明を述べる文なので、主題の「は」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「分権を、権限を一つに集めない考え方だ」では、分権が目的語になり説明の文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「分権に、権限を一つに集めない考え方だ」では、方向や対象の「に」になり文の意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「分権で、権限を一つに集めない考え方だ」では、手段の「で」になり説明の文にならない。"}], "correct_answer": "は", "explanations": {"は": "「分権」を話題として取り上げ、その説明を述べる文なので、主題の「は」が入る。", "を": "「分権を、権限を一つに集めない考え方だ」では、分権が目的語になり説明の文として成り立たない。", "に": "「分権に、権限を一つに集めない考え方だ」では、方向や対象の「に」になり文の意味が通らない。", "で": "「分権で、権限を一つに集めない考え方だ」では、手段の「で」になり説明の文にならない。"}, "error_tags": {"を": "目的語の誤り", "に": "対象・方向の誤り", "で": "手段の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "中央集権", "is_correct": true, "explanation": "国が権限を中央に集める考え方で、分権の対義語として辞書に並ぶ。"}, {"text": "分析", "is_correct": false, "explanation": "物事を細かく調べる意味で、分権の反対概念ではない。"}, {"text": "同意", "is_correct": false, "explanation": "考えが一致することで、制度の反対概念ではない。"}, {"text": "分担", "is_correct": false, "explanation": "仕事を分けて受け持つ意味で、権限の集中とは対になる語ではない。"}], "correct_answer": "中央集権", "explanations": {"中央集権": "国が権限を中央に集める考え方で、分権の対義語として辞書に並ぶ。", "分析": "物事を細かく調べる意味で、分権の反対概念ではない。", "同意": "考えが一致することで、制度の反対概念ではない。", "分担": "仕事を分けて受け持つ意味で、権限の集中とは対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39027, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「分権」は「進まない」の主語になるので、「が」が正しい。"}, {"text": "と", "is_correct": false, "explanation": "「分権と進まない理由」では相手や並列の「と」になり、文の関係が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「分権から進まない理由」は起点の「から」になり、理由の文として不自然。"}, {"text": "より", "is_correct": false, "explanation": "「分権より進まない理由」は比較の「より」になり、主語関係が通らない。"}], "correct_answer": "が", "explanations": {"が": "「分権」は「進まない」の主語になるので、「が」が正しい。", "と": "「分権と進まない理由」では相手や並列の「と」になり、文の関係が成り立たない。", "から": "「分権から進まない理由」は起点の「から」になり、理由の文として不自然。", "より": "「分権より進まない理由」は比較の「より」になり、主語関係が通らない。"}, "error_tags": {"と": "並列・相手の誤り", "から": "起点の誤り", "より": "比較の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "中央集権", "is_correct": true, "explanation": "国が権限を中央に集める考え方で、分権の対義語として辞書に並ぶ。"}, {"text": "献身", "is_correct": false, "explanation": "自分を捧げて尽くす意味で、制度の反対概念ではない。"}, {"text": "収穫", "is_correct": false, "explanation": "作物を取り入れる意味で、分権の反対概念ではない。"}, {"text": "養成", "is_correct": false, "explanation": "人を育てる意味で、分権の反対概念ではない。"}], "correct_answer": "中央集権", "explanations": {"中央集権": "国が権限を中央に集める考え方で、分権の対義語として辞書に並ぶ。", "献身": "自分を捧げて尽くす意味で、制度の反対概念ではない。", "収穫": "作物を取り入れる意味で、分権の反対概念ではない。", "養成": "人を育てる意味で、分権の反対概念ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39027, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "権限を複数の主体に分散させること。中央集権の対義語。", "primary_collocate": null, "pronunciation": "ぶんけん", "ipa": "bɯŋkeɴ", "syllable_count": 4, "sentences": [{"text": "中央集権ではなく、分権を目指す国が増えている。", "target_word": "分権", "complexity_tier": "T3", "furigana": "中央集権[ちゅうおうしゅうけん]ではなく、分権[ぶんけん]を目指[めざ]す国[くに]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "分権は、権限を一つに集めないという考え方だ。", "target_word": "分権", "complexity_tier": "T3", "furigana": "分権[ぶんけん]は、権限[けんげん]を一[ひと]つに集[あつ]めないという考[かんが]え方[かた]だ。", "sentence_source": "generated"}, {"text": "政府は、権限を自治体に渡す分権を進めると約束した。", "target_word": "分権", "complexity_tier": "T3", "furigana": "政府[せいふ]は、権限[けんげん]を自治体[じちたい]に渡[わた]す分権[ぶんけん]を進[すす]めると約束[やくそく]した。", "sentence_source": "generated"}, {"text": "分権が進むと、地域ごとに政策の違いが出てくる。", "target_word": "分権", "complexity_tier": "T3", "furigana": "分権[ぶんけん]が進[すす]むと、地域[ちいき]ごとに政策[せいさく]の違[ちが]いが出[で]てくる。", "sentence_source": "generated"}, {"text": "権限が一か所に集まると不正が起きやすいので、分権が求められる。", "target_word": "分権", "complexity_tier": "T3", "furigana": "権限[けんげん]が一[ひと]か所[しょ]に集[あつ]まると不正[ふせい]が起[お]きやすいので、分権[ぶんけん]が求[もと]められる。", "sentence_source": "generated"}, {"text": "分権を進めるには、お金を使う権限も地方に渡す必要がある。", "target_word": "分権", "complexity_tier": "T3", "furigana": "分権[ぶんけん]を進[すす]めるには、お金[かね]を使[つか]う権限[けんげん]も地方[ちほう]に渡[わた]す必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "分権の流れの中で、国から県へ多くの権限が移った。", "target_word": "分権", "complexity_tier": "T3", "furigana": "分権[ぶんけん]の流[なが]れの中[なか]で、国[くに]から県[けん]へ多[おお]くの権限[けんげん]が移[うつ]った。", "sentence_source": "generated"}, {"text": "分権が進まない理由は、国が権限を手放したがらないからだ。", "target_word": "分権", "complexity_tier": "T3", "furigana": "分権[ぶんけん]が進[すす]まない理由[りゆう]は、国[くに]が権限[けんげん]を手放[てばな]したがらないからだ。", "sentence_source": "generated"}, {"text": "集権と分権のどちらがよいかは、国によって意見が分かれる。", "target_word": "分権", "complexity_tier": "T3", "furigana": "集権[しゅうけん]と分権[ぶんけん]のどちらがよいかは、国[くに]によって意見[いけん]が分[わ]かれる。", "sentence_source": "generated"}, {"text": "分権の議論では、どの仕事を市に任せるかが問題になる。", "target_word": "分権", "complexity_tier": "T3", "furigana": "分権[ぶんけん]の議論[ぎろん]では、どの仕事[しごと]を市[し]に任[まか]せるかが問題[もんだい]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分権", "label": "基本形"}, {"form": "分権の", "label": "連体形"}], "register": "文章語", "sense_fingerprint": "国と自治体など複数の主体に権限を分散させる政治・行政上の考え方（集権の反対）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f54bc903-95d5-40b4-bd35-efc729115735') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39027, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分権", "is_correct": true, "explanation": "「中央集権ではなく」と対比して、目指す政策の方向として文が成り立つ。"}, {"text": "友情", "is_correct": false, "explanation": "「友情を目指す国」は政治の文脈に合わず、意味が通らない。"}, {"text": "感想", "is_correct": false, "explanation": "感想は人の受け止めを指し、国が目指す方向にはならない。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は残る響きや気分を指し、国が目指す方向として意味をなさない。"}], "explanations": {"分権": "「中央集権ではなく」と対比して、目指す政策の方向として文が成り立つ。", "友情": "「友情を目指す国」は政治の文脈に合わず、意味が通らない。", "感想": "感想は人の受け止めを指し、国が目指す方向にはならない。", "余韻": "余韻は残る響きや気分を指し、国が目指す方向として意味をなさない。"}, "sentence_index": 0, "correct_answer": "分権"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作業を班ごとに分権して、今日中に終わらせた。", "explanation": "ここは〈分業〉の意味。分権は権限を配る政治・行政の考え方で、作業の役割を分ける意味では使わない。"}, {"text": "避難所を三か所に分権した。", "explanation": "ここは〈分散〉の意味。分権は権限を複数の主体に分けることで、場所を散らす意味では使えない。"}, {"text": "強い分権を持つ人が一人で決めると、不満が出やすい。", "explanation": "ここは〈権力〉の意味。分権は権限を複数の主体に分けることで、ひとりが持つ力を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39027, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分権", "is_correct": true, "explanation": "国から県へ権限が移った流れを指し、「の流れの中で」と自然につながる。"}, {"text": "共感", "is_correct": false, "explanation": "「共感の流れの中で」は意味が通らず、権限の移動の話とつながらない。"}, {"text": "感傷", "is_correct": false, "explanation": "感傷は心の動きを指し、権限が国から県へ移った流れとは合わない。"}, {"text": "余裕", "is_correct": false, "explanation": "「余裕の流れ」は不自然で、権限が移った話の時間的な流れを表せない。"}], "explanations": {"分権": "国から県へ権限が移った流れを指し、「の流れの中で」と自然につながる。", "共感": "「共感の流れの中で」は意味が通らず、権限の移動の話とつながらない。", "感傷": "感傷は心の動きを指し、権限が国から県へ移った流れとは合わない。", "余裕": "「余裕の流れ」は不自然で、権限が移った話の時間的な流れを表せない。"}, "sentence_index": 6, "correct_answer": "分権"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本を種類ごとに分権して、棚に並べた。", "explanation": "ここは〈分類〉の意味。分権は権限を配る政治・行政の考え方で、物を種類に分ける意味では使わない。"}, {"text": "卵の白身と黄身を分権して、料理に使った。", "explanation": "ここは〈分離〉の意味。分権は権限の分散を表し、物を別々に分ける意味では使えない。"}, {"text": "収穫した野菜を村の家々に分権した。", "explanation": "ここは〈分配〉の意味。分権は権限を分けて渡す考え方で、物を配る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39027, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府は、分権に進めるため、各省の権限を見直した。", "corrected_sentence": "政府は、分権を進めるため、各省の権限を見直した。", "error_description": "「分権」に続く助詞が誤り。「進める」は目的語を取る他動詞なので、「に」ではなく「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39027, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府は分権を進めるないと決めて、議論を打ち切った。", "corrected_sentence": "政府は分権を進めないと決めて、議論を打ち切った。", "error_description": "「進める」の否定形は「進めない」。「進めるない」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
