INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39028, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「隠す」は目的語を取る他動詞なので、隠すものとして「実情を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「実情が社員に隠さず」では隠す対象が文に立たず、主語としても話の流れに合わない。"}, {"text": "と", "is_correct": false, "explanation": "「実情と社員に隠さず」は相手を示す「と」になり、隠す対象として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「実情から社員に隠さず」は起点の「から」になり、隠す対象の文として不自然。"}], "correct_answer": "を", "explanations": {"を": "「隠す」は目的語を取る他動詞なので、隠すものとして「実情を」が入る。", "が": "「実情が社員に隠さず」では隠す対象が文に立たず、主語としても話の流れに合わない。", "と": "「実情と社員に隠さず」は相手を示す「と」になり、隠す対象として成り立たない。", "から": "「実情から社員に隠さず」は起点の「から」になり、隠す対象の文として不自然。"}, "error_tags": {"が": "主語の誤り", "と": "相手・並列の誤り", "から": "起点の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39028, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "そのときの本当の様子や状態のこと。", "primary_collocate": null, "pronunciation": "じつじょう", "ipa": "dʑitsɯdʑoː", "syllable_count": 4, "sentences": [{"text": "新聞記者が現地に行って、被害の実情を調べた。", "target_word": "実情", "complexity_tier": "T3", "furigana": "新聞記者[しんぶんきしゃ]が現地[げんち]に行[い]って、被害[ひがい]の実情[じつじょう]を調[しら]べた。", "sentence_source": "generated"}, {"text": "表では元気そうだが、実情はかなり苦しいらしい。", "target_word": "実情", "complexity_tier": "T3", "furigana": "表[おもて]では元気[げんき]そうだが、実情[じつじょう]はかなり苦[くる]しいらしい。", "sentence_source": "generated"}, {"text": "実情を知らない人が、勝手なことを言う。", "target_word": "実情", "complexity_tier": "T3", "furigana": "実情[じつじょう]を知[し]らない人[ひと]が、勝手[かって]なことを言[い]う。", "sentence_source": "generated"}, {"text": "町の実情を見てもらうために、市長を案内した。", "target_word": "実情", "complexity_tier": "T3", "furigana": "町[まち]の実情[じつじょう]を見[み]てもらうために、市長[しちょう]を案内[あんない]した。", "sentence_source": "generated"}, {"text": "数字だけでは、店の実情は分からない。", "target_word": "実情", "complexity_tier": "T3", "furigana": "数字[すうじ]だけでは、店[みせ]の実情[じつじょう]は分[わ]からない。", "sentence_source": "generated"}, {"text": "病院の実情を伝える番組を見て、驚いた。", "target_word": "実情", "complexity_tier": "T3", "furigana": "病院[びょういん]の実情[じつじょう]を伝[つた]える番組[ばんぐみ]を見[み]て、驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "実情が分かると、彼が怒った理由も理解できた。", "target_word": "実情", "complexity_tier": "T3", "furigana": "実情[じつじょう]が分[わ]かると、彼[かれ]が怒[おこ]った理由[りゆう]も理解[りかい]できた。", "sentence_source": "generated"}, {"text": "社長は、会社の実情を社員に隠さず話した。", "target_word": "実情", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は、会社[かいしゃ]の実情[じつじょう]を社員[しゃいん]に隠[かく]さず話[はな]した。", "sentence_source": "generated"}, {"text": "留学生の生活の実情を、アンケートで調べている。", "target_word": "実情", "complexity_tier": "T3", "furigana": "留学生[りゅうがくせい]の生活[せいかつ]の実情[じつじょう]を、アンケートで調[しら]べている。", "sentence_source": "generated"}, {"text": "計画は立派だが、現場の実情に合っていない。", "target_word": "実情", "complexity_tier": "T3", "furigana": "計画[けいかく]は立派[りっぱ]だが、現場[げんば]の実情[じつじょう]に合[あ]っていない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実情", "label": "基本形"}, {"form": "実情の", "label": "連体形"}], "register": "一般", "sense_fingerprint": "見た目や建前の裏にある、ありのままの本当の様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f54bc903-95d5-40b4-bd35-efc729115735') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39028, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実情", "is_correct": true, "explanation": "「被害の」に続けると、被害の実際の様子を調べるという意味で自然に入る。"}, {"text": "寛容", "is_correct": false, "explanation": "「被害の寛容を調べた」は意味をなさず、被害の様子の話にならない。"}, {"text": "友情", "is_correct": false, "explanation": "「被害の友情」は成り立たず、被害の状況を調べる文に合わない。"}, {"text": "感傷", "is_correct": false, "explanation": "感傷は心の動きを指し、被害を調べるという行為の対象にはならない。"}], "explanations": {"実情": "「被害の」に続けると、被害の実際の様子を調べるという意味で自然に入る。", "寛容": "「被害の寛容を調べた」は意味をなさず、被害の様子の話にならない。", "友情": "「被害の友情」は成り立たず、被害の状況を調べる文に合わない。", "感傷": "感傷は心の動きを指し、被害を調べるという行為の対象にはならない。"}, "sentence_index": 0, "correct_answer": "実情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その話は実情で、記録にも残っている。", "explanation": "ここは〈事実〉の意味。実情は物事の状態を指し、話が本当かどうかを述べる文では使わない。"}, {"text": "展示会で実情の機械を動かして見せた。", "explanation": "ここは〈実物〉の意味。実情は状況を指す語で、機械そのものを表せない。"}, {"text": "町で大きな実情が起きて、警察が出動した。", "explanation": "ここは〈事件〉の意味。起きるのは出来事であって、実情は起きる対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39028, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実情", "is_correct": true, "explanation": "「が分かると」と続けると、実際の様子が分かれば理由も理解できる、という意味になる。"}, {"text": "余韻", "is_correct": false, "explanation": "「余韻が分かると」は意味が通らず、彼が怒った理由の理解とつながらない。"}, {"text": "謙遜", "is_correct": false, "explanation": "「謙遜が分かると」では、怒った理由の理解との関係が成り立たない。"}, {"text": "礼儀", "is_correct": false, "explanation": "「礼儀が分かると」は話の流れに合わず、怒った理由の理解とつながらない。"}], "explanations": {"実情": "「が分かると」と続けると、実際の様子が分かれば理由も理解できる、という意味になる。", "余韻": "「余韻が分かると」は意味が通らず、彼が怒った理由の理解とつながらない。", "謙遜": "「謙遜が分かると」では、怒った理由の理解との関係が成り立たない。", "礼儀": "「礼儀が分かると」は話の流れに合わず、怒った理由の理解とつながらない。"}, "sentence_index": 6, "correct_answer": "実情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "理科の実情で、水を一度沸騰させた。", "explanation": "ここは〈実験〉の意味。手順を試す行為を表す語で、状況を指す実情は使えない。"}, {"text": "週末は実情に帰って、母の料理を食べた。", "explanation": "ここは〈実家〉の意味。帰る場所を表す語で、状況の意味の実情では帰る先にならない。"}, {"text": "その選手は大会で実情を積んで、代表に選ばれた。", "explanation": "ここは〈実績〉の意味。積み重ねる成果を表す語で、状況を指す実情は積めない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39028, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その制度は町の実情を合わせて作られた。", "corrected_sentence": "その制度は町の実情に合わせて作られた。", "error_description": "「実情」に続く助詞が誤り。「合わせる」は「に」を取るので、「を」ではなく「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39028, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "実情を知るないと、適切な対応はできない。", "corrected_sentence": "実情を知らないと、適切な対応はできない。", "error_description": "「知る」の否定形は「知らない」。「知るない」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39029, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「考える」の対象として「学校ごとの実情を」と目的語になり、文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「実情が考えて」では主語として「考える」が成り立たず、文の意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「実情に考えて」は対象の「に」が合わず、文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「実情と考えて」は相手や並列の「と」になり、考える対象として不自然。"}], "correct_answer": "を", "explanations": {"を": "「考える」の対象として「学校ごとの実情を」と目的語になり、文が成り立つ。", "が": "「実情が考えて」では主語として「考える」が成り立たず、文の意味が通らない。", "に": "「実情に考えて」は対象の「に」が合わず、文として成り立たない。", "と": "「実情と考えて」は相手や並列の「と」になり、考える対象として不自然。"}, "error_tags": {"が": "主語の誤り", "に": "対象の誤り", "と": "並列・相手の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39029, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「無視した」の対象として「実情を」と目的語になり、文が成り立つ。"}, {"text": "で", "is_correct": false, "explanation": "「実情で無視した話」は手段・場所の「で」になり、無視する対象の文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「実情から無視した話」は起点の「から」になり、無視の対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「実情より無視した話」は比較の「より」になり、無視の対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「無視した」の対象として「実情を」と目的語になり、文が成り立つ。", "で": "「実情で無視した話」は手段・場所の「で」になり、無視する対象の文として成り立たない。", "から": "「実情から無視した話」は起点の「から」になり、無視の対象を表せない。", "より": "「実情より無視した話」は比較の「より」になり、無視の対象を表せない。"}, "error_tags": {"で": "手段・場所の誤り", "から": "起点の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39029, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実際の状況や事情。", "primary_collocate": null, "pronunciation": "じつじょう", "ipa": "dʑitsɯdʑoː", "syllable_count": 4, "sentences": [{"text": "家庭の実情に合わせて、支払いの方法を決めた。", "target_word": "実情", "complexity_tier": "T3", "furigana": "家庭[かてい]の実情[じつじょう]に合[あ]わせて、支払[しはら]いの方法[ほうほう]を決[き]めた。", "sentence_source": "generated"}, {"text": "学校ごとの実情を考えて、授業の進め方を変える。", "target_word": "実情", "complexity_tier": "T3", "furigana": "学校[がっこう]ごとの実情[じつじょう]を考[かんが]えて、授業[じゅぎょう]の進[すす]め方[かた]を変[か]える。", "sentence_source": "generated"}, {"text": "地域の実情を見ずに作ったルールは、使いにくい。", "target_word": "実情", "complexity_tier": "T3", "furigana": "地域[ちいき]の実情[じつじょう]を見[み]ずに作[つく]ったルールは、使[つか]いにくい。", "sentence_source": "generated"}, {"text": "農家の実情を聞いてから、助けるやり方を考えた。", "target_word": "実情", "complexity_tier": "T3", "furigana": "農家[のうか]の実情[じつじょう]を聞[き]いてから、助[たす]けるやり方[かた]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "実情に合った制度にするため、何度も話し合った。", "target_word": "実情", "complexity_tier": "T3", "furigana": "実情[じつじょう]に合[あ]った制度[せいど]にするため、何度[なんど]も話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "日本語学校の実情は、学校によって大きく違う。", "target_word": "実情", "complexity_tier": "T3", "furigana": "日本語学校[にほんごがっこう]の実情[じつじょう]は、学校[がっこう]によって大[おお]きく違[ちが]う。", "sentence_source": "generated"}, {"text": "会社の実情を考えると、給料を上げるのは難しい。", "target_word": "実情", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の実情[じつじょう]を考[かんが]えると、給料[きゅうりょう]を上[あ]げるのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "理想は分かるが、実情を無視した話では意味がない。", "target_word": "実情", "complexity_tier": "T3", "furigana": "理想[りそう]は分[わ]かるが、実情[じつじょう]を無視[むし]した話[はなし]では意味[いみ]がない。", "sentence_source": "generated"}, {"text": "山の村の実情を知れば、バスが少ない理由も分かる。", "target_word": "実情", "complexity_tier": "T3", "furigana": "山[やま]の村[むら]の実情[じつじょう]を知[し]れば、バスが少[すく]ない理由[りゆう]も分[わ]かる。", "sentence_source": "generated"}, {"text": "役所は、住民の実情をもとに予算を決めた。", "target_word": "実情", "complexity_tier": "T3", "furigana": "役所[やくしょ]は、住民[じゅうみん]の実情[じつじょう]をもとに予算[よさん]を決[き]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実情", "label": "基本形"}, {"form": "実情の", "label": "連体形"}], "register": "一般", "sense_fingerprint": "制度や判断が考慮すべき、その場所・立場の実際の事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f54bc903-95d5-40b4-bd35-efc729115735') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39029, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実情", "is_correct": true, "explanation": "「家庭の」に続けると、家庭の実際の事情に合わせるという意味で自然に入る。"}, {"text": "友情", "is_correct": false, "explanation": "「家庭の友情に合わせて」は意味をなさず、支払いの方法を決める文に合わない。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は残る響きや気分を指し、支払いの方法を決める基準にはならない。"}, {"text": "謙遜", "is_correct": false, "explanation": "「謙遜に合わせて」では支払いの方法を決める基準として成り立たない。"}], "explanations": {"実情": "「家庭の」に続けると、家庭の実際の事情に合わせるという意味で自然に入る。", "友情": "「家庭の友情に合わせて」は意味をなさず、支払いの方法を決める文に合わない。", "余韻": "余韻は残る響きや気分を指し、支払いの方法を決める基準にはならない。", "謙遜": "「謙遜に合わせて」では支払いの方法を決める基準として成り立たない。"}, "sentence_index": 0, "correct_answer": "実情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が実情で、試合が中止になった。", "explanation": "ここは〈原因〉の意味。結果を生んだ元を表す語で、状況を指す実情は原因の位置に入らない。"}, {"text": "彼女は実情が高く、大会で優勝した。", "explanation": "ここは〈実力〉の意味。「実力が高い」のように能力の大きさを表す語で、状況を指す実情は「高い」とは結び付かない。"}, {"text": "実情の体育館で大会が開かれた。", "explanation": "ここは〈会場〉の意味。実情は場所を表せず、「実情の体育館」は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39029, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実情", "is_correct": true, "explanation": "「会社の」に続けると、会社の実際の事情を考えるという意味で自然に入る。"}, {"text": "感傷", "is_correct": false, "explanation": "「会社の感傷を考えると」は意味が通らず、給料の話の根拠にならない。"}, {"text": "共感", "is_correct": false, "explanation": "「会社の共感を考える」は成り立たず、給料を上げられるかの判断につながらない。"}, {"text": "歓声", "is_correct": false, "explanation": "歓声は場の声を指し、給料を上げられるかを考える対象にはならない。"}], "explanations": {"実情": "「会社の」に続けると、会社の実際の事情を考えるという意味で自然に入る。", "感傷": "「会社の感傷を考えると」は意味が通らず、給料の話の根拠にならない。", "共感": "「会社の共感を考える」は成り立たず、給料を上げられるかの判断につながらない。", "歓声": "歓声は場の声を指し、給料を上げられるかを考える対象にはならない。"}, "sentence_index": 6, "correct_answer": "実情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "舞台の実情を書き直して、稽古を始めた。", "explanation": "ここは〈台本〉の意味。書き直すのは台本であって、状況を指す実情は書き直せない。"}, {"text": "毎朝、実情を量っている。", "explanation": "ここは〈体重〉の意味。量る対象は体重で、状況を指す実情は量れない。"}, {"text": "わからない単語を実情で調べた。", "explanation": "ここは〈辞書〉の意味。調べる道具を表す語で、状況を指す実情は道具にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39029, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の実情を考て、補助金の使い道を決めた。", "corrected_sentence": "町の実情を考えて、補助金の使い道を決めた。", "error_description": "「考える」の活用の誤り。「考て」は「考えて」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39029, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "実情を考れば、取り組みは別の形になった。", "corrected_sentence": "実情を考えれば、取り組みは別の形になった。", "error_description": "「考える」の仮定形は「考えれば」。「考れば」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
