INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39032, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一つのことのいいところとわるいところの両方を言いたいときに使うことば。", "primary_collocate": null, "pronunciation": "はんめん", "ipa": "hammeɴ", "syllable_count": 4, "sentences": [{"text": "このアパートは駅に近くて便利な反面、夜は少しうるさい。", "target_word": "反面", "complexity_tier": "T3", "furigana": "このアパートは駅[えき]に近[ちか]くて便利[べんり]な反面[はんめん]、夜[よる]は少[すこ]しうるさい。", "sentence_source": "generated"}, {"text": "一人暮らしは自由な反面、さびしいこともある。", "target_word": "反面", "complexity_tier": "T3", "furigana": "一人暮[ひとりぐ]らしは自由[じゆう]な反面[はんめん]、さびしいこともある。", "sentence_source": "generated"}, {"text": "スマホは便利な反面、使いすぎると目が疲れる。", "target_word": "反面", "complexity_tier": "T3", "furigana": "スマホは便利[べんり]な反面[はんめん]、使[つか]いすぎると目[め]が疲[つか]れる。", "sentence_source": "generated"}, {"text": "彼は仕事ができる反面、時間にだらしない。", "target_word": "反面", "complexity_tier": "T3", "furigana": "彼[かれ]は仕事[しごと]ができる反面[はんめん]、時間[じかん]にだらしない。", "sentence_source": "generated"}, {"text": "田舎は空気がきれいな反面、買い物が不便だ。", "target_word": "反面", "complexity_tier": "T3", "furigana": "田舎[いなか]は空気[くうき]がきれいな反面[はんめん]、買[か]い物[もの]が不便[ふべん]だ。", "sentence_source": "generated"}, {"text": "この薬はよく効く反面、眠くなりやすい。", "target_word": "反面", "complexity_tier": "T3", "furigana": "この薬[くすり]はよく効[き]く反面[はんめん]、眠[ねむ]くなりやすい。", "sentence_source": "generated"}, {"text": "電気自動車は静かな反面、値段が高い。", "target_word": "反面", "complexity_tier": "T3", "furigana": "電気自動車[でんきじどうしゃ]は静[しず]かな反面[はんめん]、値段[ねだん]が高[たか]い。", "sentence_source": "generated"}, {"text": "姉は優しい反面、怒るととても怖い。", "target_word": "反面", "complexity_tier": "T3", "furigana": "姉[あね]は優[やさ]しい反面[はんめん]、怒[おこ]るととても怖[こわ]い。", "sentence_source": "generated"}, {"text": "大きな家は広くて楽な反面、そうじが大変だ。", "target_word": "反面", "complexity_tier": "T3", "furigana": "大[おお]きな家[いえ]は広[ひろ]くて楽[らく]な反面[はんめん]、そうじが大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "都会は仕事が多い反面、家賃が高い。", "target_word": "反面", "complexity_tier": "T3", "furigana": "都会[とかい]は仕事[しごと]が多[おお]い反面[はんめん]、家賃[やちん]が高[たか]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "反面", "label": "基本形"}], "register": "一般", "sense_fingerprint": "一つの事柄の長所と短所を対比する「Aである反面、B」の形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f54bc903-95d5-40b4-bd35-efc729115735') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39032, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反面", "is_correct": true, "explanation": "「〜な反面、〜」で同じ対象の長所と短所を並べる語。「便利な反面、夜はうるさい」と自然につながる。"}, {"text": "騒音", "is_correct": false, "explanation": "うるさい音を表す名詞。「便利な騒音」とは言えず、空欄に入らない。"}, {"text": "家賃", "is_correct": false, "explanation": "部屋を借りる代金を表す名詞。「便利な家賃」という形容は成り立たず、文の流れに合わない。"}, {"text": "大家", "is_correct": false, "explanation": "家の持ち主を指す名詞。「便利な大家」では長所と短所の対比にならない。"}], "explanations": {"反面": "「〜な反面、〜」で同じ対象の長所と短所を並べる語。「便利な反面、夜はうるさい」と自然につながる。", "騒音": "うるさい音を表す名詞。「便利な騒音」とは言えず、空欄に入らない。", "家賃": "部屋を借りる代金を表す名詞。「便利な家賃」という形容は成り立たず、文の流れに合わない。", "大家": "家の持ち主を指す名詞。「便利な大家」では長所と短所の対比にならない。"}, "sentence_index": 0, "correct_answer": "反面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は朝ごはんを食べ、反面、本も読んでいた。", "explanation": "ここは〈同時に〉の意味（二つの動作を並行して行う）。反面は同じ対象の良い面と悪い面を対比する語なので、並行する動作を並べる文には合わない。"}, {"text": "兄は東京へ行った。反面、弟は家に残った。", "explanation": "ここは〈一方〉の意味。反面は同じ対象の長所と短所を対比する語なので、別々の人の行動を並べるのには使えない。"}, {"text": "弱音を吐いたら、反面、チームは強くなった。", "explanation": "ここは〈逆に〉の意味（予想と反対の結果）。反面は同じ事柄の良い面と悪い面を示す語なので、結果の逆転を表す文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39032, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反面", "is_correct": true, "explanation": "「〜な反面、〜」で同じ対象の長所と短所を並べる語。「静かな反面、値段が高い」と自然につながる。"}, {"text": "充電", "is_correct": false, "explanation": "電気をためる作業を表す名詞。「静かな充電」では長所と短所の対比にならない。"}, {"text": "修理", "is_correct": false, "explanation": "壊れたものを直す作業を表す名詞。「静かな修理」は文の意味が通らない。"}, {"text": "故障", "is_correct": false, "explanation": "機械が壊れることを表す名詞。「静かな故障」は成り立たず、空欄に入らない。"}], "explanations": {"反面": "「〜な反面、〜」で同じ対象の長所と短所を並べる語。「静かな反面、値段が高い」と自然につながる。", "充電": "電気をためる作業を表す名詞。「静かな充電」では長所と短所の対比にならない。", "修理": "壊れたものを直す作業を表す名詞。「静かな修理」は文の意味が通らない。", "故障": "機械が壊れることを表す名詞。「静かな故障」は成り立たず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "反面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は果物が好きだ。反面、特にりんごが好きだ。", "explanation": "ここは〈特に〉の意味（数ある中の一つを取り立てる）。反面は良い面と悪い面を対比する語なので、好きなものを取り立てる文には合わない。"}, {"text": "昨日は夜更かしをした。反面、そのため、朝ごはんを抜いた。", "explanation": "ここは〈その結果〉の意味（原因から結果を導く）。反面は同じ対象の良い面と悪い面を対比する語なので、原因と結果を結ぶ文には合わない。"}, {"text": "雨が降っている。反面、風も強い。", "explanation": "ここは〈さらに〉の意味（情報を加える）。反面は対立する二つの面を示す語なので、単に情報を足す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39032, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は便利な反面に、値段が高い。", "corrected_sentence": "この店は便利な反面、値段が高い。", "error_description": "「反面」に格助詞「に」は付けない。接続詞として「反面、」と読点で続けるのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39032, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この部屋は広い反面で、駅から遠い。", "corrected_sentence": "この部屋は広い反面、駅から遠い。", "error_description": "「反面」に格助詞「で」は付かない。「広い反面、」と読点で続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
