INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39033, 3, 'prompt1_core', '{"pos": "接続詞", "semantic_class": "function", "definition": "ある事柄の肯定的な面と否定的な面を同時に示す接続詞的な用法。前に述べた特徴に対し、別の側面があることを表す。", "primary_collocate": null, "pronunciation": "はんめん", "ipa": "hammeɴ", "syllable_count": 4, "sentences": [{"text": "このアプリは使いやすい。その反面、広告が多い。", "target_word": "反面", "complexity_tier": "T3", "furigana": "このアプリは使[つか]いやすい。その反面[はんめん]、広告[こうこく]が多[おお]い。", "sentence_source": "generated"}, {"text": "新しい職場は給料が高い。反面、休みが少ない。", "target_word": "反面", "complexity_tier": "T3", "furigana": "新[あたら]しい職場[しょくば]は給料[きゅうりょう]が高[たか]い。反面[はんめん]、休[やす]みが少[すく]ない。", "sentence_source": "generated"}, {"text": "彼は人気がある。その反面、敵も多い。", "target_word": "反面", "complexity_tier": "T3", "furigana": "彼[かれ]は人気[にんき]がある。その反面[はんめん]、敵[てき]も多[おお]い。", "sentence_source": "generated"}, {"text": "海外旅行は楽しい。その反面、お金がかかる。", "target_word": "反面", "complexity_tier": "T3", "furigana": "海外旅行[かいがいりょこう]は楽[たの]しい。その反面[はんめん]、お金[かね]がかかる。", "sentence_source": "generated"}, {"text": "母は厳しかった。その反面、いつも私の味方だった。", "target_word": "反面", "complexity_tier": "T3", "furigana": "母[はは]は厳[きび]しかった。その反面[はんめん]、いつも私[わたし]の味方[みかた]だった。", "sentence_source": "generated"}, {"text": "この町は静かだ。反面、夜に開いている店が少ない。", "target_word": "反面", "complexity_tier": "T3", "furigana": "この町[まち]は静[しず]かだ。反面[はんめん]、夜[よる]に開[あ]いている店[みせ]が少[すく]ない。", "sentence_source": "generated"}, {"text": "機械は作業を速くする。その反面、人の仕事を減らしている。", "target_word": "反面", "complexity_tier": "T3", "furigana": "機械[きかい]は作業[さぎょう]を速[はや]くする。その反面[はんめん]、人[ひと]の仕事[しごと]を減[へ]らしている。", "sentence_source": "generated"}, {"text": "犬を飼うと毎日楽しい。その反面、世話は大変だ。", "target_word": "反面", "complexity_tier": "T3", "furigana": "犬[いぬ]を飼[か]うと毎日[まいにち]楽[たの]しい。その反面[はんめん]、世話[せわ]は大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "彼女は明るい人だ。その反面、実は一人でいるのが好きだ。", "target_word": "反面", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は明[あか]るい人[ひと]だ。その反面[はんめん]、実[じつ]は一人[ひとり]でいるのが好[す]きだ。", "sentence_source": "generated"}, {"text": "この方法は簡単だ。その反面、あまり正確ではない。", "target_word": "反面", "complexity_tier": "T3", "furigana": "この方法[ほうほう]は簡単[かんたん]だ。その反面[はんめん]、あまり正確[せいかく]ではない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "反面", "label": "基本形"}, {"form": "その反面", "label": "連語形"}], "register": "一般", "sense_fingerprint": "文頭で「（その）反面、」と前の特徴に対する別の側面を述べる接続的用法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f54bc903-95d5-40b4-bd35-efc729115735') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39033, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反面", "is_correct": true, "explanation": "文頭の接続詞として、前の「使いやすい」に対する別の側面「広告が多い」を続ける。"}, {"text": "例えば", "is_correct": false, "explanation": "例を挙げる語。前の特徴に対する別の側面を述べる文脈ではないので合わない。"}, {"text": "なぜなら", "is_correct": false, "explanation": "理由を示す語。前文の良い点に対して別の面を続ける場面には合わない。"}, {"text": "だから", "is_correct": false, "explanation": "原因と結果を示す語。「使いやすい」から「広告が多い」とは続かず、文の流れに合わない。"}], "explanations": {"反面": "文頭の接続詞として、前の「使いやすい」に対する別の側面「広告が多い」を続ける。", "例えば": "例を挙げる語。前の特徴に対する別の側面を述べる文脈ではないので合わない。", "なぜなら": "理由を示す語。前文の良い点に対して別の面を続ける場面には合わない。", "だから": "原因と結果を示す語。「使いやすい」から「広告が多い」とは続かず、文の流れに合わない。"}, "sentence_index": 0, "correct_answer": "反面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は歌いながら、反面、ギターも弾いていた。", "explanation": "ここは〈同時に〉の意味（二つの動作を並行して行う）。反面は良い面と悪い面を対比する語なので、並行する動作を並べる文には合わない。"}, {"text": "父は会社へ行った。反面、母は家にいた。", "explanation": "ここは〈一方〉の意味。反面は同じ対象の肯定的な面と否定的な面を示すので、別々の人の行動を並べる文には使えない。"}, {"text": "このアプリは無料で使える。反面、機能も多い。", "explanation": "ここは〈さらに〉の意味。反面は肯定的な面と否定的な面の対比に使うので、どちらも良い内容を並べる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39033, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反面", "is_correct": true, "explanation": "文頭の接続詞として、前の「速くする」に対する別の面「仕事を減らしている」を続ける。"}, {"text": "ところで", "is_correct": false, "explanation": "話題を変える語。前の「速くする」の話を受けて別の話題に移る文脈ではないので、文が合わない。"}, {"text": "つまり", "is_correct": false, "explanation": "言い換えを表す語。良い面と悪い面を対比する文には合わない。"}, {"text": "ちなみに", "is_correct": false, "explanation": "補足を添える語。前文の良い面に対して悪い面を対比する文脈には合わないので不適。"}], "explanations": {"反面": "文頭の接続詞として、前の「速くする」に対する別の面「仕事を減らしている」を続ける。", "ところで": "話題を変える語。前の「速くする」の話を受けて別の話題に移る文脈ではないので、文が合わない。", "つまり": "言い換えを表す語。良い面と悪い面を対比する文には合わない。", "ちなみに": "補足を添える語。前文の良い面に対して悪い面を対比する文脈には合わないので不適。"}, "sentence_index": 6, "correct_answer": "反面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が強く降った。反面、川が増水した。", "explanation": "ここは〈その結果〉の意味（原因から結果を導く）。反面は良い面と悪い面を対比する語なので、原因と結果を結ぶ文には合わない。"}, {"text": "私は動物が好きだ。反面、例えば犬を飼っている。", "explanation": "ここは〈例えば〉の意味（具体例を挙げる）。反面は対比の語なので、具体例を導く文には合わない。"}, {"text": "名前を呼ばれた。反面、すぐに返事をした。", "explanation": "ここは〈すぐに〉の意味（間を置かず続けて）。反面は良い面と悪い面を対比する語なので、続けて行う動作を並べる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39033, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このカメラは軽い。その反面に、画質が粗い。", "corrected_sentence": "このカメラは軽い。その反面、画質が粗い。", "error_description": "接続詞「反面」に格助詞「に」は付けない。文頭で「その反面、」と読点で続けるのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39033, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この薬は安い。その反面の、効果は低い。", "corrected_sentence": "この薬は安い。その反面、効果は低い。", "error_description": "接続詞「反面」に「の」を付けるのは誤り。文頭の接続詞として「その反面、」と続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39034, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表す。「全国と二百の支店がある」では所在が示せず、不自然。"}, {"text": "に", "is_correct": true, "explanation": "「に」は存在する場所を表す。「全国に二百の支店がある」で、支店のある範囲を示す。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を表す。「全国より二百の支店がある」では比べる文脈がなく、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表す。「全国から二百の支店がある」では出どころになり、所在の意味にならない。"}], "correct_answer": "に", "explanations": {"と": "「と」は並列や相手を表す。「全国と二百の支店がある」では所在が示せず、不自然。", "に": "「に」は存在する場所を表す。「全国に二百の支店がある」で、支店のある範囲を示す。", "より": "「より」は比較の基準を表す。「全国より二百の支店がある」では比べる文脈がなく、文が成り立たない。", "から": "「から」は起点を表す。「全国から二百の支店がある」では出どころになり、所在の意味にならない。"}, "error_tags": {"と": "並列・相手", "より": "比較", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39034, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "が", "is_correct": false, "explanation": "「が」は主語を表す。「全国が回っている」では全国が動く主体になり、仕事で巡る意味に合わない。"}, {"text": "を", "is_correct": true, "explanation": "「を」は動作の対象を表す。「回る」は全国を巡る動作の対象を取るので、正しい。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を表す。「全国の回っている」では文の骨組みが成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表す。「全国で回っている」では回る範囲を示せず、不自然。"}], "correct_answer": "を", "explanations": {"が": "「が」は主語を表す。「全国が回っている」では全国が動く主体になり、仕事で巡る意味に合わない。", "を": "「を」は動作の対象を表す。「回る」は全国を巡る動作の対象を取るので、正しい。", "の": "「の」は所属や修飾を表す。「全国の回っている」では文の骨組みが成り立たない。", "で": "「で」は場所や手段を表す。「全国で回っている」では回る範囲を示せず、不自然。"}, "error_tags": {"が": "主語", "の": "修飾", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39034, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国全体のこと。", "primary_collocate": null, "pronunciation": "ぜんこく", "ipa": "dzeŋkokɯ", "syllable_count": 4, "sentences": [{"text": "明日は全国で晴れるそうだ。", "target_word": "全国", "complexity_tier": "T3", "furigana": "明日[あした]は全国[ぜんこく]で晴[は]れるそうだ。", "sentence_source": "generated"}, {"text": "この店は全国に二百の支店がある。", "target_word": "全国", "complexity_tier": "T3", "furigana": "この店[みせ]は全国[ぜんこく]に二百[にひゃく]の支店[してん]がある。", "sentence_source": "generated"}, {"text": "彼の名前は全国に知られている。", "target_word": "全国", "complexity_tier": "T3", "furigana": "彼[かれ]の名前[なまえ]は全国[ぜんこく]に知[し]られている。", "sentence_source": "generated"}, {"text": "全国の学生が、この試験を受ける。", "target_word": "全国", "complexity_tier": "T3", "furigana": "全国[ぜんこく]の学生[がくせい]が、この試験[しけん]を受[う]ける。", "sentence_source": "generated"}, {"text": "新しい商品は、全国のコンビニで買える。", "target_word": "全国", "complexity_tier": "T3", "furigana": "新[あたら]しい商品[しょうひん]は、全国[ぜんこく]のコンビニで買[か]える。", "sentence_source": "generated"}, {"text": "このニュースは全国に放送された。", "target_word": "全国", "complexity_tier": "T3", "furigana": "このニュースは全国[ぜんこく]に放送[ほうそう]された。", "sentence_source": "generated"}, {"text": "全国から集まった人々で、駅は大変込んでいた。", "target_word": "全国", "complexity_tier": "T3", "furigana": "全国[ぜんこく]から集[あつ]まった人々[ひとびと]で、駅[えき]は大変[たいへん]込[こ]んでいた。", "sentence_source": "generated"}, {"text": "私は仕事で全国を回っている。", "target_word": "全国", "complexity_tier": "T3", "furigana": "私[わたし]は仕事[しごと]で全国[ぜんこく]を回[まわ]っている。", "sentence_source": "generated"}, {"text": "祖母は全国のお茶を飲み比べるのが好きだ。", "target_word": "全国", "complexity_tier": "T3", "furigana": "祖母[そぼ]は全国[ぜんこく]のお茶[ちゃ]を飲[の]み比[くら]べるのが好[す]きだ。", "sentence_source": "generated"}, {"text": "全国どこでも、この薬は同じ値段で買える。", "target_word": "全国", "complexity_tier": "T3", "furigana": "全国[ぜんこく]どこでも、この薬[くすり]は同[おな]じ値段[ねだん]で買[か]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "全国", "label": "基本形"}, {"form": "全国の", "label": "連体修飾形"}, {"form": "全国で", "label": "場所を表す形"}], "register": "中立", "sense_fingerprint": "一つの国のどこでも、国じゅう", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b805d309-ed0d-4afe-a0c9-16e05b3d5c5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39034, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全身", "is_correct": false, "explanation": "「全身」は体全体の意味。明日の天気の範囲には使えず、「全身で晴れる」は不自然。"}, {"text": "全力", "is_correct": false, "explanation": "「全力」は力を尽くす意味。場所の範囲を示さないので、天気の文には入らない。"}, {"text": "全国", "is_correct": true, "explanation": "「全国」は国全体の意味。明日の晴れる地域の範囲として自然に入る。"}, {"text": "全部", "is_correct": false, "explanation": "「全部」は残らずの意味で、場所の範囲には使わない。「全部で晴れる」は意味が通らない。"}], "explanations": {"全身": "「全身」は体全体の意味。明日の天気の範囲には使えず、「全身で晴れる」は不自然。", "全力": "「全力」は力を尽くす意味。場所の範囲を示さないので、天気の文には入らない。", "全国": "「全国」は国全体の意味。明日の晴れる地域の範囲として自然に入る。", "全部": "「全部」は残らずの意味で、場所の範囲には使わない。「全部で晴れる」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "全国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "アメリカでは、この法律が全国で施行された。", "explanation": "ここは〈全米〉（アメリカ全土）の意味。「全国」は日本国内を指すので、外国の範囲には使えない。"}, {"text": "大雨で県の全国に避難指示が出た。", "explanation": "ここは〈全域〉（一定の区域全体）の意味。「全国」は国全体を指すので、県という区域の範囲には合わない。"}, {"text": "敵軍は、その島の全国を占領した。", "explanation": "ここは〈全土〉（土地全体）の意味。「全国」は国全体を指すので、島の土地の範囲には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39034, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全盛", "is_correct": false, "explanation": "「全盛」は勢いが最も盛んな時期の意味。人の出身の広がりを示せず、「全盛から集まった」は不自然。"}, {"text": "全景", "is_correct": false, "explanation": "「全景」は全体の眺めの意味。人々の出身地を示す語ではないので入らない。"}, {"text": "全国", "is_correct": true, "explanation": "「全国」は国全体の意味。ここでは集まった人々の出身の広がりを示し、「から」と合う。"}, {"text": "全快", "is_correct": false, "explanation": "「全快」は病気などが完全に治る意味。人が集まる範囲には使えない。"}], "explanations": {"全盛": "「全盛」は勢いが最も盛んな時期の意味。人の出身の広がりを示せず、「全盛から集まった」は不自然。", "全景": "「全景」は全体の眺めの意味。人々の出身地を示す語ではないので入らない。", "全国": "「全国」は国全体の意味。ここでは集まった人々の出身の広がりを示し、「から」と合う。", "全快": "「全快」は病気などが完全に治る意味。人が集まる範囲には使えない。"}, "sentence_index": 6, "correct_answer": "全国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この百貨店の全国で改装工事が行われた。", "explanation": "ここは〈全館〉（建物全体）の意味。「全国」は国全体を指すので、一つの店の建物の範囲には使えない。"}, {"text": "会議の全国が賛成した。", "explanation": "ここは〈全員〉（一人残らず）の意味。「全国」は国の範囲で、会議の参加者という人の集まりには使えない。"}, {"text": "この大会には全国から九十の国が参加した。", "explanation": "ここは〈世界各国〉の意味。「全国」は日本国内の範囲なので、多くの国が参加する国際的な場には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39034, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週は全国を晴れるそうだ。", "corrected_sentence": "来週は全国で晴れるそうだ。", "error_description": "誤りは「を」。正しくは「で」。「晴れる」は天気が現れる場所を「で」で示すので、対象を表す「を」は使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39034, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この事件は全国な話題になった。", "corrected_sentence": "この事件は全国的な話題になった。", "error_description": "誤りは「全国な」。正しくは「全国的な」。「全国」は名詞なので、名詞を修飾するには「的な」を付ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39035, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を表す。「全国を学校で守られる」では名詞の並びが成り立たず、文がくずれる。"}, {"text": "の", "is_correct": true, "explanation": "「の」は範囲を示す連体の助詞。「全国の学校」で、学校が全国のどの範囲かを示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は受け身の動作主を表す。「全国に学校で守られる」では全国が守る主体とは読めず、不自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表す。「全国が学校で守られる」では全国が守る主体になり、意味が合わない。"}], "correct_answer": "の", "explanations": {"を": "「を」は動作の対象を表す。「全国を学校で守られる」では名詞の並びが成り立たず、文がくずれる。", "の": "「の」は範囲を示す連体の助詞。「全国の学校」で、学校が全国のどの範囲かを示す。", "に": "「に」は受け身の動作主を表す。「全国に学校で守られる」では全国が守る主体とは読めず、不自然。", "が": "「が」は主語を表す。「全国が学校で守られる」では全国が守る主体になり、意味が合わない。"}, "error_tags": {"を": "対象", "に": "動作主", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39035, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39035, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国全体。国の中のすべての地域や人々に関わること。", "primary_collocate": null, "pronunciation": "ぜんこく", "ipa": "dzeŋkokɯ", "syllable_count": 4, "sentences": [{"text": "大雨の被害は全国に広がっている。", "target_word": "全国", "complexity_tier": "T3", "furigana": "大雨[おおあめ]の被害[ひがい]は全国[ぜんこく]に広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "新しい法律は、全国の学校で守られる。", "target_word": "全国", "complexity_tier": "T3", "furigana": "新[あたら]しい法律[ほうりつ]は、全国[ぜんこく]の学校[がっこう]で守[まも]られる。", "sentence_source": "generated"}, {"text": "全国の人が、その試合をテレビで見ていた。", "target_word": "全国", "complexity_tier": "T3", "furigana": "全国[ぜんこく]の人[ひと]が、その試合[しあい]をテレビで見[み]ていた。", "sentence_source": "generated"}, {"text": "事故の話は、全国に伝わった。", "target_word": "全国", "complexity_tier": "T3", "furigana": "事故[じこ]の話[はなし]は、全国[ぜんこく]に伝[つた]わった。", "sentence_source": "generated"}, {"text": "全国で同じ問題が起きているので、国が調べ始めた。", "target_word": "全国", "complexity_tier": "T3", "furigana": "全国[ぜんこく]で同[おな]じ問題[もんだい]が起[お]きているので、国[くに]が調[しら]べ始[はじ]めた。", "sentence_source": "generated"}, {"text": "選挙の結果は、全国の注目を集めた。", "target_word": "全国", "complexity_tier": "T3", "furigana": "選挙[せんきょ]の結果[けっか]は、全国[ぜんこく]の注目[ちゅうもく]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "全国で働く看護師の数が足りない。", "target_word": "全国", "complexity_tier": "T3", "furigana": "全国[ぜんこく]で働[はたら]く看護師[かんごし]の数[かず]が足[た]りない。", "sentence_source": "generated"}, {"text": "この制度は全国どの町でも利用できる。", "target_word": "全国", "complexity_tier": "T3", "furigana": "この制度[せいど]は全国[ぜんこく]どの町[まち]でも利用[りよう]できる。", "sentence_source": "generated"}, {"text": "全国に住む人々の意見を聞くために、調査を行った。", "target_word": "全国", "complexity_tier": "T3", "furigana": "全国[ぜんこく]に住[す]む人々[ひとびと]の意見[いけん]を聞[き]くために、調査[ちょうさ]を行[おこな]った。", "sentence_source": "generated"}, {"text": "台風は全国の交通に影響を与えた。", "target_word": "全国", "complexity_tier": "T3", "furigana": "台風[たいふう]は全国[ぜんこく]の交通[こうつう]に影響[えいきょう]を与[あた]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "全国", "label": "基本形"}, {"form": "全国の", "label": "連体修飾形"}, {"form": "全国に", "label": "範囲を表す形"}], "register": "中立", "sense_fingerprint": "国のすべての地域や人々に関わる範囲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b805d309-ed0d-4afe-a0c9-16e05b3d5c5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39035, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全景", "is_correct": false, "explanation": "「全景」は全体の眺めの意味。被害の広がる範囲を示せず、「全景に広がる」は不自然。"}, {"text": "全力", "is_correct": false, "explanation": "「全力」は力を尽くす意味。被害の広がりを表さず、文に合わない。"}, {"text": "全国", "is_correct": true, "explanation": "「全国」は国全体の意味。被害が国じゅうに広がるという範囲を示すので正しい。"}, {"text": "全快", "is_correct": false, "explanation": "「全快」は病気が完全に治ること。被害の広がりには使えない。"}], "explanations": {"全景": "「全景」は全体の眺めの意味。被害の広がる範囲を示せず、「全景に広がる」は不自然。", "全力": "「全力」は力を尽くす意味。被害の広がりを表さず、文に合わない。", "全国": "「全国」は国全体の意味。被害が国じゅうに広がるという範囲を示すので正しい。", "全快": "「全快」は病気が完全に治ること。被害の広がりには使えない。"}, "sentence_index": 0, "correct_answer": "全国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事故の話は、うちの学校の全国に伝わった。", "explanation": "ここは〈全校〉（学校全体）の意味。「全国」は国全体を指すので、一つの学校の範囲には使えない。"}, {"text": "事故の話は、イギリスの全国に伝わった。", "explanation": "ここは〈全土〉（国土全体）の意味。「全国」は日本国内を指すので、イギリスには使えない。"}, {"text": "事故の話は、この町の全国に伝わった。", "explanation": "ここは〈全町〉（町全体）の意味。「全国」は国全体を指すので、町の範囲には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39035, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全盛", "is_correct": false, "explanation": "「全盛」は勢いが最も盛んな時期の意味。働く場所を示せず、「全盛で働く」は合わない。"}, {"text": "全速", "is_correct": false, "explanation": "「全速」は全力の速さの意味。働く範囲を表さないので文に入らない。"}, {"text": "全壊", "is_correct": false, "explanation": "「全壊」は建物などが完全にこわれること。働く場所には使えない。"}, {"text": "全国", "is_correct": true, "explanation": "「全国」は国全体の意味。看護師の不足が国じゅうの範囲で起きているという意味になり、文に合う。"}], "explanations": {"全盛": "「全盛」は勢いが最も盛んな時期の意味。働く場所を示せず、「全盛で働く」は合わない。", "全速": "「全速」は全力の速さの意味。働く範囲を表さないので文に入らない。", "全壊": "「全壊」は建物などが完全にこわれること。働く場所には使えない。", "全国": "「全国」は国全体の意味。看護師の不足が国じゅうの範囲で起きているという意味になり、文に合う。"}, "sentence_index": 6, "correct_answer": "全国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台風は、この島の全国の交通に影響を与えた。", "explanation": "ここは〈全島〉（島全体）の意味。「全国」は国全体を指すので、一つの島の範囲には使えない。"}, {"text": "台風は、この会社の全国の業務に影響を与えた。", "explanation": "ここは〈全社〉（会社全体）の意味。「全国」は国の範囲で、一つの会社の範囲には当てはまらない。"}, {"text": "台風は、一日の全国の交通に影響を与えた。", "explanation": "ここは〈全日〉（一日中）の意味。「全国」は場所の範囲を表すので、時間の範囲には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39035, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この歌は全国を知られている。", "corrected_sentence": "この歌は全国に知られている。", "error_description": "誤りは「を」。正しくは「に」。「知られている」は「〜に知られている」の形で、知る人の範囲を「に」で示すので、「を」は使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39035, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この噂は全国に広げた。", "corrected_sentence": "この噂は全国に広がった。", "error_description": "誤りは「広げた」。正しくは「広がった」。噂は自然に広まるものなので、他動詞の「広げる」ではなく自動詞の「広がる」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39037, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39037, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「整合へ取れた」では向かう先が立たず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表す。「整合から取れた」では起点にならず、「取れる」と結びつかない。"}, {"text": "が", "is_correct": true, "explanation": "「が」は主語を表す。「整合が取れた」で、整合という状態が成り立つことを示す。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表す。「整合で取れた」では手段として不自然で、組織の状態を表せない。"}], "correct_answer": "が", "explanations": {"へ": "「へ」は方向を表す。「整合へ取れた」では向かう先が立たず、文が成り立たない。", "から": "「から」は起点を表す。「整合から取れた」では起点にならず、「取れる」と結びつかない。", "が": "「が」は主語を表す。「整合が取れた」で、整合という状態が成り立つことを示す。", "で": "「で」は手段や場所を表す。「整合で取れた」では手段として不自然で、組織の状態を表せない。"}, "error_tags": {"へ": "方向", "から": "起点", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39037, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の要素や部分が、矛盾なく一つの全体としてまとまっていること。また、その状態。", "primary_collocate": null, "pronunciation": "せいごう", "ipa": "seːɡoː", "syllable_count": 4, "sentences": [{"text": "各章の内容が整合するように、報告書全体を見直した。", "target_word": "整合", "complexity_tier": "T3", "furigana": "各章[かくしょう]の内容[ないよう]が整合[せいごう]するように、報告書[ほうこくしょ]全体[ぜんたい]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "彼の話は前後が整合していて、矛盾がない。", "target_word": "整合", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は前後[ぜんご]が整合[せいごう]していて、矛盾[むじゅん]がない。", "sentence_source": "generated"}, {"text": "法律と規則の整合を取らないと、現場が混乱する。", "target_word": "整合", "complexity_tier": "T3", "furigana": "法律[ほうりつ]と規則[きそく]の整合[せいごう]を取[と]らないと、現場[げんば]が混乱[こんらん]する。", "sentence_source": "generated"}, {"text": "システムの各部分が整合して動くことが大切だ。", "target_word": "整合", "complexity_tier": "T3", "furigana": "システムの各部分[かくぶぶん]が整合[せいごう]して動[うご]くことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "理論と実験の結果が整合したので、研究者は安心した。", "target_word": "整合", "complexity_tier": "T3", "furigana": "理論[りろん]と実験[じっけん]の結果[けっか]が整合[せいごう]したので、研究者[けんきゅうしゃ]は安心[あんしん]した。", "sentence_source": "generated"}, {"text": "計画の目標と予算が整合しないので、会議で問題になった。", "target_word": "整合", "complexity_tier": "T3", "furigana": "計画[けいかく]の目標[もくひょう]と予算[よさん]が整合[せいごう]しないので、会議[かいぎ]で問題[もんだい]になった。", "sentence_source": "generated"}, {"text": "物語の設定が整合していないと、読者は混乱する。", "target_word": "整合", "complexity_tier": "T3", "furigana": "物語[ものがたり]の設定[せってい]が整合[せいごう]していないと、読者[どくしゃ]は混乱[こんらん]する。", "sentence_source": "generated"}, {"text": "部門どうしの整合が取れた組織は、動きが速い。", "target_word": "整合", "complexity_tier": "T3", "furigana": "部門[ぶもん]どうしの整合[せいごう]が取[と]れた組織[そしき]は、動[うご]きが速[はや]い。", "sentence_source": "generated"}, {"text": "過去の記録と整合する形で、新しい報告を書いた。", "target_word": "整合", "complexity_tier": "T3", "furigana": "過去[かこ]の記録[きろく]と整合[せいごう]する形[かたち]で、新[あたら]しい報告[ほうこく]を書[か]いた。", "sentence_source": "generated"}, {"text": "内装は色と形が整合するように、全体のデザインを決めた。", "target_word": "整合", "complexity_tier": "T3", "furigana": "内装[ないそう]は色[いろ]と形[かたち]が整合[せいごう]するように、全体[ぜんたい]のデザインを決めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "整合する", "label": "終止形"}, {"form": "整合した", "label": "過去形"}, {"form": "整合しない", "label": "否定形"}, {"form": "整合が取れる", "label": "慣用的な形"}], "register": "硬い", "sense_fingerprint": "複数の部分が矛盾なく一つの全体にまとまること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b805d309-ed0d-4afe-a0c9-16e05b3d5c5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39037, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "散歩", "is_correct": false, "explanation": "「散歩」は気軽に歩くこと。内容どうしの関係を表さず、文が成り立たない。"}, {"text": "冷却", "is_correct": false, "explanation": "「冷却」は冷やすこと。内容どうしの関係には使えない。"}, {"text": "整合", "is_correct": true, "explanation": "「整合」は矛盾なく一つにまとまること。各章の内容が矛盾なく合うように見直す、という意味に合う。"}, {"text": "運動", "is_correct": false, "explanation": "「運動」は体を動かすこと。内容の一致を表せないので入らない。"}], "explanations": {"散歩": "「散歩」は気軽に歩くこと。内容どうしの関係を表さず、文が成り立たない。", "冷却": "「冷却」は冷やすこと。内容どうしの関係には使えない。", "整合": "「整合」は矛盾なく一つにまとまること。各章の内容が矛盾なく合うように見直す、という意味に合う。", "運動": "「運動」は体を動かすこと。内容の一致を表せないので入らない。"}, "sentence_index": 0, "correct_answer": "整合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会場の椅子を整合して並べた。", "explanation": "ここは〈整列〉（きちんと並べること）の意味。「整合」は矛盾なく合うことで、椅子を並べる動作には使わない。"}, {"text": "隊長が部隊を整合して動かした。", "explanation": "ここは〈統率〉（まとめて指揮すること）の意味。「整合」はものどうしが矛盾なく合うことで、人を指揮する意味にはならない。"}, {"text": "土地を整合した。", "explanation": "ここは〈整地〉（土地をならすこと）の意味。「整合」は矛盾なく合うことで、土地をならす意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39037, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投票", "is_correct": false, "explanation": "「投票」は選挙などで票を入れること。設定の関係を表せず、文に合わない。"}, {"text": "発熱", "is_correct": false, "explanation": "「発熱」は体温が上がること。物語の設定には当てはまらない。"}, {"text": "整合", "is_correct": true, "explanation": "「整合」は設定どうしが矛盾なく合うこと。設定が食い違わないと読者が混乱しない、という意味になる。"}, {"text": "睡眠", "is_correct": false, "explanation": "「睡眠」は眠ること。物語の設定には使えない。"}], "explanations": {"投票": "「投票」は選挙などで票を入れること。設定の関係を表せず、文に合わない。", "発熱": "「発熱」は体温が上がること。物語の設定には当てはまらない。", "整合": "「整合」は設定どうしが矛盾なく合うこと。設定が食い違わないと読者が混乱しない、という意味になる。", "睡眠": "「睡眠」は眠ること。物語の設定には使えない。"}, "sentence_index": 6, "correct_answer": "整合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は顔を整合する手術を受けた。", "explanation": "ここは〈整形〉（形を整えること）の意味。「整合」は物事が矛盾なく合うことで、体の形を変える意味にはならない。"}, {"text": "屋根を整合した。", "explanation": "ここは〈修繕〉（壊れた所を直すこと）の意味。「整合」は食い違いがないことで、壊れた物を直す意味には使わない。"}, {"text": "商品を整合して並べた。", "explanation": "ここは〈陳列〉（商品を並べて見せること）の意味。「整合」は矛盾なく合うことで、商品を見せるために並べる意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39037, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人事と財務の整合の取る作業が続いている。", "corrected_sentence": "人事と財務の整合を取る作業が続いている。", "error_description": "誤りは「の」。正しくは「を」。「取る」は「整合を取る」の形で対象を「を」で示すので、「整合の取る」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39037, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "報告書の数字は、前の調査結果を整合していた。", "corrected_sentence": "報告書の数字は、前の調査結果と整合していた。", "error_description": "誤りは「を」。正しくは「と」。「整合する」は「〜と整合する」の形で相手を「と」で示し、「を」は使えないので、「結果を整合していた」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39038, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「まとまりを欠く」の目的語を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "方向・帰着を示す「に」。「まとまりに欠く」は目的語を取れず誤り。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を示す「で」。目的語の位置には入らない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「まとまりが欠いて」では動詞との関係が合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「まとまりを欠く」の目的語を示す「を」。", "に": "方向・帰着を示す「に」。「まとまりに欠く」は目的語を取れず誤り。", "で": "場所・手段を示す「で」。目的語の位置には入らない。", "が": "主語を示す「が」。「まとまりが欠いて」では動詞との関係が合わない。"}, "error_tags": {"に": "方向・帰着", "で": "場所・手段", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39038, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「思いやりを欠く」の目的語を示す「を」。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手を示す「と」。「思いやりと欠いている」は目的語を取れず誤り。"}, {"text": "から", "is_correct": false, "explanation": "起点・理由を示す「から」。「思いやりから欠いている」は文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「思いやりの欠いている」は目的語にならず不自然。"}], "correct_answer": "を", "explanations": {"を": "正解。「思いやりを欠く」の目的語を示す「を」。", "と": "並列・相手を示す「と」。「思いやりと欠いている」は目的語を取れず誤り。", "から": "起点・理由を示す「から」。「思いやりから欠いている」は文が成り立たない。", "の": "連体修飾の「の」。「思いやりの欠いている」は目的語にならず不自然。"}, "error_tags": {"と": "並列・相手", "から": "起点・理由", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39038, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かが足りなくて、完全でないこと。", "primary_collocate": null, "pronunciation": "かく", "ipa": "kakɯ", "syllable_count": 2, "sentences": [{"text": "彼の話は、具体的な説明を欠いている。", "target_word": "欠いている", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は、具体的[ぐたいてき]な説明[せつめい]を欠[か]いている。", "sentence_source": "generated"}, {"text": "この作文は、まとまりを欠いていて読みにくい。", "target_word": "欠いて", "complexity_tier": "T3", "furigana": "この作文[さくぶん]は、まとまりを欠[か]いていて読[よ]みにくい。", "sentence_source": "generated"}, {"text": "彼女は注意を欠いた運転をして、事故を起こした。", "target_word": "欠いた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は注意[ちゅうい]を欠[か]いた運転[うんてん]をして、事故[じこ]を起[お]こした。", "sentence_source": "generated"}, {"text": "礼儀を欠く行動は、相手を不快にさせる。", "target_word": "欠く", "complexity_tier": "T3", "furigana": "礼儀[れいぎ]を欠[か]く行動[こうどう]は、相手[あいて]を不快[ふかい]にさせる。", "sentence_source": "generated"}, {"text": "会議は集中力を欠き、結論が出なかった。", "target_word": "欠き", "complexity_tier": "T3", "furigana": "会議[かいぎ]は集中力[しゅうちゅうりょく]を欠[か]き、結論[けつろん]が出[で]なかった。", "sentence_source": "generated"}, {"text": "彼の意見は現実味を欠いているので、誰も賛成しなかった。", "target_word": "欠いている", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]は現実味[げんじつみ]を欠[か]いているので、誰[だれ]も賛成[さんせい]しなかった。", "sentence_source": "generated"}, {"text": "計画は具体性を欠いたまま、実行された。", "target_word": "欠いた", "complexity_tier": "T3", "furigana": "計画[けいかく]は具体性[ぐたいせい]を欠[か]いたまま、実行[じっこう]された。", "sentence_source": "generated"}, {"text": "彼の文章は、読む人への思いやりを欠いている。", "target_word": "欠いている", "complexity_tier": "T3", "furigana": "彼[かれ]の文章[ぶんしょう]は、読[よ]む人[ひと]への思[おも]いやりを欠[か]いている。", "sentence_source": "generated"}, {"text": "統一感を欠く部屋は、落ち着かない。", "target_word": "欠く", "complexity_tier": "T3", "furigana": "統一感[とういつかん]を欠[か]く部屋[へや]は、落[お]ち着[つ]かない。", "sentence_source": "generated"}, {"text": "協調性を欠いた態度は、仲間に嫌われる。", "target_word": "欠いた", "complexity_tier": "T3", "furigana": "協調性[きょうちょうせい]を欠[か]いた態度[たいど]は、仲間[なかま]に嫌[きら]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "欠く", "label": "終止形"}, {"form": "欠いて", "label": "て形"}, {"form": "欠いた", "label": "過去形"}, {"form": "欠かない", "label": "否定形"}], "register": "やや硬い", "sense_fingerprint": "あるべき要素が足りず、完全な状態でない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b805d309-ed0d-4afe-a0c9-16e05b3d5c5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39038, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欠いている", "is_correct": true, "explanation": "正解。「説明を欠く」は必要な説明が足りないという意味で、この文に合う。"}, {"text": "通っている", "is_correct": false, "explanation": "「説明が通る」は主語が説明になる自動詞で、「説明を」の後には入らない。"}, {"text": "降りている", "is_correct": false, "explanation": "「説明を降りる」は成り立たない。「降りる」は乗り物や立場から離れる意味。"}, {"text": "乗っている", "is_correct": false, "explanation": "「説明に乗る」は話に応じる意味で「に」を取るため、「説明を」の文には入らない。"}], "explanations": {"欠いている": "正解。「説明を欠く」は必要な説明が足りないという意味で、この文に合う。", "通っている": "「説明が通る」は主語が説明になる自動詞で、「説明を」の後には入らない。", "降りている": "「説明を降りる」は成り立たない。「降りる」は乗り物や立場から離れる意味。", "乗っている": "「説明に乗る」は話に応じる意味で「に」を取るため、「説明を」の文には入らない。"}, "sentence_index": 0, "correct_answer": "欠いている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大事な財布を欠いて、途方に暮れた。", "explanation": "ここは〈失う〉の意味。欠くは要素や条件が足りないことを表し、持ち物をなくすことには使わない。"}, {"text": "学校を欠いて、一日中寝ていた。", "explanation": "ここは〈休む〉（学校に行かない）の意味。欠くは要素や条件が足りないことを表すので、登校しないことには使わない。"}, {"text": "ミスを欠いて、そのまま提出してしまった。", "explanation": "ここは〈見落とす〉（気づかず見過ごす）の意味。欠くは不足を表すので、ミスに気づかないことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39038, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欠いた", "is_correct": true, "explanation": "正解。「具体性を欠いたまま」の過去形で、「まま」に続く。"}, {"text": "欠いて", "is_correct": false, "explanation": "て形。「欠いてまま」は「まま」に続かず誤り。"}, {"text": "欠けた", "is_correct": false, "explanation": "別語の「欠ける」。「具体性が欠けた」なら「が」を取り、「具体性を」の文には合わない。"}, {"text": "欠いたり", "is_correct": false, "explanation": "列挙の形。「欠いたりまま」は「まま」に接続せず誤り。"}], "explanations": {"欠いた": "正解。「具体性を欠いたまま」の過去形で、「まま」に続く。", "欠いて": "て形。「欠いてまま」は「まま」に続かず誤り。", "欠けた": "別語の「欠ける」。「具体性が欠けた」なら「が」を取り、「具体性を」の文には合わない。", "欠いたり": "列挙の形。「欠いたりまま」は「まま」に接続せず誤り。"}, "sentence_index": 6, "correct_answer": "欠いた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "バスを欠いて、遅刻した。", "explanation": "ここは〈乗り遅れる〉（乗り物に間に合わない）の意味。欠くは不足を表すので、乗り物に乗れないことには使わない。"}, {"text": "古いノートを欠いて、もう使わないことにした。", "explanation": "ここは〈捨てる〉の意味。欠くは不足を言う語で、物を処分する意味では使わない。"}, {"text": "本を欠いて、先生に叱られた。", "explanation": "ここは〈読む〉（文字を追う）の意味。欠くは不足を表す語で、本を読む行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39038, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その作業は手順を欠いてまま進められた。", "corrected_sentence": "その作業は手順を欠いたまま進められた。", "error_description": "「まま」の前には過去の「欠いた」が入る。「欠いてまま」は「て形」が「まま」に続かないので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "欠いて", "is_correct": true, "explanation": "正解。「読みにくい」へ続けるための「て形」で、「欠いて、読みにくい」となる。"}, {"text": "欠く", "is_correct": false, "explanation": "終止形。文が切れてしまい、「読みにくい」へ続けられない。"}, {"text": "欠いた", "is_correct": false, "explanation": "過去形。「欠いた読みにくい」は接続が不自然で、「て」の続きに合わない。"}, {"text": "欠いている", "is_correct": false, "explanation": "ている形。「欠いている読みにくい」は「ている」の後に続けられず誤り。"}], "correct_form": "欠いて", "base_form": "欠く", "form_label": "て形", "sentence_index": 1, "explanations": {"欠いて": "正解。「読みにくい」へ続けるための「て形」で、「欠いて、読みにくい」となる。", "欠く": "終止形。文が切れてしまい、「読みにくい」へ続けられない。", "欠いた": "過去形。「欠いた読みにくい」は接続が不自然で、「て」の続きに合わない。", "欠いている": "ている形。「欠いている読みにくい」は「ている」の後に続けられず誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39038, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は必要な知識に欠いたまま、試験に挑んだ。", "corrected_sentence": "彼は必要な知識を欠いたまま、試験に挑んだ。", "error_description": "「欠く」は他動詞で目的語に「を」を取る。「知識に」は助詞の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "欠いている", "is_correct": true, "explanation": "正解。「思いやりを欠いている」の状態を表す「ている形」。"}, {"text": "欠け", "is_correct": false, "explanation": "命令形。文を言い切れず、「思いやりを欠け。」は成り立たない。"}, {"text": "欠き", "is_correct": false, "explanation": "連用形。文末の述語として終えられず、ここでは文が成り立たない。"}, {"text": "欠いて", "is_correct": false, "explanation": "て形。文末で終えられず、「思いやりを欠いて。」は成り立たない。"}], "correct_form": "欠いている", "base_form": "欠く", "form_label": "ている形", "sentence_index": 7, "explanations": {"欠いている": "正解。「思いやりを欠いている」の状態を表す「ている形」。", "欠け": "命令形。文を言い切れず、「思いやりを欠け。」は成り立たない。", "欠き": "連用形。文末の述語として終えられず、ここでは文が成り立たない。", "欠いて": "て形。文末で終えられず、「思いやりを欠いて。」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39039, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「資格を欠く」の目的語を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「資格が欠く人」では他動詞の目的語の関係が成り立たず誤り。"}, {"text": "に", "is_correct": false, "explanation": "方向・帰着を示す「に」。目的語の位置には入らない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を示す「で」。ここでは「欠く」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「資格を欠く」の目的語を示す「を」。", "が": "主語を示す「が」。「資格が欠く人」では他動詞の目的語の関係が成り立たず誤り。", "に": "方向・帰着を示す「に」。目的語の位置には入らない。", "で": "場所・手段を示す「で」。ここでは「欠く」の目的語にならない。"}, "error_tags": {"が": "主語", "に": "方向・帰着", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39039, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「部品を欠いた」の目的語を示す「を」。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「部品へ欠いた」は目的語を取れず誤り。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点を示す「より」。「部品より欠いた」は文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「部品の欠いた」は目的語の関係にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「部品を欠いた」の目的語を示す「を」。", "へ": "方向を示す「へ」。「部品へ欠いた」は目的語を取れず誤り。", "より": "比較・起点を示す「より」。「部品より欠いた」は文が成り立たない。", "の": "連体修飾の「の」。「部品の欠いた」は目的語の関係にならない。"}, "error_tags": {"へ": "方向", "より": "比較・起点", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39039, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "必要なものや条件が足りない状態であること。不足する。", "primary_collocate": null, "pronunciation": "かく", "ipa": "kakɯ", "syllable_count": 2, "sentences": [{"text": "その計画は、成功に必要な条件を欠いている。", "target_word": "欠いている", "complexity_tier": "T3", "furigana": "その計画[けいかく]は、成功[せいこう]に必要[ひつよう]な条件[じょうけん]を欠[か]いている。", "sentence_source": "generated"}, {"text": "資格を欠く人は、この仕事に応募できない。", "target_word": "欠く", "complexity_tier": "T3", "furigana": "資格[しかく]を欠[か]く人[ひと]は、この仕事[しごと]に応募[おうぼ]できない。", "sentence_source": "generated"}, {"text": "栄養を欠いた食事を続けると、体を壊す。", "target_word": "欠いた", "complexity_tier": "T3", "furigana": "栄養[えいよう]を欠[か]いた食事[しょくじ]を続[つづ]けると、体[からだ]を壊[こわ]す。", "sentence_source": "generated"}, {"text": "人手を欠いたため、店は昼で閉まった。", "target_word": "欠いた", "complexity_tier": "T3", "furigana": "人手[ひとで]を欠[か]いたため、店[みせ]は昼[ひる]で閉[し]まった。", "sentence_source": "generated"}, {"text": "資料を欠いたまま、会議を始めることはできない。", "target_word": "欠いた", "complexity_tier": "T3", "furigana": "資料[しりょう]を欠[か]いたまま、会議[かいぎ]を始[はじ]めることはできない。", "sentence_source": "generated"}, {"text": "基本的な知識を欠いているので、この問題は解けない。", "target_word": "欠いている", "complexity_tier": "T3", "furigana": "基本的[きほんてき]な知識[ちしき]を欠[か]いているので、この問題[もんだい]は解[と]けない。", "sentence_source": "generated"}, {"text": "十分な睡眠を欠くと、仕事の質が落ちる。", "target_word": "欠く", "complexity_tier": "T3", "furigana": "十分[じゅうぶん]な睡眠[すいみん]を欠[か]くと、仕事[しごと]の質[しつ]が落[お]ちる。", "sentence_source": "generated"}, {"text": "部品を欠いた機械は、正しく動かない。", "target_word": "欠いた", "complexity_tier": "T3", "furigana": "部品[ぶひん]を欠[か]いた機械[きかい]は、正[ただ]しく動[うご]かない。", "sentence_source": "generated"}, {"text": "必要な書類を欠いたので、申し込みは受け付けられなかった。", "target_word": "欠いた", "complexity_tier": "T3", "furigana": "必要[ひつよう]な書類[しょるい]を欠[か]いたので、申[もう]し込[こ]みは受[う]け付[つ]けられなかった。", "sentence_source": "generated"}, {"text": "資金を欠いて、工事は途中で止まった。", "target_word": "欠いて", "complexity_tier": "T3", "furigana": "資金[しきん]を欠[か]いて、工事[こうじ]は途中[とちゅう]で止[と]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "欠く", "label": "終止形"}, {"form": "欠いて", "label": "て形"}, {"form": "欠いた", "label": "過去形"}, {"form": "欠かない", "label": "否定形"}], "register": "やや硬い", "sense_fingerprint": "必要なものや条件が不足している", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b805d309-ed0d-4afe-a0c9-16e05b3d5c5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39039, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欠いている", "is_correct": true, "explanation": "正解。「条件を欠いている」は必要な条件が足りないという意味で、この文に合う。"}, {"text": "満ちている", "is_correct": false, "explanation": "「条件が満ちている」は主語に「が」を取る。「条件を」の文では成り立たない。"}, {"text": "達している", "is_correct": false, "explanation": "「条件に達している」は「に」を取るので、「条件を」の文には入らない。"}, {"text": "向いている", "is_correct": false, "explanation": "「条件に向いている」は「に」を取るので、「条件を」の文には合わない。"}], "explanations": {"欠いている": "正解。「条件を欠いている」は必要な条件が足りないという意味で、この文に合う。", "満ちている": "「条件が満ちている」は主語に「が」を取る。「条件を」の文では成り立たない。", "達している": "「条件に達している」は「に」を取るので、「条件を」の文には入らない。", "向いている": "「条件に向いている」は「に」を取るので、「条件を」の文には合わない。"}, "sentence_index": 0, "correct_answer": "欠いている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お湯を欠いて、お茶を入れた。", "explanation": "ここは〈沸かす〉（加熱して温める）の意味。欠くは不足を表すので、湯を沸かす動作には使わない。"}, {"text": "床を欠いて、ピカピカに磨いた。", "explanation": "ここは〈磨く〉（こすって光らせる）の意味。欠くは不足を表すので、表面をきれいにする動作には使わない。"}, {"text": "古い写真を欠いて、撮り直した。", "explanation": "ここは〈撮る〉（写真を写す）の意味。欠くは要素の不足を表すので、写真を写す動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39039, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欠く", "is_correct": true, "explanation": "正解。「睡眠を欠くと」の終止形で、条件を表す「と」に続く。"}, {"text": "足りる", "is_correct": false, "explanation": "「睡眠を足りると」は成り立たない。「足りる」は「が」や「に」と組む語。"}, {"text": "届く", "is_correct": false, "explanation": "「睡眠に届く」は「に」を取る。「睡眠を届くと」は文が成り立たない。"}, {"text": "向く", "is_correct": false, "explanation": "「睡眠に向く」は「に」を取る。「睡眠を向くと」は文が成り立たない。"}], "explanations": {"欠く": "正解。「睡眠を欠くと」の終止形で、条件を表す「と」に続く。", "足りる": "「睡眠を足りると」は成り立たない。「足りる」は「が」や「に」と組む語。", "届く": "「睡眠に届く」は「に」を取る。「睡眠を届くと」は文が成り立たない。", "向く": "「睡眠に向く」は「に」を取る。「睡眠を向くと」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "欠く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海を欠いて泳いだ。", "explanation": "ここは〈泳ぐ〉（水中を進む）の意味。欠くは不足を表すので、水中を進むことには使わない。"}, {"text": "古いパソコンを欠いて、処分した。", "explanation": "ここは〈捨てる〉の意味。欠くは不足を表し、物を処分する意味では使わない。"}, {"text": "電車を欠いて、約束に遅れた。", "explanation": "ここは〈乗り遅れる〉（乗り物に間に合わない）の意味。欠くは不足の状態を言うので、乗り物に間に合わないことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39039, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "資金を欠いてまま、その事業は進められた。", "corrected_sentence": "資金を欠いたまま、その事業は進められた。", "error_description": "「まま」の前には過去の「欠いた」が入る。「欠いてまま」は「て形」が「まま」に続かないので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "欠く", "is_correct": true, "explanation": "正解。「資格を欠く人」の連体形で、終止形と同じ形。"}, {"text": "欠いて", "is_correct": false, "explanation": "て形。「資格を欠いて人は」は名詞を修飾できず誤り。"}, {"text": "欠け", "is_correct": false, "explanation": "命令形・已然形。名詞を修飾できず、「資格を欠け人」は成り立たない。"}, {"text": "欠き", "is_correct": false, "explanation": "連用形。名詞を修飾できず「欠き人」は成り立たない。"}], "correct_form": "欠く", "base_form": "欠く", "form_label": "連体形", "sentence_index": 1, "explanations": {"欠く": "正解。「資格を欠く人」の連体形で、終止形と同じ形。", "欠いて": "て形。「資格を欠いて人は」は名詞を修飾できず誤り。", "欠け": "命令形・已然形。名詞を修飾できず、「資格を欠け人」は成り立たない。", "欠き": "連用形。名詞を修飾できず「欠き人」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39039, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "必要な条件を欠きまま、契約を結ぶのは危険だ。", "corrected_sentence": "必要な条件を欠いたまま、契約を結ぶのは危険だ。", "error_description": "「まま」の前には「欠いた」の形が必要。「欠き」は連用形で「まま」に続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "欠いた", "is_correct": true, "explanation": "正解。「部品を欠いた機械」の過去の連体形。"}, {"text": "欠いたら", "is_correct": false, "explanation": "条件を表す「たら」形。名詞を修飾できず、「部品を欠いたら機械」は成り立たない。"}, {"text": "欠こう", "is_correct": false, "explanation": "意志形。名詞を修飾できず、「部品を欠こう機械」は成り立たない。"}, {"text": "欠かず", "is_correct": false, "explanation": "否定の連用形。名詞を修飾できず「欠かず機械」は成り立たない。"}], "correct_form": "欠いた", "base_form": "欠く", "form_label": "過去形", "sentence_index": 7, "explanations": {"欠いた": "正解。「部品を欠いた機械」の過去の連体形。", "欠いたら": "条件を表す「たら」形。名詞を修飾できず、「部品を欠いたら機械」は成り立たない。", "欠こう": "意志形。名詞を修飾できず、「部品を欠こう機械」は成り立たない。", "欠かず": "否定の連用形。名詞を修飾できず「欠かず機械」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39040, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「双子を孕む」と対象を表す。"}, {"text": "に", "is_correct": false, "explanation": "「双子に孕んでいる」とは言えない。"}, {"text": "と", "is_correct": false, "explanation": "「双子と孕んでいる」とは言えない。"}, {"text": "へ", "is_correct": false, "explanation": "「双子へ孕んでいる」とは言えない。"}], "correct_answer": "を", "explanations": {"を": "「双子を孕む」と対象を表す。", "に": "「双子に孕んでいる」とは言えない。", "と": "「双子と孕んでいる」とは言えない。", "へ": "「双子へ孕んでいる」とは言えない。"}, "error_tags": {"に": "対象の誤り", "と": "共同の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
