INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39040, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "おなかの中に赤ちゃんができること。", "primary_collocate": null, "pronunciation": "はらむ", "ipa": "haɾamɯ", "syllable_count": 3, "sentences": [{"text": "猫が子を孕んだ。", "target_word": "孕んだ", "complexity_tier": "T1", "furigana": "ねこがこをはらんだ。", "sentence_source": "generated"}, {"text": "彼女は双子を孕んでいる。", "target_word": "孕んでいる", "complexity_tier": "T3", "furigana": "かのじょはふたごをはらんでいる。", "sentence_source": "generated"}, {"text": "母犬が子犬を孕みました。", "target_word": "孕みました", "complexity_tier": "T2", "furigana": "ははいぬがこいぬをはらみました。", "sentence_source": "generated"}, {"text": "牛が子を孕む季節になった。", "target_word": "孕む", "complexity_tier": "T3", "furigana": "うしがこをはらむきせつになった。", "sentence_source": "generated"}, {"text": "孕んだ猫を、病院に連れて行った。", "target_word": "孕んだ", "complexity_tier": "T3", "furigana": "はらんだねこを、びょういんにつれていった。", "sentence_source": "generated"}, {"text": "昔は、孕んだ女性は大切にされた。", "target_word": "孕んだ", "complexity_tier": "T4", "furigana": "むかしは、はらんだじょせいはたいせつにされた。", "sentence_source": "generated"}, {"text": "飼い猫が子を孕んだことを知って、彼女はうれしくて涙を流した。", "target_word": "孕んだ", "complexity_tier": "T4", "furigana": "かいねこがこをはらんだことをしって、かのじょはうれしくてなみだをながした。", "sentence_source": "generated"}, {"text": "孕んでいる馬は、ゆっくり歩かせなければならない。", "target_word": "孕んでいる", "complexity_tier": "T4", "furigana": "はらんでいるうまは、ゆっくりあるかせなければならない。", "sentence_source": "generated"}, {"text": "春になると、多くの野生動物が子を孕む。", "target_word": "孕む", "complexity_tier": "T3", "furigana": "はるになると、おおくのやせいどうぶつがこをはらむ。", "sentence_source": "generated"}, {"text": "子を孕んだ羊は、群れの中でゆっくり休んでいた。", "target_word": "孕んだ", "complexity_tier": "T4", "furigana": "こをはらんだひつじは、むれのなかでゆっくりやすんでいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "孕んで", "label": "活用"}, {"form": "孕んだ", "label": "活用"}, {"form": "孕まない", "label": "活用"}, {"form": "孕みます", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 体内に赤ちゃんを宿す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96f6e4-9414-4db2-8218-4b424363511e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39040, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "孕む", "is_correct": true, "explanation": "「はらむ」で、見出し語そのものの音である。"}, {"text": "挟む", "is_correct": false, "explanation": "「はさむ」で、二つ目の音が違う。"}, {"text": "阻む", "is_correct": false, "explanation": "「はばむ」で、二つ目の音が違う。"}, {"text": "弾む", "is_correct": false, "explanation": "「はずむ」で、二つ目の音が違う。"}], "explanations": {"孕む": "「はらむ」で、見出し語そのものの音である。", "挟む": "「はさむ」で、二つ目の音が違う。", "阻む": "「はばむ」で、二つ目の音が違う。", "弾む": "「はずむ」で、二つ目の音が違う。"}, "sentence_index": null, "correct_answer": "孕む"}, "level_3": {"options": [{"text": "孕んだ", "is_correct": true, "explanation": "猫が子を宿したという意味で合う。"}, {"text": "折った", "is_correct": false, "explanation": "形は合うが、「子を折る」では意味が合わない。"}, {"text": "閉じた", "is_correct": false, "explanation": "形は合うが、「子を閉じる」では意味が通らない。"}, {"text": "掘った", "is_correct": false, "explanation": "形は合うが、「猫が子を掘る」では意味が合わない。"}], "explanations": {"孕んだ": "猫が子を宿したという意味で合う。", "折った": "形は合うが、「子を折る」では意味が合わない。", "閉じた": "形は合うが、「子を閉じる」では意味が通らない。", "掘った": "形は合うが、「猫が子を掘る」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "孕んだ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は大きな荷物を孕んで駅へ走った。", "explanation": "「孕む」は荷物を持つ意味では使えず、語義の誤用である。"}, {"text": "男の子が友達を孕んで遊んだ。", "explanation": "「孕む」の対象は胎児や卵であり、友達には使えない。"}, {"text": "私は夕食にカレーを孕んだ。", "explanation": "「孕む」に食べるという意味はなく、動作を取り違えている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39040, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "孕む", "is_correct": true, "explanation": "「はらむ」で、見出し語そのものの音である。"}, {"text": "絡む", "is_correct": false, "explanation": "「からむ」で、最初の音が違う。"}, {"text": "払う", "is_correct": false, "explanation": "「はらう」で、最後の音が違う。"}, {"text": "晴らす", "is_correct": false, "explanation": "「はらす」で、最後の音が違う。"}], "explanations": {"孕む": "「はらむ」で、見出し語そのものの音である。", "絡む": "「からむ」で、最初の音が違う。", "払う": "「はらう」で、最後の音が違う。", "晴らす": "「はらす」で、最後の音が違う。"}, "sentence_index": null, "correct_answer": "孕む"}, "level_3": {"options": [{"text": "孕んだ", "is_correct": true, "explanation": "猫が子を体内に宿したという意味で、「子を」と合う。"}, {"text": "乾いた", "is_correct": false, "explanation": "自動詞なので「子を」と結びつかず、意味も合わない。"}, {"text": "折れた", "is_correct": false, "explanation": "自動詞なので「子を」と結びつかず、意味も合わない。"}, {"text": "閉じた", "is_correct": false, "explanation": "「子を閉じる」とは言えず、意味が通らない。"}], "explanations": {"孕んだ": "猫が子を体内に宿したという意味で、「子を」と合う。", "乾いた": "自動詞なので「子を」と結びつかず、意味も合わない。", "折れた": "自動詞なので「子を」と結びつかず、意味も合わない。", "閉じた": "「子を閉じる」とは言えず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "孕んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎朝、新聞を孕んで読んでいる。", "explanation": "「孕む」に持つという意味はなく、語義の誤用である。"}, {"text": "先生が生徒に宿題を孕んだ。", "explanation": "「孕む」は宿題を出すという意味では使えない。"}, {"text": "母は台所で野菜を孕んでいる。", "explanation": "「孕む」は料理する意味では使えず、対象も合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39040, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "うちの犬が三匹の子で孕んでいる。", "corrected_sentence": "うちの犬が三匹の子を孕んでいる。", "error_description": "「孕む」の対象を表す助詞は「で」ではなく「を」である。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "孕んでいる", "is_correct": true, "explanation": "妊娠している状態を表す文末の形として合う。"}, {"text": "孕んで", "is_correct": false, "explanation": "て形のままでは文が終わらない。"}, {"text": "孕めば", "is_correct": false, "explanation": "仮定形では文末として成り立たない。"}, {"text": "孕もう", "is_correct": false, "explanation": "意志形は「彼女は」の状態を述べる文末に合わない。"}], "correct_form": "孕んでいる", "base_form": "孕む", "form_label": "ている形", "sentence_index": 1, "explanations": {"孕んでいる": "妊娠している状態を表す文末の形として合う。", "孕んで": "て形のままでは文が終わらない。", "孕めば": "仮定形では文末として成り立たない。", "孕もう": "意志形は「彼女は」の状態を述べる文末に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39040, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母牛は春に子と孕んだ。", "corrected_sentence": "母牛は春に子を孕んだ。", "error_description": "「孕む」の対象を表す助詞は「と」ではなく「を」である。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "孕んでいる", "is_correct": true, "explanation": "「馬」を修飾する状態の形として合う。"}, {"text": "孕めば", "is_correct": false, "explanation": "仮定形では名詞を修飾できない。"}, {"text": "孕みます", "is_correct": false, "explanation": "「ます」形では名詞を修飾する形として不自然である。"}, {"text": "孕もう", "is_correct": false, "explanation": "意志形では名詞を修飾できない。"}], "correct_form": "孕んでいる", "base_form": "孕む", "form_label": "ている形", "sentence_index": 7, "explanations": {"孕んでいる": "「馬」を修飾する状態の形として合う。", "孕めば": "仮定形では名詞を修飾できない。", "孕みます": "「ます」形では名詞を修飾する形として不自然である。", "孕もう": "意志形では名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
