INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39041, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事がその内部に、危険・問題・矛盾などを含み持つこと。", "primary_collocate": null, "pronunciation": "はらむ", "ipa": "haɾamɯ", "syllable_count": 3, "sentences": [{"text": "中央銀行による大規模な資産買入オペレーション、すなわち量的緩和政策は、単なる流動性の供給にとどまらず、国債市場における価格発見機能を歪曲せしめる側面を孕んでいる。", "target_word": "孕んでいる", "complexity_tier": "T6", "furigana": "ちゅうおうぎんこうによるだいきぼなしさんかいいれオペレーション、すなわちりょうてきかんわせいさくは、たんなるりゅうどうせいのきょうきゅうにとどまらず、こくさいしじょうにおけるかかくはっけんきのうをわいきょくせしめるそくめんをはらんでいる。", "sentence_source": "mined"}, {"text": "この計画は危険を孕んでいる。", "target_word": "孕んでいる", "complexity_tier": "T3", "furigana": "このけいかくはきけんをはらんでいる。", "sentence_source": "generated"}, {"text": "問題を孕んだまま、話が進んだ。", "target_word": "孕んだ", "complexity_tier": "T3", "furigana": "もんだいをはらんだまま、はなしがすすんだ。", "sentence_source": "generated"}, {"text": "その言葉は、深い意味を孕んでいます。", "target_word": "孕んでいます", "complexity_tier": "T3", "furigana": "そのことばは、ふかいいみをはらんでいます。", "sentence_source": "generated"}, {"text": "静かな海も、嵐を孕んでいることがある。", "target_word": "孕んでいる", "complexity_tier": "T3", "furigana": "しずかなうみも、あらしをはらんでいることがある。", "sentence_source": "generated"}, {"text": "孕んでいる危険に、誰も気づかなかった。", "target_word": "孕んでいる", "complexity_tier": "T3", "furigana": "はらんでいるきけんに、だれもきづかなかった。", "sentence_source": "generated"}, {"text": "対立を孕む制度は、いずれ見直されるだろう。", "target_word": "孕む", "complexity_tier": "T4", "furigana": "たいりつをはらむせいどは、いずれみなおされるだろう。", "sentence_source": "generated"}, {"text": "矛盾を孕んでいない理論は、ほとんどない。", "target_word": "孕んでいない", "complexity_tier": "T4", "furigana": "むじゅんをはらんでいないりろんは、ほとんどない。", "sentence_source": "generated"}, {"text": "小さな誤解が大きな争いを孕んでいたとは、誰も思わなかった。", "target_word": "孕んでいた", "complexity_tier": "T5", "furigana": "ちいさなごかいがおおきなあらそいをはらんでいたとは、だれもおもわなかった。", "sentence_source": "generated"}, {"text": "彼の発言は、会社の将来に影響を及ぼす問題を孕んでいる。", "target_word": "孕んでいる", "complexity_tier": "T4", "furigana": "かれのはつげんは、かいしゃのしょうらいにえいきょうをおよぼすもんだいをはらんでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "孕んで", "label": "活用"}, {"form": "孕んだ", "label": "活用"}, {"form": "孕まない", "label": "活用"}, {"form": "孕みます", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 物事の内部に何かを含み持つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96f6e4-9414-4db2-8218-4b424363511e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39041, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "孕む", "is_correct": true, "explanation": "「はらむ」で、見出し語そのものの音である。"}, {"text": "挟む", "is_correct": false, "explanation": "「はさむ」で、二つ目の音が違う。"}, {"text": "阻む", "is_correct": false, "explanation": "「はばむ」で、二つ目の音が違う。"}, {"text": "弾む", "is_correct": false, "explanation": "「はずむ」で、二つ目の音が違う。"}], "explanations": {"孕む": "「はらむ」で、見出し語そのものの音である。", "挟む": "「はさむ」で、二つ目の音が違う。", "阻む": "「はばむ」で、二つ目の音が違う。", "弾む": "「はずむ」で、二つ目の音が違う。"}, "sentence_index": null, "correct_answer": "孕む"}, "level_3": {"options": [{"text": "孕んでいる", "is_correct": true, "explanation": "「側面を内部に含み持つ」という意味で文脈に合う。"}, {"text": "薄めている", "is_correct": false, "explanation": "形は合うが、「側面を薄める」では意味が合わない。"}, {"text": "数えている", "is_correct": false, "explanation": "形は合うが、「側面を数える」では文の意味が通らない。"}, {"text": "洗っている", "is_correct": false, "explanation": "形は合うが、政策の側面を洗うことはできず意味が合わない。"}], "explanations": {"孕んでいる": "「側面を内部に含み持つ」という意味で文脈に合う。", "薄めている": "形は合うが、「側面を薄める」では意味が合わない。", "数えている": "形は合うが、「側面を数える」では文の意味が通らない。", "洗っている": "形は合うが、政策の側面を洗うことはできず意味が合わない。"}, "sentence_index": 0, "correct_answer": "孕んでいる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎朝、公園で犬を孕んでいる。", "explanation": "「孕む」は犬を連れて歩く意味では使えず、対象の選び方が誤り。"}, {"text": "机の上に、本を三冊孕んでいる。", "explanation": "「孕む」は物を置くという具体的な動作には使えず、意味の誤用である。"}, {"text": "彼女は新しい靴を孕んで学校へ行った。", "explanation": "「孕む」に履くという意味はなく、語義を取り違えている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39041, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "孕む", "is_correct": true, "explanation": "「はらむ」で、見出し語そのものの音である。"}, {"text": "絡む", "is_correct": false, "explanation": "「からむ」で、最初の音が違う。"}, {"text": "払う", "is_correct": false, "explanation": "「はらう」で、最後の音が違う。"}, {"text": "晴らす", "is_correct": false, "explanation": "「はらす」で、最後の音が違う。"}], "explanations": {"孕む": "「はらむ」で、見出し語そのものの音である。", "絡む": "「からむ」で、最初の音が違う。", "払う": "「はらう」で、最後の音が違う。", "晴らす": "「はらす」で、最後の音が違う。"}, "sentence_index": null, "correct_answer": "孕む"}, "level_3": {"options": [{"text": "孕む", "is_correct": true, "explanation": "「対立を内部に含む制度」という意味で合う。"}, {"text": "数える", "is_correct": false, "explanation": "形は合うが、「対立を数える制度」では意味が合わない。"}, {"text": "洗う", "is_correct": false, "explanation": "形は合うが、「対立を洗う制度」では意味が通らない。"}, {"text": "閉じる", "is_correct": false, "explanation": "形は合うが、「対立を閉じる制度」では意味が合わない。"}], "explanations": {"孕む": "「対立を内部に含む制度」という意味で合う。", "数える": "形は合うが、「対立を数える制度」では意味が合わない。", "洗う": "形は合うが、「対立を洗う制度」では意味が通らない。", "閉じる": "形は合うが、「対立を閉じる制度」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "孕む"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は昨日、重い荷物を孕んで階段を上った。", "explanation": "「孕む」に持つ・運ぶという意味はなく、語義の取り違えである。"}, {"text": "彼女は友達に手紙を孕んで渡した。", "explanation": "「孕む」を手に持つ意味で使っており、誤用である。"}, {"text": "私は毎晩、日記を孕んでから寝る。", "explanation": "「孕む」に書くという意味はなく、動作を誤っている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39041, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この問題は大きな危険に孕んでいる。", "corrected_sentence": "この問題は大きな危険を孕んでいる。", "error_description": "「孕む」の対象を表す助詞は「に」ではなく「を」である。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "孕んでいる", "is_correct": true, "explanation": "文末で状態を表す形として自然に使える。"}, {"text": "孕んで", "is_correct": false, "explanation": "て形のままでは文が終わらない。"}, {"text": "孕めば", "is_correct": false, "explanation": "仮定形では文末として成り立たない。"}, {"text": "孕もう", "is_correct": false, "explanation": "意志形は「計画」を主語にした文末に合わない。"}], "correct_form": "孕んでいる", "base_form": "孕む", "form_label": "ている形", "sentence_index": 1, "explanations": {"孕んでいる": "文末で状態を表す形として自然に使える。", "孕んで": "て形のままでは文が終わらない。", "孕めば": "仮定形では文末として成り立たない。", "孕もう": "意志形は「計画」を主語にした文末に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39041, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その計画は多くの矛盾が孕んでいる。", "corrected_sentence": "その計画は多くの矛盾を孕んでいる。", "error_description": "「孕む」の対象は「が」ではなく「を」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "孕んでいない", "is_correct": true, "explanation": "「理論」を修飾する否定の形として合う。"}, {"text": "孕んで", "is_correct": false, "explanation": "て形のままでは「理論」を修飾できない。"}, {"text": "孕めば", "is_correct": false, "explanation": "仮定形では名詞を修飾できない。"}, {"text": "孕みます", "is_correct": false, "explanation": "「ます」形では名詞を修飾する形として不自然である。"}], "correct_form": "孕んでいない", "base_form": "孕む", "form_label": "ていない形", "sentence_index": 7, "explanations": {"孕んでいない": "「理論」を修飾する否定の形として合う。", "孕んで": "て形のままでは「理論」を修飾できない。", "孕めば": "仮定形では名詞を修飾できない。", "孕みます": "「ます」形では名詞を修飾する形として不自然である。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
