INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39044, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "とても大きい、はっきりと違う", "primary_collocate": null, "pronunciation": "いちじるしい", "ipa": "itɕidʑiɾɯɕiː", "syllable_count": 6, "sentences": [{"text": "最近、この町の変化は著しいです。", "target_word": "著しい", "complexity_tier": "T3", "furigana": "最近[さいきん]、この町[まち]の変化[へんか]は著[いちじる]しいです。", "sentence_source": "generated"}, {"text": "弟の日本語は、一年で著しく上手になりました。", "target_word": "著しく", "complexity_tier": "T3", "furigana": "弟[おとうと]の日本語[にほんご]は、一年[いちねん]で著[いちじる]しく上手[じょうず]になりました。", "sentence_source": "generated"}, {"text": "運動を始めてから、体力が著しく上がりました。", "target_word": "著しく", "complexity_tier": "T3", "furigana": "運動[うんどう]を始[はじ]めてから、体力[たいりょく]が著[いちじる]しく上[あ]がりました。", "sentence_source": "generated"}, {"text": "兄と私の考え方には、著しい違いがあります。", "target_word": "著しい", "complexity_tier": "T3", "furigana": "兄[あに]と私[わたし]の考[かんが]え方[かた]には、著[いちじる]しい違[ちが]いがあります。", "sentence_source": "generated"}, {"text": "この会社は、ここ数年で著しく成長しました。", "target_word": "著しく", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、ここ数年[すうねん]で著[いちじる]しく成長[せいちょう]しました。", "sentence_source": "generated"}, {"text": "雨の少ない年は、野菜の値段が著しく高くなります。", "target_word": "著しく", "complexity_tier": "T3", "furigana": "雨[あめ]の少[すく]ない年[とし]は、野菜[やさい]の値段[ねだん]が著[いちじる]しく高[たか]くなります。", "sentence_source": "generated"}, {"text": "薬を飲んだら、病気が著しくよくなりました。", "target_word": "著しく", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだら、病気[びょうき]が著[いちじる]しくよくなりました。", "sentence_source": "generated"}, {"text": "駅の前は、十年で著しく便利になりました。", "target_word": "著しく", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]は、十年[じゅうねん]で著[いちじる]しく便利[べんり]になりました。", "sentence_source": "generated"}, {"text": "彼女の進歩は著しいので、先生も驚いています。", "target_word": "著しい", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の進歩[しんぽ]は著[いちじる]しいので、先生[せんせい]も驚[おどろ]いています。", "sentence_source": "generated"}, {"text": "夜になると、気温の下がり方が著しいです。", "target_word": "著しい", "complexity_tier": "T3", "furigana": "夜[よる]になると、気温[きおん]の下[さ]がり方[かた]が著[いちじる]しいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "著しい", "label": "終止形・連体形"}, {"form": "著しく", "label": "連用形"}, {"form": "著しかった", "label": "過去形"}, {"form": "著しくない", "label": "否定形"}, {"form": "著しければ", "label": "仮定形"}], "register": "neutral (polite です・ます style)", "sense_fingerprint": "変化・進歩・違いなどがとても大きく、はっきり目に見えること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d892d9d-8eff-463a-a0ef-366628b4b1ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39044, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "著しい", "is_correct": true, "explanation": "「変化は著しい」で、変化がはっきり大きいことを表す。文脈に合う。"}, {"text": "甘い", "is_correct": false, "explanation": "味を表す語で、変化の大きさは表せないので「変化は甘い」は成り立たない。"}, {"text": "固い", "is_correct": false, "explanation": "硬さを表す語で、変化の程度には使えないので合わない。"}, {"text": "苦い", "is_correct": false, "explanation": "味を表す語で、変化の度合いを述べる文には合わない。"}], "explanations": {"著しい": "「変化は著しい」で、変化がはっきり大きいことを表す。文脈に合う。", "甘い": "味を表す語で、変化の大きさは表せないので「変化は甘い」は成り立たない。", "固い": "硬さを表す語で、変化の程度には使えないので合わない。", "苦い": "味を表す語で、変化の度合いを述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "著しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上に著しい本が三冊のっている。", "explanation": "ここは〈大量の〉の意味。『著しい』は差や変化の大きさを言うので、本の数には使わない。"}, {"text": "窓のそばに著しい花が咲いた。", "explanation": "ここは〈美しい〉の意味。『著しい』は差や変化の大きさを言うので、花の美しさには使わない。"}, {"text": "雨が上がって、著しい空が見えた。", "explanation": "ここは〈晴れた〉の意味。『著しい』は差や変化の大きさを言うので、空の晴れ具合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39044, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "著しく", "is_correct": true, "explanation": "「よくなる」を修飾する連用形で、病気の回復の程度を表す。文脈に合う。"}, {"text": "常に", "is_correct": false, "explanation": "「いつも」の意味で、回復の程度を表す文脈には合わない。"}, {"text": "前もって", "is_correct": false, "explanation": "「事前に」の意味で、病気が回復する文には合わない。"}, {"text": "大事に", "is_correct": false, "explanation": "「大切に」の意味で、回復の程度を述べる文には合わない。"}], "explanations": {"著しく": "「よくなる」を修飾する連用形で、病気の回復の程度を表す。文脈に合う。", "常に": "「いつも」の意味で、回復の程度を表す文脈には合わない。", "前もって": "「事前に」の意味で、病気が回復する文には合わない。", "大事に": "「大切に」の意味で、回復の程度を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "著しく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は著しい性格で、みんなに好かれている。", "explanation": "ここは〈やさしい〉の意味。『著しい』は差や変化の大きさを言うので、人の性格には使わない。"}, {"text": "テーブルを著しい布で拭いた。", "explanation": "ここは〈清潔な〉の意味。『著しい』は差や変化の大きさを言うので、布の清潔さには使わない。"}, {"text": "来週の会議は、著しい午後に開かれる。", "explanation": "ここは〈遅い〉の意味。『著しい』は差や変化の大きさを言うので、時刻の遅さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39044, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は、昨年から足の具合が著しい悪くなった。", "corrected_sentence": "祖父は、昨年から足の具合が著しく悪くなった。", "error_description": "「悪くなる」を修飾するので、連用形の「著しく」が正しい。「著しい」は終止形・連体形なので、動詞の前では使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "著しく", "is_correct": true, "explanation": "連用形で、「上手になる」を修飾する形。"}, {"text": "著しい", "is_correct": false, "explanation": "終止形・連体形なので、「上手になる」を修飾できない。"}, {"text": "著しかった", "is_correct": false, "explanation": "過去形なので、ここでは修飾の形が合わない。"}, {"text": "著しくない", "is_correct": false, "explanation": "否定形なので、肯定の文脈に合わない。"}], "correct_form": "著しく", "base_form": "著しい", "form_label": "連用形", "sentence_index": 1, "explanations": {"著しく": "連用形で、「上手になる」を修飾する形。", "著しい": "終止形・連体形なので、「上手になる」を修飾できない。", "著しかった": "過去形なので、ここでは修飾の形が合わない。", "著しくない": "否定形なので、肯定の文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39044, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先月、新しい技術で効果が著しい上がった。", "corrected_sentence": "先月、新しい技術で効果が著しく上がった。", "error_description": "「上がる」を修飾するので、連用形の「著しく」が正しい。「著しい」は終止形・連体形なので、動詞の前では使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "著しく", "is_correct": true, "explanation": "連用形で、「便利になる」を修飾する形。"}, {"text": "著しくなかった", "is_correct": false, "explanation": "否定の過去形なので、便利になったという肯定の変化の文と意味が逆になる。"}, {"text": "著しい", "is_correct": false, "explanation": "連体形なので、な形容動詞「便利」の前には「便利な」が必要で、続かない。"}, {"text": "著しさ", "is_correct": false, "explanation": "名詞なので、「便利になる」を副詞的に修飾できない。"}], "correct_form": "著しく", "base_form": "著しい", "form_label": "連用形", "sentence_index": 7, "explanations": {"著しく": "連用形で、「便利になる」を修飾する形。", "著しくなかった": "否定の過去形なので、便利になったという肯定の変化の文と意味が逆になる。", "著しい": "連体形なので、な形容動詞「便利」の前には「便利な」が必要で、続かない。", "著しさ": "名詞なので、「便利になる」を副詞的に修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
