INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39045, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "程度が非常にはなはだしく、普通とは違っているさま。際立っていること。", "primary_collocate": null, "pronunciation": "いちじるしい", "ipa": "itɕidʑiɾɯɕiː", "syllable_count": 6, "sentences": [{"text": "近年、この地域では人口の減少が著しい。", "target_word": "著しい", "complexity_tier": "T3", "furigana": "近年[きんねん]、この地域[ちいき]では人口[じんこう]の減少[げんしょう]が著[いちじる]しい。", "sentence_source": "generated"}, {"text": "彼の技術の向上は、周りの人と比べても著しい。", "target_word": "著しい", "complexity_tier": "T3", "furigana": "彼[かれ]の技術[ぎじゅつ]の向上[こうじょう]は、周[まわ]りの人[ひと]と比[くら]べても著[いちじる]しい。", "sentence_source": "generated"}, {"text": "新しい制度の導入で、業績に著しい変化が現れた。", "target_word": "著しい", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]の導入[どうにゅう]で、業績[ぎょうせき]に著[いちじる]しい変化[へんか]が現[あらわ]れた。", "sentence_source": "generated"}, {"text": "品質が著しく低下したため、製品を回収した。", "target_word": "著しく", "complexity_tier": "T3", "furigana": "品質[ひんしつ]が著[いちじる]しく低下[ていか]したため、製品[せいひん]を回収[かいしゅう]した。", "sentence_source": "generated"}, {"text": "二人の意見は著しく食い違っている。", "target_word": "著しく", "complexity_tier": "T3", "furigana": "二人[ふたり]の意見[いけん]は著[いちじる]しく食[く]い違[ちが]っている。", "sentence_source": "generated"}, {"text": "通信技術は、この二十年で著しく発達した。", "target_word": "著しく", "complexity_tier": "T3", "furigana": "通信[つうしん]技術[ぎじゅつ]は、この二十年[にじゅうねん]で著[いちじる]しく発達[はったつ]した。", "sentence_source": "generated"}, {"text": "睡眠不足は、集中力を著しく下げる。", "target_word": "著しく", "complexity_tier": "T3", "furigana": "睡眠[すいみん]不足[ぶそく]は、集中力[しゅうちゅうりょく]を著[いちじる]しく下[さ]げる。", "sentence_source": "generated"}, {"text": "都市部と地方の格差は著しい。", "target_word": "著しい", "complexity_tier": "T3", "furigana": "都市部[としぶ]と地方[ちほう]の格差[かくさ]は著[いちじる]しい。", "sentence_source": "generated"}, {"text": "川の水の汚れが著しく、魚がほとんどいなくなった。", "target_word": "著しく", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]の汚[よご]れが著[いちじる]しく、魚[さかな]がほとんどいなくなった。", "sentence_source": "generated"}, {"text": "彼女は著しい成果を上げ、社長から表彰された。", "target_word": "著しい", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は著[いちじる]しい成果[せいか]を上[あ]げ、社長[しゃちょう]から表彰[ひょうしょう]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "著しい", "label": "終止形・連体形"}, {"form": "著しく", "label": "連用形"}, {"form": "著しかった", "label": "過去形"}, {"form": "著しくない", "label": "否定形"}, {"form": "著しければ", "label": "仮定形"}], "register": "written/formal (plain だ・である style)", "sense_fingerprint": "程度が普通を大きく超えて際立つこと。報道・論文などで増減・差・発達を述べる。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d892d9d-8eff-463a-a0ef-366628b4b1ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39045, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "著しい", "is_correct": true, "explanation": "「減少が著しい」で、減少の度合いが大きいことを表す。文脈に合う。"}, {"text": "冷たい", "is_correct": false, "explanation": "温度を表す語で、人口の減少の度合いには使えないので合わない。"}, {"text": "熱い", "is_correct": false, "explanation": "温度を表す語で、減少の程度を述べる文には合わない。"}, {"text": "柔らかい", "is_correct": false, "explanation": "触感を表す語で、人口の減少には使えないので合わない。"}], "explanations": {"著しい": "「減少が著しい」で、減少の度合いが大きいことを表す。文脈に合う。", "冷たい": "温度を表す語で、人口の減少の度合いには使えないので合わない。", "熱い": "温度を表す語で、減少の程度を述べる文には合わない。", "柔らかい": "触感を表す語で、人口の減少には使えないので合わない。"}, "sentence_index": 0, "correct_answer": "著しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓辺に著しい机を置いた。", "explanation": "ここは〈家具の形〉の意味。『著しい』は違いや変化の大きさを言うので、物の形には使わない。"}, {"text": "夕食に著しい塩を入れた。", "explanation": "ここは〈しょっぱい〉の意味。『著しい』は差や変化の大きさを言うので、塩の味には使わない。"}, {"text": "窓の外で著しい鳥が鳴いている。", "explanation": "ここは〈めずらしい〉の意味。『著しい』は差や変化の大きさを言うので、鳥の珍しさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39045, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "著しく", "is_correct": true, "explanation": "「下げる」を修飾する連用形で、集中力の低下の程度が大きいことを表す。文脈に合う。"}, {"text": "全然", "is_correct": false, "explanation": "打ち消しの語と結びつくため、「全然下げる」とは言えず合わない。"}, {"text": "大事に", "is_correct": false, "explanation": "「大切に」の意味で、集中力を下げる文脈には合わない。"}, {"text": "眠そうに", "is_correct": false, "explanation": "様子を表す語で、集中力の低下を修飾する文脈には合わない。"}], "explanations": {"著しく": "「下げる」を修飾する連用形で、集中力の低下の程度が大きいことを表す。文脈に合う。", "全然": "打ち消しの語と結びつくため、「全然下げる」とは言えず合わない。", "大事に": "「大切に」の意味で、集中力を下げる文脈には合わない。", "眠そうに": "様子を表す語で、集中力の低下を修飾する文脈には合わない。"}, "sentence_index": 6, "correct_answer": "著しく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は著しい足で、毎朝駅まで歩いて通う。", "explanation": "ここは〈丈夫な〉の意味。『著しい』は差や変化の大きさを言うので、体の丈夫さには使わない。"}, {"text": "壁を著しい色に塗った。", "explanation": "ここは〈鮮やかな〉の意味。『著しい』は差や変化の大きさを言うので、色の鮮やかさには使わない。"}, {"text": "この薬は、著しい朝に飲むと効く。", "explanation": "ここは〈早い〉の意味。『著しい』は差や変化の大きさを言うので、時刻の早さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39045, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の量が著しい増えた。", "corrected_sentence": "雨の量が著しく増えた。", "error_description": "「増える」を修飾するので、連用形の「著しく」が正しい。「著しい」は終止形・連体形なので、動詞の前では使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "著しい", "is_correct": true, "explanation": "終止形で、ここでは述語になる。「格差は著しい」の形。"}, {"text": "著しく", "is_correct": false, "explanation": "連用形なので、文末の述語にはならない。"}, {"text": "著しければ", "is_correct": false, "explanation": "仮定形なので、文末で言い切れず「比べても」の述語にならない。"}, {"text": "著しくない", "is_correct": false, "explanation": "否定形なので、肯定の評価の文脈に合わない。"}], "correct_form": "著しい", "base_form": "著しい", "form_label": "終止形・連体形", "sentence_index": 1, "explanations": {"著しい": "終止形で、ここでは述語になる。「格差は著しい」の形。", "著しく": "連用形なので、文末の述語にはならない。", "著しければ": "仮定形なので、文末で言い切れず「比べても」の述語にならない。", "著しくない": "否定形なので、肯定の評価の文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39045, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この製品の売り上げは、著しくな伸びを見せた。", "corrected_sentence": "この製品の売り上げは、著しい伸びを見せた。", "error_description": "「著しく」は連用形で、「な」を付けて名詞を修飾することはできない。「伸び」の前は連体形の「著しい」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "著しい", "is_correct": true, "explanation": "終止形で、「格差は著しい」の述語になる。"}, {"text": "著しき", "is_correct": false, "explanation": "文語の連体形なので、文末で言い切れず「格差は」の述語にならない。"}, {"text": "著しくて", "is_correct": false, "explanation": "て形の接続の形なので、文末で言い切れず「格差は」の述語にならない。"}, {"text": "著しくなければ", "is_correct": false, "explanation": "否定の仮定形なので、文末で言い切れず「格差は」の述語にならない。"}], "correct_form": "著しい", "base_form": "著しい", "form_label": "終止形・連体形", "sentence_index": 7, "explanations": {"著しい": "終止形で、「格差は著しい」の述語になる。", "著しき": "文語の連体形なので、文末で言い切れず「格差は」の述語にならない。", "著しくて": "て形の接続の形なので、文末で言い切れず「格差は」の述語にならない。", "著しくなければ": "否定の仮定形なので、文末で言い切れず「格差は」の述語にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39046, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「大きな格差がある」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」。「ある」は目的語を取らないので誤り。"}, {"text": "に", "is_correct": false, "explanation": "位置・存在の場を示す「に」。「格差にある」は主語の位置として不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す「と」。「格差とある」は文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。「大きな格差がある」の主語を示す「が」。", "を": "目的語を示す「を」。「ある」は目的語を取らないので誤り。", "に": "位置・存在の場を示す「に」。「格差にある」は主語の位置として不自然。", "と": "並列を示す「と」。「格差とある」は文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "位置・帰着", "と": "並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平等", "is_correct": true, "explanation": "正解。格差の対義語として、差がない状態を表す。"}, {"text": "格闘", "is_correct": false, "explanation": "対義語ではない。格闘は激しく争うこと。"}, {"text": "格納", "is_correct": false, "explanation": "対義語ではない。格納はしまい込むことを表す。"}, {"text": "格付け", "is_correct": false, "explanation": "対義語ではない。格付けは等級を決める意味。"}], "correct_answer": "平等", "explanations": {"平等": "正解。格差の対義語として、差がない状態を表す。", "格闘": "対義語ではない。格闘は激しく争うこと。", "格納": "対義語ではない。格納はしまい込むことを表す。", "格付け": "対義語ではない。格付けは等級を決める意味。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39046, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「男女の格差を調べた」の目的語を示す「を」。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「格差へ調べた」は目的語を取れず誤り。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「格差の調べた」は目的語の関係にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点を示す「より」。「格差より調べた」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「男女の格差を調べた」の目的語を示す「を」。", "へ": "方向を示す「へ」。「格差へ調べた」は目的語を取れず誤り。", "の": "連体修飾の「の」。「格差の調べた」は目的語の関係にならない。", "より": "比較・起点を示す「より」。「格差より調べた」は文が成り立たない。"}, "error_tags": {"へ": "方向", "の": "連体修飾", "より": "比較・起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平等", "is_correct": true, "explanation": "正解。格差の対義語として、差がない状態を表す。"}, {"text": "格言", "is_correct": false, "explanation": "対義語ではない。格言は教えの言葉。"}, {"text": "同一", "is_correct": false, "explanation": "対義語ではない。同一は同じであること。"}, {"text": "統一", "is_correct": false, "explanation": "対義語ではない。統一はまとめて一つにすること。"}], "correct_answer": "平等", "explanations": {"平等": "正解。格差の対義語として、差がない状態を表す。", "格言": "対義語ではない。格言は教えの言葉。", "同一": "対義語ではない。同一は同じであること。", "統一": "対義語ではない。統一はまとめて一つにすること。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39046, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人や国の間で、あることの程度に大きなちがいがあること。", "primary_collocate": null, "pronunciation": "かくさ", "ipa": "kakɯsa", "syllable_count": 3, "sentences": [{"text": "豊かな国と貧しい国の間には、大きな格差がある。", "target_word": "格差", "complexity_tier": "T3", "furigana": "豊[ゆた]かな国[くに]と貧[まず]しい国[くに]の間[あいだ]には、大[おお]きな格差[かくさ]がある。", "sentence_source": "generated"}, {"text": "同じ国に住んでいても、人どうしの生活には大きな格差がある。", "target_word": "格差", "complexity_tier": "T3", "furigana": "同[おな]じ国[くに]に住[す]んでいても、人[ひと]どうしの生活[せいかつ]には大[おお]きな格差[かくさ]がある。", "sentence_source": "generated"}, {"text": "子どもたちの間で、学ぶ機会の格差が広がっている。", "target_word": "格差", "complexity_tier": "T3", "furigana": "子[こ]どもたちの間[あいだ]で、学[まな]ぶ機会[きかい]の格差[かくさ]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "正社員と派遣社員の間の格差は、年々大きくなっている。", "target_word": "格差", "complexity_tier": "T3", "furigana": "正社員[せいしゃいん]と派遣社員[はけんしゃいん]の間[あいだ]の格差[かくさ]は、年々[ねんねん]大[おお]きくなっている。", "sentence_source": "generated"}, {"text": "親の収入によって教育の格差が生まれる。", "target_word": "格差", "complexity_tier": "T3", "furigana": "親[おや]の収入[しゅうにゅう]によって教育[きょういく]の格差[かくさ]が生[う]まれる。", "sentence_source": "generated"}, {"text": "国どうしの格差をなくすことは、簡単ではない。", "target_word": "格差", "complexity_tier": "T3", "furigana": "国[くに]どうしの格差[かくさ]をなくすことは、簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "国民の間の格差が大きいので、政府は支援を増やした。", "target_word": "格差", "complexity_tier": "T3", "furigana": "国民[こくみん]の間[あいだ]の格差[かくさ]が大[おお]きいので、政府[せいふ]は支援[しえん]を増[ふ]やした。", "sentence_source": "generated"}, {"text": "男女の格差を調べた結果、女性の賃金が低いとわかった。", "target_word": "格差", "complexity_tier": "T3", "furigana": "男女[だんじょ]の格差[かくさ]を調[しら]べた結果[けっか]、女性[じょせい]の賃金[ちんぎん]が低[ひく]いとわかった。", "sentence_source": "generated"}, {"text": "豊かな家の子と貧しい家の子の格差が、学力にも表れている。", "target_word": "格差", "complexity_tier": "T3", "furigana": "豊[ゆた]かな家[いえ]の子[こ]と貧[まず]しい家[いえ]の子[こ]の格差[かくさ]が、学力[がくりょく]にも表[あらわ]れている。", "sentence_source": "generated"}, {"text": "国の間に格差があるため、世界の問題は複雑だ。", "target_word": "格差", "complexity_tier": "T3", "furigana": "国[くに]の間[あいだ]に格差[かくさ]があるため、世界[せかい]の問題[もんだい]は複雑[ふくざつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "格差", "label": "基本形"}, {"form": "格差の", "label": "連体修飾形"}, {"form": "格差が", "label": "主語を表す形"}], "register": "中立", "sense_fingerprint": "人や国などの間にある、程度の大きなちがい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b805d309-ed0d-4afe-a0c9-16e05b3d5c5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39046, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "格差", "is_correct": true, "explanation": "正解。「大きな格差がある」は国の間の程度の差を表し、文に合う。"}, {"text": "格言", "is_correct": false, "explanation": "「大きな格言がある」は成り立たない。格言は短い教えの言葉。"}, {"text": "格式", "is_correct": false, "explanation": "「大きな格式がある」は意味が通らない。格式は家柄や組織の伝統の高さを指す。"}, {"text": "格好", "is_correct": false, "explanation": "「大きな格好がある」は不自然で、見た目の意味では文に合わない。"}], "explanations": {"格差": "正解。「大きな格差がある」は国の間の程度の差を表し、文に合う。", "格言": "「大きな格言がある」は成り立たない。格言は短い教えの言葉。", "格式": "「大きな格式がある」は意味が通らない。格式は家柄や組織の伝統の高さを指す。", "格好": "「大きな格好がある」は不自然で、見た目の意味では文に合わない。"}, "sentence_index": 0, "correct_answer": "格差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この旅館は格差で泊まれる。", "explanation": "ここは〈格安〉（料金が安い）の意味。格差は程度の違いを指し、料金が安いことは表さない。"}, {"text": "ファイルを格差に保存した。", "explanation": "ここは〈格納〉（しまう・収める）の意味。格差は程度の違いを表すので、物を収めることには使わない。"}, {"text": "先生が格差を教えてくれた。", "explanation": "ここは〈格言〉（教訓の言葉）の意味。格差は程度の違いを指すので、教訓の言葉の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39046, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "格差", "is_correct": true, "explanation": "正解。「国民の間の格差が大きい」は社会的な差を表し、文に合う。"}, {"text": "格子", "is_correct": false, "explanation": "「国民の間の格子が大きい」は成り立たない。格子は格子状の模様や構造。"}, {"text": "格段", "is_correct": false, "explanation": "副詞的に使う語で、「格段が大きい」の名詞の用法は不自然。"}, {"text": "格上", "is_correct": false, "explanation": "実力や地位が上の相手を指すので、「国民の間の格上」は文が通らない。"}], "explanations": {"格差": "正解。「国民の間の格差が大きい」は社会的な差を表し、文に合う。", "格子": "「国民の間の格子が大きい」は成り立たない。格子は格子状の模様や構造。", "格段": "副詞的に使う語で、「格段が大きい」の名詞の用法は不自然。", "格上": "実力や地位が上の相手を指すので、「国民の間の格上」は文が通らない。"}, "sentence_index": 6, "correct_answer": "格差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "床に格差があって、つまずきそうになった。", "explanation": "ここは〈段差〉（高低の差）の意味。格差は人や国の間の程度の違いで、床の高低には使わない。"}, {"text": "社員を格差に上げた。", "explanation": "ここは〈格上げ〉（地位を上げる）の意味。格差は程度の違いの意味で、地位を上げることには使わない。"}, {"text": "新しい部屋が格差に広くなった。", "explanation": "ここは〈格段〉（ひときわ、ずっと）の意味。格差は差の程度を表す語で、副詞的に強める使い方はできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
