INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39047, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "状態や能力などに差があること。特に、社会的・経済的な不平等を指すことが多い。", "primary_collocate": null, "pronunciation": "かくさ", "ipa": "kakɯsa", "syllable_count": 3, "sentences": [{"text": "収入の格差が広がり、生活が苦しい人が増えた。", "target_word": "格差", "complexity_tier": "T3", "furigana": "収入[しゅうにゅう]の格差[かくさ]が広[ひろ]がり、生活[せいかつ]が苦[くる]しい人[ひと]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "政府は、格差を縮めるために税金の制度を変えた。", "target_word": "格差", "complexity_tier": "T3", "furigana": "政府[せいふ]は、格差[かくさ]を縮[ちぢ]めるために税金[ぜいきん]の制度[せいど]を変[か]えた。", "sentence_source": "generated"}, {"text": "金持ちと貧しい人の格差が、社会の問題になっている。", "target_word": "格差", "complexity_tier": "T3", "furigana": "金持[かねも]ちと貧[まず]しい人[ひと]の格差[かくさ]が、社会[しゃかい]の問題[もんだい]になっている。", "sentence_source": "generated"}, {"text": "仕事の機会に格差があってはいけない。", "target_word": "格差", "complexity_tier": "T3", "furigana": "仕事[しごと]の機会[きかい]に格差[かくさ]があってはいけない。", "sentence_source": "generated"}, {"text": "同じ仕事なのに給料に格差があるのは不公平だ。", "target_word": "格差", "complexity_tier": "T3", "furigana": "同[おな]じ仕事[しごと]なのに給料[きゅうりょう]に格差[かくさ]があるのは不公平[ふこうへい]だ。", "sentence_source": "generated"}, {"text": "選手の間の実力の格差が大きく、試合は一方的だった。", "target_word": "格差", "complexity_tier": "T3", "furigana": "選手[せんしゅ]の間[あいだ]の実力[じつりょく]の格差[かくさ]が大[おお]きく、試合[しあい]は一方的[いっぽうてき]だった。", "sentence_source": "generated"}, {"text": "親の仕事によって子どもの将来に格差が出るのは問題だ。", "target_word": "格差", "complexity_tier": "T3", "furigana": "親[おや]の仕事[しごと]によって子[こ]どもの将来[しょうらい]に格差[かくさ]が出[で]るのは問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "学力の格差を減らすために、無料の塾が作られた。", "target_word": "格差", "complexity_tier": "T3", "furigana": "学力[がくりょく]の格差[かくさ]を減[へ]らすために、無料[むりょう]の塾[じゅく]が作[つく]られた。", "sentence_source": "generated"}, {"text": "若者と高齢者の間の格差について、議論が続いている。", "target_word": "格差", "complexity_tier": "T3", "furigana": "若者[わかもの]と高齢者[こうれいしゃ]の間[あいだ]の格差[かくさ]について、議論[ぎろん]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "大きな格差を放っておくと、社会は不安定になる。", "target_word": "格差", "complexity_tier": "T3", "furigana": "大[おお]きな格差[かくさ]を放[ほう]っておくと、社会[しゃかい]は不安定[ふあんてい]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "格差", "label": "基本形"}, {"form": "格差の", "label": "連体修飾形"}, {"form": "格差を", "label": "目的語を表す形"}], "register": "中立", "sense_fingerprint": "状態や能力の差。特に社会的・経済的な不平等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b805d309-ed0d-4afe-a0c9-16e05b3d5c5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39047, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "格差", "is_correct": true, "explanation": "正解。「収入の格差が広がり」は収入の差を表し、文に合う。"}, {"text": "格好", "is_correct": false, "explanation": "「収入の格好が広がり」は意味が通らない。格好は見た目や姿。"}, {"text": "格闘", "is_correct": false, "explanation": "「収入の格闘が広がり」は成り立たない。格闘は激しく争うこと。"}, {"text": "格納", "is_correct": false, "explanation": "「収入の格納が広がり」は不自然。格納はしまい込むこと。"}], "explanations": {"格差": "正解。「収入の格差が広がり」は収入の差を表し、文に合う。", "格好": "「収入の格好が広がり」は意味が通らない。格好は見た目や姿。", "格闘": "「収入の格闘が広がり」は成り立たない。格闘は激しく争うこと。", "格納": "「収入の格納が広がり」は不自然。格納はしまい込むこと。"}, "sentence_index": 0, "correct_answer": "格差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "そのホテルは格差が上がって、星が増えた。", "explanation": "ここは〈格付け〉（等級）の意味。格差は差の大きさを言い、等級が上がる意味では使わない。"}, {"text": "玄関に格差があって、つまずきそうになった。", "explanation": "ここは〈段差〉（高低の差）の意味。格差は人や状態の差で、床の高低には使わない。"}, {"text": "この店は格差で料理を提供している。", "explanation": "ここは〈格安〉（料金が安い）の意味。格差は差を表す語で、安さを表す副詞的な使い方はできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39047, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "格差", "is_correct": true, "explanation": "正解。「子どもの将来に格差が出る」は社会的な差を表し、文に合う。"}, {"text": "格子", "is_correct": false, "explanation": "「将来に格子が出る」は意味が通らない。格子は格子状の構造。"}, {"text": "格段", "is_correct": false, "explanation": "副詞的に使う語で、「格段が出る」の名詞の用法は不自然。"}, {"text": "格上", "is_correct": false, "explanation": "実力や地位が上の相手を指すので、「将来に格上が出る」は文が通らない。"}], "explanations": {"格差": "正解。「子どもの将来に格差が出る」は社会的な差を表し、文に合う。", "格子": "「将来に格子が出る」は意味が通らない。格子は格子状の構造。", "格段": "副詞的に使う語で、「格段が出る」の名詞の用法は不自然。", "格上": "実力や地位が上の相手を指すので、「将来に格上が出る」は文が通らない。"}, "sentence_index": 6, "correct_answer": "格差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "文章の格差を直して、読みやすくした。", "explanation": "ここは〈推敲〉（文章を練り直す）の意味。格差は差の程度を表す語で、文章を練り直す意味は表さない。"}, {"text": "彼の服の格差は、とても洒落ている。", "explanation": "ここは〈格好〉（見た目・身なり）の意味。格差は差の程度を表す語で、服の見た目を言う語ではない。"}, {"text": "その人は格差の高い仕事を選んだ。", "explanation": "ここは〈格式〉（身分・地位の高さ）の意味。格差は差の大きさを表す語で、地位の高さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99746d12-61a8-4370-a4eb-6f0fe9e1a57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
