INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39048, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「会社の財政」と所有・所属を表すので「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「会社を財政」では名詞同士がつながらず非文。"}, {"text": "へ", "is_correct": false, "explanation": "「会社へ財政」では修飾関係にならず非文。"}, {"text": "から", "is_correct": false, "explanation": "「会社から財政は大丈夫です」では意味が通らず不自然。"}], "correct_answer": "の", "explanations": {"の": "「会社の財政」と所有・所属を表すので「の」が正しい。", "を": "「会社を財政」では名詞同士がつながらず非文。", "へ": "「会社へ財政」では修飾関係にならず非文。", "から": "「会社から財政は大丈夫です」では意味が通らず不自然。"}, "error_tags": {"を": "object_marker", "へ": "direction", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
