INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39048, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国や会社などのお金のことを言う言葉です。", "primary_collocate": null, "pronunciation": "ざいせい", "ipa": "dzaiseː", "syllable_count": 4, "sentences": [{"text": "市の財政は赤字だ。", "target_word": "財政", "complexity_tier": "T2", "furigana": "しのざいせいはあかじだ。", "sentence_source": "generated"}, {"text": "会社の財政は大丈夫です。", "target_word": "財政", "complexity_tier": "T2", "furigana": "かいしゃのざいせいはだいじょうぶです。", "sentence_source": "generated"}, {"text": "財政が苦しい。", "target_word": "財政", "complexity_tier": "T1", "furigana": "ざいせいがくるしい。", "sentence_source": "generated"}, {"text": "国の財政について話した。", "target_word": "財政", "complexity_tier": "T2", "furigana": "くにのざいせいについてはなした。", "sentence_source": "generated"}, {"text": "学校の財政を調べました。", "target_word": "財政", "complexity_tier": "T2", "furigana": "がっこうのざいせいをしらべました。", "sentence_source": "generated"}, {"text": "財政が悪くなって、会社は人を減らした。", "target_word": "財政", "complexity_tier": "T3", "furigana": "ざいせいがわるくなって、かいしゃはひとをへらした。", "sentence_source": "generated"}, {"text": "町は財政が厳しいので、新しい道路を作れない。", "target_word": "財政", "complexity_tier": "T3", "furigana": "まちはざいせいがきびしいので、あたらしいどうろをつくれない。", "sentence_source": "generated"}, {"text": "財政を良くするために、無駄を減らしている。", "target_word": "財政", "complexity_tier": "T3", "furigana": "ざいせいをよくするために、むだをへらしている。", "sentence_source": "generated"}, {"text": "財政の勉強をすると、ニュースがよく分かる。", "target_word": "財政", "complexity_tier": "T3", "furigana": "ざいせいのべんきょうをすると、ニュースがよくわかる。", "sentence_source": "generated"}, {"text": "財政が厳しくて、工事が止まってしまった。", "target_word": "財政", "complexity_tier": "T3", "furigana": "ざいせいがきびしくて、こうじがとまってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "財政的", "label": "派生"}, {"form": "財政難", "label": "派生"}, {"form": "財政上", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 国や会社のお金に関すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96f6e4-9414-4db2-8218-4b424363511e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39048, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "財政", "is_correct": true, "explanation": "「ざいせい」で、正解の見出し語。"}, {"text": "再生", "is_correct": false, "explanation": "「さいせい」で、最初の「ざ」が「さ」に変わるだけの一拍違い。"}, {"text": "体制", "is_correct": false, "explanation": "「たいせい」で、最初の一拍だけが違う。"}, {"text": "内政", "is_correct": false, "explanation": "「ないせい」で、最初の一拍だけが違う。"}, {"text": "在籍", "is_correct": false, "explanation": "「ざいせき」で、最後の一拍だけが違う。"}], "explanations": {"財政": "「ざいせい」で、正解の見出し語。", "再生": "「さいせい」で、最初の「ざ」が「さ」に変わるだけの一拍違い。", "体制": "「たいせい」で、最初の一拍だけが違う。", "内政": "「ないせい」で、最初の一拍だけが違う。", "在籍": "「ざいせき」で、最後の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "財政"}, "level_3": {"options": [{"text": "財政", "is_correct": true, "explanation": "市のお金の状況を指し、「赤字だ」と意味が合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気が赤字になることはない。"}, {"text": "気分", "is_correct": false, "explanation": "形は合うが、「市の気分」は赤字にならない。"}, {"text": "言葉", "is_correct": false, "explanation": "形は合うが、言葉が赤字になることはない。"}], "explanations": {"財政": "市のお金の状況を指し、「赤字だ」と意味が合う。", "天気": "形は合うが、天気が赤字になることはない。", "気分": "形は合うが、「市の気分」は赤字にならない。", "言葉": "形は合うが、言葉が赤字になることはない。"}, "sentence_index": 0, "correct_answer": "財政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、財政を飲んでから学校へ行く。", "explanation": "財政は飲み物ではなく、お金に関する事柄なので「飲む」の対象にならない。"}, {"text": "この箱は財政が重くて、運べない。", "explanation": "財政は物の重さを表さず、意味の使い方が誤り。"}, {"text": "空に財政が三つ浮かんでいる。", "explanation": "財政は空に浮かぶ物ではなく、物として数えられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39048, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "財政", "is_correct": true, "explanation": "「ざいせい」で、正解の見出し語。"}, {"text": "改正", "is_correct": false, "explanation": "「かいせい」で、最初の一拍だけが違う。"}, {"text": "名声", "is_correct": false, "explanation": "「めいせい」で、最初の一拍だけが違う。"}, {"text": "財形", "is_correct": false, "explanation": "「ざいけい」で、三拍目だけが違う。"}, {"text": "精製", "is_correct": false, "explanation": "「せいせい」で、最初の一拍だけが違う。"}], "explanations": {"財政": "「ざいせい」で、正解の見出し語。", "改正": "「かいせい」で、最初の一拍だけが違う。", "名声": "「めいせい」で、最初の一拍だけが違う。", "財形": "「ざいけい」で、三拍目だけが違う。", "精製": "「せいせい」で、最初の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "財政"}, "level_3": {"options": [{"text": "財政", "is_correct": true, "explanation": "町のお金の状況を指し、「厳しいので道路を作れない」と意味が合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、道路を作れない理由としては意味が合わない。"}, {"text": "気分", "is_correct": false, "explanation": "形は合うが、町について言う語として意味が合わない。"}, {"text": "景色", "is_correct": false, "explanation": "形は合うが、「厳しい」とは意味が合わない。"}], "explanations": {"財政": "町のお金の状況を指し、「厳しいので道路を作れない」と意味が合う。", "天気": "形は合うが、道路を作れない理由としては意味が合わない。", "気分": "形は合うが、町について言う語として意味が合わない。", "景色": "形は合うが、「厳しい」とは意味が合わない。"}, "sentence_index": 6, "correct_answer": "財政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "財政が甘くて、ケーキよりおいしい。", "explanation": "財政は味を持つ物ではなく、「甘い」で味を表すのは誤り。"}, {"text": "財政を着て、寒い冬の朝に外へ出た。", "explanation": "財政は服ではなく、「着る」の対象にならない。"}, {"text": "友達と財政を走ったら、足が痛くなった。", "explanation": "財政は走る場所や道ではなく、使い方が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39048, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社の財政が冷たくて、給料が払えなくなった。", "corrected_sentence": "会社の財政が苦しくて、給料が払えなくなった。", "error_description": "「財政」は「苦しい・厳しい」と言い、「冷たい」とは結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39048, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "財政が狭くて、工事が止まってしまった。", "corrected_sentence": "財政が厳しくて、工事が止まってしまった。", "error_description": "「財政」は「厳しい・苦しい」と言い、「狭い」とは結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
