INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39049, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「担当する」の目的語を示すので「を」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「財政へ担当する」では動詞と合わず非文。"}, {"text": "から", "is_correct": false, "explanation": "「財政から担当する」は、この文の意味にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「財政と担当する大臣」では修飾関係が成り立たず非文。"}], "correct_answer": "を", "explanations": {"を": "「担当する」の目的語を示すので「を」が正しい。", "へ": "「財政へ担当する」では動詞と合わず非文。", "から": "「財政から担当する」は、この文の意味にならず不自然。", "と": "「財政と担当する大臣」では修飾関係が成り立たず非文。"}, "error_tags": {"へ": "direction", "から": "source", "と": "companion"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39049, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国家や自治体などが、税金などの収入を基に、公共サービスや事業を行うための資金のやりくりに関する事項。", "primary_collocate": null, "pronunciation": "ざいせい", "ipa": "dzaiseː", "syllable_count": 4, "sentences": [{"text": "イールドカーブ・コントロールの下では、市場メカニズムを通じた適正なリスクプレミアムの形成が阻害され、結果として財政の持続可能性を担保するべき債務の価格的シグナルが鈍磨する懸念が拭えない。", "target_word": "財政", "complexity_tier": "T6", "furigana": "イールドカーブ・コントロールのもとでは、しじょうメカニズムをつうじたてきせいなリスクプレミアムのけいせいがそがいされ、けっかとしてざいせいのじぞくかのうせいをたんぽするべきさいむのかかくてきシグナルがどんまするけねんがぬぐえない。", "sentence_source": "mined"}, {"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "財政", "complexity_tier": "T6", "furigana": "さらに、こうしたひでんとうてきなきんゆうせいさくがインフレきたいのアンカーとしてきのうしえるいっぽうで、かじょうなりゅうどうせいがじったいけいざいにおけるぶっかじょうしょうあつりょくとそうじょうこうかをうみ、よきせぬスタグフレーションやざいせいしゅどうのシナリオへときけつするリスクをつねにないほうしていることを、われわれはれいてつににんしきするせきむをおっている。", "sentence_source": "mined"}, {"text": "国の財政は厳しい状況にある。", "target_word": "財政", "complexity_tier": "T2", "furigana": "くにのざいせいはきびしいじょうきょうにある。", "sentence_source": "generated"}, {"text": "市は財政を立て直すために、無駄な支出を減らした。", "target_word": "財政", "complexity_tier": "T4", "furigana": "しはざいせいをたてなおすために、むだなししゅつをへらした。", "sentence_source": "generated"}, {"text": "財政が苦しくなり、図書館が閉まった。", "target_word": "財政", "complexity_tier": "T3", "furigana": "ざいせいがくるしくなり、としょかんがしまった。", "sentence_source": "generated"}, {"text": "政府は財政の健全化を目指している。", "target_word": "財政", "complexity_tier": "T3", "furigana": "せいふはざいせいのけんぜんかをめざしている。", "sentence_source": "generated"}, {"text": "財政に余裕がある自治体は、まだ少ない。", "target_word": "財政", "complexity_tier": "T3", "furigana": "ざいせいによゆうがあるじちたいは、まだすくない。", "sentence_source": "generated"}, {"text": "財政を担当する大臣が、予算案を説明した。", "target_word": "財政", "complexity_tier": "T3", "furigana": "ざいせいをたんとうするだいじんが、よさんあんをせつめいした。", "sentence_source": "generated"}, {"text": "税収が減れば、国の財政はさらに悪化するだろう。", "target_word": "財政", "complexity_tier": "T4", "furigana": "ぜいしゅうがへれば、くにのざいせいはさらにあっかするだろう。", "sentence_source": "generated"}, {"text": "少子高齢化は、地方の財政に大きな負担をかけている。", "target_word": "財政", "complexity_tier": "T4", "furigana": "しょうしこうれいかは、ちほうのざいせいにおおきなふたんをかけている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "財政的", "label": "派生"}, {"form": "財政難", "label": "派生"}, {"form": "財政上", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 国や自治体の資金のやりくり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: スタグフレーション (Zipf 1.93)']::text[], 'dc96f6e4-9414-4db2-8218-4b424363511e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39049, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "財政", "is_correct": true, "explanation": "「ざいせい」で、正解の見出し語。"}, {"text": "再生", "is_correct": false, "explanation": "「さいせい」で、最初の「ざ」が「さ」に変わるだけの一拍違い。"}, {"text": "体制", "is_correct": false, "explanation": "「たいせい」で、最初の一拍だけが違う。"}, {"text": "内政", "is_correct": false, "explanation": "「ないせい」で、最初の一拍だけが違う。"}, {"text": "在籍", "is_correct": false, "explanation": "「ざいせき」で、最後の一拍だけが違う。"}, {"text": "財界", "is_correct": false, "explanation": "「ざいかい」で、三拍目だけが違う。"}], "explanations": {"財政": "「ざいせい」で、正解の見出し語。", "再生": "「さいせい」で、最初の「ざ」が「さ」に変わるだけの一拍違い。", "体制": "「たいせい」で、最初の一拍だけが違う。", "内政": "「ないせい」で、最初の一拍だけが違う。", "在籍": "「ざいせき」で、最後の一拍だけが違う。", "財界": "「ざいかい」で、三拍目だけが違う。"}, "sentence_index": null, "correct_answer": "財政"}, "level_3": {"options": [{"text": "財政", "is_correct": true, "explanation": "国の資金のやりくりを指し、「持続可能性を担保するべき債務」と意味が合う。"}, {"text": "気象", "is_correct": false, "explanation": "形は合うが、債務の持続可能性とは意味が合わない。"}, {"text": "感情", "is_correct": false, "explanation": "形は合うが、債務や市場の文脈に意味が合わない。"}, {"text": "地形", "is_correct": false, "explanation": "形は合うが、債務の価格的シグナルとは意味が合わない。"}], "explanations": {"財政": "国の資金のやりくりを指し、「持続可能性を担保するべき債務」と意味が合う。", "気象": "形は合うが、債務の持続可能性とは意味が合わない。", "感情": "形は合うが、債務や市場の文脈に意味が合わない。", "地形": "形は合うが、債務の価格的シグナルとは意味が合わない。"}, "sentence_index": 0, "correct_answer": "財政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夜、友達と財政を一緒に食べに行った。", "explanation": "財政は食べ物ではなく、資金のやりくりを表す語なので、「食べる」の対象にならない。"}, {"text": "この川は財政が深くて、泳ぐのは危険だ。", "explanation": "財政は川の深さのような物理的性質を表せず、意味の使い方が誤り。"}, {"text": "彼は財政が高いので、バスケットボールが得意だ。", "explanation": "財政を身長の意味で使っており、人の体の特徴を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39049, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "財政", "is_correct": true, "explanation": "「ざいせい」で、正解の見出し語。"}, {"text": "改正", "is_correct": false, "explanation": "「かいせい」で、最初の一拍だけが違う。"}, {"text": "名声", "is_correct": false, "explanation": "「めいせい」で、最初の一拍だけが違う。"}, {"text": "財形", "is_correct": false, "explanation": "「ざいけい」で、三拍目だけが違う。"}, {"text": "精製", "is_correct": false, "explanation": "「せいせい」で、最初の一拍だけが違う。"}], "explanations": {"財政": "「ざいせい」で、正解の見出し語。", "改正": "「かいせい」で、最初の一拍だけが違う。", "名声": "「めいせい」で、最初の一拍だけが違う。", "財形": "「ざいけい」で、三拍目だけが違う。", "精製": "「せいせい」で、最初の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "財政"}, "level_3": {"options": [{"text": "財政", "is_correct": true, "explanation": "自治体の資金事情を指し、「余裕がある」と意味が合う。"}, {"text": "気候", "is_correct": false, "explanation": "形は合うが、自治体の余裕とは意味が合わない。"}, {"text": "地形", "is_correct": false, "explanation": "形は合うが、「余裕がある」とは意味が合わない。"}, {"text": "言語", "is_correct": false, "explanation": "形は合うが、自治体の余裕とは意味が合わない。"}], "explanations": {"財政": "自治体の資金事情を指し、「余裕がある」と意味が合う。", "気候": "形は合うが、自治体の余裕とは意味が合わない。", "地形": "形は合うが、「余裕がある」とは意味が合わない。", "言語": "形は合うが、自治体の余裕とは意味が合わない。"}, "sentence_index": 6, "correct_answer": "財政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "財政が強く吹いて、洗濯物が飛んだ。", "explanation": "財政を風のような自然現象として使っており、資金のやりくりという意味に合わない。"}, {"text": "新しい財政を買って、毎日はいている。", "explanation": "財政は靴などの物ではなく、買ってはく対象にならない。"}, {"text": "財政が高い山に登って、景色を楽しんだ。", "explanation": "財政は山の名前や場所を表せず、「山」の修飾として誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39049, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市の財政が速いので、図書館を閉めた。", "corrected_sentence": "市の財政が苦しいので、図書館を閉めた。", "error_description": "「財政」は「苦しい・厳しい」と言い、「速い」とは結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39049, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "税収が減って財政が浅くなり、道路工事が止まった。", "corrected_sentence": "税収が減って財政が苦しくなり、道路工事が止まった。", "error_description": "「財政」は「苦しい・厳しい」と言い、「浅い」とは結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39050, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "寛大", "is_correct": true, "explanation": "寛大は人をきびしく咎めない意味で、厳格の対義語。厳しい人物像と対になる。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は明るい性格を表し、厳しさの反対を表す語ではないので対義語ではない。"}, {"text": "大胆", "is_correct": false, "explanation": "大胆は物怖じしない意味で、厳格の反対語にはならない。"}, {"text": "冷静", "is_correct": false, "explanation": "冷静は感情に流されない意味で、厳格とは別の性質なので対義語ではない。"}], "correct_answer": "寛大", "explanations": {"寛大": "寛大は人をきびしく咎めない意味で、厳格の対義語。厳しい人物像と対になる。", "陽気": "陽気は明るい性格を表し、厳しさの反対を表す語ではないので対義語ではない。", "大胆": "大胆は物怖じしない意味で、厳格の反対語にはならない。", "冷静": "冷静は感情に流されない意味で、厳格とは別の性質なので対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39050, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "寛大", "is_correct": true, "explanation": "寛大は人のあやまちを厳しく咎めない意味で、厳格の対義語。師匠の厳しさと対になる。"}, {"text": "上品", "is_correct": false, "explanation": "上品は品位のよさを表し、厳しさの反対を表す語ではないので対義語ではない。"}, {"text": "器用", "is_correct": false, "explanation": "器用は手先がうまく動く意味で、厳格とは別の性質なので対義語ではない。"}, {"text": "活発", "is_correct": false, "explanation": "活発は動きが盛んな様子を表し、厳格の反対語にはならない。"}], "correct_answer": "寛大", "explanations": {"寛大": "寛大は人のあやまちを厳しく咎めない意味で、厳格の対義語。師匠の厳しさと対になる。", "上品": "上品は品位のよさを表し、厳しさの反対を表す語ではないので対義語ではない。", "器用": "器用は手先がうまく動く意味で、厳格とは別の性質なので対義語ではない。", "活発": "活発は動きが盛んな様子を表し、厳格の反対語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39050, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とてもしっかりしていて、ルールをかならず守ること。", "primary_collocate": null, "pronunciation": "げんかく", "ipa": "ɡeŋkakɯ", "syllable_count": 4, "sentences": [{"text": "父は厳格な人で、約束の時間に遅れると必ず叱った。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "父[ちち]は厳格[げんかく]な人[ひと]で、約束[やくそく]の時間[じかん]に遅[おく]れると必[かなら]ず叱[しか]った。", "sentence_source": "generated"}, {"text": "祖父は厳格だったので、子どもの私たちも礼儀を守った。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "祖父[そふ]は厳格[げんかく]だったので、子[こ]どもの私[わたし]たちも礼儀[れいぎ]を守[まも]った。", "sentence_source": "generated"}, {"text": "厳格な先生のクラスでは、だれも宿題を忘れない。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "厳格[げんかく]な先生[せんせい]のクラスでは、だれも宿題[しゅくだい]を忘[わす]れない。", "sentence_source": "generated"}, {"text": "彼女は自分にも他人にも厳格で、ルールを破ることがない。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]にも他人[たにん]にも厳格[げんかく]で、ルールを破[やぶ]ることがない。", "sentence_source": "generated"}, {"text": "厳格な家庭に育ったので、夜遅く出かけたことがなかった。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "厳格[げんかく]な家庭[かてい]に育[そだ]ったので、夜遅[よるおそ]く出[で]かけたことがなかった。", "sentence_source": "generated"}, {"text": "母は厳格な性格だが、本当はとてもやさしい。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "母[はは]は厳格[げんかく]な性格[せいかく]だが、本当[ほんとう]はとてもやさしい。", "sentence_source": "generated"}, {"text": "厳格な監督のもとで、選手たちは毎朝同じ練習をくり返した。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "厳格[げんかく]な監督[かんとく]のもとで、選手[せんしゅ]たちは毎朝[まいあさ]同[おな]じ練習[れんしゅう]をくり返[かえ]した。", "sentence_source": "generated"}, {"text": "あの校長は厳格なことで有名で、制服の乱れも見逃さない。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "あの校長[こうちょう]は厳格[げんかく]なことで有名[ゆうめい]で、制服[せいふく]の乱[みだ]れも見逃[みのが]さない。", "sentence_source": "generated"}, {"text": "厳格に育てられた兄は、今もきちんと時間を守る。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "厳格[げんかく]に育[そだ]てられた兄[あに]は、今[いま]もきちんと時間[じかん]を守[まも]る。", "sentence_source": "generated"}, {"text": "厳格な師匠は、弟子のまちがいを一度も許さなかった。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "厳格[げんかく]な師匠[ししょう]は、弟子[でし]のまちがいを一度[いちど]も許[ゆる]さなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "厳格だ", "label": "終止形"}, {"form": "厳格な", "label": "連体形"}, {"form": "厳格に", "label": "連用形"}, {"form": "厳格で", "label": "連用形(て形)"}], "register": "neutral", "sense_fingerprint": "人の性格・態度がきびしく、決まりを必ず守らせる・守る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a9d509c-8b22-4e3f-930f-2c4fe6e564c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39050, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厳格", "is_correct": true, "explanation": "「厳格な人」で、約束の遅刻を必ず叱る厳しさに合う。"}, {"text": "寛大", "is_correct": false, "explanation": "寛大は人をとがめない意味で、「必ず叱った」と矛盾する。"}, {"text": "甘い", "is_correct": false, "explanation": "甘いは厳しさがない意味で、「必ず叱った」と矛盾する。"}, {"text": "不器用", "is_correct": false, "explanation": "不器用は手先の動きが苦手な意味で、遅刻への叱責と結びつかない。"}], "explanations": {"厳格": "「厳格な人」で、約束の遅刻を必ず叱る厳しさに合う。", "寛大": "寛大は人をとがめない意味で、「必ず叱った」と矛盾する。", "甘い": "甘いは厳しさがない意味で、「必ず叱った」と矛盾する。", "不器用": "不器用は手先の動きが苦手な意味で、遅刻への叱責と結びつかない。"}, "sentence_index": 0, "correct_answer": "厳格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年の厳格な寒さで、水道管が凍った。", "explanation": "ここは〈厳しい〉の意味。厳しい寒さが普通の言い方で、厳格は人や規則に使う語なので天候には合わない。"}, {"text": "会社の金庫は厳格な扉で守られている。", "explanation": "ここは〈厳重〉の意味。扉や警備の堅固さには厳重を使い、厳格（規則を守らせる厳しさ）は合わない。"}, {"text": "この計算は厳格で、少しの誤差もない。", "explanation": "ここは〈厳密〉の意味。数値や論理の精密さには厳密を使い、厳格は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39050, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厳格", "is_correct": true, "explanation": "「厳格な監督」で、毎朝同じ練習を繰り返させる厳しい指導に合う。"}, {"text": "気楽", "is_correct": false, "explanation": "気楽は気兼ねがない意味で、同じ練習を繰り返す指導と合わない。"}, {"text": "甘い", "is_correct": false, "explanation": "甘いは指導がゆるい意味で、毎朝同じ練習を繰り返させる指導と矛盾する。"}, {"text": "大らか", "is_correct": false, "explanation": "大らかは細かく咎めない性格で、同じ練習を繰り返させる指導と矛盾する。"}], "explanations": {"厳格": "「厳格な監督」で、毎朝同じ練習を繰り返させる厳しい指導に合う。", "気楽": "気楽は気兼ねがない意味で、同じ練習を繰り返す指導と合わない。", "甘い": "甘いは指導がゆるい意味で、毎朝同じ練習を繰り返させる指導と矛盾する。", "大らか": "大らかは細かく咎めない性格で、同じ練習を繰り返させる指導と矛盾する。"}, "sentence_index": 6, "correct_answer": "厳格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その山は厳格で、登る者を寄せつけなかった。", "explanation": "ここは〈峻厳〉の意味。険しく近づきがたい山の様子には峻厳を使い、厳格（規則への厳しさ）は合わない。"}, {"text": "この知らせは厳格で、社員たちは言葉を失った。", "explanation": "ここは〈深刻〉の意味。事態の重大さには深刻を使い、厳格（規則を守らせる厳しさ）は合わない。"}, {"text": "この店は厳格な食材だけを使っている。", "explanation": "ここは〈厳選〉の意味。良いものを選び抜く意味で、厳格（規則への厳しさ）は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39050, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は厳格に性格で、宿題を忘れると必ず注意した。", "corrected_sentence": "兄は厳格な性格で、宿題を忘れると必ず注意した。", "error_description": "正しくは「厳格な性格」（連体修飾の「な」）。「厳格に」は連用形で、名詞「性格」を直接修飾できない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "厳格", "is_correct": true, "explanation": "「祖父は厳格だったので」の語幹。過去の「だった」の前に来る形。"}, {"text": "厳格な", "is_correct": false, "explanation": "連体形で、「だった」の前に置くと「厳格なだった」となり文が成り立たない。"}, {"text": "厳格ではない", "is_correct": false, "explanation": "否定形で、「ではないだったので」となり二重の判断になって不自然。"}, {"text": "厳格なら", "is_correct": false, "explanation": "仮定形で、「だった」の前には置けず文が成り立たない。"}], "correct_form": "厳格", "base_form": "厳格だ", "form_label": "「だった」の前の語幹", "sentence_index": 1, "explanations": {"厳格": "「祖父は厳格だったので」の語幹。過去の「だった」の前に来る形。", "厳格な": "連体形で、「だった」の前に置くと「厳格なだった」となり文が成り立たない。", "厳格ではない": "否定形で、「ではないだったので」となり二重の判断になって不自然。", "厳格なら": "仮定形で、「だった」の前には置けず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39050, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叔父は厳格を、約束を破った人を二度と家に入れない。", "corrected_sentence": "叔父は厳格で、約束を破った人を二度と家に入れない。", "error_description": "正しくは「厳格で」（状態を表す「で」）。「を」は目的格で、形状詞「厳格」の後には続かず文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "厳格", "is_correct": true, "explanation": "「あの校長は厳格なことで」の語幹。「なこと」の前に来る形。"}, {"text": "厳格だ", "is_correct": false, "explanation": "断定形で、「なこと」の前には置けず「厳格だなこと」となる。"}, {"text": "厳格で", "is_correct": false, "explanation": "て形で、「なこと」の前には続かず文が成り立たない。"}, {"text": "厳格だろう", "is_correct": false, "explanation": "推量形で、「なこと」と続けると不自然で文が成り立たない。"}], "correct_form": "厳格", "base_form": "厳格だ", "form_label": "連体修飾「な」の前の語幹", "sentence_index": 7, "explanations": {"厳格": "「あの校長は厳格なことで」の語幹。「なこと」の前に来る形。", "厳格だ": "断定形で、「なこと」の前には置けず「厳格だなこと」となる。", "厳格で": "て形で、「なこと」の前には続かず文が成り立たない。", "厳格だろう": "推量形で、「なこと」と続けると不自然で文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
