INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39051, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "規則や基準に従って、少しのゆるみもなく行動や状態をきちんと管理すること。", "primary_collocate": null, "pronunciation": "げんかく", "ipa": "ɡeŋkakɯ", "syllable_count": 4, "sentences": [{"text": "この工場では品質を厳格に管理している。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では品質[ひんしつ]を厳格[げんかく]に管理[かんり]している。", "sentence_source": "generated"}, {"text": "試験会場では、持ち物の検査が厳格に行われた。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "試験会場[しけんかいじょう]では、持[も]ち物[もの]の検査[けんさ]が厳格[げんかく]に行[おこな]われた。", "sentence_source": "generated"}, {"text": "食品の安全基準は厳格で、少しの違反も認められない。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "食品[しょくひん]の安全基準[あんぜんきじゅん]は厳格[げんかく]で、少[すこ]しの違反[いはん]も認[みと]められない。", "sentence_source": "generated"}, {"text": "会社は情報の取り扱いに厳格なルールを設けた。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は情報[じょうほう]の取[と]り扱[あつか]いに厳格[げんかく]なルールを設[もう]けた。", "sentence_source": "generated"}, {"text": "空港では入国の審査が厳格なので、時間がかかる。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "空港[くうこう]では入国[にゅうこく]の審査[しんさ]が厳格[げんかく]なので、時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "薬の量は厳格に守らないと、体に悪い。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "薬[くすり]の量[りょう]は厳格[げんかく]に守[まも]らないと、体[からだ]に悪[わる]い。", "sentence_source": "generated"}, {"text": "厳格な管理のおかげで、事故はほとんど起きていない。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "厳格[げんかく]な管理[かんり]のおかげで、事故[じこ]はほとんど起[お]きていない。", "sentence_source": "generated"}, {"text": "校則が厳格すぎて、髪の色を変えることもできない。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "校則[こうそく]が厳格[げんかく]すぎて、髪[かみ]の色[いろ]を変[か]えることもできない。", "sentence_source": "generated"}, {"text": "図書館は本の返却期限を厳格に決めている。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "図書館[としょかん]は本[ほん]の返却期限[へんきゃくきげん]を厳格[げんかく]に決[き]めている。", "sentence_source": "generated"}, {"text": "温度の管理が厳格でなければ、このワインは作れない。", "target_word": "厳格", "complexity_tier": "T3", "furigana": "温度[おんど]の管理[かんり]が厳格[げんかく]でなければ、このワインは作[つく]れない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "厳格だ", "label": "終止形"}, {"form": "厳格な", "label": "連体形"}, {"form": "厳格に", "label": "連用形"}, {"form": "厳格で", "label": "連用形(て形)"}], "register": "neutral", "sense_fingerprint": "規則・基準・管理・検査が少しのゆるみもなくきびしい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a9d509c-8b22-4e3f-930f-2c4fe6e564c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39051, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厳格", "is_correct": true, "explanation": "「品質を厳格に管理」の副詞形で、基準にゆるみがない管理の仕方に合う。"}, {"text": "賑やか", "is_correct": false, "explanation": "賑やかは場や人が活気づく様子で、品質管理の仕方には使えない。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は性格や雰囲気を表し、品質を管理する方法を説明する語ではない。"}, {"text": "上品", "is_correct": false, "explanation": "上品は品位のよさを表し、品質を管理する仕方とは結びつかない。"}], "explanations": {"厳格": "「品質を厳格に管理」の副詞形で、基準にゆるみがない管理の仕方に合う。", "賑やか": "賑やかは場や人が活気づく様子で、品質管理の仕方には使えない。", "陽気": "陽気は性格や雰囲気を表し、品質を管理する方法を説明する語ではない。", "上品": "上品は品位のよさを表し、品質を管理する仕方とは結びつかない。"}, "sentence_index": 0, "correct_answer": "厳格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場の入口は厳格な鍵で守られている。", "explanation": "ここは〈厳重〉の意味。鍵や守りの堅さには厳重を使い、厳格（規則への厳しさ）は合わない。"}, {"text": "この山道は厳格な坂が続いて、息が切れた。", "explanation": "ここは〈険しい〉の意味。急な坂の様子には険しいを使い、厳格（基準を守らせる厳しさ）は合わない。"}, {"text": "このワインは厳格な香りで、口に含むと果実の味が広がる。", "explanation": "ここは〈芳醇〉の意味。香りや味の豊かさには芳醇を使い、厳格（基準を守らせる厳しさ）は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39051, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厳格", "is_correct": true, "explanation": "「厳格な管理」で、基準を守らせ事故を防ぐ管理の仕方に合う。"}, {"text": "気楽", "is_correct": false, "explanation": "気楽は気兼ねがない意味で、事故を防ぐ管理とは結びつかない。"}, {"text": "無頓着", "is_correct": false, "explanation": "無頓着は気にかけない意味で、事故がほとんど起きていない理由にはならない。"}, {"text": "不器用", "is_correct": false, "explanation": "不器用は手先が苦手な意味で、管理の仕方を表す語ではない。"}], "explanations": {"厳格": "「厳格な管理」で、基準を守らせ事故を防ぐ管理の仕方に合う。", "気楽": "気楽は気兼ねがない意味で、事故を防ぐ管理とは結びつかない。", "無頓着": "無頓着は気にかけない意味で、事故がほとんど起きていない理由にはならない。", "不器用": "不器用は手先が苦手な意味で、管理の仕方を表す語ではない。"}, "sentence_index": 6, "correct_answer": "厳格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "気温が厳格に下がり、夜には霜が降りた。", "explanation": "ここは〈急激〉の意味。急に大きく変わる様子には急激を使い、厳格は規則を守らせる厳しさを表すので合わない。"}, {"text": "部屋の壁は厳格な色で塗られていた。", "explanation": "ここは〈派手〉の意味。目立つ明るい色には派手を使い、厳格（基準を守らせる厳しさ）は合わない。"}, {"text": "彼は厳格な知識を持ち、質問にすぐ答えた。", "explanation": "ここは〈豊富〉の意味。量が多いことには豊富を使い、厳格は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39051, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店では食材の産地を厳格な確かめている。", "corrected_sentence": "この店では食材の産地を厳格に確かめている。", "error_description": "正しくは「厳格に確かめている」（動詞を修飾する連用形の「に」）。「厳格な」は連体形で、動詞「確かめる」の前には置けない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "厳格", "is_correct": true, "explanation": "「検査が厳格に行われた」の語幹。「に行われた」の前に来る連用形。"}, {"text": "厳格な", "is_correct": false, "explanation": "連体形で、「検査が厳格な行われた」となり文が成り立たない。"}, {"text": "厳格だ", "is_correct": false, "explanation": "断定形で、「検査が厳格だ行われた」となり文が成り立たない。"}, {"text": "厳格ではない", "is_correct": false, "explanation": "否定形で、「検査が厳格ではない行われた」となり文が成り立たない。"}], "correct_form": "厳格", "base_form": "厳格だ", "form_label": "連用形「に」の前", "sentence_index": 1, "explanations": {"厳格": "「検査が厳格に行われた」の語幹。「に行われた」の前に来る連用形。", "厳格な": "連体形で、「検査が厳格な行われた」となり文が成り立たない。", "厳格だ": "断定形で、「検査が厳格だ行われた」となり文が成り立たない。", "厳格ではない": "否定形で、「検査が厳格ではない行われた」となり文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39051, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "検査員は部品の寸法を厳格を測っている。", "corrected_sentence": "検査員は部品の寸法を厳格に測っている。", "error_description": "正しくは「厳格に測っている」（「に」で動詞を修飾）。「を」は目的格で、「厳格を測る」は成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "厳格", "is_correct": true, "explanation": "「校則が厳格すぎて」の語幹。「すぎて」の前に来る形。"}, {"text": "厳格に", "is_correct": false, "explanation": "連用形「に」で、「厳格にすぎて」となり「すぎて」の前には置けず文が成り立たない。"}, {"text": "厳格だろう", "is_correct": false, "explanation": "推量形で、「だろうすぎて」となり文が成り立たない。"}, {"text": "厳格で", "is_correct": false, "explanation": "て形で、「厳格ですぎて」となり「すぎて」の前には置けず文が成り立たない。"}], "correct_form": "厳格", "base_form": "厳格だ", "form_label": "「すぎて」の前の語幹", "sentence_index": 7, "explanations": {"厳格": "「校則が厳格すぎて」の語幹。「すぎて」の前に来る形。", "厳格に": "連用形「に」で、「厳格にすぎて」となり「すぎて」の前には置けず文が成り立たない。", "厳格だろう": "推量形で、「だろうすぎて」となり文が成り立たない。", "厳格で": "て形で、「厳格ですぎて」となり「すぎて」の前には置けず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39054, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「恐れを顔に出す」の目的語。恐れを表に出さないという文の骨格に合う。"}, {"text": "が", "is_correct": false, "explanation": "「恐れが顔に出さず」では、他動詞「出す」の目的語が主語になり、文が不自然。"}, {"text": "に", "is_correct": false, "explanation": "「恐れに顔に出さず」は位置の「に」を置いても名詞と結びつかず、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「恐れで顔に出さず」は手段・原因の「で」だが、「出さず」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「恐れを顔に出す」の目的語。恐れを表に出さないという文の骨格に合う。", "が": "「恐れが顔に出さず」では、他動詞「出す」の目的語が主語になり、文が不自然。", "に": "「恐れに顔に出さず」は位置の「に」を置いても名詞と結びつかず、意味が通らない。", "で": "「恐れで顔に出さず」は手段・原因の「で」だが、「出さず」の目的語にならない。"}, "error_tags": {"が": "主格（主語）", "に": "位置・帰着", "で": "手段・原因"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勇気", "is_correct": true, "explanation": "勇気は怖がらない心の状態で、恐れの対義語。恐れと対になる感情を表す。"}, {"text": "喜び", "is_correct": false, "explanation": "喜びは楽しい感情で、恐れの対義語とはされない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は身体の状態で、恐れと対になる語ではない。"}, {"text": "誇り", "is_correct": false, "explanation": "誇りは自信や名誉の感情で、恐れの反対を表す語ではない。"}], "correct_answer": "勇気", "explanations": {"勇気": "勇気は怖がらない心の状態で、恐れの対義語。恐れと対になる感情を表す。", "喜び": "喜びは楽しい感情で、恐れの対義語とはされない。", "眠気": "眠気は身体の状態で、恐れと対になる語ではない。", "誇り": "誇りは自信や名誉の感情で、恐れの反対を表す語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39054, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「恐れを知らない」の目的語。恐れを知らないという意味の骨格を作る。"}, {"text": "と", "is_correct": false, "explanation": "「恐れと知らない」は並列の「と」だが、「知らない」の対象として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「恐れへ知らない」は方向の「へ」で、「知らない」の方向にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「恐れから知らない」は起点の「から」だが、「知らない」の起点にはならない。"}], "correct_answer": "を", "explanations": {"を": "「恐れを知らない」の目的語。恐れを知らないという意味の骨格を作る。", "と": "「恐れと知らない」は並列の「と」だが、「知らない」の対象として成り立たない。", "へ": "「恐れへ知らない」は方向の「へ」で、「知らない」の方向にはならない。", "から": "「恐れから知らない」は起点の「から」だが、「知らない」の起点にはならない。"}, "error_tags": {"と": "並列・引用", "へ": "方向", "から": "起点・理由"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勇気", "is_correct": true, "explanation": "勇気は怖がらず立ち向かう心の状態で、恐れの対義語。暗闇で前へ進む姿と対になる。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は人の好意に応える気持ちで、恐れの反対を表す語ではない。"}, {"text": "好奇心", "is_correct": false, "explanation": "好奇心は知りたい気持ちで、恐れの対義語とはされない。"}, {"text": "遠慮", "is_correct": false, "explanation": "遠慮は控えめにふるまう態度で、恐れと反対の意味関係にはない。"}], "correct_answer": "勇気", "explanations": {"勇気": "勇気は怖がらず立ち向かう心の状態で、恐れの対義語。暗闇で前へ進む姿と対になる。", "感謝": "感謝は人の好意に応える気持ちで、恐れの反対を表す語ではない。", "好奇心": "好奇心は知りたい気持ちで、恐れの対義語とはされない。", "遠慮": "遠慮は控えめにふるまう態度で、恐れと反対の意味関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39054, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "こわいと思う気持ちのこと。", "primary_collocate": null, "pronunciation": "おそれ", "ipa": "osoɾe", "syllable_count": 3, "sentences": [{"text": "暗い森に入ると、強い恐れを感じた。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "暗[くら]い森[もり]に入[はい]ると、強[つよ]い恐[おそ]れを感[かん]じた。", "sentence_source": "generated"}, {"text": "彼は恐れを顔に出さず、静かに話し始めた。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "彼[かれ]は恐[おそ]れを顔[かお]に出[だ]さず、静[しず]かに話[はな]し始[はじ]めた。", "sentence_source": "generated"}, {"text": "初めて飛行機に乗る前、私は恐れで手が震えた。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "初[はじ]めて飛行機[ひこうき]に乗[の]る前[まえ]、私[わたし]は恐[おそ]れで手[て]が震[ふる]えた。", "sentence_source": "generated"}, {"text": "子どもは雷への恐れから、布団にもぐりこんだ。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "子[こ]どもは雷[かみなり]への恐[おそ]れから、布団[ふとん]にもぐりこんだ。", "sentence_source": "generated"}, {"text": "恐れを抱いたまま、ドアをゆっくり開けた。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "恐[おそ]れを抱[いだ]いたまま、ドアをゆっくり開[あ]けた。", "sentence_source": "generated"}, {"text": "失敗への恐れがなくなって、前より自由に話せる。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "失敗[しっぱい]への恐[おそ]れがなくなって、前[まえ]より自由[じゆう]に話[はな]せる。", "sentence_source": "generated"}, {"text": "大きな犬を見た弟の目には、恐れが浮かんでいた。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "大[おお]きな犬[いぬ]を見[み]た弟[おとうと]の目[め]には、恐[おそ]れが浮[う]かんでいた。", "sentence_source": "generated"}, {"text": "恐れを知らない若者は、一人で山に登った。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "恐[おそ]れを知[し]らない若者[わかもの]は、一人[ひとり]で山[やま]に登[のぼ]った。", "sentence_source": "generated"}, {"text": "長い間、水に対する恐れを克服できなかった。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]、水[みず]に対[たい]する恐[おそ]れを克服[こくふく]できなかった。", "sentence_source": "generated"}, {"text": "暗闇の中、彼女は恐れに負けずに前へ進んだ。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "暗闇[くらやみ]の中[なか]、彼女[かのじょ]は恐[おそ]れに負[ま]けずに前[まえ]へ進[すす]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "恐れ", "label": "基本形"}, {"form": "恐れが", "label": "が格"}, {"form": "恐れを", "label": "を格"}, {"form": "恐れの", "label": "の格"}], "register": "neutral", "sense_fingerprint": "こわいと感じる心の状態(恐怖心)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: もぐりこん (Zipf 2.03)']::text[], '6a9d509c-8b22-4e3f-930f-2c4fe6e564c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39054, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恐れ", "is_correct": true, "explanation": "「強い恐れを感じた」で、暗い森に入った時の怖さに合う。"}, {"text": "喜び", "is_correct": false, "explanation": "喜びは明るい感情で、暗い森に入る場面の感覚と矛盾する。"}, {"text": "誇り", "is_correct": false, "explanation": "誇りは自信や名誉に関する感情で、暗い森の場面とは結びつかない。"}, {"text": "照れ", "is_correct": false, "explanation": "照れは人前での気恥ずかしさで、暗い森で一人のときの感覚に合わない。"}], "explanations": {"恐れ": "「強い恐れを感じた」で、暗い森に入った時の怖さに合う。", "喜び": "喜びは明るい感情で、暗い森に入る場面の感覚と矛盾する。", "誇り": "誇りは自信や名誉に関する感情で、暗い森の場面とは結びつかない。", "照れ": "照れは人前での気恥ずかしさで、暗い森で一人のときの感覚に合わない。"}, "sentence_index": 0, "correct_answer": "恐れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は眠くなる恐れがあるので、運転は控えてください。", "explanation": "ここは〈悪いことが起こる心配〉の意味。こわいと思う気持ちという本項目の定義とは別の意味で、この文はその用法を使っている。"}, {"text": "株価の大暴落で、市場は恐れに陥った。", "explanation": "ここは〈恐慌〉の意味。社会全体が混乱してパニックになる場面には恐慌を使い、個人のこわさを表す恐れは「陥る」とも結びつかないので合わない。"}, {"text": "ご多忙の中お越しいただき、恐れの至りです。", "explanation": "ここは〈恐縮〉の意味。詫びや感謝を丁寧に伝える定型句「恐縮の至り」が正しく、こわいと思う気持ちの恐れは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39054, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恐れ", "is_correct": true, "explanation": "「弟の目には恐れが浮かんでいた」で、大きな犬に怯える表情に合う。"}, {"text": "怒り", "is_correct": false, "explanation": "怒りは腹を立てる感情で、犬を見て怯える場面とは合わない。"}, {"text": "安堵", "is_correct": false, "explanation": "安堵はほっとした気持ちで、犬を見て怯える場面とは逆になる。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は体が眠くなる状態で、目に浮かぶ感情ではなく、怯えの表情とは結びつかない。"}], "explanations": {"恐れ": "「弟の目には恐れが浮かんでいた」で、大きな犬に怯える表情に合う。", "怒り": "怒りは腹を立てる感情で、犬を見て怯える場面とは合わない。", "安堵": "安堵はほっとした気持ちで、犬を見て怯える場面とは逆になる。", "眠気": "眠気は体が眠くなる状態で、目に浮かぶ感情ではなく、怯えの表情とは結びつかない。"}, "sentence_index": 6, "correct_answer": "恐れ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家族を失って、彼は恐れに暮れて何日も泣いた。", "explanation": "ここは〈悲嘆〉の意味。悲しみに沈む意味の「悲嘆に暮れる」が定型で、こわいと思う気持ちの恐れは合わない。"}, {"text": "優勝の知らせに、彼は恐れに涙した。", "explanation": "ここは〈感激〉の意味。心を強く動かされて涙する場面には感激を使い、恐れは合わない。"}, {"text": "彼は研究に恐れを注いだ。", "explanation": "ここは〈情熱〉の意味。熱心に打ち込む気持ちには情熱を使い、こわいと思う気持ちの恐れは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39054, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもは暗闇への恐れを、大声で泣き出した。", "corrected_sentence": "子どもは暗闇への恐れで、大声で泣き出した。", "error_description": "正しくは「恐れで」（原因を表す「で」）。「恐れを」は目的格で、「泣き出す」の目的語にならず文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39054, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は恐れるを感じながらも、山道を一人で歩いた。", "corrected_sentence": "彼は恐れを感じながらも、山道を一人で歩いた。", "error_description": "正しくは「恐れを感じる」。「恐れ」は名詞なので「を」で「感じる」の目的語になる。「恐れる」（動詞）を置くと「恐れるを」となり成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
