INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39055, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何か悪いことが起こるかもしれないと心配する気持ち。", "primary_collocate": null, "pronunciation": "おそれ", "ipa": "osoɾe", "syllable_count": 3, "sentences": [{"text": "大雨のため、川があふれる恐れがある。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "大雨[おおあめ]のため、川[かわ]があふれる恐[おそ]れがある。", "sentence_source": "generated"}, {"text": "この薬は眠くなる恐れがあるので、運転してはいけない。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "この薬[くすり]は眠[ねむ]くなる恐[おそ]れがあるので、運転[うんてん]してはいけない。", "sentence_source": "generated"}, {"text": "台風が近づいていて、電車が止まる恐れがある。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づいていて、電車[でんしゃ]が止[と]まる恐[おそ]れがある。", "sentence_source": "generated"}, {"text": "古い橋が崩れる恐れがあり、通行が禁止された。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "古[ふる]い橋[はし]が崩[くず]れる恐[おそ]れがあり、通行[つうこう]が禁止[きんし]された。", "sentence_source": "generated"}, {"text": "火が広がる恐れはないと、消防士が言った。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "火[ひ]が広[ひろ]がる恐[おそ]れはないと、消防士[しょうぼうし]が言[い]った。", "sentence_source": "generated"}, {"text": "このまま練習しないと、試合に負ける恐れがある。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "このまま練習[れんしゅう]しないと、試合[しあい]に負[ま]ける恐[おそ]れがある。", "sentence_source": "generated"}, {"text": "風邪がうつる恐れがあるから、今日は会わない。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "風邪[かぜ]がうつる恐[おそ]れがあるから、今日[きょう]は会[あ]わない。", "sentence_source": "generated"}, {"text": "雪で道が凍る恐れがあるため、早めに出発した。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "雪[ゆき]で道[みち]が凍[こお]る恐[おそ]れがあるため、早[はや]めに出発[しゅっぱつ]した。", "sentence_source": "generated"}, {"text": "情報がもれる恐れがあるので、書類は鍵のかかる棚にしまう。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "情報[じょうほう]がもれる恐[おそ]れがあるので、書類[しょるい]は鍵[かぎ]のかかる棚[たな]にしまう。", "sentence_source": "generated"}, {"text": "山では、天気が急に変わる恐れがある。", "target_word": "恐れ", "complexity_tier": "T3", "furigana": "山[やま]では、天気[てんき]が急[きゅう]に変[か]わる恐[おそ]れがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "恐れ", "label": "基本形"}, {"form": "恐れが", "label": "が格"}, {"form": "恐れはない", "label": "否定の述語形"}, {"form": "恐れの", "label": "の格"}], "register": "neutral", "sense_fingerprint": "悪い事態が起こる可能性・心配(〜のおそれがある)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: もれる (Zipf 2.42)']::text[], '6a9d509c-8b22-4e3f-930f-2c4fe6e564c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39055, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恐れ", "is_correct": true, "explanation": "「川があふれる恐れがある」で、悪い事態が起こる可能性を表す。"}, {"text": "義務", "is_correct": false, "explanation": "義務は果たすべきことで、川があふれる事態には結びつかない。"}, {"text": "感覚", "is_correct": false, "explanation": "感覚は五感や感じ方のことで、川があふれる事態の可能性を表さない。"}, {"text": "名残", "is_correct": false, "explanation": "名残は過ぎ去ったものの跡で、これから起こる事態の可能性とは合わない。"}], "explanations": {"恐れ": "「川があふれる恐れがある」で、悪い事態が起こる可能性を表す。", "義務": "義務は果たすべきことで、川があふれる事態には結びつかない。", "感覚": "感覚は五感や感じ方のことで、川があふれる事態の可能性を表さない。", "名残": "名残は過ぎ去ったものの跡で、これから起こる事態の可能性とは合わない。"}, "sentence_index": 0, "correct_answer": "恐れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は神への恐れを胸に、質素な暮らしを守った。", "explanation": "ここは〈敬虔〉の意味。神を敬う心には敬虔を使い、悪い事態が起こる可能性を表す恐れは合わない。"}, {"text": "この取引で、会社は大きな恐れを得た。", "explanation": "ここは〈利益〉の意味。得るものには利益を使い、悪い事態の可能性を表す恐れは合わない。"}, {"text": "彼女は助けてくれた人々に、深い恐れを伝えた。", "explanation": "ここは〈感謝〉の意味。人に伝える気持ちには感謝を使い、恐れは悪い事態の可能性を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39055, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恐れ", "is_correct": true, "explanation": "「風邪がうつる恐れがある」で、悪い事態が起こる可能性を表す。"}, {"text": "手応え", "is_correct": false, "explanation": "手応えは何かに働きかけた時の感触で、風邪がうつる事態には結びつかない。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は残る響きや気配で、これから起こる感染の可能性とは合わない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は生き続ける期間で、風邪がうつる可能性を表す語ではない。"}], "explanations": {"恐れ": "「風邪がうつる恐れがある」で、悪い事態が起こる可能性を表す。", "手応え": "手応えは何かに働きかけた時の感触で、風邪がうつる事態には結びつかない。", "余韻": "余韻は残る響きや気配で、これから起こる感染の可能性とは合わない。", "寿命": "寿命は生き続ける期間で、風邪がうつる可能性を表す語ではない。"}, "sentence_index": 6, "correct_answer": "恐れ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は部下に大きな恐れを寄せていた。", "explanation": "ここは〈信頼〉の意味。人に寄せる気持ちには信頼を使い、悪い事態の可能性を表す恐れは合わない。"}, {"text": "その作品は恐れを受け取った。", "explanation": "ここは〈賞〉の意味。受け取るものには賞を使い、恐れは悪い事態の可能性を表すので合わない。"}, {"text": "彼は戦いで恐れを守ろうとした。", "explanation": "ここは〈名誉〉の意味。守るものには名誉を使い、恐れは悪い事態の可能性で守る対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
