INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39056, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするために使うお金のことです。", "primary_collocate": null, "pronunciation": "しきん", "ipa": "ɕikiɴ", "syllable_count": 3, "sentences": [{"text": "新しい店を開くための資金を、銀行から借りた。", "target_word": "資金", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]を開[ひら]くための資金[しきん]を、銀行[ぎんこう]から借[か]りた。", "sentence_source": "generated"}, {"text": "研究を続けるには、もっと資金が必要だ。", "target_word": "資金", "complexity_tier": "T3", "furigana": "研究[けんきゅう]を続[つづ]けるには、もっと資金[しきん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "町の祭りの資金は、みんなの寄付で集めた。", "target_word": "資金", "complexity_tier": "T3", "furigana": "町[まち]の祭[まつ]りの資金[しきん]は、みんなの寄付[きふ]で集[あつ]めた。", "sentence_source": "generated"}, {"text": "会社は工場を作る資金が足りなくて、計画を止めた。", "target_word": "資金", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は工場[こうじょう]を作[つく]る資金[しきん]が足[た]りなくて、計画[けいかく]を止[と]めた。", "sentence_source": "generated"}, {"text": "彼は五年かけて、留学の資金をためた。", "target_word": "資金", "complexity_tier": "T3", "furigana": "彼[かれ]は五年[ごねん]かけて、留学[りゅうがく]の資金[しきん]をためた。", "sentence_source": "generated"}, {"text": "資金がなくなり、映画の撮影は途中で終わった。", "target_word": "資金", "complexity_tier": "T3", "furigana": "資金[しきん]がなくなり、映画[えいが]の撮影[さつえい]は途中[とちゅう]で終[お]わった。", "sentence_source": "generated"}, {"text": "若い社長は、投資家から資金を集めた。", "target_word": "資金", "complexity_tier": "T3", "furigana": "若[わか]い社長[しゃちょう]は、投資家[とうしか]から資金[しきん]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "事業を始めたいが、資金の見通しが立たない。", "target_word": "資金", "complexity_tier": "T3", "furigana": "事業[じぎょう]を始[はじ]めたいが、資金[しきん]の見通[みとお]しが立[た]たない。", "sentence_source": "generated"}, {"text": "この団体は、集めた資金を学校の建設に使う。", "target_word": "資金", "complexity_tier": "T3", "furigana": "この団体[だんたい]は、集[あつ]めた資金[しきん]を学校[がっこう]の建設[けんせつ]に使[つか]う。", "sentence_source": "generated"}, {"text": "店を続ける資金を増やすために、バザーを開く予定だ。", "target_word": "資金", "complexity_tier": "T3", "furigana": "店[みせ]を続[つづ]ける資金[しきん]を増[ふ]やすために、バザーを開[ひら]く予定[よてい]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "資金", "label": "基本形"}, {"form": "資金が", "label": "が格"}, {"form": "資金を", "label": "を格"}, {"form": "資金の", "label": "の格"}], "register": "neutral", "sense_fingerprint": "事業・計画・活動のために用意して使うお金", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a9d509c-8b22-4e3f-930f-2c4fe6e564c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39056, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "資金", "is_correct": true, "explanation": "開店のための資金を銀行から借りる、という文脈に合う。"}, {"text": "看板", "is_correct": false, "explanation": "看板は店の目印で、銀行から借りて開店の準備に使うお金の代わりにはならない。"}, {"text": "免許", "is_correct": false, "explanation": "営業の免許は銀行から借りるものではないので、借りたという文脈と合わない。"}, {"text": "座席", "is_correct": false, "explanation": "座席は店の備品で、銀行から借りて開店のために用意するものとして成り立たない。"}], "explanations": {"資金": "開店のための資金を銀行から借りる、という文脈に合う。", "看板": "看板は店の目印で、銀行から借りて開店の準備に使うお金の代わりにはならない。", "免許": "営業の免許は銀行から借りるものではないので、借りたという文脈と合わない。", "座席": "座席は店の備品で、銀行から借りて開店のために用意するものとして成り立たない。"}, "sentence_index": 0, "correct_answer": "資金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は一年間働いて、報酬として資金を受け取った。", "explanation": "ここは〈給料〉の意味。資金は何かのために用意するお金で、働いた対価として受け取るお金には使わないので合わない。"}, {"text": "交通違反をして、資金を三万円払うはめになった。", "explanation": "ここは〈罰金〉の意味。資金は何かに使うために用意するお金で、違反の支払いには使わないので合わない。"}, {"text": "この本の資金を、レジで払った。", "explanation": "ここは〈代金〉の意味。資金は払うお金ではなく、何かのために用意するお金なので、買い物の支払いには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39056, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "資金", "is_correct": true, "explanation": "投資家から集めるものは資金なので、「集めた」に合う。"}, {"text": "名札", "is_correct": false, "explanation": "名札は身につけるもので、投資家から集める対象ではない。"}, {"text": "筆箱", "is_correct": false, "explanation": "筆箱は文房具で、投資家から集める対象ではない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は置物で、投資家から集める対象ではない。"}], "explanations": {"資金": "投資家から集めるものは資金なので、「集めた」に合う。", "名札": "名札は身につけるもので、投資家から集める対象ではない。", "筆箱": "筆箱は文房具で、投資家から集める対象ではない。", "花瓶": "花瓶は置物で、投資家から集める対象ではない。"}, "sentence_index": 6, "correct_answer": "資金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車の資金は、大人一人二百円だ。", "explanation": "ここは〈運賃〉の意味。資金は何かのために用意するお金で、乗るときに払う料金ではないので合わない。"}, {"text": "資金を納める期限が、来月末だ。", "explanation": "ここは〈税金〉の意味。資金は納めるものではなく、何かのために用意するお金なので合わない。"}, {"text": "資金は毎月、五日までに払う。", "explanation": "ここは〈家賃〉の意味。資金は払うお金ではなく、何かのために用意するお金なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39056, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店を続けるための資金を、いつも困っている。", "corrected_sentence": "店を続けるための資金に、いつも困っている。", "error_description": "「困る」は「〜に困る」の形で、「資金を」は誤り。「資金に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39056, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "資金で足りず、店を閉めることにした。", "corrected_sentence": "資金が足りず、店を閉めることにした。", "error_description": "「足りる」は「資金が足りる」の形で主語に「が」を使う。「資金で」は誤りで、「資金が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39058, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「移転が決まる」の形で、決まる物事の主語は「が」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「決まる」は「を」を取らないので、ここでは成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「決まる」とは続かない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、「移転から決まる」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「移転が決まる」の形で、決まる物事の主語は「が」で示す。", "を": "「決まる」は「を」を取らないので、ここでは成り立たない。", "へ": "「へ」は方向を表し、「決まる」とは続かない。", "から": "「から」は起点を表し、「移転から決まる」は意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39058, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39058, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを別の場所にうつすこと。", "primary_collocate": null, "pronunciation": "いてん", "ipa": "iteɴ", "syllable_count": 3, "sentences": [{"text": "会社は来月、駅の近くに移転する。", "target_word": "移転", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は来月[らいげつ]、駅[えき]の近[ちか]くに移転[いてん]する。", "sentence_source": "generated"}, {"text": "病院の移転が決まり、新しい建物の工事が始まった。", "target_word": "移転", "complexity_tier": "T3", "furigana": "病院[びょういん]の移転[いてん]が決[き]まり、新[あたら]しい建物[たてもの]の工事[こうじ]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "店が移転したので、前の場所には行っても無駄だ。", "target_word": "移転", "complexity_tier": "T3", "furigana": "店[みせ]が移転[いてん]したので、前[まえ]の場所[ばしょ]には行[い]っても無駄[むだ]だ。", "sentence_source": "generated"}, {"text": "古い校舎が危ないため、学校は丘の上へ移転した。", "target_word": "移転", "complexity_tier": "T3", "furigana": "古[ふる]い校舎[こうしゃ]が危[あぶ]ないため、学校[がっこう]は丘[おか]の上[うえ]へ移転[いてん]した。", "sentence_source": "generated"}, {"text": "事務所を移転する日に、みんなで荷物を運んだ。", "target_word": "移転", "complexity_tier": "T3", "furigana": "事務所[じむしょ]を移転[いてん]する日[ひ]に、みんなで荷物[にもつ]を運[はこ]んだ。", "sentence_source": "generated"}, {"text": "移転したあとの住所は、はがきで知らせる。", "target_word": "移転", "complexity_tier": "T3", "furigana": "移転[いてん]したあとの住所[じゅうしょ]は、はがきで知[し]らせる。", "sentence_source": "generated"}, {"text": "工場の移転で、通勤の時間が長くなった。", "target_word": "移転", "complexity_tier": "T3", "furigana": "工場[こうじょう]の移転[いてん]で、通勤[つうきん]の時間[じかん]が長[なが]くなった。", "sentence_source": "generated"}, {"text": "市役所が移転したことを知らず、前の建物に行ってしまった。", "target_word": "移転", "complexity_tier": "T3", "furigana": "市役所[しやくしょ]が移転[いてん]したことを知[し]らず、前[まえ]の建物[たてもの]に行[い]ってしまった。", "sentence_source": "generated"}, {"text": "図書館の移転は、来年の春に終わる予定だ。", "target_word": "移転", "complexity_tier": "T3", "furigana": "図書館[としょかん]の移転[いてん]は、来年[らいねん]の春[はる]に終[お]わる予定[よてい]だ。", "sentence_source": "generated"}, {"text": "店の移転を知らせる紙が、ドアにはってあった。", "target_word": "移転", "complexity_tier": "T3", "furigana": "店[みせ]の移転[いてん]を知[し]らせる紙[かみ]が、ドアにはってあった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "移転する", "label": "基本形"}, {"form": "移転した", "label": "過去形"}, {"form": "移転して", "label": "て形"}, {"form": "移転しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "会社・店・施設などが別の場所へ引っ越すこと(場所の移動)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a9d509c-8b22-4e3f-930f-2c4fe6e564c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39058, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移転", "is_correct": true, "explanation": "会社が駅の近くへ場所を変えるという文脈に合う。"}, {"text": "勉強", "is_correct": false, "explanation": "「勉強する」は場所の変更を表さず、文の意味が成り立たない。"}, {"text": "料理", "is_correct": false, "explanation": "「料理する」は場所を変えることを表さず、文が成り立たない。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩する」は一時的に歩くことで、会社が場所を変える文には合わない。"}], "explanations": {"移転": "会社が駅の近くへ場所を変えるという文脈に合う。", "勉強": "「勉強する」は場所の変更を表さず、文の意味が成り立たない。", "料理": "「料理する」は場所を変えることを表さず、文が成り立たない。", "散歩": "「散歩する」は一時的に歩くことで、会社が場所を変える文には合わない。"}, "sentence_index": 0, "correct_answer": "移転"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹の風邪が、私に移転してしまった。", "explanation": "ここは〈感染させる〉の意味。病気を人にうつす場合は「うつす」「感染させる」を使い、移転は会社や店などの場所の変更に使うので合わない。"}, {"text": "電車での移転の間、本を読んだ。", "explanation": "ここは〈移動〉の意味。移転は会社や店などが場所を変えることで、乗り物で移動する間には使わない。"}, {"text": "友達は来年、別の小学校へ移転する。", "explanation": "ここは〈転校〉の意味。人の学校の変更に移転は使わず、会社や店などの場所の変更に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39058, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移転", "is_correct": true, "explanation": "工場の移転が原因で通勤時間が長くなる、という因果関係に合う。"}, {"text": "掃除", "is_correct": false, "explanation": "工場の掃除で通勤時間が長くなるという因果関係は成り立たない。"}, {"text": "入学", "is_correct": false, "explanation": "「入学」は工場には使わず、通勤時間が長くなる原因にもならない。"}, {"text": "離婚", "is_correct": false, "explanation": "「離婚」は工場には使わず、通勤時間が長くなる原因にもならない。"}], "explanations": {"移転": "工場の移転が原因で通勤時間が長くなる、という因果関係に合う。", "掃除": "工場の掃除で通勤時間が長くなるという因果関係は成り立たない。", "入学": "「入学」は工場には使わず、通勤時間が長くなる原因にもならない。", "離婚": "「離婚」は工場には使わず、通勤時間が長くなる原因にもならない。"}, "sentence_index": 6, "correct_answer": "移転"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "選手は来季、別のチームへ移転する。", "explanation": "ここは〈移籍〉の意味。選手など人の所属先の変更には移転を使わず、会社・店・施設の場所の変更に使う。"}, {"text": "届いたメールを、友達のアドレスへ移転した。", "explanation": "ここは〈転送〉の意味。メールの送り先を変えることには移転は使わない。"}, {"text": "社員は来年から、子会社へ移転する。", "explanation": "ここは〈出向〉の意味。社員の所属の変更は、会社や店の場所の移転とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39058, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "移転した前に、古い看板を外した。", "corrected_sentence": "移転する前に、古い看板を外した。", "error_description": "「〜前に」は動詞の辞書形に続ける。「移転した前に」は誤りで、「移転する前に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39058, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "移転を準備は、来月から始まる。", "corrected_sentence": "移転の準備は、来月から始まる。", "error_description": "「移転の準備」は「の」で名詞をつなぐ。「移転を準備」の「を」は動詞の目的語を示すもので、名詞の「準備」には続かないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39059, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「子へ移転した」の形で、所有権の移転先は「へ」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「子を移転した」は子を物のように渡す文になり、所有権の移転先にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「親から子から移転した」は「から」が二つ重なり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「子と移転した」は相手や共同を表し、所有権の移転先を示せない。"}], "correct_answer": "へ", "explanations": {"へ": "「子へ移転した」の形で、所有権の移転先は「へ」で示す。", "を": "「子を移転した」は子を物のように渡す文になり、所有権の移転先にはならない。", "から": "「親から子から移転した」は「から」が二つ重なり、文が成り立たない。", "と": "「子と移転した」は相手や共同を表し、所有権の移転先を示せない。"}, "error_tags": {"を": "目的語", "から": "起点", "と": "相手・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39059, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「子会社に移転される」の形で、移転の相手や先は「に」で示す。"}, {"text": "を", "is_correct": false, "explanation": "移転先を「を」で示すことはできず、「子会社を移転される」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "「子会社が」は主語になり、文の意味が変わって合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を表し、移転先には使わない。"}], "correct_answer": "に", "explanations": {"に": "「子会社に移転される」の形で、移転の相手や先は「に」で示す。", "を": "移転先を「を」で示すことはできず、「子会社を移転される」は不自然。", "が": "「子会社が」は主語になり、文の意味が変わって合わない。", "と": "「と」は相手や共同を表し、移転先には使わない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39059, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物や権利、技術などを別の場所や人にうつすこと。", "primary_collocate": null, "pronunciation": "いてん", "ipa": "iteɴ", "syllable_count": 3, "sentences": [{"text": "外国の会社から、新しい技術の移転を受けた。", "target_word": "移転", "complexity_tier": "T3", "furigana": "外国[がいこく]の会社[かいしゃ]から、新[あたら]しい技術[ぎじゅつ]の移転[いてん]を受[う]けた。", "sentence_source": "generated"}, {"text": "土地の所有権が、親から子へ移転した。", "target_word": "移転", "complexity_tier": "T3", "furigana": "土地[とち]の所有権[しょゆうけん]が、親[おや]から子[こ]へ移転[いてん]した。", "sentence_source": "generated"}, {"text": "技術を移転する契約を、両社が結んだ。", "target_word": "移転", "complexity_tier": "T3", "furigana": "技術[ぎじゅつ]を移転[いてん]する契約[けいやく]を、両社[りょうしゃ]が結[むす]んだ。", "sentence_source": "generated"}, {"text": "権利の移転には、書類に印を押す必要がある。", "target_word": "移転", "complexity_tier": "T3", "furigana": "権利[けんり]の移転[いてん]には、書類[しょるい]に印[いん]を押[お]す必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "工場の機械だけでなく、作り方の知識も移転された。", "target_word": "移転", "complexity_tier": "T3", "furigana": "工場[こうじょう]の機械[きかい]だけでなく、作[つく]り方[かた]の知識[ちしき]も移転[いてん]された。", "sentence_source": "generated"}, {"text": "家を買ったので、所有権を移転する手続きをした。", "target_word": "移転", "complexity_tier": "T3", "furigana": "家[いえ]を買[か]ったので、所有権[しょゆうけん]を移転[いてん]する手続[てつづ]きをした。", "sentence_source": "generated"}, {"text": "国は、進んだ農業の技術を貧しい国へ移転している。", "target_word": "移転", "complexity_tier": "T3", "furigana": "国[くに]は、進[すす]んだ農業[のうぎょう]の技術[ぎじゅつ]を貧[まず]しい国[くに]へ移転[いてん]している。", "sentence_source": "generated"}, {"text": "会社の財産が子会社に移転され、社名も変わった。", "target_word": "移転", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の財産[ざいさん]が子会社[こがいしゃ]に移転[いてん]され、社名[しゃめい]も変[か]わった。", "sentence_source": "generated"}, {"text": "特許を移転すれば、その会社が自由に使えるようになる。", "target_word": "移転", "complexity_tier": "T3", "furigana": "特許[とっきょ]を移転[いてん]すれば、その会社[かいしゃ]が自由[じゆう]に使[つか]えるようになる。", "sentence_source": "generated"}, {"text": "技術の移転が進めば、現地の人だけで製品を作れる。", "target_word": "移転", "complexity_tier": "T3", "furigana": "技術[ぎじゅつ]の移転[いてん]が進[すす]めば、現地[げんち]の人[ひと]だけで製品[せいひん]を作[つく]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "移転する", "label": "基本形"}, {"form": "移転した", "label": "過去形"}, {"form": "移転される", "label": "受身形"}, {"form": "移転して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "権利・財産・技術などが別の人や組織へ渡ること(譲り渡し)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a9d509c-8b22-4e3f-930f-2c4fe6e564c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39059, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移転", "is_correct": true, "explanation": "外国の会社から技術を受け取るという文脈に合う。"}, {"text": "病気", "is_correct": false, "explanation": "「技術の病気を受けた」は意味をなさず、受け取る対象にならない。"}, {"text": "招待", "is_correct": false, "explanation": "「技術の招待を受けた」は、技術を受け取る文脈に合わない。"}, {"text": "誕生", "is_correct": false, "explanation": "「技術の誕生を受けた」は、受け取る対象として成り立たない。"}], "explanations": {"移転": "外国の会社から技術を受け取るという文脈に合う。", "病気": "「技術の病気を受けた」は意味をなさず、受け取る対象にならない。", "招待": "「技術の招待を受けた」は、技術を受け取る文脈に合わない。", "誕生": "「技術の誕生を受けた」は、受け取る対象として成り立たない。"}, "sentence_index": 0, "correct_answer": "移転"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "インフルエンザを、家族全員に移転してしまった。", "explanation": "ここは〈感染させる〉の意味。病気を人にうつす場合は「うつす」「感染させる」を使い、権利や技術を渡す意味の移転は合わないので誤り。"}, {"text": "空港までの移転に、一時間かかった。", "explanation": "ここは〈移動〉の意味。人が乗り物で行くことには移転は使わず、権利や技術の受け渡しにも当てはまらない。"}, {"text": "社員は来年から、子会社へ移転する。", "explanation": "ここは〈出向〉の意味。人の所属の変更は、権利・財産・技術を渡す移転の意味には当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39059, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移転", "is_correct": true, "explanation": "国が技術を貧しい国へ渡すという文脈に合う。"}, {"text": "掃除", "is_correct": false, "explanation": "「技術を貧しい国へ掃除している」は、技術を渡す行為として成り立たない。"}, {"text": "記念", "is_correct": false, "explanation": "「記念している」は技術を渡す行為にならない。"}, {"text": "誤解", "is_correct": false, "explanation": "「技術を誤解している」は、貧しい国へ渡す行為を表さない。"}], "explanations": {"移転": "国が技術を貧しい国へ渡すという文脈に合う。", "掃除": "「技術を貧しい国へ掃除している」は、技術を渡す行為として成り立たない。", "記念": "「記念している」は技術を渡す行為にならない。", "誤解": "「技術を誤解している」は、貧しい国へ渡す行為を表さない。"}, "sentence_index": 6, "correct_answer": "移転"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "タバコのにおいが、服に移転してしまった。", "explanation": "ここは〈移る〉の意味。においや色が別のものに移る場合は「移る」を使い、移転は物や権利、技術などを別の場所や人に渡すときに使うので合わない。"}, {"text": "選手は来季、別のチームへ移転する。", "explanation": "ここは〈移籍〉の意味。人の所属の変更には、権利や技術を渡す移転の意味は当てはまらない。"}, {"text": "妹は春に、別の中学へ移転した。", "explanation": "ここは〈転校〉の意味。人の学校の変更は、移転の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39059, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "特許の移転が、弁護士に頼んだ。", "corrected_sentence": "特許の移転を、弁護士に頼んだ。", "error_description": "「頼む」の対象は「を」で示す。「移転が」の「が」は誤りで、「移転を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39059, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "技術を移転した前に、契約書を確認した。", "corrected_sentence": "技術を移転する前に、契約書を確認した。", "error_description": "「〜前に」は動詞の辞書形に続ける。「移転した前に」は誤りで、「移転する前に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39060, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「意志が強い」の主語。「強い」の主語は「が」で示す。"}, {"text": "へ", "is_correct": false, "explanation": "「意志へ強く」は方向の「へ」で、「強い」の主語にならず文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「意志から強く」は起点の「から」で、「強い」の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「意志と強く」は並列の「と」で、並べる相手がなく文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「意志が強い」の主語。「強い」の主語は「が」で示す。", "へ": "「意志へ強く」は方向の「へ」で、「強い」の主語にならず文が成り立たない。", "から": "「意志から強く」は起点の「から」で、「強い」の主語にはならない。", "と": "「意志と強く」は並列の「と」で、並べる相手がなく文が成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
