INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39060, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「こうしたい」という強い気持ちのこと。", "primary_collocate": null, "pronunciation": "いし", "ipa": "iɕi", "syllable_count": 2, "sentences": [{"text": "私は自分の意志で、この大学を選んだ。", "target_word": "意志", "complexity_tier": "T3", "furigana": "私[わたし]は自分[じぶん]の意志[いし]で、この大学[だいがく]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "彼は意志が強く、一度決めたことは変えない。", "target_word": "意志", "complexity_tier": "T3", "furigana": "彼[かれ]は意志[いし]が強[つよ]く、一度[いちど]決[き]めたことは変[か]えない。", "sentence_source": "generated"}, {"text": "本人の意志を無視して、仕事を決めてはいけない。", "target_word": "意志", "complexity_tier": "T3", "furigana": "本人[ほんにん]の意志[いし]を無視[むし]して、仕事[しごと]を決[き]めてはいけない。", "sentence_source": "generated"}, {"text": "子どもにも意志があるので、話をよく聞こう。", "target_word": "意志", "complexity_tier": "T3", "furigana": "子[こ]どもにも意志[いし]があるので、話[はなし]をよく聞[き]こう。", "sentence_source": "generated"}, {"text": "彼女は反対されても、留学したい意志をつらぬいた。", "target_word": "意志", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は反対[はんたい]されても、留学[りゅうがく]したい意志[いし]をつらぬいた。", "sentence_source": "generated"}, {"text": "意志の弱い私は、ダイエットが続かない。", "target_word": "意志", "complexity_tier": "T3", "furigana": "意志[いし]の弱[よわ]い私[わたし]は、ダイエットが続[つづ]かない。", "sentence_source": "generated"}, {"text": "彼は会議で、最後まで自分の意志を曲げなかった。", "target_word": "意志", "complexity_tier": "T3", "furigana": "彼[かれ]は会議[かいぎ]で、最後[さいご]まで自分[じぶん]の意志[いし]を曲[ま]げなかった。", "sentence_source": "generated"}, {"text": "弟は何も言わなかったが、その態度から行きたくない意志がはっきり伝わってきた。", "target_word": "意志", "complexity_tier": "T3", "furigana": "弟[おとうと]は何[なに]も言[い]わなかったが、その態度[たいど]から行[い]きたくない意志[いし]がはっきり伝[つた]わってきた。", "sentence_source": "generated"}, {"text": "彼の意志は固く、だれの言葉でも変わらなかった。", "target_word": "意志", "complexity_tier": "T3", "furigana": "彼[かれ]の意志[いし]は固[かた]く、だれの言葉[ことば]でも変[か]わらなかった。", "sentence_source": "generated"}, {"text": "自分の意志と関係なく、転勤が決まった。", "target_word": "意志", "complexity_tier": "T3", "furigana": "自分[じぶん]の意志[いし]と関係[かんけい]なく、転勤[てんきん]が決[き]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "意志", "label": "基本形"}, {"form": "意志が", "label": "が格"}, {"form": "意志を", "label": "を格"}, {"form": "意志の", "label": "の格"}], "register": "neutral", "sense_fingerprint": "自分でこうしたいと決める心の働き・本人の望み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: つらぬい (Zipf 1.77)']::text[], '6a9d509c-8b22-4e3f-930f-2c4fe6e564c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39060, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意志", "is_correct": true, "explanation": "「自分の意志で」は自分で決めたという意味で、大学を選ぶ理由として合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は大学を選ぶ理由にならず、「自分の天気で」は意味をなさない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は大学を選ぶ理由にならず、「自分の季節で」は不自然で文が成り立たない。"}, {"text": "足跡", "is_correct": false, "explanation": "足跡は歩いた跡で、大学を選ぶ理由とは結びつかない。"}], "explanations": {"意志": "「自分の意志で」は自分で決めたという意味で、大学を選ぶ理由として合う。", "天気": "天気は大学を選ぶ理由にならず、「自分の天気で」は意味をなさない。", "季節": "季節は大学を選ぶ理由にならず、「自分の季節で」は不自然で文が成り立たない。", "足跡": "足跡は歩いた跡で、大学を選ぶ理由とは結びつかない。"}, "sentence_index": 0, "correct_answer": "意志"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この言葉の意志がわからない。", "explanation": "ここは〈意味〉の意味。言葉の内容を指すには意味を使い、意志は人の強い気持ちなので合わない。"}, {"text": "事故のあと、彼は意志を取り戻し、目を開けた。", "explanation": "ここは〈意識〉の意味。意識を取り戻すという場合は意識を使い、意志は強く決める心の働きなので合わない。"}, {"text": "彼女は悲しい意志を隠した。", "explanation": "ここは〈感情〉の意味。悲しみなどの気持ちには感情を使い、意志は自分で決める心の働きなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39060, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意志", "is_correct": true, "explanation": "「自分の意志を曲げる」は決めた気持ちを変えないという意味で、ここに合う。"}, {"text": "煙", "is_correct": false, "explanation": "煙は曲げられるものではなく、「煙を曲げなかった」は意味をなさない。"}, {"text": "空気", "is_correct": false, "explanation": "空気は曲げる対象ではなく、「空気を曲げなかった」は文が成り立たない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は曲げられるものではなく、「眠気を曲げなかった」は文が成り立たない。"}], "explanations": {"意志": "「自分の意志を曲げる」は決めた気持ちを変えないという意味で、ここに合う。", "煙": "煙は曲げられるものではなく、「煙を曲げなかった」は意味をなさない。", "空気": "空気は曲げる対象ではなく、「空気を曲げなかった」は文が成り立たない。", "眠気": "眠気は曲げられるものではなく、「眠気を曲げなかった」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "意志"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は音楽への意志が鋭く、わずかな音のずれも分かる。", "explanation": "ここは〈感覚〉の意味。音を感じ取る力には感覚を使い、意志は決める心の働きなので合わない。"}, {"text": "この石の意志は重く、子どもには持ち上げられない。", "explanation": "ここは〈重さ〉の意味。石の重さには重さを使い、意志は人の強い気持ちなので合わない。"}, {"text": "古い記憶の意志が、今も残っている。", "explanation": "ここは〈記憶〉の意味。過去の出来事を覚えている場合は記憶を使い、意志は決める心の働きなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39060, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は留学する意志が持っていた。", "corrected_sentence": "彼女は留学する意志を持っていた。", "error_description": "「意志を持つ」が正しい。「持つ」の目的語は「を」で示すので、「意志が持っていた」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39060, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の意志を固さに、みんなが驚いた。", "corrected_sentence": "彼の意志の固さに、みんなが驚いた。", "error_description": "「意志の固さ」は「の」で名詞をつなぐ。「意志を固さ」の「を」は動詞の目的語を示すもので、名詞の「固さ」にはつながらないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39061, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「意志を失わなかった」の「を」。「失う」は目的語に「を」を取る。"}, {"text": "が", "is_correct": false, "explanation": "「意志が最後まで失わなかった」は文として成り立たない。「失わない」には目的語が必要。"}, {"text": "に", "is_correct": false, "explanation": "「意志に失わなかった」は誤り。「失う」は「に」ではなく「を」で目的語を取る。"}, {"text": "で", "is_correct": false, "explanation": "「意志で失わなかった」は意味が通らない。「で」は手段や場所を表し、ここでは目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「意志を失わなかった」の「を」。「失う」は目的語に「を」を取る。", "が": "「意志が最後まで失わなかった」は文として成り立たない。「失わない」には目的語が必要。", "に": "「意志に失わなかった」は誤り。「失う」は「に」ではなく「を」で目的語を取る。", "で": "「意志で失わなかった」は意味が通らない。「で」は手段や場所を表し、ここでは目的語にならない。"}, "error_tags": {"が": "主格", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39061, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「強い意志があれば」の「が」。「ある」は主語に「が」を取る。"}, {"text": "を", "is_correct": false, "explanation": "「強い意志を、あれば」は文が成り立たない。「ある」は「を」ではなく「が」で主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「強い意志と、あれば」は並列や相手を表し、ここでは主語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「強い意志へ、あれば」は方向を表し、ここでは主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「強い意志があれば」の「が」。「ある」は主語に「が」を取る。", "を": "「強い意志を、あれば」は文が成り立たない。「ある」は「を」ではなく「が」で主語を示す。", "と": "「強い意志と、あれば」は並列や相手を表し、ここでは主語にならない。", "へ": "「強い意志へ、あれば」は方向を表し、ここでは主語を示せない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39061, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある目標を達成しようとする、強い心の決まり。", "primary_collocate": null, "pronunciation": "いし", "ipa": "iɕi", "syllable_count": 2, "sentences": [{"text": "金メダルを取るという強い意志で、毎日走った。", "target_word": "意志", "complexity_tier": "T3", "furigana": "金[きん]メダルを取[と]るという強[つよ]い意志[いし]で、毎日[まいにち]走[はし]った。", "sentence_source": "generated"}, {"text": "彼女は医者になる意志を、最後まで失わなかった。", "target_word": "意志", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は医者[いしゃ]になる意志[いし]を、最後[さいご]まで失[うしな]わなかった。", "sentence_source": "generated"}, {"text": "勝ちたいという意志がなければ、練習は続かない。", "target_word": "意志", "complexity_tier": "T3", "furigana": "勝[か]ちたいという意志[いし]がなければ、練習[れんしゅう]は続[つづ]かない。", "sentence_source": "generated"}, {"text": "意志の力で、痛みをこらえてゴールまで走った。", "target_word": "意志", "complexity_tier": "T3", "furigana": "意志[いし]の力[ちから]で、痛[いた]みをこらえてゴールまで走[はし]った。", "sentence_source": "generated"}, {"text": "山の頂上に立つ意志が、彼を前に進ませた。", "target_word": "意志", "complexity_tier": "T3", "furigana": "山[やま]の頂上[ちょうじょう]に立[た]つ意志[いし]が、彼[かれ]を前[まえ]に進[すす]ませた。", "sentence_source": "generated"}, {"text": "彼は強い意志をもって、むずかしい試験に挑んだ。", "target_word": "意志", "complexity_tier": "T3", "furigana": "彼[かれ]は強[つよ]い意志[いし]をもって、むずかしい試験[しけん]に挑[いど]んだ。", "sentence_source": "generated"}, {"text": "夢をかなえる意志がある人は、少しずつ前に進む。", "target_word": "意志", "complexity_tier": "T3", "furigana": "夢[ゆめ]をかなえる意志[いし]がある人[ひと]は、少[すこ]しずつ前[まえ]に進[すす]む。", "sentence_source": "generated"}, {"text": "強い意志があれば、遠い目標にも近づける。", "target_word": "意志", "complexity_tier": "T3", "furigana": "強[つよ]い意志[いし]があれば、遠[とお]い目標[もくひょう]にも近[ちか]づける。", "sentence_source": "generated"}, {"text": "目標をやりとげる意志を、仲間とたしかめ合った。", "target_word": "意志", "complexity_tier": "T3", "furigana": "目標[もくひょう]をやりとげる意志[いし]を、仲間[なかま]とたしかめ合[あ]った。", "sentence_source": "generated"}, {"text": "病気になっても、また舞台に立つ意志は消えなかった。", "target_word": "意志", "complexity_tier": "T3", "furigana": "病気[びょうき]になっても、また舞台[ぶたい]に立[た]つ意志[いし]は消[き]えなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "意志", "label": "基本形"}, {"form": "意志が", "label": "が格"}, {"form": "意志の", "label": "の格"}, {"form": "意志で", "label": "で格"}], "register": "neutral", "sense_fingerprint": "目標をやりとげようとする固い決意・心の力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: やりとげる (Zipf 1.92), たしかめ (Zipf 1.67)']::text[], '6a9d509c-8b22-4e3f-930f-2c4fe6e564c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39061, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意志", "is_correct": true, "explanation": "「強い意志で」は、目標に向かう固い心の力を表す。正解。"}, {"text": "規則", "is_correct": false, "explanation": "「強い規則で、毎日走った」は意味が通らない。規則は守るもので、走る原動力にはならない。"}, {"text": "記憶", "is_correct": false, "explanation": "「強い記憶で、毎日走った」は不自然。記憶は走る力を表す語として使えない。"}, {"text": "評判", "is_correct": false, "explanation": "「強い評判で、毎日走った」は成り立たない。評判は他人の評価であり、走る力の意味にならない。"}], "explanations": {"意志": "「強い意志で」は、目標に向かう固い心の力を表す。正解。", "規則": "「強い規則で、毎日走った」は意味が通らない。規則は守るもので、走る原動力にはならない。", "記憶": "「強い記憶で、毎日走った」は不自然。記憶は走る力を表す語として使えない。", "評判": "「強い評判で、毎日走った」は成り立たない。評判は他人の評価であり、走る力の意味にならない。"}, "sentence_index": 0, "correct_answer": "意志"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家族との意志の疎通がうまくいかず、話し合いを続けた。", "explanation": "ここは〈意思〉の意味。考えを通じ合わせる場合は一般に「意思疎通」と書き、「意志疎通」は標準的な表記ではないので合わない。"}, {"text": "寒さに負けないよう、意志を入れて練習する。", "explanation": "ここは〈根性〉の意味。気持ちを込めて奮い立つ場合は「根性を入れる」と言い、「意志を入れる」とは言わないので合わない。"}, {"text": "ライバルに負けたくなくて、意志を張って練習した。", "explanation": "ここは〈意地〉の意味。我を通そうとする場合は「意地を張る」と言い、意志は張るものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39061, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意志", "is_correct": true, "explanation": "「夢をかなえる意志がある人」は、夢を実現しようとする強い心を表す。正解。"}, {"text": "天気", "is_correct": false, "explanation": "「夢をかなえる天気がある人」は意味をなさない。天気は心の決まりを表さない。"}, {"text": "注意", "is_correct": false, "explanation": "「夢をかなえる注意がある人」は不自然。注意は気をつけることで、夢に向かう心の力ではない。"}, {"text": "欠点", "is_correct": false, "explanation": "「夢をかなえる欠点がある人」は文脈に合わない。欠点は夢に向かう力を表さない。"}], "explanations": {"意志": "「夢をかなえる意志がある人」は、夢を実現しようとする強い心を表す。正解。", "天気": "「夢をかなえる天気がある人」は意味をなさない。天気は心の決まりを表さない。", "注意": "「夢をかなえる注意がある人」は不自然。注意は気をつけることで、夢に向かう心の力ではない。", "欠点": "「夢をかなえる欠点がある人」は文脈に合わない。欠点は夢に向かう力を表さない。"}, "sentence_index": 6, "correct_answer": "意志"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合を前に、意志が上がっている。", "explanation": "ここは〈意気〉の意味。盛り上がる気持ちには「意気が上がる」を使い、「意志が上がる」とは言わないので合わない。"}, {"text": "朝から意志を出して、家の掃除をした。", "explanation": "ここは〈元気〉の意味。活力は「元気を出す」と言い、「意志を出す」とは言わないので合わない。"}, {"text": "川原で丸い意志を拾った。", "explanation": "ここは〈石〉の意味。同じ読みの「石」で、拾える物体を指す。抽象的な意志は拾えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39061, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は勝つ意志に、試合の最後まで失わなかった。", "corrected_sentence": "彼は勝つ意志を、試合の最後まで失わなかった。", "error_description": "「失う」は目的語に「を」を取る。「意志に」の「に」が誤りで、「意志を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39061, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は夢をかなえる意志に、仲間の前で見せた。", "corrected_sentence": "彼女は夢をかなえる意志を、仲間の前で見せた。", "error_description": "「見せる」は見せるものを「を」で示す。「意志に」の「に」は誤りで、「意志を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39062, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「試金石を持ち歩いていた」の「を」。「持ち歩く」は目的語に「を」を取る。"}, {"text": "が", "is_correct": false, "explanation": "「試金石が持ち歩いていた」では、持ち歩く対象が主語になり合わない。"}, {"text": "に", "is_correct": false, "explanation": "「試金石に持ち歩いていた」は方向を表し、目的語の位置には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「試金石と持ち歩いていた」は並列を表し、目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「試金石を持ち歩いていた」の「を」。「持ち歩く」は目的語に「を」を取る。", "が": "「試金石が持ち歩いていた」では、持ち歩く対象が主語になり合わない。", "に": "「試金石に持ち歩いていた」は方向を表し、目的語の位置には合わない。", "と": "「試金石と持ち歩いていた」は並列を表し、目的語にはならない。"}, "error_tags": {"が": "主格", "に": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39062, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「試金石を使って」の「を」。「使う」は目的語に「を」を取る。"}, {"text": "へ", "is_correct": false, "explanation": "「試金石へ使って」は方向を表し、使う対象の位置にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「試金石から使って」は起点を表し、使う対象にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「試金石の使って」は名詞をつなぐ用法で、動詞「使う」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「試金石を使って」の「を」。「使う」は目的語に「を」を取る。", "へ": "「試金石へ使って」は方向を表し、使う対象の位置にはならない。", "から": "「試金石から使って」は起点を表し、使う対象にはならない。", "の": "「試金石の使って」は名詞をつなぐ用法で、動詞「使う」の目的語にならない。"}, "error_tags": {"へ": "方向", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39062, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かの本当の価値や性質をためすための石のようなもの。", "primary_collocate": null, "pronunciation": "しきんせき", "ipa": "ɕikiɴseki", "syllable_count": 5, "sentences": [{"text": "金の純度は、試金石にこすりつけて調べる。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "金[きん]の純度[じゅんど]は、試金石[しきんせき]にこすりつけて調[しら]べる。", "sentence_source": "generated"}, {"text": "昔の商人は、小さな試金石を持ち歩いていた。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "昔[むかし]の商人[しょうにん]は、小[ちい]さな試金石[しきんせき]を持[も]ち歩[ある]いていた。", "sentence_source": "generated"}, {"text": "試金石の黒い面に、金色の線が残った。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "試金石[しきんせき]の黒[くろ]い面[めん]に、金色[きんいろ]の線[せん]が残[のこ]った。", "sentence_source": "generated"}, {"text": "博物館に、江戸時代に使われた試金石が展示されている。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]に、江戸時代[えどじだい]に使[つか]われた試金石[しきんせき]が展示[てんじ]されている。", "sentence_source": "generated"}, {"text": "店の主人は、指輪を試金石にこすって本物かどうか調べた。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "店[みせ]の主人[しゅじん]は、指輪[ゆびわ]を試金石[しきんせき]にこすって本物[ほんもの]かどうか調[しら]べた。", "sentence_source": "generated"}, {"text": "試金石は、金や銀の品質を調べるための黒っぽい石だ。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "試金石[しきんせき]は、金[きん]や銀[ぎん]の品質[ひんしつ]を調[しら]べるための黒[くろ]っぽい石[いし]だ。", "sentence_source": "generated"}, {"text": "彼は川で拾った黒い石を、試金石だと思って大切にしている。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "彼[かれ]は川[かわ]で拾[ひろ]った黒[くろ]い石[いし]を、試金石[しきんせき]だと思[おも]って大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "職人は試金石を使って、金の色を見比べた。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "職人[しょくにん]は試金石[しきんせき]を使[つか]って、金[きん]の色[いろ]を見比[みくら]べた。", "sentence_source": "generated"}, {"text": "試金石に残った線が薄ければ、金の割合が少ない。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "試金石[しきんせき]に残[のこ]った線[せん]が薄[うす]ければ、金[きん]の割合[わりあい]が少[すく]ない。", "sentence_source": "generated"}, {"text": "祖父の道具箱には、古い試金石が入っていた。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "祖父[そふ]の道具箱[どうぐばこ]には、古[ふる]い試金石[しきんせき]が入[はい]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "試金石", "label": "実際に使われる形"}, {"form": "試金石が", "label": "が格"}, {"form": "試金石に", "label": "に格"}, {"form": "試金石を", "label": "を格"}], "register": "neutral", "sense_fingerprint": "金や銀の純度を調べるために使う黒っぽい石(試金石)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: 薄けれ (Zipf 1.24)']::text[], '6a9d509c-8b22-4e3f-930f-2c4fe6e564c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39062, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "試金石", "is_correct": true, "explanation": "「金の純度は、試金石にこすりつけて調べる」。金の純度を調べる黒い石を表す。正解。"}, {"text": "鋳型", "is_correct": false, "explanation": "「鋳型にこすりつけて調べる」は不自然。鋳型は金属を流し込む型で、純度を調べる道具ではない。"}, {"text": "窯", "is_correct": false, "explanation": "「窯にこすりつけて調べる」は成り立たない。窯は焼成に使う設備で、こすって調べるものではない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「鉛筆にこすりつけて調べる」は不自然。金の純度を調べる道具として使う場面はない。"}], "explanations": {"試金石": "「金の純度は、試金石にこすりつけて調べる」。金の純度を調べる黒い石を表す。正解。", "鋳型": "「鋳型にこすりつけて調べる」は不自然。鋳型は金属を流し込む型で、純度を調べる道具ではない。", "窯": "「窯にこすりつけて調べる」は成り立たない。窯は焼成に使う設備で、こすって調べるものではない。", "鉛筆": "「鉛筆にこすりつけて調べる」は不自然。金の純度を調べる道具として使う場面はない。"}, "sentence_index": 0, "correct_answer": "試金石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "包丁を試金石で研いだ。", "explanation": "ここは〈砥石〉の意味。刃物を研ぐ道具は砥石で、試金石は刃を研ぐのに使わないので合わない。"}, {"text": "薬を試金石で量った。", "explanation": "ここは〈秤〉の意味。分量を量る道具は秤で、試金石では分量を量れないので合わない。"}, {"text": "薬品に試金石を浸して、酸性かどうか調べた。", "explanation": "ここは〈試験紙〉の意味。液に浸して色で酸性かどうかを調べるのは試験紙で、試金石は液に浸して使う道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39062, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "試金石", "is_correct": true, "explanation": "「黒い石を試金石だと思って大切にしている」。金属の純度を調べる石だと考えている意味。正解。"}, {"text": "芋", "is_correct": false, "explanation": "「黒い石を芋だと思って」は不自然。石を芋と見間違える文脈は成り立たない。"}, {"text": "箸", "is_correct": false, "explanation": "「黒い石を箸だと思って」は文脈に合わない。石と箸は見間違える関係にない。"}, {"text": "紙風船", "is_correct": false, "explanation": "「黒い石を紙風船だと思って」は成り立たない。石と紙風船は見間違えない。"}], "explanations": {"試金石": "「黒い石を試金石だと思って大切にしている」。金属の純度を調べる石だと考えている意味。正解。", "芋": "「黒い石を芋だと思って」は不自然。石を芋と見間違える文脈は成り立たない。", "箸": "「黒い石を箸だと思って」は文脈に合わない。石と箸は見間違える関係にない。", "紙風船": "「黒い石を紙風船だと思って」は成り立たない。石と紙風船は見間違えない。"}, "sentence_index": 6, "correct_answer": "試金石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "書道の時間、試金石で墨をすった。", "explanation": "ここは〈硯〉の意味。墨をする道具は硯で、試金石では墨をすれないので合わない。"}, {"text": "切手の細かい文字を、試金石で読んだ。", "explanation": "ここは〈ルーペ〉の意味。小さな字を拡大して読む道具はルーペで、試金石では文字は読めないので合わない。"}, {"text": "落ちた釘を、試金石で集めた。", "explanation": "ここは〈磁石〉の意味。釘を引き寄せて集めるのは磁石で、試金石にはその働きがないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39062, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "職人は金貨の純度を、試金石をこすりつけて確かめた。", "corrected_sentence": "職人は金貨の純度を、試金石にこすりつけて確かめた。", "error_description": "「こすりつける」は、こすりつける先に「に」を取る。「試金石を」の「を」が誤りで、「試金石に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39062, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は銀の指輪を試金石をこすりつけて、本物か確かめた。", "corrected_sentence": "祖母は銀の指輪を試金石にこすりつけて、本物か確かめた。", "error_description": "「こすりつける」の相手は「に」で示す。「試金石を」の「を」が誤りで、「試金石に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39063, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「会社の試金石だ」の「の」。名詞どうしをつなぐ連体修飾。"}, {"text": "を", "is_correct": false, "explanation": "「会社を試金石だ」は文の骨組みが成り立たない。「を」は動作の対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「会社へ試金石だ」は方向を表し、断定の文にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「会社から試金石だ」は起点を表し、断定の文にはならない。"}], "correct_answer": "の", "explanations": {"の": "「会社の試金石だ」の「の」。名詞どうしをつなぐ連体修飾。", "を": "「会社を試金石だ」は文の骨組みが成り立たない。「を」は動作の対象を示す。", "へ": "「会社へ試金石だ」は方向を表し、断定の文にはならない。", "から": "「会社から試金石だ」は起点を表し、断定の文にはならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
