INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39063, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の真価や本質を判断するための基準となるもの。", "primary_collocate": null, "pronunciation": "しきんせき", "ipa": "ɕikiɴseki", "syllable_count": 5, "sentences": [{"text": "この大会は、チームの本当の力を見る試金石になる。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "この大会[たいかい]は、チームの本当[ほんとう]の力[ちから]を見[み]る試金石[しきんせき]になる。", "sentence_source": "generated"}, {"text": "新しい商品が売れるかどうかが、会社の試金石だ。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "新[あたら]しい商品[しょうひん]が売[う]れるかどうかが、会社[かいしゃ]の試金石[しきんせき]だ。", "sentence_source": "generated"}, {"text": "困難なときの行動は、人間の価値を見る試金石になる。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "困難[こんなん]なときの行動[こうどう]は、人間[にんげん]の価値[かち]を見[み]る試金石[しきんせき]になる。", "sentence_source": "generated"}, {"text": "今回の選挙は、新しい政権への評価を示す試金石だった。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "今回[こんかい]の選挙[せんきょ]は、新[あたら]しい政権[せいけん]への評価[ひょうか]を示[しめ]す試金石[しきんせき]だった。", "sentence_source": "generated"}, {"text": "初めての海外での試合は、若い選手にとって試金石だ。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "初[はじ]めての海外[かいがい]での試合[しあい]は、若[わか]い選手[せんしゅ]にとって試金石[しきんせき]だ。", "sentence_source": "generated"}, {"text": "この実験が成功するかどうかが、計画全体の試金石になる。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "この実験[じっけん]が成功[せいこう]するかどうかが、計画全体[けいかくぜんたい]の試金石[しきんせき]になる。", "sentence_source": "generated"}, {"text": "友情の試金石は、苦しいときにそばにいてくれるかどうかだ。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "友情[ゆうじょう]の試金石[しきんせき]は、苦[くる]しいときにそばにいてくれるかどうかだ。", "sentence_source": "generated"}, {"text": "新人にとって、最初の大きな仕事は試金石だ。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "新人[しんじん]にとって、最初[さいしょ]の大[おお]きな仕事[しごと]は試金石[しきんせき]だ。", "sentence_source": "generated"}, {"text": "この制度は、社会が変われるかどうかの試金石となる。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "この制度[せいど]は、社会[しゃかい]が変[か]われるかどうかの試金石[しきんせき]となる。", "sentence_source": "generated"}, {"text": "難しい交渉は、彼の実力の試金石となった。", "target_word": "試金石", "complexity_tier": "T3", "furigana": "難[むずか]しい交渉[こうしょう]は、彼[かれ]の実力[じつりょく]の試金石[しきんせき]となった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "試金石", "label": "実際に使われる形"}, {"form": "試金石だ", "label": "断定形"}, {"form": "試金石になる", "label": "なる述語形"}, {"form": "試金石となる", "label": "となる述語形"}], "register": "neutral", "sense_fingerprint": "人や物事の本当の力・価値をはかる機会や基準(試金石)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a9d509c-8b22-4e3f-930f-2c4fe6e564c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39063, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "試金石", "is_correct": true, "explanation": "「チームの本当の力を見る試金石になる」。力や価値をはかる基準を表す。正解。"}, {"text": "疲労", "is_correct": false, "explanation": "「チームの本当の力を見る疲労になる」は不自然。疲労は力をはかる基準にならない。"}, {"text": "寂寥", "is_correct": false, "explanation": "「チームの本当の力を見る寂寥になる」は文脈に合わない。寂寥は感情で、基準を表さない。"}, {"text": "雑念", "is_correct": false, "explanation": "「チームの本当の力を見る雑念になる」は不自然。雑念は集中を妨げる考えで、力をはかるものではない。"}], "explanations": {"試金石": "「チームの本当の力を見る試金石になる」。力や価値をはかる基準を表す。正解。", "疲労": "「チームの本当の力を見る疲労になる」は不自然。疲労は力をはかる基準にならない。", "寂寥": "「チームの本当の力を見る寂寥になる」は文脈に合わない。寂寥は感情で、基準を表さない。", "雑念": "「チームの本当の力を見る雑念になる」は不自然。雑念は集中を妨げる考えで、力をはかるものではない。"}, "sentence_index": 0, "correct_answer": "試金石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい試みに、試金石を感じた。", "explanation": "ここは〈手応え〉の意味。手応えは感じるものだが、試金石は感じるものではないので合わない。"}, {"text": "審判は、試金石を下した。", "explanation": "ここは〈判定〉の意味。判定を下すとは言うが、試金石を下すとは言わないので合わない。"}, {"text": "先生は試金石で生徒の身長を測った。", "explanation": "ここは〈物差し〉の意味。長さを測る道具は物差しで、試金石は身長を測るものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39063, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "試金石", "is_correct": true, "explanation": "「友情の試金石は、苦しいときにそばにいてくれるかどうかだ」。友情の真価をはかる基準の意味。正解。"}, {"text": "寝具", "is_correct": false, "explanation": "「友情の寝具は」は意味をなさない。寝具は友情の真価を示さない。"}, {"text": "騒音", "is_correct": false, "explanation": "「友情の騒音は」は文脈に合わない。騒音は友情の基準にならない。"}, {"text": "雑草", "is_correct": false, "explanation": "「友情の雑草は」は不自然。雑草は友情の真価をはかるものではない。"}], "explanations": {"試金石": "「友情の試金石は、苦しいときにそばにいてくれるかどうかだ」。友情の真価をはかる基準の意味。正解。", "寝具": "「友情の寝具は」は意味をなさない。寝具は友情の真価を示さない。", "騒音": "「友情の騒音は」は文脈に合わない。騒音は友情の基準にならない。", "雑草": "「友情の雑草は」は不自然。雑草は友情の真価をはかるものではない。"}, "sentence_index": 6, "correct_answer": "試金石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "重さを量るときは、試金石に両方を乗せて比べる。", "explanation": "ここは〈天秤〉の意味。両方を乗せて比べる道具は天秤で、試金石に物を乗せて比べることはないので合わない。"}, {"text": "メーターの試金石を読んだ。", "explanation": "ここは〈目盛り〉の意味。数値を読むのは目盛りで、試金石は読むものではないので合わない。"}, {"text": "試金石に映った自分の顔を見た。", "explanation": "ここは〈鏡〉の意味。姿を映すのは鏡で、試金石は像を映す道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39063, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この試練は、新人の心を見る試金石がなる。", "corrected_sentence": "この試練は、新人の心を見る試金石になる。", "error_description": "「なる」は「に」を取る。「試金石が」の「が」は誤りで、「試金石に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39063, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この面接は、学生の覚悟を見る試金石でなる。", "corrected_sentence": "この面接は、学生の覚悟を見る試金石になる。", "error_description": "「なる」は「に」を取る。「試金石で」の「で」が誤りで、「試金石に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbede87-e7d6-4bb5-b3c3-b2694aa7f34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39066, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39066, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『選ぶ』の目的語を示す『を』で、綿を選ぶという文に合う。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す『が』だと『綿が選ぶ』となり、不自然で合わない。"}, {"text": "に", "is_correct": false, "explanation": "『綿に選ぶ』となり、『選ぶ』の目的語としては合わない。"}, {"text": "と", "is_correct": false, "explanation": "『綿と選ぶ』となり、並列や相手を示す文脈にならず合わない。"}], "correct_answer": "を", "explanations": {"を": "『選ぶ』の目的語を示す『を』で、綿を選ぶという文に合う。", "が": "主語を示す『が』だと『綿が選ぶ』となり、不自然で合わない。", "に": "『綿に選ぶ』となり、『選ぶ』の目的語としては合わない。", "と": "『綿と選ぶ』となり、並列や相手を示す文脈にならず合わない。"}, "error_tags": {"が": "主語", "に": "方向・位置", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39066, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ふわふわした白いもので、洋服を作るのに使います。", "primary_collocate": null, "pronunciation": "めん", "ipa": "meɴ", "syllable_count": 2, "sentences": [{"text": "夏は汗をよく吸うので、綿のシャツを着る。", "target_word": "綿", "complexity_tier": "T3", "furigana": "夏(なつ)は汗(あせ)をよく吸(す)うので、綿(めん)のシャツを着(き)る。", "sentence_source": "generated"}, {"text": "この靴下は綿100%だから、肌にやさしい。", "target_word": "綿", "complexity_tier": "T3", "furigana": "この靴下(くつした)は綿(めん)100%だから、肌(はだ)にやさしい。", "sentence_source": "generated"}, {"text": "綿のワンピースは洗いやすくて、毎日着られる。", "target_word": "綿", "complexity_tier": "T3", "furigana": "綿(めん)のワンピースは洗(あら)いやすくて、毎日(まいにち)着(き)られる。", "sentence_source": "generated"}, {"text": "このTシャツは綿と化学繊維が半分ずつなので、すぐ乾く。", "target_word": "綿", "complexity_tier": "T3", "furigana": "このTシャツは綿(めん)と化学(かがく)繊維(せんい)が半分(はんぶん)ずつなので、すぐ乾(かわ)く。", "sentence_source": "generated"}, {"text": "赤ちゃんの服は、やわらかい綿で作られている。", "target_word": "綿", "complexity_tier": "T3", "furigana": "赤(あか)ちゃんの服(ふく)は、やわらかい綿(めん)で作(つく)られている。", "sentence_source": "generated"}, {"text": "綿の白いハンカチを一枚買った。", "target_word": "綿", "complexity_tier": "T3", "furigana": "綿(めん)の白(しろ)いハンカチを一枚(いちまい)買(か)った。", "sentence_source": "generated"}, {"text": "綿は水をよく吸うが、乾くのに時間がかかる。", "target_word": "綿", "complexity_tier": "T3", "furigana": "綿(めん)は水(みず)をよく吸(す)うが、乾(かわ)くのに時間(じかん)がかかる。", "sentence_source": "generated"}, {"text": "絹より綿のほうが安いので、普段着には綿を選ぶ。", "target_word": "綿", "complexity_tier": "T3", "furigana": "絹(きぬ)より綿(めん)のほうが安(やす)いので、普段着(ふだんぎ)には綿(めん)を選(えら)ぶ。", "sentence_source": "generated"}, {"text": "汗をかく仕事なので、綿の下着を選んでいる。", "target_word": "綿", "complexity_tier": "T3", "furigana": "汗(あせ)をかく仕事(しごと)なので、綿(めん)の下着(したぎ)を選(えら)んでいる。", "sentence_source": "generated"}, {"text": "この白い綿のシャツは、洗うたびにやわらかくなる。", "target_word": "綿", "complexity_tier": "T3", "furigana": "この白(しろ)い綿(めん)のシャツは、洗(あら)うたびにやわらかくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "綿", "label": "基本形"}], "register": "中立(普通体)", "sense_fingerprint": "洋服の素材としての綿。やわらかく白い布のもと。シャツや靴下など身につけるものの素材。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd49ee28-674e-431e-aee3-ee814a8995c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39066, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "綿", "is_correct": true, "explanation": "夏に汗を吸う素材として自然で、文の内容と合う綿の素材。"}, {"text": "革", "is_correct": false, "explanation": "革は汗を吸わないので、汗を吸うから夏に着るという理由と合わない。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は服の素材にならず、文が成り立たない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は夏のシャツの素材として不自然で、汗を吸う理由とも合わない。"}], "explanations": {"綿": "夏に汗を吸う素材として自然で、文の内容と合う綿の素材。", "革": "革は汗を吸わないので、汗を吸うから夏に着るという理由と合わない。", "鉄": "鉄は服の素材にならず、文が成り立たない。", "紙": "紙は夏のシャツの素材として不自然で、汗を吸う理由とも合わない。"}, "sentence_index": 0, "correct_answer": "綿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "綿を焼いて、陶器の器を作る。", "explanation": "ここは粘土を焼いて陶器にする話。綿は焼いても器にならないので、陶器の材料にはならない。"}, {"text": "畑で綿の乳を搾って、チーズを作る。", "explanation": "ここは牛の乳を搾る話。綿から乳はとれないので、チーズの材料にはならない。"}, {"text": "綿をなめして、靴を作る。", "explanation": "ここは革をなめして柔らかくする話。綿は皮ではないので、なめす対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39066, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "綿", "is_correct": true, "explanation": "水をよく吸うが乾きにくい素材として、文の内容に合う綿。"}, {"text": "石", "is_correct": false, "explanation": "石は水を吸わないので、水をよく吸うという文が成り立たない。"}, {"text": "ガラス", "is_correct": false, "explanation": "ガラスは水を吸わないので、文の前半と合わない。"}, {"text": "氷", "is_correct": false, "explanation": "氷は水を吸う素材ではなく、乾くのに時間がかかるという話とも合わない。"}], "explanations": {"綿": "水をよく吸うが乾きにくい素材として、文の内容に合う綿。", "石": "石は水を吸わないので、水をよく吸うという文が成り立たない。", "ガラス": "ガラスは水を吸わないので、文の前半と合わない。", "氷": "氷は水を吸う素材ではなく、乾くのに時間がかかるという話とも合わない。"}, "sentence_index": 6, "correct_answer": "綿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の予定を綿に書いて、壁に貼った。", "explanation": "ここは字を書く紙の話。綿には字を書けないので、この使い方はしない。"}, {"text": "綿を水に溶かして、シロップを作った。", "explanation": "ここは水に溶ける砂糖の話。綿は水に溶けないので、溶かすとは言わない。"}, {"text": "綿を磨いて、きれいな光沢を出した。", "explanation": "ここは石を磨く話。綿は磨いて光沢を出すものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39066, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暑い日は、綿に白い帽子をかぶる。", "corrected_sentence": "暑い日は、綿の白い帽子をかぶる。", "error_description": "綿の後の助詞が『に』になっている。綿は帽子の素材を表すので『の』で続け、正しくは『綿の白い帽子』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39066, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "綿に使った布団は、思ったより軽い。", "corrected_sentence": "綿を使った布団は、思ったより軽い。", "error_description": "綿の後の助詞が『に』になっている。『使う』は目的語に『を』を取るので、正しくは『綿を使った』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39067, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『育てる』の目的語を示す『を』で、綿を育てるという文に合う。"}, {"text": "に", "is_correct": false, "explanation": "『綿に育てて』となり、目的語として合わない。"}, {"text": "が", "is_correct": false, "explanation": "主語の『が』だと『綿が育てて』となり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "『綿と育てて』となり、並列を示す文脈にならず合わない。"}], "correct_answer": "を", "explanations": {"を": "『育てる』の目的語を示す『を』で、綿を育てるという文に合う。", "に": "『綿に育てて』となり、目的語として合わない。", "が": "主語の『が』だと『綿が育てて』となり、文が成り立たない。", "と": "『綿と育てて』となり、並列を示す文脈にならず合わない。"}, "error_tags": {"に": "方向・位置", "が": "主語", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39067, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『綿の値段』と所属を示す『の』で、文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語の『を』だと『綿を値段が上がった』となり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『綿に値段が上がった』は文が成り立たず、『値段が上がる』に『に』は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』だと『綿へ値段が上がった』となり、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "『綿の値段』と所属を示す『の』で、文の意味に合う。", "を": "目的語の『を』だと『綿を値段が上がった』となり、文が成り立たない。", "に": "『綿に値段が上がった』は文が成り立たず、『値段が上がる』に『に』は合わない。", "へ": "方向の『へ』だと『綿へ値段が上がった』となり、文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "方向・位置", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39067, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "衣服などの原料となる、植物の種子からとれる繊維です。", "primary_collocate": null, "pronunciation": "めん", "ipa": "meɴ", "syllable_count": 2, "sentences": [{"text": "綿は植物の種からとれる繊維で、服の原料になる。", "target_word": "綿", "complexity_tier": "T3", "furigana": "綿(めん)は植物(しょくぶつ)の種(たね)からとれる繊維(せんい)で、服(ふく)の原料(げんりょう)になる。", "sentence_source": "generated"}, {"text": "この畑では、綿を育てて糸にしている。", "target_word": "綿", "complexity_tier": "T3", "furigana": "この畑(はたけ)では、綿(めん)を育(そだ)てて糸(いと)にしている。", "sentence_source": "generated"}, {"text": "綿の糸を染めて、布を織る。", "target_word": "綿", "complexity_tier": "T3", "furigana": "綿(めん)の糸(いと)を染(そ)めて、布(ぬの)を織(お)る。", "sentence_source": "generated"}, {"text": "綿と麻は、どちらも植物からとれる素材だ。", "target_word": "綿", "complexity_tier": "T3", "furigana": "綿(めん)と麻(あさ)は、どちらも植物(しょくぶつ)からとれる素材(そざい)だ。", "sentence_source": "generated"}, {"text": "暑い国では、綿の生産がさかんだ。", "target_word": "綿", "complexity_tier": "T3", "furigana": "暑(あつ)い国(くに)では、綿(めん)の生産(せいさん)がさかんだ。", "sentence_source": "generated"}, {"text": "工場は外国から綿を買って、タオルを作っている。", "target_word": "綿", "complexity_tier": "T3", "furigana": "工場(こうじょう)は外国(がいこく)から綿(めん)を買(か)って、タオルを作(つく)っている。", "sentence_source": "generated"}, {"text": "動物からとる絹とちがって、綿は植物の繊維だ。", "target_word": "綿", "complexity_tier": "T3", "furigana": "動物(どうぶつ)からとる絹(きぬ)とちがって、綿(めん)は植物(しょくぶつ)の繊維(せんい)だ。", "sentence_source": "generated"}, {"text": "綿の値段が上がったので、シャツも高くなった。", "target_word": "綿", "complexity_tier": "T3", "furigana": "綿(めん)の値段(ねだん)が上(あ)がったので、シャツも高(たか)くなった。", "sentence_source": "generated"}, {"text": "綿を細い糸にする機械を見学した。", "target_word": "綿", "complexity_tier": "T3", "furigana": "綿(めん)を細(ほそ)い糸(いと)にする機械(きかい)を見学(けんがく)した。", "sentence_source": "generated"}, {"text": "昔、この町は綿の産地として栄えた。", "target_word": "綿", "complexity_tier": "T3", "furigana": "昔(むかし)、この町(まち)は綿(めん)の産地(さんち)として栄(さか)えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "綿", "label": "基本形"}], "register": "中立(普通体)", "sense_fingerprint": "植物の種子からとれる繊維としての綿。糸や布の原料、栽培・生産・産地の話題。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd49ee28-674e-431e-aee3-ee814a8995c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39067, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "綿", "is_correct": true, "explanation": "植物の種からとれる繊維として、文の内容に合う綿。"}, {"text": "木", "is_correct": false, "explanation": "木は種からとれる繊維ではなく、服の原料にもならない。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は繊維ではなく、服の原料にもならないので文が成り立たない。"}, {"text": "氷", "is_correct": false, "explanation": "氷は繊維ではなく、服の原料になるという文と合わない。"}], "explanations": {"綿": "植物の種からとれる繊維として、文の内容に合う綿。", "木": "木は種からとれる繊維ではなく、服の原料にもならない。", "鉄": "鉄は繊維ではなく、服の原料にもならないので文が成り立たない。", "氷": "氷は繊維ではなく、服の原料になるという文と合わない。"}, "sentence_index": 0, "correct_answer": "綿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山の奥で綿を掘り出して、トラックで運ぶ。", "explanation": "ここは地下から石炭を掘る話。綿は畑で摘み取るもので、掘り出すとは言わない。"}, {"text": "綿を精錬して、丈夫な鋼を作る。", "explanation": "ここは鉄を精錬する話。綿は精錬の対象ではなく、鋼の材料にもならない。"}, {"text": "綿を砕いて、ガラスのコップを作る。", "explanation": "ここはガラスを作る話。綿は砕いてもガラスにはならないので、コップの材料にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39067, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "綿", "is_correct": true, "explanation": "動物からとる素材と対比して植物の繊維と言える綿。"}, {"text": "毛", "is_correct": false, "explanation": "毛は動物の体からとれるもので、植物の繊維とは合わない。"}, {"text": "皮", "is_correct": false, "explanation": "皮は動物からとれるもので、植物の繊維とは言えない。"}, {"text": "骨", "is_correct": false, "explanation": "骨は繊維ではなく、動物の対比の文と合わない。"}], "explanations": {"綿": "動物からとる素材と対比して植物の繊維と言える綿。", "毛": "毛は動物の体からとれるもので、植物の繊維とは合わない。", "皮": "皮は動物からとれるもので、植物の繊維とは言えない。", "骨": "骨は繊維ではなく、動物の対比の文と合わない。"}, "sentence_index": 6, "correct_answer": "綿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "綿を粉にひいて、パンを焼く。", "explanation": "ここは小麦を粉にひく話。綿は粉にしてパンの材料にするものではないので、この使い方はしない。"}, {"text": "綿を電池の代わりに入れて、ラジオをつける。", "explanation": "ここは電池の話。綿は電気をためられないので、電池の代わりにはならない。"}, {"text": "綿をうすく切って、おにぎりの具にする。", "explanation": "ここは具材の話。綿は食べられないので、おにぎりの具にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39067, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "綿に植える畑は、暑い地方に多い。", "corrected_sentence": "綿を植える畑は、暑い地方に多い。", "error_description": "綿の後の助詞が『に』になっている。『植える』は目的語に『を』を取るので、正しくは『綿を植える畑』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
