INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39068, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体に着るものです。", "primary_collocate": null, "pronunciation": "ふく", "ipa": "ɸɯkɯ", "syllable_count": 2, "sentences": [{"text": "今日は暑いので、うすい服を着て学校に行きます。", "target_word": "服", "complexity_tier": "T3", "furigana": "今日[きょう]は暑[あつ]いので、うすい服[ふく]を着[き]て学校[がっこう]に行[い]きます。", "sentence_source": "generated"}, {"text": "妹は毎日、自分で服をえらびます。", "target_word": "服", "complexity_tier": "T3", "furigana": "妹[いもうと]は毎日[まいにち]、自分[じぶん]で服[ふく]をえらびます。", "sentence_source": "generated"}, {"text": "服が小さくなったので、新しいのを買いに行きました。", "target_word": "服", "complexity_tier": "T3", "furigana": "服[ふく]が小[ちい]さくなったので、新[あたら]しいのを買[か]いに行[い]きました。", "sentence_source": "generated"}, {"text": "赤い服を着た女の子が、公園であそんでいます。", "target_word": "服", "complexity_tier": "T3", "furigana": "赤[あか]い服[ふく]を着[き]た女[おんな]の子[こ]が、公園[こうえん]であそんでいます。", "sentence_source": "generated"}, {"text": "雨の日は、服がぬれないようにかさをさします。", "target_word": "服", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、服[ふく]がぬれないようにかさをさします。", "sentence_source": "generated"}, {"text": "兄は服をたたんで、たんすにしまいました。", "target_word": "服", "complexity_tier": "T3", "furigana": "兄[あに]は服[ふく]をたたんで、たんすにしまいました。", "sentence_source": "generated"}, {"text": "このシャツは、わたしの好きな服です。", "target_word": "服", "complexity_tier": "T3", "furigana": "このシャツは、わたしの好[す]きな服[ふく]です。", "sentence_source": "generated"}, {"text": "冬は寒いので、服を何まいも重ねて着ます。", "target_word": "服", "complexity_tier": "T3", "furigana": "冬[ふゆ]は寒[さむ]いので、服[ふく]を何[なん]まいも重[かさ]ねて着[き]ます。", "sentence_source": "generated"}, {"text": "服をよごしたら、お母さんにおこられました。", "target_word": "服", "complexity_tier": "T3", "furigana": "服[ふく]をよごしたら、お母[かあ]さんにおこられました。", "sentence_source": "generated"}, {"text": "友だちの家に行く前に、服をきれいなものにかえた。", "target_word": "服", "complexity_tier": "T3", "furigana": "友[とも]だちの家[いえ]に行[い]く前[まえ]に、服[ふく]をきれいなものにかえた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "服", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "体に着るもの、衣類を指す基本的な名詞(ふく)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: contains vocabulary far above tier T1: えらび (Zipf 1.84)','sentence 4 above tier T1: 3 words above tier T1 (max 2): ぬれ (Zipf 3.24), かさ (Zipf 3.68), さし (Zipf 3.76)','sentence 8 above tier T1: contains vocabulary far above tier T1: よごし (Zipf 1.74)']::text[], 'c8c15191-2253-47bd-9d8a-2b9974970fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39068, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "服", "is_correct": true, "explanation": "正解。「着て学校に行く」ものとして成り立つ衣類を指す。"}, {"text": "雨", "is_correct": false, "explanation": "雨は「着て」学校に行くものではないので、空欄に入らない。"}, {"text": "会議", "is_correct": false, "explanation": "会議は「着て」学校に行くものではないので、文が成り立たない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は「着て」学校に行くものではないので、この文には入らない。"}], "explanations": {"服": "正解。「着て学校に行く」ものとして成り立つ衣類を指す。", "雨": "雨は「着て」学校に行くものではないので、空欄に入らない。", "会議": "会議は「着て」学校に行くものではないので、文が成り立たない。", "宿題": "宿題は「着て」学校に行くものではないので、この文には入らない。"}, "sentence_index": 0, "correct_answer": "服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服で水をのみました。", "explanation": "ここは〈コップ〉（飲み物を入れる器）の意味。服は体に着るものなので、飲み物を入れる用途には合わない。"}, {"text": "服で野菜を切って、サラダを作った。", "explanation": "ここは〈包丁〉（野菜を切る道具）の意味。服は体に着るものなので、切る道具としては合わない。"}, {"text": "ノートの服に字を書いた。", "explanation": "ここは〈紙〉（字を書く面）の意味。服は体に着るものなので、書く面としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39068, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "服", "is_correct": true, "explanation": "正解。「わたしの好きな」の後に入り、衣類を指す。"}, {"text": "試験", "is_correct": false, "explanation": "試験は「好きな」と修飾して「です」で結ぶ対象として不自然。"}, {"text": "病気", "is_correct": false, "explanation": "病気は「好きな」の対象として意味が通らないので、この文には入らない。"}, {"text": "事故", "is_correct": false, "explanation": "事故は「好きな」の対象として意味が通らないので、空欄に入らない。"}], "explanations": {"服": "正解。「わたしの好きな」の後に入り、衣類を指す。", "試験": "試験は「好きな」と修飾して「です」で結ぶ対象として不自然。", "病気": "病気は「好きな」の対象として意味が通らないので、この文には入らない。", "事故": "事故は「好きな」の対象として意味が通らないので、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服でパンを焼いて、朝食に出した。", "explanation": "ここは〈オーブン〉（焼く器具）の意味。服は体に着るものなので、焼く道具としては合わない。"}, {"text": "ノートの服を一枚やぶって、手紙を書いた。", "explanation": "ここは〈紙〉（ノートの紙）の意味。服は体に着るものなので、紙を指す用途には合わない。"}, {"text": "服で野菜を煮込んで、スープを作った。", "explanation": "ここは〈鍋〉（煮るための器具）の意味。服は体に着るものなので、煮る道具としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39068, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝、ぬれた服が乾かしました。", "corrected_sentence": "朝、ぬれた服を乾かしました。", "error_description": "「乾かす」の対象は「を」で示す。「服が」と主語にすると、乾かす動作の対象として不自然なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
