INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39069, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "より", "options": [{"text": "より", "is_correct": true, "explanation": "正解（比較：青い服より白い服）"}, {"text": "を", "is_correct": false, "explanation": "対象（服を白い服のほうが好き、は成り立たない）"}, {"text": "から", "is_correct": false, "explanation": "起点（服から白い服、は比較として不自然）"}, {"text": "の", "is_correct": false, "explanation": "所属（服の白い服、は比較として不自然）"}], "correct_answer": "より", "explanations": {"より": "正解（比較：青い服より白い服）", "を": "対象（服を白い服のほうが好き、は成り立たない）", "から": "起点（服から白い服、は比較として不自然）", "の": "所属（服の白い服、は比較として不自然）"}, "error_tags": {"より": "正解（比較：青い服より白い服）", "を": "対象（服を白い服のほうが好き、は成り立たない）", "から": "起点（服から白い服、は比較として不自然）", "の": "所属（服の白い服、は比較として不自然）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39069, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が体に着る衣類の総称。", "primary_collocate": null, "pronunciation": "ふく", "ipa": "ɸɯkɯ", "syllable_count": 2, "sentences": [{"text": "今日はこの服を着て、出かけます。", "target_word": "服", "complexity_tier": "T3", "furigana": "今日[きょう]はこの服[ふく]を着[き]て、出[で]かけます。", "sentence_source": "generated"}, {"text": "雨にぬれたので、新しい服にきがえました。", "target_word": "服", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれたので、新[あたら]しい服[ふく]にきがえました。", "sentence_source": "generated"}, {"text": "弟は大きくなって、去年の服がきつくなった。", "target_word": "服", "complexity_tier": "T3", "furigana": "弟[おとうと]は大[おお]きくなって、去年[きょねん]の服[ふく]がきつくなった。", "sentence_source": "generated"}, {"text": "この店は子ども用の服をたくさん売っています。", "target_word": "服", "complexity_tier": "T3", "furigana": "この店[みせ]は子[こ]ども用[よう]の服[ふく]をたくさん売[う]っています。", "sentence_source": "generated"}, {"text": "寒い日は、あつい服を二枚着て出かけます。", "target_word": "服", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]は、あつい服[ふく]を二枚[にまい]着[き]て出[で]かけます。", "sentence_source": "generated"}, {"text": "母は毎朝、洗った服をベランダにほします。", "target_word": "服", "complexity_tier": "T3", "furigana": "母[はは]は毎朝[まいあさ]、洗[あら]った服[ふく]をベランダにほします。", "sentence_source": "generated"}, {"text": "旅行のとき、服はかばんに入れて持っていきます。", "target_word": "服", "complexity_tier": "T3", "furigana": "旅行[りょこう]のとき、服[ふく]はかばんに入[い]れて持[も]っていきます。", "sentence_source": "generated"}, {"text": "私は青い服より、白い服のほうが好きです。", "target_word": "服", "complexity_tier": "T3", "furigana": "私[わたし]は青[あお]い服[ふく]より、白[しろ]い服[ふく]のほうが好[す]きです。", "sentence_source": "generated"}, {"text": "服にソースがついてしまい、すぐに洗いました。", "target_word": "服", "complexity_tier": "T3", "furigana": "服[ふく]にソースがついてしまい、すぐに洗[あら]いました。", "sentence_source": "generated"}, {"text": "パーティーがあるので、きれいな服を買いたいです。", "target_word": "服", "complexity_tier": "T3", "furigana": "パーティーがあるので、きれいな服[ふく]を買[か]いたいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "服", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人が体に着る衣類全般を指す名詞(ふく)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: contains vocabulary far above tier T1: きがえ (Zipf 1.73)','sentence 5 above tier T1: 3 words above tier T1 (max 2): 毎朝 (Zipf 3.91), ベランダ (Zipf 3.66), ほし (Zipf 3.83)']::text[], 'c8c15191-2253-47bd-9d8a-2b9974970fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39069, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "服", "is_correct": true, "explanation": "正解。「着て出かける」対象になる衣類を指す。"}, {"text": "雨", "is_correct": false, "explanation": "雨は「着て」出かける対象にならないので、空欄に入らない。"}, {"text": "会議", "is_correct": false, "explanation": "会議は「着て」出かける対象にならず、この文は成り立たない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は「着て」出かける対象にならず、この文には入らない。"}], "explanations": {"服": "正解。「着て出かける」対象になる衣類を指す。", "雨": "雨は「着て」出かける対象にならないので、空欄に入らない。", "会議": "会議は「着て」出かける対象にならず、この文は成り立たない。", "宿題": "宿題は「着て」出かける対象にならず、この文には入らない。"}, "sentence_index": 0, "correct_answer": "服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服で水をのみ、のどをうるおした。", "explanation": "ここは〈コップ〉（飲み物を入れる器）の意味。服は体に着る衣類なので、飲み物を入れる用途には合わない。"}, {"text": "服でお湯をわかして、紅茶を入れた。", "explanation": "ここは〈やかん〉（湯をわかす器具）の意味。服は体に着る衣類なので、湯をわかす用途には合わない。"}, {"text": "ノートの服に、大事な予定を書いた。", "explanation": "ここは〈紙〉（書く面）の意味。服は体に着る衣類なので、書く面としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39069, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "服", "is_correct": true, "explanation": "正解。「かばんに入れて持っていく」ものとして成り立つ衣類を指す。"}, {"text": "天気", "is_correct": false, "explanation": "天気はかばんに入れて持っていけないので、この文には入らない。"}, {"text": "会議", "is_correct": false, "explanation": "会議はかばんに入れて持っていけないので、空欄に入らない。"}, {"text": "病気", "is_correct": false, "explanation": "病気はかばんに入れて持っていけないので、文が成り立たない。"}], "explanations": {"服": "正解。「かばんに入れて持っていく」ものとして成り立つ衣類を指す。", "天気": "天気はかばんに入れて持っていけないので、この文には入らない。", "会議": "会議はかばんに入れて持っていけないので、空欄に入らない。", "病気": "病気はかばんに入れて持っていけないので、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服でパンを焼いて、朝食に出した。", "explanation": "ここは〈オーブン〉（焼く器具）の意味。服は体に着る衣類なので、焼く道具としては合わない。"}, {"text": "ノートの服を一枚ちぎりました。", "explanation": "ここは〈紙〉（ノートの紙）の意味。服は衣類なので、ノートの紙を指す用途には合わない。"}, {"text": "服で野菜を煮て、スープを作りました。", "explanation": "ここは〈鍋〉（煮るための器具）の意味。服は衣類なので、煮る道具としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39069, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒いので、厚い服が着て出かけました。", "corrected_sentence": "寒いので、厚い服を着て出かけました。", "error_description": "「着る」の対象は「を」で示す。「服が」と主語にすると、着る動作の対象として不自然なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39069, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "引き出しに服にしまいました。", "corrected_sentence": "引き出しに服をしまいました。", "error_description": "「しまう」の対象は「を」で示す。「服に」と書くと、しまう対象として不自然なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39070, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "材料を表す『で』で、『繊維でできている』という文に合う。"}, {"text": "に", "is_correct": false, "explanation": "『繊維にできている』となり、材料を示す表現として合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の『を』だと『繊維をできている』となり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "『繊維とできている』となり、材料を示す文脈にならず合わない。"}], "correct_answer": "で", "explanations": {"で": "材料を表す『で』で、『繊維でできている』という文に合う。", "に": "『繊維にできている』となり、材料を示す表現として合わない。", "を": "目的語の『を』だと『繊維をできている』となり、文が成り立たない。", "と": "『繊維とできている』となり、材料を示す文脈にならず合わない。"}, "error_tags": {"に": "方向・帰着", "を": "目的語", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39070, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『切れる』の主語を示す『が』で、繊維が切れたという文に合う。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』だと『繊維へ切れて』となり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "所属の『の』だと『繊維の切れて』となり、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の『より』だと『繊維より切れて』となり、不自然で合わない。"}], "correct_answer": "が", "explanations": {"が": "『切れる』の主語を示す『が』で、繊維が切れたという文に合う。", "へ": "方向の『へ』だと『繊維へ切れて』となり、文が成り立たない。", "の": "所属の『の』だと『繊維の切れて』となり、文が成り立たない。", "より": "比較の『より』だと『繊維より切れて』となり、不自然で合わない。"}, "error_tags": {"へ": "方向", "の": "所属・修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39070, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "布や紙のもとになる、細くて長いものです。", "primary_collocate": null, "pronunciation": "せんい", "ipa": "seɴi", "syllable_count": 3, "sentences": [{"text": "紙は、木の繊維をからませて作る。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "紙(かみ)は、木(き)の繊維(せんい)をからませて作(つく)る。", "sentence_source": "generated"}, {"text": "この布は、細い繊維でできているので、とても軽い。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "この布(ぬの)は、細(ほそ)い繊維(せんい)でできているので、とても軽(かる)い。", "sentence_source": "generated"}, {"text": "顕微鏡で見ると、布の繊維が一本一本見える。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "顕微鏡(けんびきょう)で見(み)ると、布(ぬの)の繊維(せんい)が一本一本(いっぽんいっぽん)見(み)える。", "sentence_source": "generated"}, {"text": "綿や麻は、植物の繊維から作られる。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "綿(めん)や麻(あさ)は、植物(しょくぶつ)の繊維(せんい)から作(つく)られる。", "sentence_source": "generated"}, {"text": "古い服から繊維を取り出して、新しい布に作り直す。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "古(ふる)い服(ふく)から繊維(せんい)を取(と)り出(だ)して、新(あたら)しい布(ぬの)に作(つく)り直(なお)す。", "sentence_source": "generated"}, {"text": "この紙は繊維が長いので、破れにくい。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "この紙(かみ)は繊維(せんい)が長(なが)いので、破(やぶ)れにくい。", "sentence_source": "generated"}, {"text": "ポリエステルの繊維は、乾きが早い。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "ポリエステルの繊維(せんい)は、乾(かわ)きが早(はや)い。", "sentence_source": "generated"}, {"text": "繊維が切れて、セーターに穴があいた。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "繊維(せんい)が切(き)れて、セーターに穴(あな)があいた。", "sentence_source": "generated"}, {"text": "太い繊維で織ったので、このカーペットは丈夫だ。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "太(ふと)い繊維(せんい)で織(お)ったので、このカーペットは丈夫(じょうぶ)だ。", "sentence_source": "generated"}, {"text": "町の工場では、繊維を糸にしてから布を織る。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "町(まち)の工場(こうじょう)では、繊維(せんい)を糸(いと)にしてから布(ぬの)を織(お)る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "繊維", "label": "基本形"}], "register": "中立(普通体)", "sense_fingerprint": "布や紙の材料になる細く長いもの。糸状の素材そのもの。食物繊維の意味ではない。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd49ee28-674e-431e-aee3-ee814a8995c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39070, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繊維", "is_correct": true, "explanation": "木からからませて紙を作る細く長い素材として、文の内容に合う繊維。"}, {"text": "粒", "is_correct": false, "explanation": "粒は細く長いものではなく、からませて紙を作る材料にならない。"}, {"text": "石", "is_correct": false, "explanation": "石はからませて紙を作る材料にならず、文が成り立たない。"}, {"text": "油", "is_correct": false, "explanation": "油はからませて紙を作る材料にならず、文が成り立たない。"}], "explanations": {"繊維": "木からからませて紙を作る細く長い素材として、文の内容に合う繊維。", "粒": "粒は細く長いものではなく、からませて紙を作る材料にならない。", "石": "石はからませて紙を作る材料にならず、文が成り立たない。", "油": "油はからませて紙を作る材料にならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "繊維"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "繊維を煮詰めて、砂糖の代わりに甘いシロップを作る。", "explanation": "ここは果物の砂糖を煮詰める話。繊維は甘くないので、砂糖の代わりにはならない。"}, {"text": "繊維をふるって、ケーキ生地に混ぜる。", "explanation": "ここは粉の小麦粉をふるう話。繊維は細く長いもので、粉のようにふるうことはできない。"}, {"text": "繊維を溶接して、鉄骨の柱を作る。", "explanation": "ここは鉄骨を溶接する話。繊維は溶接の材料にならないので、柱の材料にもならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39070, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繊維", "is_correct": true, "explanation": "ポリエステルの糸状の素材として、乾きが早いと述べる文に合う繊維。"}, {"text": "氷", "is_correct": false, "explanation": "氷はポリエステルの素材ではなく、乾きが早いという文と合わない。"}, {"text": "粉", "is_correct": false, "explanation": "粉はポリエステルの素材ではなく、文が成り立たない。"}, {"text": "砂", "is_correct": false, "explanation": "砂はポリエステルの素材ではなく、文が成り立たない。"}], "explanations": {"繊維": "ポリエステルの糸状の素材として、乾きが早いと述べる文に合う繊維。", "氷": "氷はポリエステルの素材ではなく、乾きが早いという文と合わない。", "粉": "粉はポリエステルの素材ではなく、文が成り立たない。", "砂": "砂はポリエステルの素材ではなく、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "繊維"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "繊維を板に打ちつけて、釘の代わりにする。", "explanation": "ここは釘の話。繊維は硬い金属ではないので、釘の代わりにはならない。"}, {"text": "繊維を磨いて、指輪にする。", "explanation": "ここは石を磨く話。繊維は磨いて光らせるものではなく、指輪の材料にもならない。"}, {"text": "繊維を沸かして、お茶を入れる。", "explanation": "ここは水を沸かす話。繊維は沸かして飲むものではないので、お茶の材料にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39070, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この毛布は、細い繊維に作られている。", "corrected_sentence": "この毛布は、細い繊維で作られている。", "error_description": "繊維の後の助詞が『に』になっている。材料を表すには『で』を使うので、正しくは『細い繊維で作られている』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39070, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "繊維を長いほど、紙は破れにくくなる。", "corrected_sentence": "繊維が長いほど、紙は破れにくくなる。", "error_description": "繊維の後の助詞が『を』になっている。『長い』の主語は『が』で示すので、正しくは『繊維が長いほど』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39072, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「将来のことを思う」と、思う対象を示す格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「将来のことに思う」は対象を示す格として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、思う対象とは合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を示す「で」は、思う対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「将来のことを思う」と、思う対象を示す格助詞。", "に": "「将来のことに思う」は対象を示す格として不自然。", "へ": "方向を示す「へ」は、思う対象とは合わない。", "で": "手段・場所を示す「で」は、思う対象を示せない。"}, "error_tags": {"に": "対象の格不一致", "へ": "方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39072, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「友達のことを思い」と、思う対象を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「友達のことが思い」は主語の格になり、思う対象として成立しない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」では「友達のことの思い、」と名詞で止まり、文が続かない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「友達のことより思い」となり、対象を示す格にならず不自然。"}], "correct_answer": "を", "explanations": {"を": "正解。「友達のことを思い」と、思う対象を示す格助詞。", "が": "「友達のことが思い」は主語の格になり、思う対象として成立しない。", "の": "連体修飾の「の」では「友達のことの思い、」と名詞で止まり、文が続かない。", "より": "比較の「より」では「友達のことより思い」となり、対象を示す格にならず不自然。"}, "error_tags": {"が": "主語の格", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39072, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "頭の中で何かを考えることです。", "primary_collocate": null, "pronunciation": "おもう", "ipa": "omoɯ", "syllable_count": 3, "sentences": [{"text": "明日の発表について、どう話そうかと思っている。", "target_word": "思って", "complexity_tier": "T3", "furigana": "明日[あした]の発表[はっぴょう]について、どう話[はな]そうかと思[おも]っている。", "sentence_source": "generated"}, {"text": "将来のことを思うと、少し不安になる。", "target_word": "思う", "complexity_tier": "T3", "furigana": "将来[しょうらい]のことを思[おも]うと、少[すこ]し不安[ふあん]になる。", "sentence_source": "generated"}, {"text": "彼が怒った理由を、帰り道でずっと思っていた。", "target_word": "思って", "complexity_tier": "T3", "furigana": "彼[かれ]が怒[おこ]った理由[りゆう]を、帰[かえ]り道[みち]でずっと思[おも]っていた。", "sentence_source": "generated"}, {"text": "この問題の答えについて、解く前に頭の中で思ってみた。", "target_word": "思って", "complexity_tier": "T3", "furigana": "この問題[もんだい]の答[こた]えについて、解[と]く前[まえ]に頭[あたま]の中[なか]で思[おも]ってみた。", "sentence_source": "generated"}, {"text": "先生はどう思うか、聞いてみよう。", "target_word": "思う", "complexity_tier": "T3", "furigana": "先生[せんせい]はどう思[おも]うか、聞[き]いてみよう。", "sentence_source": "generated"}, {"text": "失敗の原因を静かに思ってみると、準備不足だとわかった。", "target_word": "思って", "complexity_tier": "T3", "furigana": "失敗[しっぱい]の原因[げんいん]を静[しず]かに思[おも]ってみると、準備不足[じゅんびぶそく]だとわかった。", "sentence_source": "generated"}, {"text": "電車の中で、今日の予定をあれこれ思っていた。", "target_word": "思って", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の中[なか]で、今日[きょう]の予定[よてい]をあれこれ思[おも]っていた。", "sentence_source": "generated"}, {"text": "ふと昔の友達のことを思い、手紙を書いた。", "target_word": "思い", "complexity_tier": "T3", "furigana": "ふと昔[むかし]の友達[ともだち]のことを思[おも]い、手紙[てがみ]を書[か]いた。", "sentence_source": "generated"}, {"text": "みんなが賛成するとは思わないが、提案してみる。", "target_word": "思わ", "complexity_tier": "T3", "furigana": "みんなが賛成[さんせい]するとは思[おも]わないが、提案[ていあん]してみる。", "sentence_source": "generated"}, {"text": "この方法について、もう一度じっくり思ってみた。", "target_word": "思って", "complexity_tier": "T3", "furigana": "この方法[ほうほう]について、もう一度[いちど]じっくり思[おも]ってみた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "思わ", "label": "未然形"}, {"form": "思い", "label": "連用形"}, {"form": "思う", "label": "終止形・連体形"}, {"form": "思え", "label": "仮定形・命令形"}, {"form": "思った", "label": "過去形"}, {"form": "思って", "label": "て形"}], "register": "標準", "sense_fingerprint": "頭の中で物事について考える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0988d614-3a17-476b-9005-b96be10d1534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39072, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "思って", "is_correct": true, "explanation": "正解。「思っている」のて形。"}, {"text": "思わ", "is_correct": false, "explanation": "未然形では「思わている」となり成立しない。"}, {"text": "思い", "is_correct": false, "explanation": "連用形では「思いている」となり成立しない。"}, {"text": "思った", "is_correct": false, "explanation": "過去形では「思ったている」となり成立しない。"}], "explanations": {"思って": "正解。「思っている」のて形。", "思わ": "未然形では「思わている」となり成立しない。", "思い": "連用形では「思いている」となり成立しない。", "思った": "過去形では「思ったている」となり成立しない。"}, "sentence_index": 0, "correct_answer": "思って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玄関の鍵を、三十分かけて思った。", "explanation": "ここは〈開ける〉の意味。鍵を開ける動作は〈開ける〉で、〈思う〉は頭の中で考えることに限られる。"}, {"text": "職人は木材の表面を、丁寧に思っている。", "explanation": "ここは〈磨く〉の意味。表面を磨く作業は〈磨く〉で、〈思う〉は頭の中で考えることに限られる。"}, {"text": "店員は皿を、もう一度思った。", "explanation": "ここは〈洗う〉の意味。汚れた皿を洗う動作は〈洗う〉で、〈思う〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39072, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思って", "is_correct": true, "explanation": "正解。「思っていた」のて形。"}, {"text": "思わない", "is_correct": false, "explanation": "否定形「思わない」に「ていた」は続かず、「思わないていた」は成立しない。"}, {"text": "思います", "is_correct": false, "explanation": "丁寧語「思います」に「ていた」は続かず、「思いますていた」は成立しない。"}, {"text": "思え", "is_correct": false, "explanation": "仮定形・命令形の「思え」は「思える」の意味になり、「思えていた」は文脈に合わない。"}], "explanations": {"思って": "正解。「思っていた」のて形。", "思わない": "否定形「思わない」に「ていた」は続かず、「思わないていた」は成立しない。", "思います": "丁寧語「思います」に「ていた」は続かず、「思いますていた」は成立しない。", "思え": "仮定形・命令形の「思え」は「思える」の意味になり、「思えていた」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "思って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パン生地を、一晩中思った。", "explanation": "ここは〈寝かせる〉の意味。生地を一晩休ませる作業は〈寝かせる〉で、〈思う〉は頭の中で考える意味に限られる。"}, {"text": "レポートを三ページ分、思った。", "explanation": "ここは〈書く〉の意味。文章を作成する行為は〈書く〉で、〈思う〉は使わない。"}, {"text": "英文を日本語に思った。", "explanation": "ここは〈翻訳する〉の意味。言語を別の言語に移す作業は〈翻訳する〉で、〈思う〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39072, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "過去の失敗に思い、反省した。", "corrected_sentence": "過去の失敗を思い、反省した。", "error_description": "「思う」の対象は「を」で示す。「に」は誤り（誤：に、正：を）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "思う", "is_correct": true, "explanation": "正解。「思うと」の終止形・連体形。"}, {"text": "思わ", "is_correct": false, "explanation": "未然形では「思わと」となり成立しない。"}, {"text": "思い", "is_correct": false, "explanation": "連用形では「思いと」となり成立しない。"}, {"text": "思え", "is_correct": false, "explanation": "仮定形・命令形では「思えと」となり成立しない。"}], "correct_form": "思う", "base_form": "思う", "form_label": "終止形・連体形", "sentence_index": 1, "explanations": {"思う": "正解。「思うと」の終止形・連体形。", "思わ": "未然形では「思わと」となり成立しない。", "思い": "連用形では「思いと」となり成立しない。", "思え": "仮定形・命令形では「思えと」となり成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39072, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母の言葉を思う、涙が出た。", "corrected_sentence": "祖母の言葉を思い、涙が出た。", "error_description": "「思い」は連用中止形で、後ろに文を続ける。「思う、」と終止形で切ると文が続かない（誤：思う、正：思い）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "思い", "is_correct": true, "explanation": "正解。「思い、手紙を書いた」と続ける連用形。"}, {"text": "思わない", "is_correct": false, "explanation": "否定の終止形「思わない」は「、」で続く中止の形にならず、「思わない、手紙を書いた」は文にならない。"}, {"text": "思います", "is_correct": false, "explanation": "丁寧語の「思います」は中止の形にならず、「思います、手紙を書いた」は続かない。"}, {"text": "思った", "is_correct": false, "explanation": "過去形では「思った、」と続けると文として不自然で、文脈に合わない。"}], "correct_form": "思い", "base_form": "思う", "form_label": "連用形", "sentence_index": 7, "explanations": {"思い": "正解。「思い、手紙を書いた」と続ける連用形。", "思わない": "否定の終止形「思わない」は「、」で続く中止の形にならず、「思わない、手紙を書いた」は文にならない。", "思います": "丁寧語の「思います」は中止の形にならず、「思います、手紙を書いた」は続かない。", "思った": "過去形では「思った、」と続けると文として不自然で、文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39073, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "正解。「と思います」の引用の「と」。"}, {"text": "が", "is_correct": false, "explanation": "「面白いが思います」は主語にも引用にもならず、文が成立しない。"}, {"text": "を", "is_correct": false, "explanation": "「面白いを思います」は対象の格として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「面白いに思います」は成立せず、目標を示す格にもならない。"}], "correct_answer": "と", "explanations": {"と": "正解。「と思います」の引用の「と」。", "が": "「面白いが思います」は主語にも引用にもならず、文が成立しない。", "を": "「面白いを思います」は対象の格として不自然。", "に": "「面白いに思います」は成立せず、目標を示す格にもならない。"}, "error_tags": {"が": "主語の格", "を": "対象の格", "に": "与格・目標"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39073, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "正解。「と思っている」の引用の「と」。"}, {"text": "を", "is_correct": false, "explanation": "「無理だを思っている」は対象の格として成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「無理だに思っている」は成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「無理だで思っている」は手段・場所の意味にならず成立しない。"}], "correct_answer": "と", "explanations": {"と": "正解。「と思っている」の引用の「と」。", "を": "「無理だを思っている」は対象の格として成立しない。", "に": "「無理だに思っている」は成立しない。", "で": "「無理だで思っている」は手段・場所の意味にならず成立しない。"}, "error_tags": {"を": "対象の格", "に": "与格・目標", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39073, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "自分の考えや気持ちを心の中で感じたり、判断したりすること。", "primary_collocate": null, "pronunciation": "おもう", "ipa": "omoɯ", "syllable_count": 3, "sentences": [{"text": "彼の言葉は、私にそうだと思わせた。", "target_word": "思わ", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]は、私[わたし]にそうだと思[おも]わせた。", "sentence_source": "generated"}, {"text": "この映画はとても面白いと思います。", "target_word": "思います", "complexity_tier": "T3", "furigana": "この映画[えいが]はとても面白[おもしろ]いと思[おも]います。", "sentence_source": "generated"}, {"text": "彼の意見は正しいと思ったので、賛成した。", "target_word": "思った", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]は正[ただ]しいと思[おも]ったので、賛成[さんせい]した。", "sentence_source": "generated"}, {"text": "試験に落ちて、悔しいと思う気持ちが強かった。", "target_word": "思う", "complexity_tier": "T3", "furigana": "試験[しけん]に落[お]ちて、悔[くや]しいと思[おも]う気持[きも]ちが強[つよ]かった。", "sentence_source": "generated"}, {"text": "外は寒そうだと思って、コートを持って出かけた。", "target_word": "思って", "complexity_tier": "T3", "furigana": "外[そと]は寒[さむ]そうだと思[おも]って、コートを持[も]って出[で]かけた。", "sentence_source": "generated"}, {"text": "彼女が来るとは思わなかったので、とても驚いた。", "target_word": "思わ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]が来[く]るとは思[おも]わなかったので、とても驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "母の手料理を食べると、家に帰ってきたと思う。", "target_word": "思う", "complexity_tier": "T3", "furigana": "母[はは]の手料理[てりょうり]を食[た]べると、家[いえ]に帰[かえ]ってきたと思[おも]う。", "sentence_source": "generated"}, {"text": "私はこの計画は無理だと思っているが、まだ言えていない。", "target_word": "思って", "complexity_tier": "T3", "furigana": "私[わたし]はこの計画[けいかく]は無理[むり]だと思[おも]っているが、まだ言[い]えていない。", "sentence_source": "generated"}, {"text": "一人で行くのは危ないと思い、友達を誘った。", "target_word": "思い", "complexity_tier": "T3", "furigana": "一人[ひとり]で行[い]くのは危[あぶ]ないと思[おも]い、友達[ともだち]を誘[さそ]った。", "sentence_source": "generated"}, {"text": "初めて富士山を見たとき、きれいだと思った。", "target_word": "思った", "complexity_tier": "T3", "furigana": "初[はじ]めて富士山[ふじさん]を見[み]たとき、きれいだと思[おも]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "思わ", "label": "未然形"}, {"form": "思い", "label": "連用形"}, {"form": "思う", "label": "終止形・連体形"}, {"form": "思え", "label": "仮定形・命令形"}, {"form": "思った", "label": "過去形"}, {"form": "思って", "label": "て形"}, {"form": "思います", "label": "ます形"}], "register": "標準", "sense_fingerprint": "ある物事について心に感じたり、そうだと判断したりする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0988d614-3a17-476b-9005-b96be10d1534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39073, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "思わ", "is_correct": true, "explanation": "正解。使役「思わせる」の未然形。"}, {"text": "思い", "is_correct": false, "explanation": "連用形では「思いせた」となり成立しない。"}, {"text": "思う", "is_correct": false, "explanation": "終止形では「思うせた」となり成立しない。"}, {"text": "思って", "is_correct": false, "explanation": "て形では「思ってせた」となり成立しない。"}], "explanations": {"思わ": "正解。使役「思わせる」の未然形。", "思い": "連用形では「思いせた」となり成立しない。", "思う": "終止形では「思うせた」となり成立しない。", "思って": "て形では「思ってせた」となり成立しない。"}, "sentence_index": 0, "correct_answer": "思わ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は川の水を、バケツで思った。", "explanation": "ここは〈汲む〉の意味。水を汲む作業は〈汲む〉で、〈思う〉は使わない。"}, {"text": "体温を、体温計で思った。", "explanation": "ここは〈測る〉の意味。体温を計る作業は〈測る〉で、〈思う〉は使わない。"}, {"text": "新しい単語を、寝る前に思った。", "explanation": "ここは〈覚える〉の意味。記憶する行為は〈覚える〉で、〈思う〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39073, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思う", "is_correct": true, "explanation": "正解。終止形で文を締める。"}, {"text": "思えば", "is_correct": false, "explanation": "仮定形＋「ば」で、「と思えば。」は続く文が必要で、文が締まらない。"}, {"text": "思わず", "is_correct": false, "explanation": "副詞「思わず」の形で、「と思わず。」は文が締まらず成立しない。"}, {"text": "思われ", "is_correct": false, "explanation": "受身「思われる」の連用形で、「と思われ。」は文が締まらず成立しない。"}], "explanations": {"思う": "正解。終止形で文を締める。", "思えば": "仮定形＋「ば」で、「と思えば。」は続く文が必要で、文が締まらない。", "思わず": "副詞「思わず」の形で、「と思わず。」は文が締まらず成立しない。", "思われ": "受身「思われる」の連用形で、「と思われ。」は文が締まらず成立しない。"}, "sentence_index": 6, "correct_answer": "思う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "重い荷物を、玄関まで思って運んだ。", "explanation": "ここは〈運ぶ〉の意味。身体の動作は〈運ぶ〉で、〈思う〉は心の働きを表す。"}, {"text": "締め切り前に、レポートを思った。", "explanation": "ここは〈仕上げる〉の意味。作業を完成させる行為は〈仕上げる〉で、〈思う〉は使わない。"}, {"text": "機械の電源を、ゆっくり思った。", "explanation": "ここは〈操作する〉の意味。機械を動かす行為は〈操作する〉で、〈思う〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39073, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生の説明は分かりやすいを思った。", "corrected_sentence": "先生の説明は分かりやすいと思った。", "error_description": "「思う」の前には引用の「と」を置く。「を」は誤り（誤：を、正：と）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "思います", "is_correct": true, "explanation": "正解。丁寧語の「ます形」。"}, {"text": "思わ", "is_correct": false, "explanation": "未然形では「思わます」となり成立しない。"}, {"text": "思って", "is_correct": false, "explanation": "て形では「思ってます」となり成立しない。"}, {"text": "思った", "is_correct": false, "explanation": "過去形では「思ったます」となり成立しない。"}], "correct_form": "思います", "base_form": "思う", "form_label": "ます形", "sentence_index": 1, "explanations": {"思います": "正解。丁寧語の「ます形」。", "思わ": "未然形では「思わます」となり成立しない。", "思って": "て形では「思ってます」となり成立しない。", "思った": "過去形では「思ったます」となり成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39073, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼はきっと来ると思いていた。", "corrected_sentence": "彼はきっと来ると思っていた。", "error_description": "「思う」のて形は「思って」（促音の「っ」）。「思いて」は誤り（誤：思いて、正：思って）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "思って", "is_correct": true, "explanation": "正解。「思っている」のて形。"}, {"text": "思い", "is_correct": false, "explanation": "連用形では「思いている」となり成立しない。"}, {"text": "思わず", "is_correct": false, "explanation": "副詞「思わず」の形では「思わずている」となり、「ている」に続かない。"}, {"text": "思えば", "is_correct": false, "explanation": "仮定形＋「ば」では「思えばている」となり成立しない。"}], "correct_form": "思って", "base_form": "思う", "form_label": "て形", "sentence_index": 7, "explanations": {"思って": "正解。「思っている」のて形。", "思い": "連用形では「思いている」となり成立しない。", "思わず": "副詞「思わず」の形では「思わずている」となり、「ている」に続かない。", "思えば": "仮定形＋「ば」では「思えばている」となり成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dfba2e5-35c5-43d5-aff9-b9b853de9f9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39074, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「工場で働く」の「で」。働く場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「工場を働いている」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「工場へ働いている」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示す。「工場と働いている」は意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "「工場で働く」の「で」。働く場所を示す。", "を": "「を」は目的語を示す。「工場を働いている」は文が成り立たない。", "へ": "「へ」は方向を示す。「工場へ働いている」は不自然。", "と": "「と」は相手や並列を示す。「工場と働いている」は意味が通らない。"}, "error_tags": {"を": "目的語（対象）", "へ": "方向・行き先", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39074, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「工場が川の近くにある」と、工場を主語として示す「が」。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示す。「工場で川の近くにある」は主語が立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「工場より川の近くにある」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「工場から川の近くにある」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「工場が川の近くにある」と、工場を主語として示す「が」。", "で": "「で」は場所や手段を示す。「工場で川の近くにある」は主語が立たない。", "より": "「より」は比較を示す。「工場より川の近くにある」は不自然。", "から": "「から」は起点を示す。「工場から川の近くにある」は意味が通らない。"}, "error_tags": {"で": "場所・手段", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39074, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物を作る大きな建物です。", "primary_collocate": null, "pronunciation": "こうじょう", "ipa": "koːdʑoː", "syllable_count": 4, "sentences": [{"text": "駅の近くに、新しい工場が建った。", "target_word": "工場", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに、新[あたら]しい工場[こうじょう]が建[た]った。", "sentence_source": "generated"}, {"text": "父は自動車の工場で働いている。", "target_word": "工場", "complexity_tier": "T3", "furigana": "父[ちち]は自動車[じどうしゃ]の工場[こうじょう]で働[はたら]いている。", "sentence_source": "generated"}, {"text": "工場の煙突から、白い煙が出ている。", "target_word": "工場", "complexity_tier": "T3", "furigana": "工場[こうじょう]の煙突[えんとつ]から、白[しろ]い煙[けむり]が出[で]ている。", "sentence_source": "generated"}, {"text": "小学校の見学で、お菓子の工場に行った。", "target_word": "工場", "complexity_tier": "T3", "furigana": "小学校[しょうがっこう]の見学[けんがく]で、お菓子[かし]の工場[こうじょう]に行[い]った。", "sentence_source": "generated"}, {"text": "工場の中は機械の音がうるさくて、話し声が聞こえない。", "target_word": "工場", "complexity_tier": "T3", "furigana": "工場[こうじょう]の中[なか]は機械[きかい]の音[おと]がうるさくて、話[はな]し声[ごえ]が聞[き]こえない。", "sentence_source": "generated"}, {"text": "この町には、古い工場の建物がそのまま残っている。", "target_word": "工場", "complexity_tier": "T3", "furigana": "この町[まち]には、古[ふる]い工場[こうじょう]の建物[たてもの]がそのまま残[のこ]っている。", "sentence_source": "generated"}, {"text": "工場の前には、大きなトラックが並んでいた。", "target_word": "工場", "complexity_tier": "T3", "furigana": "工場[こうじょう]の前[まえ]には、大[おお]きなトラックが並[なら]んでいた。", "sentence_source": "generated"}, {"text": "工場が川の近くにあるので、水の管理が大切だ。", "target_word": "工場", "complexity_tier": "T3", "furigana": "工場[こうじょう]が川[かわ]の近[ちか]くにあるので、水[みず]の管理[かんり]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "朝七時に、工場の門が開く。", "target_word": "工場", "complexity_tier": "T3", "furigana": "朝[あさ]七時[しちじ]に、工場[こうじょう]の門[もん]が開[ひら]く。", "sentence_source": "generated"}, {"text": "あの大きな工場は、昔は紙を作っていたそうだ。", "target_word": "工場", "complexity_tier": "T3", "furigana": "あの大[おお]きな工場[こうじょう]は、昔[むかし]は紙[かみ]を作[つく]っていたそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "工場", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物を作るための大きな建物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44bb0fd-3452-43af-b204-23fdee287513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39074, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工場", "is_correct": true, "explanation": "〈工場〉は建物なので、駅の近くに「建った」と合う。"}, {"text": "森", "is_correct": false, "explanation": "森は自然にあるもので、建つものではない。"}, {"text": "湖", "is_correct": false, "explanation": "湖は地形で、建つものではないので文が成り立たない。"}, {"text": "滝", "is_correct": false, "explanation": "滝は自然の景色で、建つものではない。"}], "explanations": {"工場": "〈工場〉は建物なので、駅の近くに「建った」と合う。", "森": "森は自然にあるもので、建つものではない。", "湖": "湖は地形で、建つものではないので文が成り立たない。", "滝": "滝は自然の景色で、建つものではない。"}, "sentence_index": 0, "correct_answer": "工場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場では、毎朝、牛が新鮮なミルクを出す。", "explanation": "ここは〈農場〉の意味。工場は機械や人が製品を作る建物で、牛を飼って乳をしぼる場所ではないので合わない。"}, {"text": "工場では、子どもたちが夕方まで走り回って遊んでいる。", "explanation": "ここは〈遊び場〉の意味。工場は製品を作る建物で、子どもが遊ぶ場所ではないので合わない。"}, {"text": "工場では、保育士が小さな子どもを昼寝させる。", "explanation": "ここは〈保育所〉の意味。工場は製品を作る建物で、子どもを預けて昼寝させる施設ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39074, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工場", "is_correct": true, "explanation": "建物の前にトラックが並ぶ場面なので、〈工場〉が入る。"}, {"text": "雲", "is_correct": false, "explanation": "雲の前にトラックが並ぶことはなく、文が成り立たない。"}, {"text": "星", "is_correct": false, "explanation": "星の前にトラックが並ぶという文にはならない。"}, {"text": "波", "is_correct": false, "explanation": "波の前にトラックが並ぶという文にはならない。"}], "explanations": {"工場": "建物の前にトラックが並ぶ場面なので、〈工場〉が入る。", "雲": "雲の前にトラックが並ぶことはなく、文が成り立たない。", "星": "星の前にトラックが並ぶという文にはならない。", "波": "波の前にトラックが並ぶという文にはならない。"}, "sentence_index": 6, "correct_answer": "工場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場では、先生が生徒に漢字の書き取りを教える。", "explanation": "ここは〈学校〉の意味。工場は物を作る建物で、先生と生徒が授業をする場所ではないので合わない。"}, {"text": "工場では、医師が患者の傷口を縫う。", "explanation": "ここは〈診療所〉の意味。工場は物を作る建物で、医師が患者を治療する場所ではないので合わない。"}, {"text": "工場では、客が試着室で服を選ぶ。", "explanation": "ここは〈洋服店〉の意味。工場は客が服を選んで買う店ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39074, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は工場を、車の部品を組み立てている。", "corrected_sentence": "父は工場で、車の部品を組み立てている。", "error_description": "「工場で」の「で」を「を」にしている。作業の場所を表すには「で」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39074, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い工場を閉鎖された。", "corrected_sentence": "古い工場が閉鎖された。", "error_description": "「工場が閉鎖された」の「が」を「を」にしている。受け身の文では主語を「が」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39075, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「工場の人」と、工場が人を修飾する「の」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「工場を人が」は文の形にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「工場へ人が」は文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「工場より人が」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「工場の人」と、工場が人を修飾する「の」が入る。", "を": "「を」は目的語を示す。「工場を人が」は文の形にならない。", "へ": "「へ」は方向を示す。「工場へ人が」は文が成り立たない。", "より": "「より」は比較を示す。「工場より人が」は意味が通らない。"}, "error_tags": {"を": "目的語（対象）", "へ": "方向・行き先", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39075, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「工場で働く人たち」の「で」。働く場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「工場が働く人たちは」は主語が二つ続き不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示す。「工場と働く人たちは」は意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は存在や到着の場所を示す。「工場に働く人たちは」は働く場所を表せない。"}], "correct_answer": "で", "explanations": {"で": "「工場で働く人たち」の「で」。働く場所を示す。", "が": "「が」は主語を示す。「工場が働く人たちは」は主語が二つ続き不自然。", "と": "「と」は相手や並列を示す。「工場と働く人たちは」は意味が通らない。", "に": "「に」は存在や到着の場所を示す。「工場に働く人たちは」は働く場所を表せない。"}, "error_tags": {"が": "主語（格）", "と": "並列・相手", "に": "存在・到着点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39075, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "製品を機械や人の力でたくさん作るところ。", "primary_collocate": null, "pronunciation": "こうじょう", "ipa": "koːdʑoː", "syllable_count": 4, "sentences": [{"text": "この工場では、毎日一万個のパンを作っている。", "target_word": "工場", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、毎日[まいにち]一万個[いちまんこ]のパンを作[つく]っている。", "sentence_source": "generated"}, {"text": "工場の人が手と機械で、部品をていねいに組み立てる。", "target_word": "工場", "complexity_tier": "T3", "furigana": "工場[こうじょう]の人[ひと]が手[て]と機械[きかい]で、部品[ぶひん]をていねいに組[く]み立[た]てる。", "sentence_source": "generated"}, {"text": "工場を海外に移したので、製品の値段が安くなった。", "target_word": "工場", "complexity_tier": "T3", "furigana": "工場[こうじょう]を海外[かいがい]に移[うつ]したので、製品[せいひん]の値段[ねだん]が安[やす]くなった。", "sentence_source": "generated"}, {"text": "注文が増えて、工場は夜も動き続けている。", "target_word": "工場", "complexity_tier": "T3", "furigana": "注文[ちゅうもん]が増[ふ]えて、工場[こうじょう]は夜[よる]も動[うご]き続[つづ]けている。", "sentence_source": "generated"}, {"text": "工場で作った製品は、検査を受けてから店に運ばれる。", "target_word": "工場", "complexity_tier": "T3", "furigana": "工場[こうじょう]で作[つく]った製品[せいひん]は、検査[けんさ]を受[う]けてから店[みせ]に運[はこ]ばれる。", "sentence_source": "generated"}, {"text": "新しい機械を入れた工場では、生産が二倍になった。", "target_word": "工場", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]を入[い]れた工場[こうじょう]では、生産[せいさん]が二倍[にばい]になった。", "sentence_source": "generated"}, {"text": "家具の工場を見学し、木から椅子ができるまでを見た。", "target_word": "工場", "complexity_tier": "T3", "furigana": "家具[かぐ]の工場[こうじょう]を見学[けんがく]し、木[き]から椅子[いす]ができるまでを見[み]た。", "sentence_source": "generated"}, {"text": "工場で働く人たちは、決まった時間に交代する。", "target_word": "工場", "complexity_tier": "T3", "furigana": "工場[こうじょう]で働[はたら]く人[ひと]たちは、決[き]まった時間[じかん]に交代[こうたい]する。", "sentence_source": "generated"}, {"text": "工場の製品に問題が見つかり、店から回収された。", "target_word": "工場", "complexity_tier": "T3", "furigana": "工場[こうじょう]の製品[せいひん]に問題[もんだい]が見[み]つかり、店[みせ]から回収[かいしゅう]された。", "sentence_source": "generated"}, {"text": "小さな工場でも、技術が高ければ世界中から注文が来る。", "target_word": "工場", "complexity_tier": "T3", "furigana": "小[ちい]さな工場[こうじょう]でも、技術[ぎじゅつ]が高[たか]ければ世界中[せかいじゅう]から注文[ちゅうもん]が来[く]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "工場", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "製品を機械や人の力で大量に生産する場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44bb0fd-3452-43af-b204-23fdee287513') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39075, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工場", "is_correct": true, "explanation": "大量にパンを作る場所なので、〈工場〉が入る。"}, {"text": "森", "is_correct": false, "explanation": "森でパンを大量に作るとは言えず、文が成り立たない。"}, {"text": "山", "is_correct": false, "explanation": "山でパンを作るという文にはならない。"}, {"text": "滝", "is_correct": false, "explanation": "滝でパンを作るという文にはならない。"}], "explanations": {"工場": "大量にパンを作る場所なので、〈工場〉が入る。", "森": "森でパンを大量に作るとは言えず、文が成り立たない。", "山": "山でパンを作るという文にはならない。", "滝": "滝でパンを作るという文にはならない。"}, "sentence_index": 0, "correct_answer": "工場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場では、子どもたちが夕方までブランコで遊んでいる。", "explanation": "ここは〈公園〉の意味。工場は製品を作る建物で、子どもが遊ぶ場所ではないので合わない。"}, {"text": "工場では、看護師が夜通し患者を見守っている。", "explanation": "ここは〈病院〉の意味。工場は患者を診て看護する場所ではないので合わない。"}, {"text": "工場では、司書が来館者に本の貸し出しをしている。", "explanation": "ここは〈図書館〉の意味。工場は本を貸し出す施設ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39075, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工場", "is_correct": true, "explanation": "家具を製造する場所を見学したので、〈工場〉が入る。"}, {"text": "寺", "is_correct": false, "explanation": "寺で家具の製造工程を見学するとは言えない。"}, {"text": "雲", "is_correct": false, "explanation": "雲を見学するという文にはならない。"}, {"text": "星", "is_correct": false, "explanation": "星の製造工程を見学するという文にはならない。"}], "explanations": {"工場": "家具を製造する場所を見学したので、〈工場〉が入る。", "寺": "寺で家具の製造工程を見学するとは言えない。", "雲": "雲を見学するという文にはならない。", "星": "星の製造工程を見学するという文にはならない。"}, "sentence_index": 6, "correct_answer": "工場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場では、お客さんがスクリーンで映画を観る。", "explanation": "ここは〈映画館〉の意味。工場は製品を作る建物で、映画を上映して観せる場所ではないので合わない。"}, {"text": "工場では、俳優たちが舞台で劇の稽古をする。", "explanation": "ここは〈劇場〉の意味。工場は舞台で演じる場所ではないので合わない。"}, {"text": "工場では、象が大きな声で鳴いている。", "explanation": "ここは〈動物園〉の意味。工場は動物を飼う場所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39075, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この工場の、夏も休まず動いている。", "corrected_sentence": "この工場が、夏も休まず動いている。", "error_description": "「工場が動いている」の「が」を「の」にしている。動作の主体は「が」で示すので、「工場の」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39075, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この工場を、一日に三百台の車を組み立てる。", "corrected_sentence": "この工場は、一日に三百台の車を組み立てる。", "error_description": "「この工場は」の「は」を「を」にしている。組み立てる主体は主題の「は」で示すので、「工場を」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ad329a-4299-4caf-ba9b-70ac9db5e3a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
