INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39076, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "物事が速く進むようす。", "primary_collocate": null, "pronunciation": "どんどん", "ipa": "doɴdoɴ", "syllable_count": 4, "sentences": [{"text": "工事がどんどん進んで、ビルが高くなった。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "工事[こうじ]がどんどん進[すす]んで、ビルが高[たか]くなった。", "sentence_source": "generated"}, {"text": "宿題は、始めたらどんどん終わった。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]は、始[はじ]めたらどんどん終[お]わった。", "sentence_source": "generated"}, {"text": "友だちは日本語がどんどん上手になっている。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "友[とも]だちは日本語[にほんご]がどんどん上手[じょうず]になっている。", "sentence_source": "generated"}, {"text": "雨がやんで、雲がどんどん消えていった。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "雨[あめ]がやんで、雲[くも]がどんどん消[き]えていった。", "sentence_source": "generated"}, {"text": "話し合いはどんどん進み、一時間で決まった。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いはどんどん進[すす]み、一時間[いちじかん]で決[き]まった。", "sentence_source": "generated"}, {"text": "彼は食べるのが速く、料理をどんどん食べていった。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "彼[かれ]は食[た]べるのが速[はや]く、料理[りょうり]をどんどん食[た]べていった。", "sentence_source": "generated"}, {"text": "道がすいていたので、車はどんどん進んだ。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "道[みち]がすいていたので、車[くるま]はどんどん進[すす]んだ。", "sentence_source": "generated"}, {"text": "子どもたちは、坂をどんどん走って下りていった。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、坂[さか]をどんどん走[はし]って下[お]りていった。", "sentence_source": "generated"}, {"text": "作業に慣れてきて、仕事がどんどん片づく。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "作業[さぎょう]に慣[な]れてきて、仕事[しごと]がどんどん片[かた]づく。", "sentence_source": "generated"}, {"text": "急いでいるので、荷物をどんどん運んでください。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "急[いそ]いでいるので、荷物[にもつ]をどんどん運[はこ]んでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "どんどん", "label": "基本形"}], "register": "口語", "sense_fingerprint": "作業・工事・移動などが滞りなく速く進むようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 片づく (Zipf 1.88)']::text[], 'f54bc903-95d5-40b4-bd35-efc729115735') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39076, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "どんどん", "is_correct": true, "explanation": "物事が速く進むさまを表す副詞。「工事がどんどん進んで」と自然に続く。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "深く眠るさまを表す副詞。工事が進む動作には合わない。"}, {"text": "きらきら", "is_correct": false, "explanation": "光が輝くさまを表す副詞。工事の進みの速さは表せない。"}, {"text": "ふわふわ", "is_correct": false, "explanation": "軽く柔らかいさまを表す副詞。進みの速さを表す文脈ではない。"}], "explanations": {"どんどん": "物事が速く進むさまを表す副詞。「工事がどんどん進んで」と自然に続く。", "ぐっすり": "深く眠るさまを表す副詞。工事が進む動作には合わない。", "きらきら": "光が輝くさまを表す副詞。工事の進みの速さは表せない。", "ふわふわ": "軽く柔らかいさまを表す副詞。進みの速さを表す文脈ではない。"}, "sentence_index": 0, "correct_answer": "どんどん"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車がどんどん七時ちょうどに着いた。", "explanation": "ここは〈ちょうど〉の意味（時刻や数量がぴったり）。どんどんは物事が速く進むさまを表すので、時刻ぴったりを示す文には合わない。"}, {"text": "彼はどんどん温厚だ。", "explanation": "ここは〈ずっと〉の意味（変わらず続く状態）。どんどんは物事が速く進むさまを表すので、性格のような状態には使えない。"}, {"text": "ふたをどんどんそっと閉めた。", "explanation": "ここは〈そっと〉の意味（静かに注意して）。どんどんは勢いよく進むさまなので、慎重に静かに動かす動作には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39076, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "どんどん", "is_correct": true, "explanation": "車が速く進むさまを表す副詞。「車はどんどん進んだ」と自然に続く。"}, {"text": "ぺこぺこ", "is_correct": false, "explanation": "お腹が空いたさまを表す副詞。車が進む動作には合わない。"}, {"text": "にこにこ", "is_correct": false, "explanation": "笑顔のさまを表す副詞。車の進みを表すことはできない。"}, {"text": "ぎらぎら", "is_correct": false, "explanation": "強く光るさまを表す副詞。進みの速さとは結びつかない。"}], "explanations": {"どんどん": "車が速く進むさまを表す副詞。「車はどんどん進んだ」と自然に続く。", "ぺこぺこ": "お腹が空いたさまを表す副詞。車が進む動作には合わない。", "にこにこ": "笑顔のさまを表す副詞。車の進みを表すことはできない。", "ぎらぎら": "強く光るさまを表す副詞。進みの速さとは結びつかない。"}, "sentence_index": 6, "correct_answer": "どんどん"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一つずつ丁寧に、どんどん確かめてください。", "explanation": "ここは〈一つずつ丁寧に〉の意味（時間をかけて確かめる）。どんどんは物事が速く進むさまなので、丁寧さを求める文には合わない。"}, {"text": "彼女はどんどん振り返った。", "explanation": "ここは〈ふと〉の意味（一度だけ不意に）。どんどんは同じ動作が勢いよく続くさまなので、一回の動作には合わない。"}, {"text": "どんどん味わって食べてください。", "explanation": "ここは〈ゆっくり〉の意味（時間をかける）。どんどんは勢いよく進むさまなので、味わう動作には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39076, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "準備がどんどん進めました。", "corrected_sentence": "準備がどんどん進みました。", "error_description": "「準備が」に続くのは自動詞「進む」。他動詞「進める」は誤りで、正しくは「進みました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
