INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39077, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "物事が勢いよく、次々に進むさま。また、程度がますますはげしくなるさま。", "primary_collocate": null, "pronunciation": "どんどん", "ipa": "doɴdoɴ", "syllable_count": 4, "sentences": [{"text": "雨がどんどん強くなってきたので、家に入った。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "雨[あめ]がどんどん強[つよ]くなってきたので、家[いえ]に入[はい]った。", "sentence_source": "generated"}, {"text": "遠慮しないで、どんどん食べてください。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "遠慮[えんりょ]しないで、どんどん食[た]べてください。", "sentence_source": "generated"}, {"text": "人口はどんどん減っている。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "人口[じんこう]はどんどん減[へ]っている。", "sentence_source": "generated"}, {"text": "分からないことは、どんどん質問してください。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "分[わ]からないことは、どんどん質問[しつもん]してください。", "sentence_source": "generated"}, {"text": "夜が深くなり、気温がどんどん下がった。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "夜[よる]が深[ふか]くなり、気温[きおん]がどんどん下[さ]がった。", "sentence_source": "generated"}, {"text": "注文が次々に入って、商品がどんどん売れた。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "注文[ちゅうもん]が次々[つぎつぎ]に入[はい]って、商品[しょうひん]がどんどん売[う]れた。", "sentence_source": "generated"}, {"text": "試合が進むにつれて、応援の声がどんどん大きくなった。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "試合[しあい]が進[すす]むにつれて、応援[おうえん]の声[こえ]がどんどん大[おお]きくなった。", "sentence_source": "generated"}, {"text": "物の値段がどんどん上がって、生活が苦しい。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "物[もの]の値段[ねだん]がどんどん上[あ]がって、生活[せいかつ]が苦[くる]しい。", "sentence_source": "generated"}, {"text": "新しいアイデアがあれば、会議でどんどん出してほしい。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "新[あたら]しいアイデアがあれば、会議[かいぎ]でどんどん出[だ]してほしい。", "sentence_source": "generated"}, {"text": "痛みがどんどんひどくなったので、病院へ行った。", "target_word": "どんどん", "complexity_tier": "T3", "furigana": "痛[いた]みがどんどんひどくなったので、病院[びょういん]へ行[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "どんどん", "label": "基本形"}], "register": "口語", "sense_fingerprint": "勢いよく次々に行う／程度が急にますます強まるようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f54bc903-95d5-40b4-bd35-efc729115735') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39077, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "どんどん", "is_correct": true, "explanation": "雨の勢いや程度が増すさまを表す副詞。「雨がどんどん強くなってきた」と自然に続く。"}, {"text": "ふわふわ", "is_correct": false, "explanation": "軽く柔らかいさまを表す副詞。強さの変化には使えない。"}, {"text": "しみじみ", "is_correct": false, "explanation": "心に深く感じるさまを表す副詞。雨の強まりには合わない。"}, {"text": "にこにこ", "is_correct": false, "explanation": "笑顔のさまを表す副詞。雨の強さは表せない。"}], "explanations": {"どんどん": "雨の勢いや程度が増すさまを表す副詞。「雨がどんどん強くなってきた」と自然に続く。", "ふわふわ": "軽く柔らかいさまを表す副詞。強さの変化には使えない。", "しみじみ": "心に深く感じるさまを表す副詞。雨の強まりには合わない。", "にこにこ": "笑顔のさまを表す副詞。雨の強さは表せない。"}, "sentence_index": 0, "correct_answer": "どんどん"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "少しずつどんどん食べた。", "explanation": "ここは〈少しずつ〉の意味（少量ずつ段階的に）。どんどんは勢いよく次々と進むさまなので、少量ずつの進み方には合わない。"}, {"text": "その人はどんどん顔を上げた。", "explanation": "ここは〈ふと〉の意味（一度だけ不意に）。どんどんは同じ動作が勢いよく続く語なので、一回の動作には合わない。"}, {"text": "会議はどんどん十時に始まった。", "explanation": "ここは〈きっかり〉の意味（時刻ちょうどに）。どんどんは勢いを表すので、時刻を正確に示す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39077, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "どんどん", "is_correct": true, "explanation": "声の大きさが増していくさまを表す副詞。「応援の声がどんどん大きくなった」と自然に続く。"}, {"text": "ぐるぐる", "is_correct": false, "explanation": "回るさまを表す副詞。声の大きさの変化には使えない。"}, {"text": "きらきら", "is_correct": false, "explanation": "光が輝くさまを表す副詞。声の大きさには合わない。"}, {"text": "ぺらぺら", "is_correct": false, "explanation": "話し方が流暢なさまを表す副詞。声の大きさの変化は表せない。"}], "explanations": {"どんどん": "声の大きさが増していくさまを表す副詞。「応援の声がどんどん大きくなった」と自然に続く。", "ぐるぐる": "回るさまを表す副詞。声の大きさの変化には使えない。", "きらきら": "光が輝くさまを表す副詞。声の大きさには合わない。", "ぺらぺら": "話し方が流暢なさまを表す副詞。声の大きさの変化は表せない。"}, "sentence_index": 6, "correct_answer": "どんどん"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その犬はどんどん待っていた。", "explanation": "ここは〈じっと〉の意味（動かずに待つ）。どんどんは勢いよく進むさまを表すので、動かずに待つ様子には合わない。"}, {"text": "ドアをどんどんそっと閉めてください。", "explanation": "ここは〈そっと〉の意味（静かに気をつけて）。どんどんは勢いよく進むさまなので、静かに慎重に動かす文には合わない。"}, {"text": "おずおずどんどん手を挙げた。", "explanation": "ここは〈おずおず〉の意味（遠慮がちに）。どんどんは勢いのあるさまなので、遠慮がちな動作には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39077, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風がどんどん強い、窓を閉めた。", "corrected_sentence": "風がどんどん強くなって、窓を閉めた。", "error_description": "程度が増していく様子は「強くなって」と変化を示す形で表す必要がある。「強い」で止めるのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39077, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人口がどんどん減らして、町が寂しい。", "corrected_sentence": "人口がどんどん減って、町が寂しい。", "error_description": "「人口が」に続くのは自動詞「減る」。他動詞「減らす」は誤りで、正しくは「減って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1a28cef-08d7-4a84-a5c8-f119b7d22b38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
