INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39081, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "野球で、内野の一塁の守備位置、またはそこを守る選手。", "primary_collocate": null, "pronunciation": "ふぁーすと", "ipa": "ɸaːsɯto", "syllable_count": 4, "sentences": [{"text": "彼は野球チームでファーストを守っていて、送球を受けるのが上手だ。", "target_word": "ファースト", "complexity_tier": "T3", "furigana": "彼[かれ]は野球[やきゅう]チームでファーストを守[まも]っていて、送球[そうきゅう]を受[う]けるのが上手[じょうず]だ。", "sentence_source": "generated"}, {"text": "ファーストが体を伸ばして送球を捕ったので、走者はアウトになった。", "target_word": "ファースト", "complexity_tier": "T3", "furigana": "ファーストが体[からだ]を伸[の]ばして送球[そうきゅう]を捕[と]ったので、走者[そうしゃ]はアウトになった。", "sentence_source": "generated"}, {"text": "打球はファーストの頭上を越えて、ライトの前に落ちた。", "target_word": "ファースト", "complexity_tier": "T3", "furigana": "打球[だきゅう]はファーストの頭上[ずじょう]を越[こ]えて、ライトの前[まえ]に落[お]ちた。", "sentence_source": "generated"}, {"text": "ファーストの守備が安定していて、内野がよく締まっている。", "target_word": "ファースト", "complexity_tier": "T3", "furigana": "ファーストの守備[しゅび]が安定[あんてい]していて、内野[ないや]がよく締[し]まっている。", "sentence_source": "generated"}, {"text": "私はファーストで先発することになり、朝から緊張している。", "target_word": "ファースト", "complexity_tier": "T3", "furigana": "私[わたし]はファーストで先発[せんぱつ]することになり、朝[あさ]から緊張[きんちょう]している。", "sentence_source": "generated"}, {"text": "ファーストの選手がベースを離れた隙に、走者が二塁へ進んだ。", "target_word": "ファースト", "complexity_tier": "T3", "furigana": "ファーストの選手[せんしゅ]がベースを離[はな]れた隙[すき]に、走者[そうしゃ]が二塁[にるい]へ進[すす]んだ。", "sentence_source": "generated"}, {"text": "ファーストの守備練習に、今日は一時間使った。", "target_word": "ファースト", "complexity_tier": "T3", "furigana": "ファーストの守備練習[しゅびれんしゅう]に、今日[きょう]は一時間[いちじかん]使[つか]った。", "sentence_source": "generated"}, {"text": "監督は怪我をした選手に代わって、若手をファーストに起用した。", "target_word": "ファースト", "complexity_tier": "T3", "furigana": "監督[かんとく]は怪我[けが]をした選手[せんしゅ]に代[か]わって、若手[わかて]をファーストに起用[きよう]した。", "sentence_source": "generated"}, {"text": "ファーストへの送球が少しそれて、打者は出塁した。", "target_word": "ファースト", "complexity_tier": "T3", "furigana": "ファーストへの送球[そうきゅう]が少[すこ]しそれて、打者[だしゃ]は出塁[しゅつるい]した。", "sentence_source": "generated"}, {"text": "ファーストが送球を受けるまで、走者は塁を離れられなかった。", "target_word": "ファースト", "complexity_tier": "T3", "furigana": "ファーストが送球[そうきゅう]を受[う]けるまで、走者[そうしゃ]は塁[るい]を離[はな]れられなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ファースト", "label": "基本形"}, {"form": "ファーストな", "label": "連体形"}, {"form": "ファーストの", "label": "連体修飾"}], "register": "casual", "sense_fingerprint": "ファースト=野球の一塁（守備位置・一塁手）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '902e7101-6d8c-4209-9d40-e9cb41ee9d7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39081, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ファースト", "is_correct": true, "explanation": "ここは「野球の一塁」の意味。一塁を守る話なので、ファーストが合う。"}, {"text": "捕球", "is_correct": false, "explanation": "ボールを受ける動作の名前で、守る位置を表さない。「捕球を守る」とは言わない。"}, {"text": "ヒット", "is_correct": false, "explanation": "打撃の結果を指し、守る場所ではない。「ヒットを守る」は成り立たない。"}, {"text": "アウト", "is_correct": false, "explanation": "打者や走者の状態で、守る位置の名前にはならない。"}], "explanations": {"ファースト": "ここは「野球の一塁」の意味。一塁を守る話なので、ファーストが合う。", "捕球": "ボールを受ける動作の名前で、守る位置を表さない。「捕球を守る」とは言わない。", "ヒット": "打撃の結果を指し、守る場所ではない。「ヒットを守る」は成り立たない。", "アウト": "打者や走者の状態で、守る位置の名前にはならない。"}, "sentence_index": 0, "correct_answer": "ファースト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ファーストエイドの講習で、止血の方法を習った。", "explanation": "ファーストエイドのファーストは「最初の」で、一塁の守備位置とは別の意味なので、この文には合わない。"}, {"text": "転校生は、クラスで誰からもファーストネームで呼ばれている。", "explanation": "ファーストネームのファーストは「最初の」で、一塁の守備位置とは別の意味なので、この文には合わない。"}, {"text": "公式行事では、首相夫人がファーストレディとして挨拶した。", "explanation": "ファーストレディのファーストは「最初の」で、一塁の守備位置とは別の意味なので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39081, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ファースト", "is_correct": true, "explanation": "ここは「野球の一塁」の意味。一塁の守備練習という意味で合う。"}, {"text": "三振", "is_correct": false, "explanation": "打者が打てずに終わる結果で、守備練習の種類にはならない。「三振の守備練習」は不自然。"}, {"text": "ストライク", "is_correct": false, "explanation": "投球の判定の名前で、守備練習の内容を表さない。「ストライクの守備練習」は成り立たない。"}, {"text": "四球", "is_correct": false, "explanation": "打者が四球で塁に出る結果で、守備練習とは結びつかない。"}], "explanations": {"ファースト": "ここは「野球の一塁」の意味。一塁の守備練習という意味で合う。", "三振": "打者が打てずに終わる結果で、守備練習の種類にはならない。「三振の守備練習」は不自然。", "ストライク": "投球の判定の名前で、守備練習の内容を表さない。「ストライクの守備練習」は成り立たない。", "四球": "打者が四球で塁に出る結果で、守備練習とは結びつかない。"}, "sentence_index": 6, "correct_answer": "ファースト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新作ドラマのファーストシーズンが、来月配信される。", "explanation": "ここは〈最初の〉の意味。ファーストシーズンのファーストは「最初の」で、一塁の守備位置とは別の意味なので、この文には合わない。"}, {"text": "新しい取り組みに最初に飛び込んだ彼は、ファーストペンギンと呼ばれている。", "explanation": "ファーストペンギンのファーストは「最初の」で、一塁の守備位置とは別の意味なので、この文には合わない。"}, {"text": "初めての恋で、ファーストキスの相手をまだ覚えている。", "explanation": "ファーストキスのファーストは「最初の」で、一塁の守備位置とは別の意味なので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39081, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三塁手が投げた球を、ファーストを素早く捕った。", "corrected_sentence": "三塁手が投げた球を、ファーストが素早く捕った。", "error_description": "捕る主語になるファーストは「が」で続ける。「ファーストを」と目的語の助詞を付けると、捕る主語が消えて誤りになる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39081, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は急にファーストを守るになった。", "corrected_sentence": "彼は急にファーストを守ることになった。", "error_description": "「守ること」と名詞化の「こと」が必要。「守るになった」は文法的に誤りで、「守ることになった」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '788aba68-07fe-4396-bcff-dfa93bd18f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39082, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「ファッションは」で話題を示す。文の主題として自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「ファッションを」だと目的語になるが、この文は「人気です」で主題を述べる文なので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「ファッションの」は後に続けられず、「の、明るい色が…」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「ファッションで」は手段の意味になり、主題を示す役割には合わない。"}], "correct_answer": "は", "explanations": {"は": "「ファッションは」で話題を示す。文の主題として自然に続く。", "を": "「ファッションを」だと目的語になるが、この文は「人気です」で主題を述べる文なので合わない。", "の": "「ファッションの」は後に続けられず、「の、明るい色が…」は文として成り立たない。", "で": "「ファッションで」は手段の意味になり、主題を示す役割には合わない。"}, "error_tags": {"は": "主題", "を": "目的語", "に": "方向・対象", "の": "修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39082, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「調べました」の目的語として「ファッションを」が続き、文が自然になる。"}, {"text": "が", "is_correct": false, "explanation": "「ファッションが調べました」では「調べる」の目的語を示せず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ファッションに調べました」は対象の格として成り立たず、不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "「ファッションで調べました」は手段の意味になり、「調べる」の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「調べました」の目的語として「ファッションを」が続き、文が自然になる。", "が": "「ファッションが調べました」では「調べる」の目的語を示せず、文が成り立たない。", "に": "「ファッションに調べました」は対象の格として成り立たず、不自然になる。", "で": "「ファッションで調べました」は手段の意味になり、「調べる」の対象を示せない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "方向・対象", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39082, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "服やかばんなどの、新しい形や色の流行のことです。", "primary_collocate": null, "pronunciation": "ふぁっしょん", "ipa": "ɸaɕːoɴ", "syllable_count": 4, "sentences": [{"text": "妹は服のファッションが好きで、毎月雑誌を買っています。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "妹[いもうと]は服[ふく]のファッションが好[す]きで、毎月[まいつき]雑誌[ざっし]を買[か]っています。", "sentence_source": "generated"}, {"text": "今年のファッションは、明るい色が人気です。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "今年[ことし]のファッションは、明[あか]るい色[いろ]が人気[にんき]です。", "sentence_source": "generated"}, {"text": "彼女はファッションが好きなので、服を選ぶのに時間がかかります。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はファッションが好[す]きなので、服[ふく]を選[えら]ぶのに時間[じかん]がかかります。", "sentence_source": "generated"}, {"text": "パリは世界のファッションの中心として知られています。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "パリは世界[せかい]のファッションの中心[ちゅうしん]として知[し]られています。", "sentence_source": "generated"}, {"text": "若い人のファッションを知りたくて、駅前の店を見て回りました。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "若[わか]い人[ひと]のファッションを知[し]りたくて、駅前[えきまえ]の店[みせ]を見[み]て回[まわ]りました。", "sentence_source": "generated"}, {"text": "兄はファッションより、食べ物にお金を使います。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "兄[あに]はファッションより、食[た]べ物[もの]にお金[かね]を使[つか]います。", "sentence_source": "generated"}, {"text": "春になると、ファッションの色も軽くなります。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "春[はる]になると、ファッションの色[いろ]も軽[かる]くなります。", "sentence_source": "generated"}, {"text": "雑誌で今年の春のファッションを調べました。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "雑誌[ざっし]で今年[ことし]の春[はる]のファッションを調[しら]べました。", "sentence_source": "generated"}, {"text": "母は年をとっても、ファッションを楽しんでいます。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "母[はは]は年[とし]をとっても、ファッションを楽[たの]しんでいます。", "sentence_source": "generated"}, {"text": "ファッションを変えたら、友だちに「雰囲気が違うね」と言われました。", "target_word": "ファッション", "complexity_tier": "T3", "furigana": "ファッションを変[か]えたら、友[とも]だちに「雰囲気[ふんいき]が違[ちが]うね」と言[い]われました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ファッション", "label": "基本形"}], "register": "標準", "sense_fingerprint": "服や小物の流行・おしゃれのスタイル", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b906860-ce3e-49f4-97db-f10691e443cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39082, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ファッション", "is_correct": true, "explanation": "「服の＿＿が好き」の空欄は服の流行を指し、毎月雑誌を買う文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「服の天気」は成り立たず、服の好みを述べる文には入らない。"}, {"text": "化石", "is_correct": false, "explanation": "「服の化石」は意味をなさず、服の好みの話とは結びつかない。"}, {"text": "電圧", "is_correct": false, "explanation": "物理の用語で、雑誌を毎月買う話題とは関係がなく、この空欄には入らない。"}], "explanations": {"ファッション": "「服の＿＿が好き」の空欄は服の流行を指し、毎月雑誌を買う文脈に合う。", "天気": "「服の天気」は成り立たず、服の好みを述べる文には入らない。", "化石": "「服の化石」は意味をなさず、服の好みの話とは結びつかない。", "電圧": "物理の用語で、雑誌を毎月買う話題とは関係がなく、この空欄には入らない。"}, "sentence_index": 0, "correct_answer": "ファッション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この病気はファッションとなって町中に広がり、患者が増えている。", "explanation": "ここは〈流行〉（病気が広がる意味）の場面。ファッションは服や小物の流行に限られるので、病気の広がりには使わない。"}, {"text": "この建物は洋風のファッションで建てられた。", "explanation": "ここは〈様式〉の意味。ファッションは服装の流行で、建築の様式を指す語ではない。"}, {"text": "彼は足のファッションがとても長い。", "explanation": "ここは〈スタイル〉（体つき）の意味。ファッションは服の流行で、体の形は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39082, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ファッション", "is_correct": true, "explanation": "「ファッションの色」は服の流行の色調を表し、春に流行色が軽くなるという文脈に合う。"}, {"text": "試験", "is_correct": false, "explanation": "「試験の色」は意味をなさず、春に色が軽くなる文脈とは関係がない。"}, {"text": "野球", "is_correct": false, "explanation": "「野球の色」は不自然で、春の色の変化を述べる文には入らない。"}, {"text": "地震", "is_correct": false, "explanation": "「地震の色」は不自然で、春になると色が軽くなるという内容とは無関係。"}], "explanations": {"ファッション": "「ファッションの色」は服の流行の色調を表し、春に流行色が軽くなるという文脈に合う。", "試験": "「試験の色」は意味をなさず、春に色が軽くなる文脈とは関係がない。", "野球": "「野球の色」は不自然で、春の色の変化を述べる文には入らない。", "地震": "「地震の色」は不自然で、春になると色が軽くなるという内容とは無関係。"}, "sentence_index": 6, "correct_answer": "ファッション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "加速すると、車のファッションが上がった。", "explanation": "ここは〈速度〉の意味。ファッションは服の流行で、速さを表す語ではないので合わない。"}, {"text": "食事のファッションを守るのが、このレストランのルールだ。", "explanation": "ここは〈マナー・作法〉の意味。ファッションは服の流行で、食事の作法には使わない。"}, {"text": "この皿のファッションは陶器だ。", "explanation": "ここは〈材質〉の意味。ファッションは服などの流行で、物の素材は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39082, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟はファッションを興味があって、毎週服を買っています。", "corrected_sentence": "弟はファッションに興味があって、毎週服を買っています。", "error_description": "「興味がある」に続く助詞は「に」。「を」は誤りで、「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39082, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母はファッションを好きで、毎月新しい服を買っています。", "corrected_sentence": "祖母はファッションが好きで、毎月新しい服を買っています。", "error_description": "「好き」の前に来る助詞は「が」。「を」は誤りで、「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39084, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稀", "is_correct": true, "explanation": "頻繁の対義語。回数が少ないようすを表し、繰り返しの多さと対になる。"}, {"text": "穏やか", "is_correct": false, "explanation": "穏やかは性格や様子の落ち着きを表し、回数の対義語ではない。"}, {"text": "豪華", "is_correct": false, "explanation": "豪華は派手で贅沢なようすを表し、回数とは無関係。"}, {"text": "頑丈", "is_correct": false, "explanation": "頑丈は堅くしっかりしたようすを表し、回数の対義語ではない。"}], "correct_answer": "稀", "explanations": {"稀": "頻繁の対義語。回数が少ないようすを表し、繰り返しの多さと対になる。", "穏やか": "穏やかは性格や様子の落ち着きを表し、回数の対義語ではない。", "豪華": "豪華は派手で贅沢なようすを表し、回数とは無関係。", "頑丈": "頑丈は堅くしっかりしたようすを表し、回数の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39084, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稀", "is_correct": true, "explanation": "頻繁の対義語。回数が少ないようすを表し、繰り返しの多さと対になる。"}, {"text": "確実", "is_correct": false, "explanation": "確実は間違いがないようすを表し、回数の対義語ではない。"}, {"text": "簡素", "is_correct": false, "explanation": "簡素は飾りがなくシンプルなようすを表し、回数とは無関係。"}, {"text": "慎重", "is_correct": false, "explanation": "慎重は注意深いようすを表し、回数の対義語ではない。"}], "correct_answer": "稀", "explanations": {"稀": "頻繁の対義語。回数が少ないようすを表し、繰り返しの多さと対になる。", "確実": "確実は間違いがないようすを表し、回数の対義語ではない。", "簡素": "簡素は飾りがなくシンプルなようすを表し、回数とは無関係。", "慎重": "慎重は注意深いようすを表し、回数の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39084, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "何度も何度も、同じことをするようす。", "primary_collocate": null, "pronunciation": "ひんぱん", "ipa": "çimpaɴ", "syllable_count": 4, "sentences": [{"text": "彼は頻繁に図書館へ行くので、司書さんと仲がいい。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "彼(かれ)は頻繁(ひんぱん)に図書館(としょかん)へ行(い)くので、司書(ししょ)さんと仲(なか)がいい。", "sentence_source": "generated"}, {"text": "弟は頻繁に電話をかけてくるから、少しうるさい。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "弟(おとうと)は頻繁(ひんぱん)に電話(でんわ)をかけてくるから、少(すこ)しうるさい。", "sentence_source": "generated"}, {"text": "母は頻繁に掃除をするので、家はいつもきれいだ。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "母(はは)は頻繁(ひんぱん)に掃除(そうじ)をするので、家(いえ)はいつもきれいだ。", "sentence_source": "generated"}, {"text": "頻繁に忘れ物をするなら、前の晩に準備したほうがいい。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "頻繁(ひんぱん)に忘(わす)れ物(もの)をするなら、前(まえ)の晩(ばん)に準備(じゅんび)したほうがいい。", "sentence_source": "generated"}, {"text": "駅前の道は、頻繁に工事をしていて通りにくい。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "駅前(えきまえ)の道(みち)は、頻繁(ひんぱん)に工事(こうじ)をしていて通(とお)りにくい。", "sentence_source": "generated"}, {"text": "頻繁に会っていた友達と、引っ越して会えなくなった。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "頻繁(ひんぱん)に会(あ)っていた友達(ともだち)と、引(ひ)っ越(こ)して会(あ)えなくなった。", "sentence_source": "generated"}, {"text": "彼女は頻繁にメールを送ってくるが、返事は短い。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は頻繁(ひんぱん)にメールを送(おく)ってくるが、返事(へんじ)は短(みじか)い。", "sentence_source": "generated"}, {"text": "この機械は頻繁に止まるので、新しいのに替えたい。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "この機械(きかい)は頻繁(ひんぱん)に止(と)まるので、新(あたら)しいのに替(か)えたい。", "sentence_source": "generated"}, {"text": "犬は頻繁に外へ出たがるので、一日に何回も散歩をする。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "犬(いぬ)は頻繁(ひんぱん)に外(そと)へ出(で)たがるので、一日(いちにち)に何回(なんかい)も散歩(さんぽ)をする。", "sentence_source": "generated"}, {"text": "頻繁な連絡は大切だが、ときには一人の時間もほしい。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "頻繁(ひんぱん)な連絡(れんらく)は大切(たいせつ)だが、ときには一人(ひとり)の時間(じかん)もほしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "頻繁", "label": "語幹"}, {"form": "頻繁だ", "label": "終止形"}, {"form": "頻繁な", "label": "連体形"}, {"form": "頻繁に", "label": "連用形"}, {"form": "頻繁で", "label": "中止形"}], "register": "中立(普通体)", "sense_fingerprint": "何度も繰り返されるようす。人や動物の行動にも、機械や工事などの出来事にも使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd49ee28-674e-431e-aee3-ee814a8995c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39084, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "頻繁", "is_correct": true, "explanation": "『に』が続いて副詞になり、何度も図書館へ行くという文に合う。"}, {"text": "頑丈", "is_correct": false, "explanation": "頑丈は堅くしっかりしたようすで、行く回数の話と合わない。"}, {"text": "豪華", "is_correct": false, "explanation": "豪華は派手で贅沢なようすで、図書館へ行く文と合わない。"}, {"text": "盛大", "is_correct": false, "explanation": "盛大は規模が大きいようすで、図書館へ行く文と合わない。"}], "explanations": {"頻繁": "『に』が続いて副詞になり、何度も図書館へ行くという文に合う。", "頑丈": "頑丈は堅くしっかりしたようすで、行く回数の話と合わない。", "豪華": "豪華は派手で贅沢なようすで、図書館へ行く文と合わない。", "盛大": "盛大は規模が大きいようすで、図書館へ行く文と合わない。"}, "sentence_index": 0, "correct_answer": "頻繁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は頻繁に明るい性格だ。", "explanation": "ここは状態が続く意味の常に。頻繁は同じ行動の繰り返しに使うので、性格の状態には合わない。"}, {"text": "この山は頻繁に高い。", "explanation": "ここは程度を表す極めて。頻繁は回数の多さを表すので、山の高さには使えない。"}, {"text": "その事件は頻繁に一度だけ起きた。", "explanation": "ここは回数が少ないという意味のたまに。頻繁は繰り返しの多さを表すので、回数の少なさとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39084, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頻繁", "is_correct": true, "explanation": "『に』が続いて副詞になり、何度もメールを送るという文に合う。"}, {"text": "頑丈", "is_correct": false, "explanation": "頑丈は堅くしっかりしたようすで、メールを送る回数の文と合わない。"}, {"text": "壮大", "is_correct": false, "explanation": "壮大は規模が大きいようすで、メールを送る文と合わない。"}, {"text": "豪快", "is_correct": false, "explanation": "豪快は大胆で勢いがよいようすで、メールを送る文と合わない。"}], "explanations": {"頻繁": "『に』が続いて副詞になり、何度もメールを送るという文に合う。", "頑丈": "頑丈は堅くしっかりしたようすで、メールを送る回数の文と合わない。", "壮大": "壮大は規模が大きいようすで、メールを送る文と合わない。", "豪快": "豪快は大胆で勢いがよいようすで、メールを送る文と合わない。"}, "sentence_index": 6, "correct_answer": "頻繁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "頻繁な森で、道に迷ってしまった。", "explanation": "ここは木が密集しているという意味の密。頻繁は回数を表すので、森の密さには使えない。"}, {"text": "頻繁な色が、部屋を明るく見せる。", "explanation": "ここは色が鮮やかという意味の鮮やか。頻繁は回数を表すので、色の鮮やかさには合わない。"}, {"text": "頻繁な意見で、議論に勝った。", "explanation": "ここは筋が通っているという意味の論理的。頻繁は回数を表すので、意見の筋の通り方には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39084, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店には、頻繁だ客が来る。", "corrected_sentence": "この店には、頻繁に客が来る。", "error_description": "『頻繁』の直後が『だ』になっている。『だ』は名詞の前に置けず、『来る』を修飾する『に』が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "頻繁", "is_correct": true, "explanation": "語幹の形で、『に』と続けて副詞になる形として文中の形に当たる。"}, {"text": "頻繁だ", "is_correct": false, "explanation": "終止形で、『に』の前に置けず、動詞を修飾できない。"}, {"text": "頻繁な", "is_correct": false, "explanation": "連体形で、名詞の前に置く形のため、動詞『かけてくる』を修飾できない。"}, {"text": "頻繁で", "is_correct": false, "explanation": "中止形で、ここでは動詞を修飾する役目を果たせない。"}], "correct_form": "頻繁", "base_form": "頻繁だ", "form_label": "語幹", "sentence_index": 1, "explanations": {"頻繁": "語幹の形で、『に』と続けて副詞になる形として文中の形に当たる。", "頻繁だ": "終止形で、『に』の前に置けず、動詞を修飾できない。", "頻繁な": "連体形で、名詞の前に置く形のため、動詞『かけてくる』を修飾できない。", "頻繁で": "中止形で、ここでは動詞を修飾する役目を果たせない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39084, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この時期は、頻繁を雨が降る。", "corrected_sentence": "この時期は、頻繁に雨が降る。", "error_description": "頻繁の直後の助詞が『を』になっている。頻繁は『に』で動詞を修飾する副詞なので、正しくは『頻繁に雨が降る』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "頻繁", "is_correct": true, "explanation": "語幹の形で、『に』と続けて副詞になる形として文中の形に当たる。"}, {"text": "頻繁だった", "is_correct": false, "explanation": "過去形で、ここでは現在の動作を修飾する形として合わない。"}, {"text": "頻繁ではない", "is_correct": false, "explanation": "否定形で、回数の多さを述べる文脈と合わない。"}, {"text": "頻繁であれば", "is_correct": false, "explanation": "仮定形で、ここでは止まる回数を述べる文として合わない。"}], "correct_form": "頻繁", "base_form": "頻繁だ", "form_label": "語幹", "sentence_index": 7, "explanations": {"頻繁": "語幹の形で、『に』と続けて副詞になる形として文中の形に当たる。", "頻繁だった": "過去形で、ここでは現在の動作を修飾する形として合わない。", "頻繁ではない": "否定形で、回数の多さを述べる文脈と合わない。", "頻繁であれば": "仮定形で、ここでは止まる回数を述べる文として合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39085, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "まれ", "is_correct": true, "explanation": "回数が少ないさまを表し、頻繁の対義語として辞典に挙がる。"}, {"text": "確実", "is_correct": false, "explanation": "確かであるさまを表す語で、回数の多少とは対義関係にない。"}, {"text": "静か", "is_correct": false, "explanation": "物音が少ないさまを表し、頻繁の対義語ではない。"}, {"text": "盛大", "is_correct": false, "explanation": "規模が大きく華やかなさまを表し、回数の対義語ではない。"}], "correct_answer": "まれ", "explanations": {"まれ": "回数が少ないさまを表し、頻繁の対義語として辞典に挙がる。", "確実": "確かであるさまを表す語で、回数の多少とは対義関係にない。", "静か": "物音が少ないさまを表し、頻繁の対義語ではない。", "盛大": "規模が大きく華やかなさまを表し、回数の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39085, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "まれ", "is_correct": true, "explanation": "回数が少ないさまを表し、頻繁の対義語として辞典に挙がる。"}, {"text": "頑丈", "is_correct": false, "explanation": "丈夫で壊れにくいさまを表し、回数の対義語ではない。"}, {"text": "膨大", "is_correct": false, "explanation": "非常に大きいさまを表し、回数の対義語ではない。"}, {"text": "公平", "is_correct": false, "explanation": "偏りがないさまを表し、回数の対義語ではない。"}], "correct_answer": "まれ", "explanations": {"まれ": "回数が少ないさまを表し、頻繁の対義語として辞典に挙がる。", "頑丈": "丈夫で壊れにくいさまを表し、回数の対義語ではない。", "膨大": "非常に大きいさまを表し、回数の対義語ではない。", "公平": "偏りがないさまを表し、回数の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39085, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "回数が多いさま。たびたび。", "primary_collocate": null, "pronunciation": "ひんぱん", "ipa": "çimpaɴ", "syllable_count": 4, "sentences": [{"text": "この地域では地震が頻繁に起こる。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "この地域(ちいき)では地震(じしん)が頻繁(ひんぱん)に起(お)こる。", "sentence_source": "generated"}, {"text": "春は天気が変わりやすく、雨が頻繁に降る。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "春(はる)は天気(てんき)が変(か)わりやすく、雨(あめ)が頻繁(ひんぱん)に降(ふ)る。", "sentence_source": "generated"}, {"text": "最近、この道で事故が頻繁に起きている。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "最近(さいきん)、この道(みち)で事故(じこ)が頻繁(ひんぱん)に起(お)きている。", "sentence_source": "generated"}, {"text": "空港には、飛行機が頻繁に離着陸する。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "空港(くうこう)には、飛行機(ひこうき)が頻繁(ひんぱん)に離着陸(りちゃくりく)する。", "sentence_source": "generated"}, {"text": "朝のバスは頻繁に来るので、待たなくてもいい。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "朝(あさ)のバスは頻繁(ひんぱん)に来(く)るので、待(ま)たなくてもいい。", "sentence_source": "generated"}, {"text": "頻繁に停電が起こるため、ろうそくを用意している。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "頻繁(ひんぱん)に停電(ていでん)が起(お)こるため、ろうそくを用意(ようい)している。", "sentence_source": "generated"}, {"text": "頻繁な引っ越しは、子どもにとって大変だ。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "頻繁(ひんぱん)な引(ひ)っ越(こ)しは、子(こ)どもにとって大変(たいへん)だ。", "sentence_source": "generated"}, {"text": "この駅は人の出入りが頻繁だ。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "この駅(えき)は人(ひと)の出入(でい)りが頻繁(ひんぱん)だ。", "sentence_source": "generated"}, {"text": "冬は頻繁に雪が降るので、毎朝雪かきをする。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "冬(ふゆ)は頻繁(ひんぱん)に雪(ゆき)が降(ふ)るので、毎朝(まいあさ)雪(ゆき)かきをする。", "sentence_source": "generated"}, {"text": "頻繁に起こる故障のせいで、工場の生産が遅れた。", "target_word": "頻繁", "complexity_tier": "T3", "furigana": "頻繁(ひんぱん)に起(お)こる故障(こしょう)のせいで、工場(こうじょう)の生産(せいさん)が遅(おく)れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "頻繁", "label": "語幹"}, {"form": "頻繁だ", "label": "終止形"}, {"form": "頻繁な", "label": "連体形"}, {"form": "頻繁に", "label": "連用形"}, {"form": "頻繁で", "label": "中止形"}], "register": "中立(普通体)", "sense_fingerprint": "出来事や現象が起こる回数が多いようす。地震・事故・停電などの発生頻度に使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd49ee28-674e-431e-aee3-ee814a8995c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39085, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "頻繁", "is_correct": true, "explanation": "「地震が頻繁に起こる」で、起こる回数が多いことを表す。"}, {"text": "深刻", "is_correct": false, "explanation": "「深刻に起こる」は不自然。深刻は事態の重大さを表し、回数には使わない。"}, {"text": "鮮明", "is_correct": false, "explanation": "「鮮明に起こる」は意味が通らない。鮮明は映像や色がはっきりしていることを表す。"}, {"text": "静粛", "is_correct": false, "explanation": "「静粛に起こる」は成り立たない。静粛は音や態度が静かなことを表す。"}], "explanations": {"頻繁": "「地震が頻繁に起こる」で、起こる回数が多いことを表す。", "深刻": "「深刻に起こる」は不自然。深刻は事態の重大さを表し、回数には使わない。", "鮮明": "「鮮明に起こる」は意味が通らない。鮮明は映像や色がはっきりしていることを表す。", "静粛": "「静粛に起こる」は成り立たない。静粛は音や態度が静かなことを表す。"}, "sentence_index": 0, "correct_answer": "頻繁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このパンは味が頻繁だ。", "explanation": "ここは〈美味しい〉の意味。頻繁は回数の多さを表すので、味の良さを言う文には合わない。"}, {"text": "この絵は色使いが頻繁で、遠くからでもよく分かる。", "explanation": "ここは〈鮮やか〉の意味。頻繁は回数の多さなので、色の鮮やかさには使わない。"}, {"text": "この国は資源が頻繁だ。", "explanation": "ここは〈豊富〉の意味。頻繁は回数の多さなので、資源の量を表す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39085, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頻繁", "is_correct": true, "explanation": "「頻繁な引っ越し」で、引っ越しの回数が多いことを表す。"}, {"text": "豊富", "is_correct": false, "explanation": "「豊富な引っ越し」は不自然。豊富は量が多いことを表す。"}, {"text": "頑丈", "is_correct": false, "explanation": "「頑丈な引っ越し」は意味が通らない。頑丈は物の丈夫さを表す。"}, {"text": "広大", "is_correct": false, "explanation": "「広大な引っ越し」は成り立たない。広大は面積が広いことを表す。"}], "explanations": {"頻繁": "「頻繁な引っ越し」で、引っ越しの回数が多いことを表す。", "豊富": "「豊富な引っ越し」は不自然。豊富は量が多いことを表す。", "頑丈": "「頑丈な引っ越し」は意味が通らない。頑丈は物の丈夫さを表す。", "広大": "「広大な引っ越し」は成り立たない。広大は面積が広いことを表す。"}, "sentence_index": 6, "correct_answer": "頻繁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場の在庫が頻繁で、倉庫がいっぱいだ。", "explanation": "ここは〈膨大〉の意味。頻繁は回数の多さなので、在庫の量を表す文には合わない。"}, {"text": "この機械は頻繁で、長く使える。", "explanation": "ここは〈頑丈〉の意味。頻繁は回数を表すので、機械の丈夫さには使わない。"}, {"text": "夜の町は頻繁だ。", "explanation": "ここは〈静か〉の意味。頻繁は回数の多さを表すので、町の静けさには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39085, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は雨が頻繁の降る。", "corrected_sentence": "週末は雨が頻繁に降る。", "error_description": "動詞「降る」を修飾するには副詞形「頻繁に」が必要。「頻繁の」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "頻繁", "is_correct": true, "explanation": "「雨が頻繁に降る」の語幹。ここで正しい形。"}, {"text": "頻繁だ", "is_correct": false, "explanation": "終止形。「頻繁だに降る」となり、副詞として動詞に続かない。"}, {"text": "頻繁な", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、動詞「降る」を直接修飾できない。"}, {"text": "頻繁だった", "is_correct": false, "explanation": "過去形の述語。ここでは時制も形も合わない。"}], "correct_form": "頻繁", "base_form": "頻繁だ", "form_label": "語幹", "sentence_index": 1, "explanations": {"頻繁": "「雨が頻繁に降る」の語幹。ここで正しい形。", "頻繁だ": "終止形。「頻繁だに降る」となり、副詞として動詞に続かない。", "頻繁な": "連体形。名詞を修飾する形で、動詞「降る」を直接修飾できない。", "頻繁だった": "過去形の述語。ここでは時制も形も合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39085, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この道は車が頻繁な通る。", "corrected_sentence": "この道は車が頻繁に通る。", "error_description": "動詞「通る」を修飾するには副詞形「頻繁に」が必要。連体形「頻繁な」は名詞を修飾する形なので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "頻繁", "is_correct": true, "explanation": "「人の出入りが頻繁だ」の語幹。ここで正しい形。"}, {"text": "頻繁に", "is_correct": false, "explanation": "連用形。「人の出入りが頻繁にだ」となり、述語として成り立たない。"}, {"text": "頻繁で", "is_correct": false, "explanation": "中止形。ここでは後ろに続く述語が「だ」と重なり、文が成り立たない。"}, {"text": "頻繁ではない", "is_correct": false, "explanation": "否定形。文の意味が「頻繁でない」に変わり、元の文と合わない。"}], "correct_form": "頻繁", "base_form": "頻繁だ", "form_label": "語幹", "sentence_index": 7, "explanations": {"頻繁": "「人の出入りが頻繁だ」の語幹。ここで正しい形。", "頻繁に": "連用形。「人の出入りが頻繁にだ」となり、述語として成り立たない。", "頻繁で": "中止形。ここでは後ろに続く述語が「だ」と重なり、文が成り立たない。", "頻繁ではない": "否定形。文の意味が「頻繁でない」に変わり、元の文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
