INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39088, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「シャツを買う」の「を」で、買う対象を示すので文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「シャツが買おう」では意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や相手を示すので、買う対象の前には置けない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すので、「シャツで買おう」は目的語にならず不自然。"}], "correct_answer": "を", "explanations": {"を": "「シャツを買う」の「を」で、買う対象を示すので文に合う。", "が": "「が」は主語を示すので、「シャツが買おう」では意味が通らない。", "に": "「に」は到達点や相手を示すので、買う対象の前には置けない。", "で": "「で」は手段を示すので、「シャツで買おう」は目的語にならず不自然。"}, "error_tags": {"が": "主語", "に": "方向", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39088, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体に着るものです。", "primary_collocate": null, "pronunciation": "しゃつ", "ipa": "ɕatsɯ", "syllable_count": 2, "sentences": [{"text": "朝、白いシャツにアイロンをかけました。", "target_word": "シャツ", "complexity_tier": "T3", "furigana": "朝(あさ)、白(しろ)いシャツにアイロンをかけました。", "sentence_source": "generated"}, {"text": "このシャツは小さいので、着られません。", "target_word": "シャツ", "complexity_tier": "T3", "furigana": "このシャツは小(ちい)さいので、着(き)られません。", "sentence_source": "generated"}, {"text": "汗でシャツがぬれて、気持ちが悪い。", "target_word": "シャツ", "complexity_tier": "T3", "furigana": "汗(あせ)でシャツがぬれて、気持(きも)ちが悪(わる)い。", "sentence_source": "generated"}, {"text": "弟は毎日、同じシャツを着ている。", "target_word": "シャツ", "complexity_tier": "T3", "furigana": "弟(おとうと)は毎日(まいにち)、同(おな)じシャツを着(き)ている。", "sentence_source": "generated"}, {"text": "シャツのボタンが取れたので、母に直してもらった。", "target_word": "シャツ", "complexity_tier": "T3", "furigana": "シャツのボタンが取(と)れたので、母(はは)に直(なお)してもらった。", "sentence_source": "generated"}, {"text": "寒いから、シャツの上にセーターを着なさい。", "target_word": "シャツ", "complexity_tier": "T3", "furigana": "寒(さむ)いから、シャツの上(うえ)にセーターを着(き)なさい。", "sentence_source": "generated"}, {"text": "洗ったシャツをベランダにほした。", "target_word": "シャツ", "complexity_tier": "T3", "furigana": "洗(あら)ったシャツをベランダにほした。", "sentence_source": "generated"}, {"text": "赤いシャツを買おうと思ったが、高すぎてやめた。", "target_word": "シャツ", "complexity_tier": "T3", "furigana": "赤(あか)いシャツを買(か)おうと思(おも)ったが、高(たか)すぎてやめた。", "sentence_source": "generated"}, {"text": "シャツのそでが長すぎて、手が出ません。", "target_word": "シャツ", "complexity_tier": "T3", "furigana": "シャツのそでが長(なが)すぎて、手(て)が出(で)ません。", "sentence_source": "generated"}, {"text": "彼は青いシャツがよく似合う。", "target_word": "シャツ", "complexity_tier": "T3", "furigana": "彼(かれ)は青(あお)いシャツがよく似合(にあ)う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "シャツ", "label": "基本形"}], "register": "日常語", "sense_fingerprint": "上半身に着る衣類", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0767258-83b5-4171-bcae-53bbc15f4a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39088, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "シャツ", "is_correct": true, "explanation": "衣類で、アイロンをかける対象として自然に文に合う。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋はアイロンをかける物ではなく、「白い鍋にアイロン」は意味をなさない。"}, {"text": "窓", "is_correct": false, "explanation": "窓はアイロンをかける物ではないので、文が成り立たない。"}, {"text": "机", "is_correct": false, "explanation": "机にはアイロンをかけないので、この文脈では不自然になる。"}], "explanations": {"シャツ": "衣類で、アイロンをかける対象として自然に文に合う。", "鍋": "鍋はアイロンをかける物ではなく、「白い鍋にアイロン」は意味をなさない。", "窓": "窓はアイロンをかける物ではないので、文が成り立たない。", "机": "机にはアイロンをかけないので、この文脈では不自然になる。"}, "sentence_index": 0, "correct_answer": "シャツ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は昨日、新しいシャツを履いて出かけた。", "explanation": "ここは〈ズボン〉の意味。シャツは上半身に着る衣類で、足に履くものではないので使えない。"}, {"text": "風邪をひいたので、シャツをつけて外へ出た。", "explanation": "ここは〈マスク〉の意味。シャツは体に着る衣類で、顔につけるものとしては使わない。"}, {"text": "寒い日は、シャツを手袋のようにはめる。", "explanation": "ここは〈グローブ〉の意味。シャツは体に着る衣類で、手に着けるものとしては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39088, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "シャツ", "is_correct": true, "explanation": "洗って干す衣類として自然な対象で、ベランダにほす文に合う。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は洗って干す物ではなく、文の意味が成り立たない。"}, {"text": "本棚", "is_correct": false, "explanation": "大きな家具は洗って干さないので、この文脈では不自然になる。"}, {"text": "植木", "is_correct": false, "explanation": "植木は洗って干すものではないので、文の意味が合わない。"}], "explanations": {"シャツ": "洗って干す衣類として自然な対象で、ベランダにほす文に合う。", "花瓶": "花瓶は洗って干す物ではなく、文の意味が成り立たない。", "本棚": "大きな家具は洗って干さないので、この文脈では不自然になる。", "植木": "植木は洗って干すものではないので、文の意味が合わない。"}, "sentence_index": 6, "correct_answer": "シャツ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "重い荷物を運ぶため、彼は重いシャツを背負って山道を登った。", "explanation": "ここは〈リュック〉の意味。シャツは体に着る衣類で、背負う荷物にはならない。"}, {"text": "雨の日は、シャツをさして出かけた。", "explanation": "「さす」は傘に使う動詞で、シャツには使わない。ここは〈傘〉の意味。"}, {"text": "夏の朝、彼はネクタイのかわりにシャツを締めた。", "explanation": "ここは〈首元に締める装身具〉の意味。シャツは体に着る衣類で、首元に締めるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39088, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は白いシャツをはいて、学校へ行った。", "corrected_sentence": "妹は白いシャツを着て、学校へ行った。", "error_description": "シャツは上半身の衣類なので「着る」を使う。「はく」は下半身の衣類に使うため誤り。正しくは「着て」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39088, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は青いシャツが着て、会社へ行った。", "corrected_sentence": "父は青いシャツを着て、会社へ行った。", "error_description": "「着る」の対象は「を」で示すので、「シャツが」は誤り。正しくは「シャツを」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39090, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「年間を通して」の「を」。年間が「通す」の対象として続く。"}, {"text": "に", "is_correct": false, "explanation": "「年間に通して」は成り立たない。「に」は時点や方向を示す助詞。"}, {"text": "で", "is_correct": false, "explanation": "「年間で通して」は不自然。「で」は手段や場所を示す助詞。"}, {"text": "が", "is_correct": false, "explanation": "「年間が通して」は成り立たない。「が」は主語を示す助詞。"}], "correct_answer": "を", "explanations": {"を": "「年間を通して」の「を」。年間が「通す」の対象として続く。", "に": "「年間に通して」は成り立たない。「に」は時点や方向を示す助詞。", "で": "「年間で通して」は不自然。「で」は手段や場所を示す助詞。", "が": "「年間が通して」は成り立たない。「が」は主語を示す助詞。"}, "error_tags": {"に": "時点・方向", "で": "場所・手段", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39090, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「年間を通して使える」の「を」。年間が「通す」の対象として続く。"}, {"text": "と", "is_correct": false, "explanation": "「年間と通して」は成り立たない。「と」は並列や相手を示す助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「年間へ通して」は不自然。「へ」は方向を示す助詞。"}, {"text": "より", "is_correct": false, "explanation": "「年間より通して」は成り立たない。「より」は比較や起点を示す助詞。"}], "correct_answer": "を", "explanations": {"を": "「年間を通して使える」の「を」。年間が「通す」の対象として続く。", "と": "「年間と通して」は成り立たない。「と」は並列や相手を示す助詞。", "へ": "「年間へ通して」は不自然。「へ」は方向を示す助詞。", "より": "「年間より通して」は成り立たない。「より」は比較や起点を示す助詞。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39090, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一年の間、ずっとという意味です。", "primary_collocate": null, "pronunciation": "ねんかん", "ipa": "neŋkaɴ", "syllable_count": 4, "sentences": [{"text": "この島は、年間を通して暖かい。", "target_word": "年間", "complexity_tier": "T3", "furigana": "この島(しま)は、年間(ねんかん)を通(とお)して暖(あたた)かい。", "sentence_source": "generated"}, {"text": "彼は年間を通してジョギングを続けている。", "target_word": "年間", "complexity_tier": "T3", "furigana": "彼(かれ)は年間(ねんかん)を通(とお)してジョギングを続(つづ)けている。", "sentence_source": "generated"}, {"text": "このスキー場は、年間を通じて雪がある。", "target_word": "年間", "complexity_tier": "T3", "furigana": "このスキー場(じょう)は、年間(ねんかん)を通(つう)じて雪(ゆき)がある。", "sentence_source": "generated"}, {"text": "花屋には年間を通して、いろいろな花が並んでいる。", "target_word": "年間", "complexity_tier": "T3", "furigana": "花屋(はなや)には年間(ねんかん)を通(とお)して、いろいろな花(はな)が並(なら)んでいる。", "sentence_source": "generated"}, {"text": "祖父は年間を通して畑で働いている。", "target_word": "年間", "complexity_tier": "T3", "furigana": "祖父(そふ)は年間(ねんかん)を通(とお)して畑(はたけ)で働(はたら)いている。", "sentence_source": "generated"}, {"text": "この図書館は、年間を通して休みがない。", "target_word": "年間", "complexity_tier": "T3", "furigana": "この図書館(としょかん)は、年間(ねんかん)を通(とお)して休(やす)みがない。", "sentence_source": "generated"}, {"text": "山の上の寺は、年間を通して観光客が多い。", "target_word": "年間", "complexity_tier": "T3", "furigana": "山(やま)の上(うえ)の寺(てら)は、年間(ねんかん)を通(とお)して観光客(かんこうきゃく)が多(おお)い。", "sentence_source": "generated"}, {"text": "年間を通して使える傘を買った。", "target_word": "年間", "complexity_tier": "T3", "furigana": "年間(ねんかん)を通(とお)して使(つか)える傘(かさ)を買(か)った。", "sentence_source": "generated"}, {"text": "動物園は、年間を通して朝九時から開いている。", "target_word": "年間", "complexity_tier": "T3", "furigana": "動物園(どうぶつえん)は、年間(ねんかん)を通(とお)して朝(あさ)九時(くじ)から開(あ)いている。", "sentence_source": "generated"}, {"text": "この店は、年間を通して同じ値段で売っている。", "target_word": "年間", "complexity_tier": "T3", "furigana": "この店(みせ)は、年間(ねんかん)を通(とお)して同(おな)じ値段(ねだん)で売(う)っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "年間", "label": "基本形"}], "register": "中立(普通体)", "sense_fingerprint": "一年中ずっと。「年間を通して」の形で、一年を通じて変わらない状態や行動を表す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd49ee28-674e-431e-aee3-ee814a8995c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39090, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年間", "is_correct": true, "explanation": "「この島は年間を通して暖かい」で、一年中ずっとという意味を表す。"}, {"text": "日付", "is_correct": false, "explanation": "「日付を通して暖かい」は成り立たない。日付は特定の日を示す語。"}, {"text": "時刻", "is_correct": false, "explanation": "「時刻を通して暖かい」は意味が通らない。時刻は時間の一点を示す語。"}, {"text": "曜日", "is_correct": false, "explanation": "「曜日を通して暖かい」は不自然。曜日は一週間の中の日を示す語。"}], "explanations": {"年間": "「この島は年間を通して暖かい」で、一年中ずっとという意味を表す。", "日付": "「日付を通して暖かい」は成り立たない。日付は特定の日を示す語。", "時刻": "「時刻を通して暖かい」は意味が通らない。時刻は時間の一点を示す語。", "曜日": "「曜日を通して暖かい」は不自然。曜日は一週間の中の日を示す語。"}, "sentence_index": 0, "correct_answer": "年間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は年間の広さが広い。", "explanation": "ここは〈広い〉の意味。年間は期間を表す語で、空間の広さには使わない。"}, {"text": "彼は年間の足が速い。", "explanation": "ここは〈速い〉の意味。年間は期間を表す語で、人の動作の速さには使わない。"}, {"text": "この駅は年間の午後三時に閉まる。", "explanation": "ここは〈毎日〉の意味と混同している。年間は一年の期間を指す語なので、一日の時刻には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39090, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年間", "is_correct": true, "explanation": "「年間を通して観光客が多い」で、一年中ずっとという意味を表す。"}, {"text": "受付", "is_correct": false, "explanation": "「受付を通して観光客が多い」は意味が通らない。受付は手続きの場所。"}, {"text": "金庫", "is_correct": false, "explanation": "「金庫を通して観光客が多い」は成り立たない。金庫は物を保管する容器。"}, {"text": "雑誌", "is_correct": false, "explanation": "「雑誌を通して観光客が多い」は不自然。雑誌は読み物を指す語。"}], "explanations": {"年間": "「年間を通して観光客が多い」で、一年中ずっとという意味を表す。", "受付": "「受付を通して観光客が多い」は意味が通らない。受付は手続きの場所。", "金庫": "「金庫を通して観光客が多い」は成り立たない。金庫は物を保管する容器。", "雑誌": "「雑誌を通して観光客が多い」は不自然。雑誌は読み物を指す語。"}, "sentence_index": 6, "correct_answer": "年間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋は年間だ。", "explanation": "ここは〈古い〉の意味と混同している。年間は期間を表す語なので、部屋の古さを言う文には合わない。"}, {"text": "彼は年間の大声で話した。", "explanation": "ここは〈大きな〉の意味と混同している。年間は一年を単位に数える語で、声の大きさには使わない。"}, {"text": "この箱は年間の重さがある。", "explanation": "ここは〈重い〉の意味と混同している。年間は期間を表す語で、物の重さを言う文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39090, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この湖は年間に通して凍らない。", "corrected_sentence": "この湖は年間を通して凍らない。", "error_description": "「年間」に続けるのは「を」。「に」は誤りで、正しくは「年間を通して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39090, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この池は年間を通して水が枯れたない。", "corrected_sentence": "この池は年間を通して水が枯れない。", "error_description": "「ない」の前に「た」は付かない。「枯れたない」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
