INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39091, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "1年という期間を単位として数えること。", "primary_collocate": null, "pronunciation": "ねんかん", "ipa": "neŋkaɴ", "syllable_count": 4, "sentences": [{"text": "この店は年間で三万人のお客さんが来る。", "target_word": "年間", "complexity_tier": "T3", "furigana": "この店(みせ)は年間(ねんかん)で三万人(さんまんにん)のお客(きゃく)さんが来(く)る。", "sentence_source": "generated"}, {"text": "私は年間五十冊の本を読む。", "target_word": "年間", "complexity_tier": "T3", "furigana": "私(わたし)は年間(ねんかん)五十冊(ごじゅっさつ)の本(ほん)を読(よ)む。", "sentence_source": "generated"}, {"text": "年間の予定を、四月に先生が配ってくれた。", "target_word": "年間", "complexity_tier": "T3", "furigana": "年間(ねんかん)の予定(よてい)を、四月(しがつ)に先生(せんせい)が配(くば)ってくれた。", "sentence_source": "generated"}, {"text": "この工場は、年間百万個の部品を作っている。", "target_word": "年間", "complexity_tier": "T3", "furigana": "この工場(こうじょう)は、年間(ねんかん)百万個(ひゃくまんこ)の部品(ぶひん)を作(つく)っている。", "sentence_source": "generated"}, {"text": "年間の費用を計算したら、思ったより高かった。", "target_word": "年間", "complexity_tier": "T3", "furigana": "年間(ねんかん)の費用(ひよう)を計算(けいさん)したら、思(おも)ったより高(たか)かった。", "sentence_source": "generated"}, {"text": "国内の旅行者は、年間で何百万人にもなる。", "target_word": "年間", "complexity_tier": "T3", "furigana": "国内(こくない)の旅行者(りょこうしゃ)は、年間(ねんかん)で何百万人(なんひゃくまんにん)にもなる。", "sentence_source": "generated"}, {"text": "年間の休みは、会社によってちがう。", "target_word": "年間", "complexity_tier": "T3", "furigana": "年間(ねんかん)の休(やす)みは、会社(かいしゃ)によってちがう。", "sentence_source": "generated"}, {"text": "この町では、年間二百日ほど晴れる。", "target_word": "年間", "complexity_tier": "T3", "furigana": "この町(まち)では、年間(ねんかん)二百日(にひゃくにち)ほど晴(は)れる。", "sentence_source": "generated"}, {"text": "年間の売り上げを見て、来年の計画を立てた。", "target_word": "年間", "complexity_tier": "T3", "furigana": "年間(ねんかん)の売(う)り上(あ)げを見(み)て、来年(らいねん)の計画(けいかく)を立(た)てた。", "sentence_source": "generated"}, {"text": "年間で十回、家族と旅行に行く。", "target_word": "年間", "complexity_tier": "T3", "furigana": "年間(ねんかん)で十回(じゅっかい)、家族(かぞく)と旅行(りょこう)に行(い)く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "年間", "label": "基本形"}], "register": "中立(普通体)", "sense_fingerprint": "一年を単位にして数や量を数える言い方。年間の回数・人数・費用・予定など。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd49ee28-674e-431e-aee3-ee814a8995c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39091, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年間", "is_correct": true, "explanation": "「この店は年間で三万人のお客さんが来る」で、一年を単位に数える意味を表す。"}, {"text": "小包", "is_correct": false, "explanation": "「小包で三万人のお客さんが来る」は意味が通らない。小包は荷物を指す語。"}, {"text": "手帳", "is_correct": false, "explanation": "「手帳で三万人のお客さんが来る」は成り立たない。手帳は書き込む帳面。"}, {"text": "氷山", "is_correct": false, "explanation": "「氷山で三万人のお客さんが来る」は不自然。氷山は海に浮かぶ氷の塊。"}], "explanations": {"年間": "「この店は年間で三万人のお客さんが来る」で、一年を単位に数える意味を表す。", "小包": "「小包で三万人のお客さんが来る」は意味が通らない。小包は荷物を指す語。", "手帳": "「手帳で三万人のお客さんが来る」は成り立たない。手帳は書き込む帳面。", "氷山": "「氷山で三万人のお客さんが来る」は不自然。氷山は海に浮かぶ氷の塊。"}, "sentence_index": 0, "correct_answer": "年間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この川は年間で深い。", "explanation": "ここは〈深さ〉の意味と混同している。年間で数える語は回数や量に使い、川の深さの状態には合わない。"}, {"text": "年間の一瞬に、雨が降った。", "explanation": "ここは〈一瞬〉の意味と混同している。年間は一年を単位に数える語で、一瞬の出来事を言う文には合わない。"}, {"text": "彼は年間の社長が三人いる。", "explanation": "ここは〈歴代〉の意味と混同している。年間は一年単位の数を表す語で、人の役職の数には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39091, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年間", "is_correct": true, "explanation": "「年間の休みは、会社によってちがう」で、一年を単位にした休みの日数を表す。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「夕焼けの休みは、会社によってちがう」は意味が通らない。夕焼けは空の現象。"}, {"text": "石鹸", "is_correct": false, "explanation": "「石鹸の休みは、会社によってちがう」は成り立たない。石鹸は洗浄に使う物。"}, {"text": "砂利", "is_correct": false, "explanation": "「砂利の休みは、会社によってちがう」は不自然。砂利は小石の集まり。"}], "explanations": {"年間": "「年間の休みは、会社によってちがう」で、一年を単位にした休みの日数を表す。", "夕焼け": "「夕焼けの休みは、会社によってちがう」は意味が通らない。夕焼けは空の現象。", "石鹸": "「石鹸の休みは、会社によってちがう」は成り立たない。石鹸は洗浄に使う物。", "砂利": "「砂利の休みは、会社によってちがう」は不自然。砂利は小石の集まり。"}, "sentence_index": 6, "correct_answer": "年間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この町は年間の人口が多い。", "explanation": "ここは〈総数〉の意味と混同している。年間は一年を単位に数える語で、ある時点の人口の多さには使わない。"}, {"text": "この料理は年間の香りが強い。", "explanation": "ここは〈香ばしい〉の意味と混同している。年間は一年単位の数を表す語で、香りの強さには使わない。"}, {"text": "この道は年間の幅が狭い。", "explanation": "ここは〈狭い〉の意味。年間は期間を単位に数える語で、道の幅には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39091, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町は年間を二十回雨が降る。", "corrected_sentence": "この町は年間で二十回雨が降る。", "error_description": "「一年で何回」と数える場合は「年間で」が必要。「年間を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39091, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社員の年間が休みは、会社によってちがう。", "corrected_sentence": "社員の年間の休みは、会社によってちがう。", "error_description": "「年間」が「休み」を修飾するには「の」が必要。「が」は主語を示す助詞で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39092, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "改善", "is_correct": true, "explanation": "よくなることを表し、悪化の対義語として辞典に挙がる。"}, {"text": "継続", "is_correct": false, "explanation": "続くことを表し、悪化の対義語ではない。"}, {"text": "発生", "is_correct": false, "explanation": "新たに起こることを表し、悪化の対義語ではない。"}, {"text": "維持", "is_correct": false, "explanation": "同じ状態を保つことを表し、悪化の対義語ではない。"}], "correct_answer": "改善", "explanations": {"改善": "よくなることを表し、悪化の対義語として辞典に挙がる。", "継続": "続くことを表し、悪化の対義語ではない。", "発生": "新たに起こることを表し、悪化の対義語ではない。", "維持": "同じ状態を保つことを表し、悪化の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39092, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好転", "is_correct": true, "explanation": "状況がよい方へ向かうことを表し、悪化の対義語として辞典に挙がる。"}, {"text": "進行", "is_correct": false, "explanation": "物事が前へ進むことを表し、悪化の対義語ではない。"}, {"text": "拡大", "is_correct": false, "explanation": "範囲や規模が広がることを表し、悪化の対義語ではない。"}, {"text": "流行", "is_correct": false, "explanation": "広く行われることを表し、悪化の対義語ではない。"}], "correct_answer": "好転", "explanations": {"好転": "状況がよい方へ向かうことを表し、悪化の対義語として辞典に挙がる。", "進行": "物事が前へ進むことを表し、悪化の対義語ではない。", "拡大": "範囲や規模が広がることを表し、悪化の対義語ではない。", "流行": "広く行われることを表し、悪化の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39092, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "わるくなること。", "primary_collocate": null, "pronunciation": "あっか", "ipa": "akka", "syllable_count": 3, "sentences": [{"text": "風邪を放っておいたら、病気が悪化した。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "風邪(かぜ)を放(ほう)っておいたら、病気(びょうき)が悪化(あっか)した。", "sentence_source": "generated"}, {"text": "雨が強くなり、道路の状態が悪化している。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "雨(あめ)が強(つよ)くなり、道路(どうろ)の状態(じょうたい)が悪化(あっか)している。", "sentence_source": "generated"}, {"text": "薬をやめたせいで、体の調子が悪化した。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "薬(くすり)をやめたせいで、体(からだ)の調子(ちょうし)が悪化(あっか)した。", "sentence_source": "generated"}, {"text": "天気の悪化で、試合は中止になった。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "天気(てんき)の悪化(あっか)で、試合(しあい)は中止(ちゅうし)になった。", "sentence_source": "generated"}, {"text": "けんかのあと、二人の仲は悪化する一方だ。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "けんかのあと、二人(ふたり)の仲(なか)は悪化(あっか)する一方(いっぽう)だ。", "sentence_source": "generated"}, {"text": "悪化を防ぐために、早めに医者に行こう。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "悪化(あっか)を防(ふせ)ぐために、早(はや)めに医者(いしゃ)に行(い)こう。", "sentence_source": "generated"}, {"text": "部屋が寒すぎて、せきが悪化してしまった。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "部屋(へや)が寒(さむ)すぎて、せきが悪化(あっか)してしまった。", "sentence_source": "generated"}, {"text": "景気が悪化して、店を閉める会社が増えた。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "景気(けいき)が悪化(あっか)して、店(みせ)を閉(し)める会社(かいしゃ)が増(ふ)えた。", "sentence_source": "generated"}, {"text": "夜ふかしを続けると、目の病気が悪化するそうだ。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "夜(よる)ふかしを続(つづ)けると、目(め)の病気(びょうき)が悪化(あっか)するそうだ。", "sentence_source": "generated"}, {"text": "交通事故のあと、父の足の痛みは悪化した。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "交通(こうつう)事故(じこ)のあと、父(ちち)の足(あし)の痛(いた)みは悪化(あっか)した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "悪化", "label": "基本形"}, {"form": "悪化する", "label": "終止形"}, {"form": "悪化した", "label": "過去形"}, {"form": "悪化して", "label": "て形"}, {"form": "悪化している", "label": "継続形"}], "register": "中立(普通体)", "sense_fingerprint": "病気・体調・天気・仲など身近なものが前よりわるくなること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd49ee28-674e-431e-aee3-ee814a8995c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39092, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悪化", "is_correct": true, "explanation": "「病気が悪化した」で、状態がわるくなることを表す。"}, {"text": "解散", "is_correct": false, "explanation": "「病気が解散した」は成り立たない。解散は団体がまとまりをやめること。"}, {"text": "放置", "is_correct": false, "explanation": "「病気が放置した」は意味が通らない。放置はものや人をそのままにすること。"}, {"text": "逮捕", "is_correct": false, "explanation": "「病気が逮捕した」は成り立たない。逮捕は人を捕らえること。"}], "explanations": {"悪化": "「病気が悪化した」で、状態がわるくなることを表す。", "解散": "「病気が解散した」は成り立たない。解散は団体がまとまりをやめること。", "放置": "「病気が放置した」は意味が通らない。放置はものや人をそのままにすること。", "逮捕": "「病気が逮捕した」は成り立たない。逮捕は人を捕らえること。"}, "sentence_index": 0, "correct_answer": "悪化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人口が悪化した。", "explanation": "ここは〈増加〉の意味。悪化は状態がわるくなることで、数が増えることには使わない。"}, {"text": "工場は悪化を行った。", "explanation": "ここは〈実施〉の意味と混同している。悪化は状態がわるくなることを表す語で、何かを行う動作には使わない。"}, {"text": "この会社は悪化を三社に決めた。", "explanation": "ここは〈選定〉の意味と混同している。悪化は状態がわるくなることを表す語で、会社を選ぶ動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39092, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悪化", "is_correct": true, "explanation": "「せきが悪化してしまった」で、症状がわるくなることを表す。"}, {"text": "中断", "is_correct": false, "explanation": "「せきが中断した」は意味が通らない。中断は途中でやめること。"}, {"text": "撤回", "is_correct": false, "explanation": "「せきが撤回した」は成り立たない。撤回は発言や決定を取り消すこと。"}, {"text": "延期", "is_correct": false, "explanation": "「せきが延期した」は不自然。延期は予定の日を後にずらすこと。"}], "explanations": {"悪化": "「せきが悪化してしまった」で、症状がわるくなることを表す。", "中断": "「せきが中断した」は意味が通らない。中断は途中でやめること。", "撤回": "「せきが撤回した」は成り立たない。撤回は発言や決定を取り消すこと。", "延期": "「せきが延期した」は不自然。延期は予定の日を後にずらすこと。"}, "sentence_index": 6, "correct_answer": "悪化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の時間が悪化した。", "explanation": "ここは〈延長〉の意味。悪化は状態がわるくなることで、時間を長くすることには使わない。"}, {"text": "この駅は悪化が便利で、人が集まる。", "explanation": "ここは〈便利〉の意味と混同している。悪化は状態がわるくなることを表す語で、駅の利便性には使わない。"}, {"text": "賞が悪化した。", "explanation": "ここは〈授与〉の意味。悪化は状態がわるくなることで、賞を渡すことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39092, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天候が悪化すので、船は出られない。", "corrected_sentence": "天候が悪化するので、船は出られない。", "error_description": "「悪化」の後は「する」（または「した」）が続く。「悪化すので」は活用が誤りで、「悪化するので」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39092, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父の病気が悪化を、入院が長引いた。", "corrected_sentence": "父の病気が悪化して、入院が長引いた。", "error_description": "「悪化」の後は「して」で続けて因果を表す。「悪化を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39093, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好転", "is_correct": true, "explanation": "「好転」は「悪化」の対義語として辞典に載る。悪い方向から良い方向へ向かう意味で、この意味と対になる。"}, {"text": "増加", "is_correct": false, "explanation": "「増加」は数が増える意味で、悪化の対義語ではない。"}, {"text": "完成", "is_correct": false, "explanation": "「完成」は仕事や品物が仕上がる意味で、悪化と対になる関係ではない。"}, {"text": "発見", "is_correct": false, "explanation": "「発見」は見つけることで、状態の良し悪しを表す語ではない。"}], "correct_answer": "好転", "explanations": {"好転": "「好転」は「悪化」の対義語として辞典に載る。悪い方向から良い方向へ向かう意味で、この意味と対になる。", "増加": "「増加」は数が増える意味で、悪化の対義語ではない。", "完成": "「完成」は仕事や品物が仕上がる意味で、悪化と対になる関係ではない。", "発見": "「発見」は見つけることで、状態の良し悪しを表す語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
