INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39093, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "状態や事態が、以前よりもっと悪い方向に進むこと。", "primary_collocate": null, "pronunciation": "あっか", "ipa": "akka", "syllable_count": 3, "sentences": [{"text": "両国の関係が悪化して、貿易が止まった。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "両国(りょうこく)の関係(かんけい)が悪化(あっか)して、貿易(ぼうえき)が止(と)まった。", "sentence_source": "generated"}, {"text": "川の水が汚れ、環境の悪化が問題になっている。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "川(かわ)の水(みず)が汚(よご)れ、環境(かんきょう)の悪化(あっか)が問題(もんだい)になっている。", "sentence_source": "generated"}, {"text": "事態はさらに悪化しているので、すぐ対策が必要だ。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "事態(じたい)はさらに悪化(あっか)しているので、すぐ対策(たいさく)が必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "経済の悪化で、仕事を失う人が増えた。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "経済(けいざい)の悪化(あっか)で、仕事(しごと)を失(うしな)う人(ひと)が増(ふ)えた。", "sentence_source": "generated"}, {"text": "台風が近づき、海の状態が急速に悪化した。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "台風(たいふう)が近(ちか)づき、海(うみ)の状態(じょうたい)が急速(きゅうそく)に悪化(あっか)した。", "sentence_source": "generated"}, {"text": "会社の状況が悪化する前に、社長は計画を変えた。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "会社(かいしゃ)の状況(じょうきょう)が悪化(あっか)する前(まえ)に、社長(しゃちょう)は計画(けいかく)を変(か)えた。", "sentence_source": "generated"}, {"text": "病気ではなく、職場の人間関係が悪化したのが原因だ。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "病気(びょうき)ではなく、職場(しょくば)の人間(にんげん)関係(かんけい)が悪化(あっか)したのが原因(げんいん)だ。", "sentence_source": "generated"}, {"text": "説明が足りなかったため、客との関係が悪化した。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "説明(せつめい)が足(た)りなかったため、客(きゃく)との関係(かんけい)が悪化(あっか)した。", "sentence_source": "generated"}, {"text": "治安が悪化した町から、多くの人が引っ越した。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "治安(ちあん)が悪化(あっか)した町(まち)から、多(おお)くの人(ひと)が引(ひ)っ越(こ)した。", "sentence_source": "generated"}, {"text": "悪化を止めるには、原因を早く見つけることだ。", "target_word": "悪化", "complexity_tier": "T3", "furigana": "悪化(あっか)を止(と)めるには、原因(げんいん)を早(はや)く見(み)つけることだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "悪化", "label": "基本形"}, {"form": "悪化する", "label": "終止形"}, {"form": "悪化した", "label": "過去形"}, {"form": "悪化して", "label": "て形"}, {"form": "悪化している", "label": "継続形"}], "register": "中立(普通体)", "sense_fingerprint": "関係・経済・環境・治安など社会的な状態や事態が、以前より悪い方向へ進むこと。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd49ee28-674e-431e-aee3-ee814a8995c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39093, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悪化", "is_correct": true, "explanation": "「関係が悪化して、貿易が止まった」と自然につながる。以前より悪い方向に進む意味で、ここに入る。"}, {"text": "発行", "is_correct": false, "explanation": "発行は証明書や紙幣などを出す意味で、「関係が発行して」は成り立たない。"}, {"text": "収集", "is_correct": false, "explanation": "収集は物や情報を集める意味で、人間関係を対象にしても文が通じない。"}, {"text": "集計", "is_correct": false, "explanation": "集計は数値をまとめる意味で、両国の関係を対象にできない。"}], "explanations": {"悪化": "「関係が悪化して、貿易が止まった」と自然につながる。以前より悪い方向に進む意味で、ここに入る。", "発行": "発行は証明書や紙幣などを出す意味で、「関係が発行して」は成り立たない。", "収集": "収集は物や情報を集める意味で、人間関係を対象にしても文が通じない。", "集計": "集計は数値をまとめる意味で、両国の関係を対象にできない。"}, "sentence_index": 0, "correct_answer": "悪化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "洗濯機が悪化して、水が出なくなった。", "explanation": "ここは〈故障〉の意味。機械が急に動かなくなる場合は故障と言い、悪化は状態が次第に悪くなることに使う。"}, {"text": "この新しい製品には、設計の悪化が見つかった。", "explanation": "ここは〈欠陥〉の意味。製品に最初からある欠点は欠陥と言い、悪化は時間とともに進む状態の変化に使う。"}, {"text": "地震でダムが悪化し、村が流された。", "explanation": "ここは〈決壊〉の意味。ダムが壊れて水が溢れる場合は決壊と言い、悪化は少しずつ悪くなる状態に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39093, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悪化", "is_correct": true, "explanation": "「人間関係が悪化したのが原因だ」で、関係が悪い方向に進んだことを表す。ここに入る。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案に点数をつける意味で、人間関係には使えない。"}, {"text": "輸入", "is_correct": false, "explanation": "輸入は外国から品物を取り入れる意味で、人間関係とは組み合わない。"}, {"text": "製造", "is_correct": false, "explanation": "製造は品物を作る意味で、人間関係を対象にすると文が通じない。"}], "explanations": {"悪化": "「人間関係が悪化したのが原因だ」で、関係が悪い方向に進んだことを表す。ここに入る。", "採点": "採点は答案に点数をつける意味で、人間関係には使えない。", "輸入": "輸入は外国から品物を取り入れる意味で、人間関係とは組み合わない。", "製造": "製造は品物を作る意味で、人間関係を対象にすると文が通じない。"}, "sentence_index": 6, "correct_answer": "悪化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "パンの悪化を防ぐため、冷凍庫に入れた。", "explanation": "ここは〈劣化〉の意味。品質が落ちる変化には劣化を使い、悪化とは言わない。"}, {"text": "ファイルが悪化して、開けなくなった。", "explanation": "ここは〈破損〉の意味。データが壊れて使えなくなる場合は破損と言い、悪化とは言わない。"}, {"text": "牛乳が悪化したので、すべて捨てた。", "explanation": "ここは〈腐敗〉の意味。食品が菌によって傷むことには腐敗を使い、悪化とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39093, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "経済が悪化で、仕事を失う人が増えた。", "corrected_sentence": "経済が悪化して、仕事を失う人が増えた。", "error_description": "「経済が悪化で」は、名詞の「悪化」に主語の「が」を付けて「で」で続けた形で誤り。動詞として使うなら「悪化して」、名詞として使うなら「経済の悪化で」にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39093, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "職場の人間関係が悪化されたため、仕事が進まなかった。", "corrected_sentence": "職場の人間関係が悪化したため、仕事が進まなかった。", "error_description": "「悪化」は自分で変化する意味で、受身の「悪化される」は不自然。過去の形は「悪化した」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39096, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「次の工程に進む」の「に」。進んでいく先を表し、文として自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すので、「次の工程で進む」は進む先を示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や共同を表すので、「次の工程と進む」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ働きで、「次の工程の進む前に」は動詞を名詞のように続けられない。"}], "correct_answer": "に", "explanations": {"に": "「次の工程に進む」の「に」。進んでいく先を表し、文として自然。", "で": "「で」は手段や場所を表すので、「次の工程で進む」は進む先を示せず不自然。", "と": "「と」は相手や共同を表すので、「次の工程と進む」は成り立たない。", "の": "「の」は名詞をつなぐ働きで、「次の工程の進む前に」は動詞を名詞のように続けられない。"}, "error_tags": {"で": "手段・場所", "と": "相手・共同", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39096, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「工程を見直す」の「を」。見直す対象を表し、文として自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「工程が見直した」は見直す人が誰かを示せず成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「工程へ見直した」は見直す対象を示せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すので、「工程より見直した」は比べる対象がなく意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「工程を見直す」の「を」。見直す対象を表し、文として自然。", "が": "「が」は主語を示すので、「工程が見直した」は見直す人が誰かを示せず成り立たない。", "へ": "「へ」は方向を表すので、「工程へ見直した」は見直す対象を示せず不自然。", "より": "「より」は比較を表すので、「工程より見直した」は比べる対象がなく意味が通らない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39096, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものを作るときの、一つ一つの作業の順番のことです。", "primary_collocate": null, "pronunciation": "こうてい", "ipa": "koːteː", "syllable_count": 4, "sentences": [{"text": "この工場では、パンを作る工程が全部で五つあります。", "target_word": "工程", "complexity_tier": "T3", "furigana": "この工場(こうじょう)では、パンを作(つく)る工程(こうてい)が全部(ぜんぶ)で五(いつ)つあります。", "sentence_source": "generated"}, {"text": "次の工程に進む前に、部品をよく洗います。", "target_word": "工程", "complexity_tier": "T3", "furigana": "次(つぎ)の工程(こうてい)に進(すす)む前(まえ)に、部品(ぶひん)をよく洗(あら)います。", "sentence_source": "generated"}, {"text": "工程が多いので、一つの製品を作るのに三日かかります。", "target_word": "工程", "complexity_tier": "T3", "furigana": "工程(こうてい)が多(おお)いので、一(ひと)つの製品(せいひん)を作(つく)るのに三日(みっか)かかります。", "sentence_source": "generated"}, {"text": "最後の工程で、できあがった品物の検査をします。", "target_word": "工程", "complexity_tier": "T3", "furigana": "最後(さいご)の工程(こうてい)で、できあがった品物(しなもの)の検査(けんさ)をします。", "sentence_source": "generated"}, {"text": "私は、紙を切る工程を担当しています。", "target_word": "工程", "complexity_tier": "T3", "furigana": "私(わたし)は、紙(かみ)を切(き)る工程(こうてい)を担当(たんとう)しています。", "sentence_source": "generated"}, {"text": "工程の順番をまちがえると、きれいに仕上がりません。", "target_word": "工程", "complexity_tier": "T3", "furigana": "工程(こうてい)の順番(じゅんばん)をまちがえると、きれいに仕上(しあ)がりません。", "sentence_source": "generated"}, {"text": "茶碗は、土をこねる工程からすべて手作業です。", "target_word": "工程", "complexity_tier": "T3", "furigana": "茶碗(ちゃわん)は、土(つち)をこねる工程(こうてい)からすべて手作業(てさぎょう)です。", "sentence_source": "generated"}, {"text": "工程を見直したので、作業の時間が半分になりました。", "target_word": "工程", "complexity_tier": "T3", "furigana": "工程(こうてい)を見直(みなお)したので、作業(さぎょう)の時間(じかん)が半分(はんぶん)になりました。", "sentence_source": "generated"}, {"text": "ここでは、色をつける工程だけを機械が行います。", "target_word": "工程", "complexity_tier": "T3", "furigana": "ここでは、色(いろ)をつける工程(こうてい)だけを機械(きかい)が行(おこな)います。", "sentence_source": "generated"}, {"text": "見学では、お菓子ができるまでの工程を見られます。", "target_word": "工程", "complexity_tier": "T3", "furigana": "見学(けんがく)では、お菓子(かし)ができるまでの工程(こうてい)を見(み)られます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "工程", "label": "基本形"}, {"form": "工程の", "label": "連体修飾形"}], "register": "中立（丁寧体）", "sense_fingerprint": "製品を作る過程を構成する段階的な作業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: まちがえる (Zipf 1.77)']::text[], 'eab72206-6277-420c-88d0-f9c8f74db76f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39096, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工程", "is_correct": true, "explanation": "製造の段階を数えるので、「工程が全部で五つある」と自然につながる。"}, {"text": "香り", "is_correct": false, "explanation": "香りはできあがった製品の性質で、作る段階の数には当たらないので「作る香りが五つ」は成り立たない。"}, {"text": "色", "is_correct": false, "explanation": "色は仕上がりの性質で、作業の段階として数える語ではないので合わない。"}, {"text": "感触", "is_correct": false, "explanation": "感触は触ったときの印象で、作業の順番や段階として数えられないので合わない。"}], "explanations": {"工程": "製造の段階を数えるので、「工程が全部で五つある」と自然につながる。", "香り": "香りはできあがった製品の性質で、作る段階の数には当たらないので「作る香りが五つ」は成り立たない。", "色": "色は仕上がりの性質で、作業の段階として数える語ではないので合わない。", "感触": "感触は触ったときの印象で、作業の順番や段階として数えられないので合わない。"}, "sentence_index": 0, "correct_answer": "工程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "東京から京都までの工程は、新幹線でおよそ二時間半です。", "explanation": "ここは〈行程〉（移動の道のりや所要時間）の意味。工程は作業の段階なので、移動の距離や時間には使えない。"}, {"text": "大学の四年間は、社会人になるまでの工程でした。", "explanation": "ここは〈過程〉（変化や成長の進み方）の意味。工程は製造の段階を指すので、人の成長には使わない。"}, {"text": "この町には、大きな工程がたくさんあります。", "explanation": "ここは〈工場〉（作業を行う施設）の意味。工程は作業の段階なので、建物を数える言い方には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39096, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工程", "is_correct": true, "explanation": "作業の段階の始まりを表し、「土をこねる工程からすべて手作業」と自然につながる。"}, {"text": "名前", "is_correct": false, "explanation": "名前は呼び名で、作業の段階を表さないので「土をこねる名前から」は意味が通らない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは物の性質で、作業の始まりを示す語ではないので「土をこねる重さから」は成り立たない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格で、作業の段階を表さないので「土をこねる値段から」は意味が通らない。"}], "explanations": {"工程": "作業の段階の始まりを表し、「土をこねる工程からすべて手作業」と自然につながる。", "名前": "名前は呼び名で、作業の段階を表さないので「土をこねる名前から」は意味が通らない。", "重さ": "重さは物の性質で、作業の始まりを示す語ではないので「土をこねる重さから」は成り立たない。", "値段": "値段は価格で、作業の段階を表さないので「土をこねる値段から」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "工程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客を喜ばせるために、この店は工程を凝らしています。", "explanation": "ここは〈工夫〉（うまくやるための知恵や工夫）の意味。工程は作業の段階なので、知恵や工夫の意味では使えない。"}, {"text": "私の工程は、毎朝六時に起きることです。", "explanation": "ここは〈日課〉の意味。工程は製造などの作業の段階を指すので、毎朝の習慣には使わない。"}, {"text": "彼は大学院の工程を修了して、研究所に入りました。", "explanation": "ここは〈課程〉（学校などで定められた学びの段階）の意味。工程は作業の段階なので、大学院の課程の修了には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39096, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "機械は、この工程を部品を切ります。", "corrected_sentence": "機械は、この工程で部品を切ります。", "error_description": "「この工程で」（手段・場所の「で」）が正しい。「工程を」にすると「工程」が目的語になり、後ろの「部品を」と目的語が二つ並んで文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39096, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この工程を終えるたら、部品を箱に入れます。", "corrected_sentence": "この工程を終えたら、部品を箱に入れます。", "error_description": "「終えたら」が正しい。「終えるたら」は動詞「終える」の活用の誤りで、「終えた」の形にして「ら」をつける必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
