INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39098, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「水で流した」で、手段として水を使ったことを示す格助詞。"}, {"text": "から", "is_correct": false, "explanation": "「水から流した」は起点の意味になり、洗い流す手段として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「水の流した」は名詞を修飾する形で、動詞の文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「絵の具を水を流した」は二つの対象が重なり、文として不自然。"}], "correct_answer": "で", "explanations": {"で": "「水で流した」で、手段として水を使ったことを示す格助詞。", "から": "「水から流した」は起点の意味になり、洗い流す手段として成り立たない。", "の": "「水の流した」は名詞を修飾する形で、動詞の文として成り立たない。", "を": "「絵の具を水を流した」は二つの対象が重なり、文として不自然。"}, "error_tags": {"から": "起点", "の": "連体修飾", "を": "目的語の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39098, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "水や湯を、ある場所から別の場所へ動かして行かせること。", "primary_collocate": null, "pronunciation": "ながす", "ipa": "naɡasɯ", "syllable_count": 3, "sentences": [{"text": "汚れた水をそのまま川に流してはいけない。", "target_word": "流して", "complexity_tier": "T3", "furigana": "汚(よご)れた水(みず)をそのまま川(かわ)に流(なが)してはいけない。", "sentence_source": "generated"}, {"text": "トイレを使ったあと、水を流す。", "target_word": "流す", "complexity_tier": "T3", "furigana": "トイレを使(つか)ったあと、水(みず)を流(なが)す。", "sentence_source": "generated"}, {"text": "雨水を庭の外に流すために、みぞを掘った。", "target_word": "流す", "complexity_tier": "T3", "furigana": "雨水(あまみず)を庭(にわ)の外(そと)に流(なが)すために、みぞを掘(ほ)った。", "sentence_source": "generated"}, {"text": "皿の泡を、水道の水で流した。", "target_word": "流した", "complexity_tier": "T3", "furigana": "皿(さら)の泡(あわ)を、水道(すいどう)の水(みず)で流(なが)した。", "sentence_source": "generated"}, {"text": "田んぼの水を川へ流して、土をかわかした。", "target_word": "流して", "complexity_tier": "T3", "furigana": "田(た)んぼの水(みず)を川(かわ)へ流(なが)して、土(つち)をかわかした。", "sentence_source": "generated"}, {"text": "パスタをゆでた湯を、排水口へ流した。", "target_word": "流した", "complexity_tier": "T3", "furigana": "パスタをゆでた湯(ゆ)を、排水口(はいすいこう)へ流(なが)した。", "sentence_source": "generated"}, {"text": "汗を流すために、プールのあとでシャワーを浴びた。", "target_word": "流す", "complexity_tier": "T3", "furigana": "汗(あせ)を流(なが)すために、プールのあとでシャワーを浴(あ)びた。", "sentence_source": "generated"}, {"text": "筆についた絵の具を水で流した。", "target_word": "流した", "complexity_tier": "T3", "furigana": "筆(ふで)についた絵(え)の具(ぐ)を水(みず)で流(なが)した。", "sentence_source": "generated"}, {"text": "庭の泥を、ホースの水で流しておいた。", "target_word": "流して", "complexity_tier": "T3", "furigana": "庭(にわ)の泥(どろ)を、ホースの水(みず)で流(なが)しておいた。", "sentence_source": "generated"}, {"text": "川の水を畑へ流す工事が、来月から始まる。", "target_word": "流す", "complexity_tier": "T3", "furigana": "川(かわ)の水(みず)を畑(はたけ)へ流(なが)す工事(こうじ)が、来月(らいげつ)から始(はじ)まる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "流す", "label": "終止形"}, {"form": "流さない", "label": "否定形"}, {"form": "流します", "label": "丁寧形"}, {"form": "流して", "label": "て形"}, {"form": "流した", "label": "過去形"}, {"form": "流せば", "label": "仮定形"}, {"form": "流そう", "label": "意向形"}, {"form": "流せる", "label": "可能形"}], "register": "中立(普通体)", "sense_fingerprint": "水や湯を川・排水口・外などへ動かして行かせる。トイレや汚れを水で流すこと。音楽や涙の意味ではない。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: かわかし (Zipf 1.27)']::text[], 'fd49ee28-674e-431e-aee3-ee814a8995c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39098, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流して", "is_correct": true, "explanation": "「流してはいけない」で、汚れた水を川に流すことを禁じる文になる。"}, {"text": "干して", "is_correct": false, "explanation": "川に干すという行為は意味が成り立たない。"}, {"text": "磨いて", "is_correct": false, "explanation": "川を磨く行為は文脈に合わず、汚れた水を川に入れる意味にならない。"}, {"text": "乾かして", "is_correct": false, "explanation": "川を乾かすという意味になり、汚れた水を川へ入れる禁止の文にならない。"}], "explanations": {"流して": "「流してはいけない」で、汚れた水を川に流すことを禁じる文になる。", "干して": "川に干すという行為は意味が成り立たない。", "磨いて": "川を磨く行為は文脈に合わず、汚れた水を川に入れる意味にならない。", "乾かして": "川を乾かすという意味になり、汚れた水を川へ入れる禁止の文にならない。"}, "sentence_index": 0, "correct_answer": "流して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもが紙飛行機を流して、公園で遊んだ。", "explanation": "ここは〈飛ばす〉の意味。紙飛行機を空中で進ませる場合は飛ばすと言い、流すとは言わない。"}, {"text": "駅で別れるとき、友人に手を流した。", "explanation": "ここは〈振る〉の意味。手を左右に動かして合図する場合は振ると言い、流すとは言わない。"}, {"text": "引っ越しの荷物を、トラックで流した。", "explanation": "ここは〈運ぶ〉の意味。荷物を車で移す場合は運ぶと言い、流すとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39098, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流す", "is_correct": true, "explanation": "「汗を流すために、シャワーを浴びた」で、汗を洗い落とす意味になる。"}, {"text": "数える", "is_correct": false, "explanation": "「汗を数えるために」は意味が成り立たない。"}, {"text": "見つける", "is_correct": false, "explanation": "「汗を見つけるために」は目的として不自然で、文脈に合わない。"}, {"text": "眺める", "is_correct": false, "explanation": "「汗を眺めるために」は意味が通じない。"}], "explanations": {"流す": "「汗を流すために、シャワーを浴びた」で、汗を洗い落とす意味になる。", "数える": "「汗を数えるために」は意味が成り立たない。", "見つける": "「汗を見つけるために」は目的として不自然で、文脈に合わない。", "眺める": "「汗を眺めるために」は意味が通じない。"}, "sentence_index": 6, "correct_answer": "流す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コップに麦茶を流して、一気に飲んだ。", "explanation": "ここは〈注ぐ〉の意味。飲み物を容器に入れる場合は注ぐと言い、流すとは言わない。"}, {"text": "疲れた顔で、ため息を流した。", "explanation": "ここは〈吐く〉の意味。息を外へ出す場合は吐くと言い、流すとは言わない。"}, {"text": "友人に手紙を流した。", "explanation": "ここは〈送る〉の意味。手紙を相手に届ける場合は送ると言い、流すとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39098, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汚れた水をそのまま排水口に流したはいけない。", "corrected_sentence": "汚れた水をそのまま排水口に流してはいけない。", "error_description": "「〜てはいけない」には過去形の「した」ではなく、て形の「して」を続ける。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "流す", "is_correct": true, "explanation": "「水を流す」で、トイレを使ったあとに水を流す動作を表す終止形。"}, {"text": "流し", "is_correct": false, "explanation": "連用形のため、文を終えられず、ここでは不完全な形になる。"}, {"text": "流せば", "is_correct": false, "explanation": "仮定形のため、文を終えられず、ここでは不完全な形になる。"}, {"text": "流さ", "is_correct": false, "explanation": "未然形のため、文を終えられず、ここでは不完全な形になる。"}], "correct_form": "流す", "base_form": "流す", "form_label": "終止形", "sentence_index": 1, "explanations": {"流す": "「水を流す」で、トイレを使ったあとに水を流す動作を表す終止形。", "流し": "連用形のため、文を終えられず、ここでは不完全な形になる。", "流せば": "仮定形のため、文を終えられず、ここでは不完全な形になる。", "流さ": "未然形のため、文を終えられず、ここでは不完全な形になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39098, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汗を流しために、シャワーを浴びた。", "corrected_sentence": "汗を流すために、シャワーを浴びた。", "error_description": "「ために」の前は動詞の終止形の「流す」にする。連用形の「流し」は続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "流した", "is_correct": true, "explanation": "「水で流した」で、絵の具を洗い流した過去の動作を表す。"}, {"text": "流して", "is_correct": false, "explanation": "て形のため、文を終えられず、ここでは不完全な形になる。"}, {"text": "流させ", "is_correct": false, "explanation": "使役の連用形のため、文を終えられず、ここでは不完全な形になる。"}, {"text": "流しながら", "is_correct": false, "explanation": "「ながら」の形のため、文を終えられず、ここでは不完全な形になる。"}], "correct_form": "流した", "base_form": "流す", "form_label": "過去形", "sentence_index": 7, "explanations": {"流した": "「水で流した」で、絵の具を洗い流した過去の動作を表す。", "流して": "て形のため、文を終えられず、ここでは不完全な形になる。", "流させ": "使役の連用形のため、文を終えられず、ここでは不完全な形になる。", "流しながら": "「ながら」の形のため、文を終えられず、ここでは不完全な形になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39099, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「水をたっぷり流した」で、流す対象の水を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「水がたっぷり流した」は動作の対象を示せず、文として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「水にたっぷり流した」は方向や相手の意味になり、対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「水とたっぷり流した」は共同の意味になり、対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「水をたっぷり流した」で、流す対象の水を示す格助詞。", "が": "「水がたっぷり流した」は動作の対象を示せず、文として不自然。", "に": "「水にたっぷり流した」は方向や相手の意味になり、対象を示せない。", "と": "「水とたっぷり流した」は共同の意味になり、対象として成り立たない。"}, "error_tags": {"が": "主語", "に": "帰着・相手", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39099, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「地面へ流す」で、雨水の移動先を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「地面を流す」は地面を動かす意味になり、移動先を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「地面の流す」は名詞を修飾する形で、動詞の文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「地面から流す」は起点の意味になり、流す先を示せない。"}], "correct_answer": "へ", "explanations": {"へ": "「地面へ流す」で、雨水の移動先を示す格助詞。", "を": "「地面を流す」は地面を動かす意味になり、移動先を示せない。", "の": "「地面の流す」は名詞を修飾する形で、動詞の文として成り立たない。", "から": "「地面から流す」は起点の意味になり、流す先を示せない。"}, "error_tags": {"を": "目的語の格", "の": "連体修飾", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39099, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "液体を、ある場所から別の場所へ移動させること。また、液体が自然に移動すること。", "primary_collocate": null, "pronunciation": "ながす", "ipa": "naɡasɯ", "syllable_count": 3, "sentences": [{"text": "お風呂のお湯を流して、そうじをする。", "target_word": "流して", "complexity_tier": "T3", "furigana": "お風呂(ふろ)のお湯(ゆ)を流(なが)して、そうじをする。", "sentence_source": "generated"}, {"text": "洗剤が残らないよう、水をたっぷり流した。", "target_word": "流した", "complexity_tier": "T3", "furigana": "洗剤(せんざい)が残(のこ)らないよう、水(みず)をたっぷり流(なが)した。", "sentence_source": "generated"}, {"text": "油を流さないで、紙でふいてから洗いなさい。", "target_word": "流さないで", "complexity_tier": "T3", "furigana": "油(あぶら)を流(なが)さないで、紙(かみ)でふいてから洗(あら)いなさい。", "sentence_source": "generated"}, {"text": "洗濯機は、汚れた水を外へ流す仕組みになっている。", "target_word": "流す", "complexity_tier": "T3", "furigana": "洗濯機(せんたくき)は、汚(よご)れた水(みず)を外(そと)へ流(なが)す仕組(しく)みになっている。", "sentence_source": "generated"}, {"text": "工場は、きれいにした水だけを川に流している。", "target_word": "流している", "complexity_tier": "T3", "furigana": "工場(こうじょう)は、きれいにした水(みず)だけを川(かわ)に流(なが)している。", "sentence_source": "generated"}, {"text": "髪についたシャンプーを、ぬるま湯で流した。", "target_word": "流した", "complexity_tier": "T3", "furigana": "髪(かみ)についたシャンプーを、ぬるま湯(ゆ)で流(なが)した。", "sentence_source": "generated"}, {"text": "雪がとけた水を、溝からゆっくり流す。", "target_word": "流す", "complexity_tier": "T3", "furigana": "雪(ゆき)がとけた水(みず)を、溝(みぞ)からゆっくり流(なが)す。", "sentence_source": "generated"}, {"text": "雨どいは、屋根の雨水を地面へ流す道具だ。", "target_word": "流す", "complexity_tier": "T3", "furigana": "雨(あま)どいは、屋根(やね)の雨水(あまみず)を地面(じめん)へ流(なが)す道具(どうぐ)だ。", "sentence_source": "generated"}, {"text": "魚をさばいたあと、血を水で流しておく。", "target_word": "流して", "complexity_tier": "T3", "furigana": "魚(さかな)をさばいたあと、血(ち)を水(みず)で流(なが)しておく。", "sentence_source": "generated"}, {"text": "川は、山の水を海まで流している。", "target_word": "流している", "complexity_tier": "T3", "furigana": "川(かわ)は、山(やま)の水(みず)を海(うみ)まで流(なが)している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "流す", "label": "終止形"}, {"form": "流さない", "label": "否定形"}, {"form": "流します", "label": "丁寧形"}, {"form": "流して", "label": "て形"}, {"form": "流した", "label": "過去形"}, {"form": "流せば", "label": "仮定形"}, {"form": "流そう", "label": "意向形"}, {"form": "流せる", "label": "可能形"}], "register": "中立(普通体)", "sense_fingerprint": "お湯・油・血・雨水などの液体を、人や仕組みが別の場所へ移す。洗い落とす・排水する場面。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd49ee28-674e-431e-aee3-ee814a8995c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39099, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流して", "is_correct": true, "explanation": "「お風呂のお湯を流して、そうじをする」で、お湯を流してから掃除する順序を表す。"}, {"text": "眺めて", "is_correct": false, "explanation": "お湯を眺めてからそうじをする文脈にはならない。"}, {"text": "数えて", "is_correct": false, "explanation": "お湯を数えるという行為は文脈に合わない。"}, {"text": "結んで", "is_correct": false, "explanation": "お湯を結ぶという行為は意味が成り立たない。"}], "explanations": {"流して": "「お風呂のお湯を流して、そうじをする」で、お湯を流してから掃除する順序を表す。", "眺めて": "お湯を眺めてからそうじをする文脈にはならない。", "数えて": "お湯を数えるという行為は文脈に合わない。", "結んで": "お湯を結ぶという行為は意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "流して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬の夜、空から雪を流して、町を白くした。", "explanation": "ここは〈降らせる〉の意味。空から雪や雨を降らせる場合は降らせると言い、流すとは言わない。"}, {"text": "ネジを流して、棚をしっかり固定した。", "explanation": "ここは〈締める〉の意味。ネジを回して固定する場合は締めると言い、流すとは言わない。"}, {"text": "警備システムは、不審者を外へ流す仕組みになっている。", "explanation": "ここは〈追い出す〉の意味。人を外へ出す場合は追い出すと言い、流すとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39099, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流す", "is_correct": true, "explanation": "「雪がとけた水を、溝からゆっくり流す」で、水を溝に移す動作を表す。"}, {"text": "磨く", "is_correct": false, "explanation": "水を溝から磨く行為は文脈に合わない。"}, {"text": "編む", "is_correct": false, "explanation": "水を編むという行為は意味が成り立たない。"}, {"text": "叩く", "is_correct": false, "explanation": "水を溝から叩くという意味は文脈に合わない。"}], "explanations": {"流す": "「雪がとけた水を、溝からゆっくり流す」で、水を溝に移す動作を表す。", "磨く": "水を溝から磨く行為は文脈に合わない。", "編む": "水を編むという行為は意味が成り立たない。", "叩く": "水を溝から叩くという意味は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "流す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "やかんの湯を、湯飲みへ流して注いだ。", "explanation": "ここは〈注ぐ〉の意味。液体を容器に入れる場合は注ぐと言い、流すとは言わない。"}, {"text": "エレベーターのボタンを流して、扉を閉めた。", "explanation": "ここは〈押す〉の意味。指で押して操作する場合は押すと言い、流すとは言わない。"}, {"text": "ファイルを本社へ流した。", "explanation": "ここは〈送る〉の意味。データを相手に届ける場合は送ると言い、流すとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39099, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "泡が残らないよう、水がたっぷり流した。", "corrected_sentence": "泡が残らないよう、水をたっぷり流した。", "error_description": "「流す」は水を対象にとるので、水の後ろには「を」を置く。「が」では他動詞の文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "流した", "is_correct": true, "explanation": "「水をたっぷり流した」で、洗い流した過去の動作を表す。"}, {"text": "流し", "is_correct": false, "explanation": "連用形のため、文を終えられず、ここでは不完全な形になる。"}, {"text": "流せば", "is_correct": false, "explanation": "仮定形のため、文を終えられず、ここでは不完全な形になる。"}, {"text": "流さ", "is_correct": false, "explanation": "未然形のため、文を終えられず、ここでは不完全な形になる。"}], "correct_form": "流した", "base_form": "流す", "form_label": "過去形", "sentence_index": 1, "explanations": {"流した": "「水をたっぷり流した」で、洗い流した過去の動作を表す。", "流し": "連用形のため、文を終えられず、ここでは不完全な形になる。", "流せば": "仮定形のため、文を終えられず、ここでは不完全な形になる。", "流さ": "未然形のため、文を終えられず、ここでは不完全な形になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39099, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪解けの水を、溝からゆっくり流さる。", "corrected_sentence": "雪解けの水を、溝からゆっくり流す。", "error_description": "「流す」の終止形は「流す」。「流さる」という形は存在せず、語幹の後ろに余分な活用語尾が付いている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "流す", "is_correct": true, "explanation": "「地面へ流す道具」の形で、道具を修飾する連体形。雨水を地面に移す道具を説明する。"}, {"text": "流して", "is_correct": false, "explanation": "て形のため、名詞を修飾できず、文も成立しない。"}, {"text": "流そう", "is_correct": false, "explanation": "意向形のため、名詞を修飾できず、文も成立しない。"}, {"text": "流させ", "is_correct": false, "explanation": "使役の連用形のため、名詞を修飾できず、文も成立しない。"}], "correct_form": "流す", "base_form": "流す", "form_label": "連体形", "sentence_index": 7, "explanations": {"流す": "「地面へ流す道具」の形で、道具を修飾する連体形。雨水を地面に移す道具を説明する。", "流して": "て形のため、名詞を修飾できず、文も成立しない。", "流そう": "意向形のため、名詞を修飾できず、文も成立しない。", "流させ": "使役の連用形のため、名詞を修飾できず、文も成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c6061-26fe-40f8-97ef-ad8179170cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
