INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39100, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あとにする。先にやることをやってから、あとでやること。", "primary_collocate": null, "pronunciation": "あとまわし", "ipa": "atomawaɕi", "syllable_count": 5, "sentences": [{"text": "先に食事をして、宿題は後回しにした。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "先[さき]に食事[しょくじ]をして、宿題[しゅくだい]は後回し[あとまわし]にした。", "sentence_source": "generated"}, {"text": "今日は会議の資料を先に作って、メールの返信は後回しにした。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "今日[きょう]は会議[かいぎ]の資料[しりょう]を先[さき]に作[つく]って、メールの返信[へんしん]は後回[あとまわ]しにした。", "sentence_source": "generated"}, {"text": "今日は時間がないから、買い物は後回しだ。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "今日[きょう]は時間[じかん]がないから、買い物[かいもの]は後回し[あとまわし]だ。", "sentence_source": "generated"}, {"text": "弟の相談は後回しにして、母の電話に先に出た。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "弟[おとうと]の相談[そうだん]は後回し[あとまわし]にして、母[はは]の電話[でんわ]に先[さき]に出[で]た。", "sentence_source": "generated"}, {"text": "急ぎの用事があるので、掃除は後回しにする。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "急[いそ]ぎの用事[ようじ]があるので、掃除[そうじ]は後回し[あとまわし]にする。", "sentence_source": "generated"}, {"text": "料理の材料を先に買って、洗濯は後回しにした。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "料理[りょうり]の材料[ざいりょう]を先[さき]に買[か]って、洗濯[せんたく]は後回[あとまわ]しにした。", "sentence_source": "generated"}, {"text": "先に重い荷物を運んで、軽いものは後回しにした。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "先[さき]に重[おも]い荷物[にもつ]を運[はこ]んで、軽[かる]いものは後回し[あとまわし]にした。", "sentence_source": "generated"}, {"text": "出張の準備を先に終えて、経費の精算は後回しにした。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "出張[しゅっちょう]の準備[じゅんび]を先[さき]に終[お]えて、経費[けいひ]の精算[せいさん]は後回[あとまわ]しにした。", "sentence_source": "generated"}, {"text": "試験が終わるまで、ゲームは後回しだ。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "試験[しけん]が終[お]わるまで、ゲームは後回し[あとまわし]だ。", "sentence_source": "generated"}, {"text": "急な会議が入って、昼ごはんは後回しになった。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "急[きゅう]な会議[かいぎ]が入[はい]って、昼[ひる]ごはんは後回し[あとまわし]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "後回し", "label": "基本形"}, {"form": "後回しにする", "label": "動詞句（にする）"}, {"form": "後回しにした", "label": "過去形"}, {"form": "後回しだ", "label": "断定形"}], "register": "neutral", "sense_fingerprint": "先にやることを済ませてから、あとでやることにして順番を下げること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8da5f40a-19ae-49fd-abf3-80abdb2562f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39100, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "後回し", "is_correct": true, "explanation": "宿題は後回しにした、と読めば、順番を遅らせる意味で文が通る。"}, {"text": "散歩", "is_correct": false, "explanation": "宿題は散歩にした、では宿題を別の行動に替えたことになり、文が成り立たない。"}, {"text": "洗濯", "is_correct": false, "explanation": "宿題は洗濯にした、は行動の種類が合わず、宿題の扱いとして意味が通らない。"}, {"text": "外出", "is_correct": false, "explanation": "宿題は外出にした、は宿題を外出に変えるという意味になり、文が成り立たない。"}], "explanations": {"後回し": "宿題は後回しにした、と読めば、順番を遅らせる意味で文が通る。", "散歩": "宿題は散歩にした、では宿題を別の行動に替えたことになり、文が成り立たない。", "洗濯": "宿題は洗濯にした、は行動の種類が合わず、宿題の扱いとして意味が通らない。", "外出": "宿題は外出にした、は宿題を外出に変えるという意味になり、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "後回し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "敵に気づかれないよう、彼は建物の後回しへ回り、出口を見張った。", "explanation": "ここは〈裏手〉の意味。後回しは物事を先へ延ばすことで、建物の裏側を指す語ではないので合わない。"}, {"text": "驚いて、彼は一歩後回しした。", "explanation": "ここは〈後ずさり〉の意味。後回しは物事の順番を遅らせることで、体を後ろへ下げる動きには使わないので合わない。"}, {"text": "彼の後回しが、雨の街に消えていった。", "explanation": "ここは〈後ろ姿〉の意味。後回しは物事を先へ延ばすことで、人の背中の姿を表す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39100, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "後回し", "is_correct": true, "explanation": "軽いものは後回しにした、と読めば、順番を遅らせる意味で文が通る。"}, {"text": "散髪", "is_correct": false, "explanation": "軽いものは散髪にした、は物と行動が合わず、文が成り立たない。"}, {"text": "通院", "is_correct": false, "explanation": "軽いものは通院にした、は物を病院へ通わせる意味になり、文が通らない。"}, {"text": "昼寝", "is_correct": false, "explanation": "軽いものは昼寝にした、は物が寝るという意味になり、文が成り立たない。"}], "explanations": {"後回し": "軽いものは後回しにした、と読めば、順番を遅らせる意味で文が通る。", "散髪": "軽いものは散髪にした、は物と行動が合わず、文が成り立たない。", "通院": "軽いものは通院にした、は物を病院へ通わせる意味になり、文が通らない。", "昼寝": "軽いものは昼寝にした、は物が寝るという意味になり、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "後回し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の後回しで、チームが逆転した。", "explanation": "ここは〈後半〉の意味。後回しは順番を遅らせることで、試合の時間の区切りを表す語ではないので合わない。"}, {"text": "彼は会社の後回しがあるので強い。", "explanation": "ここは〈後ろ盾〉の意味。後回しは物事を先送りすることで、支えてくれる人を指すのには使わないので合わない。"}, {"text": "彼は前の選手の後回しを追いかけ、記録を伸ばした。", "explanation": "ここは〈後追い〉の意味。後回しは順番を遅らせることで、前を行く人を追いかける意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39100, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日の準備は後回しを、今日は休もう。", "corrected_sentence": "明日の準備は後回しにして、今日は休もう。", "error_description": "「後回し」は「にする」の形で動詞として使う。「後回しを」と「を」で続けると、名詞に目的語を付けた形となり文が成り立たない。正しくは「後回しにして」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39100, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大事な書類は後回しにできるない。", "corrected_sentence": "大事な書類は後回しにできない。", "error_description": "「できない」が「できるない」となり、誤った形。正しくは「後回しにできない」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39101, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39101, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「後回しにして」の「に」は、後回しを「にする」の形で使う形。宿題を先延ばしにする意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「後回しがして」は「が」が動詞の形に続かず、「にして」の形にならないので不自然。"}, {"text": "より", "is_correct": false, "explanation": "「後回しよりして」は比べる形で、宿題を後回しと比べる意味になり、文が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「後回しとして」は立場を表す形で、宿題が後回しとして扱われるという意味になり、文の流れに合わない。"}], "correct_answer": "に", "explanations": {"に": "「後回しにして」の「に」は、後回しを「にする」の形で使う形。宿題を先延ばしにする意味になる。", "が": "「後回しがして」は「が」が動詞の形に続かず、「にして」の形にならないので不自然。", "より": "「後回しよりして」は比べる形で、宿題を後回しと比べる意味になり、文が通らない。", "と": "「後回しとして」は立場を表す形で、宿題が後回しとして扱われるという意味になり、文の流れに合わない。"}, "error_tags": {"に": "変化の結果", "が": "主語", "より": "比較", "と": "資格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39101, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あとでやろうと思って、今はやらないこと。順番を遅らせること。", "primary_collocate": null, "pronunciation": "あとまわし", "ipa": "atomawaɕi", "syllable_count": 5, "sentences": [{"text": "面倒な書類を後回しにする癖が、なかなか直らない。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "面倒[めんどう]な書類[しょるい]を後回し[あとまわし]にする癖[くせ]が、なかなか直[なお]らない。", "sentence_source": "generated"}, {"text": "歯医者に行くのを後回しにしていたら、痛みがひどくなった。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "歯医者[はいしゃ]に行[い]くのを後回し[あとまわし]にしていたら、痛[いた]みがひどくなった。", "sentence_source": "generated"}, {"text": "明日やろうと思って後回しにしても、仕事は減らない。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "明日[あした]やろうと思[おも]って後回し[あとまわし]にしても、仕事[しごと]は減[へ]らない。", "sentence_source": "generated"}, {"text": "彼は嫌いな勉強をいつも後回しにする。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "彼[かれ]は嫌[きら]いな勉強[べんきょう]をいつも後回し[あとまわし]にする。", "sentence_source": "generated"}, {"text": "後回しにしないで、気づいたときにすぐ返事を書こう。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "後回し[あとまわし]にしないで、気[き]づいたときにすぐ返事[へんじ]を書[か]こう。", "sentence_source": "generated"}, {"text": "部屋の掃除を後回しにしたせいで、足の置き場もない。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "部屋[へや]の掃除[そうじ]を後回し[あとまわし]にしたせいで、足[あし]の置[お]き場[ば]もない。", "sentence_source": "generated"}, {"text": "病院の予約を後回しにするのは、よくない。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "病院[びょういん]の予約[よやく]を後回し[あとまわし]にするのは、よくない。", "sentence_source": "generated"}, {"text": "夏休みの宿題を後回しにして、最後の日に泣いた。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの宿題[しゅくだい]を後回し[あとまわし]にして、最後[さいご]の日[ひ]に泣[な]いた。", "sentence_source": "generated"}, {"text": "面倒なことほど後回しにしたくなる。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "面倒[めんどう]なことほど後回し[あとまわし]にしたくなる。", "sentence_source": "generated"}, {"text": "大事な連絡を後回しにしたため、相手に迷惑をかけた。", "target_word": "後回し", "complexity_tier": "T3", "furigana": "大事[だいじ]な連絡[れんらく]を後回し[あとまわし]にしたため、相手[あいて]に迷惑[めいわく]をかけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "後回し", "label": "基本形"}, {"form": "後回しにする", "label": "動詞句（にする）"}, {"form": "後回しにしない", "label": "否定形"}, {"form": "後回しにしたい", "label": "願望形"}], "register": "neutral", "sense_fingerprint": "あとでやろうと思って、今やるべきことをやらずに先へ延ばすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8da5f40a-19ae-49fd-abf3-80abdb2562f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39101, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "後回し", "is_correct": true, "explanation": "面倒な書類を後回しにする癖、と読めば、先送りする意味で文が通る。"}, {"text": "散歩", "is_correct": false, "explanation": "面倒な書類を散歩にする癖は、書類を散歩に替えるという意味になり、文が成り立たない。"}, {"text": "昼寝", "is_correct": false, "explanation": "面倒な書類を昼寝にする癖は、書類と昼寝が結びつかず、意味が通らない。"}, {"text": "通院", "is_correct": false, "explanation": "面倒な書類を通院にする癖は、書類を病院へ通わせる意味になり、通じない。"}], "explanations": {"後回し": "面倒な書類を後回しにする癖、と読めば、先送りする意味で文が通る。", "散歩": "面倒な書類を散歩にする癖は、書類を散歩に替えるという意味になり、文が成り立たない。", "昼寝": "面倒な書類を昼寝にする癖は、書類と昼寝が結びつかず、意味が通らない。", "通院": "面倒な書類を通院にする癖は、書類を病院へ通わせる意味になり、通じない。"}, "sentence_index": 0, "correct_answer": "後回し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "前の部長が退いたので、彼が後回しとして部長を継いだ。", "explanation": "ここは〈後任〉の意味。後回しは物事を先へ延ばすことで、人の交代を表す語ではないので合わない。"}, {"text": "雨で車が少しずつ後回ししていった。", "explanation": "ここは〈後退〉の意味。後回しは物事を延ばすことで、車が後ろへ下がる動きには使わないので合わない。"}, {"text": "市の後回しで、音楽会が開かれた。", "explanation": "ここは〈後援〉の意味。後回しは物事を先送りすることで、資金や支えを出す意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39101, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "後回し", "is_correct": true, "explanation": "病院の予約を後回しにするのは、よくない、と読めば、先送りが良くないという意味で通る。"}, {"text": "散髪", "is_correct": false, "explanation": "病院の予約を散髪にするのは、予約を散髪に替えるという意味になり、文が通らない。"}, {"text": "買い物", "is_correct": false, "explanation": "病院の予約を買い物にするのは、予約の対象が変わり、文として意味が通らない。"}, {"text": "読書", "is_correct": false, "explanation": "病院の予約を読書にするのは、予約と読書がつながらず、文が成り立たない。"}], "explanations": {"後回し": "病院の予約を後回しにするのは、よくない、と読めば、先送りが良くないという意味で通る。", "散髪": "病院の予約を散髪にするのは、予約を散髪に替えるという意味になり、文が通らない。", "買い物": "病院の予約を買い物にするのは、予約の対象が変わり、文として意味が通らない。", "読書": "病院の予約を読書にするのは、予約と読書がつながらず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "後回し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "食事のあとの後回しは、家族みんなで分担する。", "explanation": "ここは〈後片付け〉の意味。後回しは先送りすることで、食事のあとの片付けを指す語ではないので合わない。"}, {"text": "上司の後回しを受けて、新しい企画を出した。", "explanation": "ここは〈後押し〉の意味。後回しは物事を先送りすることで、背中を押して応援する意味では使わないので合わない。"}, {"text": "祖父の後回しを受けて、彼は会社を任された。", "explanation": "ここは〈後見〉の意味。後回しは順番を遅らせる語で、保護し支える意味には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39101, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は面倒な電話を後回しでしてしまう。", "corrected_sentence": "私は面倒な電話を後回しにしてしまう。", "error_description": "「後回し」は「にする」の形で動詞になる。「後回しでする」では「で」が誤り。正しくは「後回しにしてしまう」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39101, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大事な連絡は後回しにできないない。", "corrected_sentence": "大事な連絡は後回しにできない。", "error_description": "「できないない」は「ない」が重なった誤った形。正しくは「後回しにできない」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39102, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「字を拡大して」で、「拡大する」の対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「字が拡大して読む」では読む人がいなくなり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「字に拡大して」では対象を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「拡大する」の対象に使えない。"}], "correct_answer": "を", "explanations": {"を": "「字を拡大して」で、「拡大する」の対象を表す。", "が": "「字が拡大して読む」では読む人がいなくなり、文が成り立たない。", "に": "「字に拡大して」では対象を表せない。", "へ": "方向を表す「へ」は「拡大する」の対象に使えない。"}, "error_tags": {"が": "subject_marker", "に": "target_of_action", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "縮小", "is_correct": true, "explanation": "物事が小さくなることで、拡大の反対。"}, {"text": "拡張", "is_correct": false, "explanation": "範囲を広げることで、拡大に近い。"}, {"text": "増大", "is_correct": false, "explanation": "大きく増えることで、拡大と近い。"}, {"text": "拡充", "is_correct": false, "explanation": "内容を広げて充実させることで、拡大と近い。"}], "correct_answer": "縮小", "explanations": {"縮小": "物事が小さくなることで、拡大の反対。", "拡張": "範囲を広げることで、拡大に近い。", "増大": "大きく増えることで、拡大と近い。", "拡充": "内容を広げて充実させることで、拡大と近い。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39102, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「拡大を考えている」で、考える対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「拡大が考えている」では主語と対象が逆になり、成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「拡大に考えている」は文法的に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「考える」の対象には使えない。"}], "correct_answer": "を", "explanations": {"を": "「拡大を考えている」で、考える対象を表す。", "が": "「拡大が考えている」では主語と対象が逆になり、成り立たない。", "に": "「拡大に考えている」は文法的に合わない。", "へ": "方向の「へ」は「考える」の対象には使えない。"}, "error_tags": {"が": "subject_marker", "に": "target_of_action", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "縮小", "is_correct": true, "explanation": "物事が小さくなることで、拡大の反対。"}, {"text": "拡散", "is_correct": false, "explanation": "広がり散ることで、拡大の反対ではない。"}, {"text": "膨張", "is_correct": false, "explanation": "ふくらんで大きくなることで、拡大に近い。"}, {"text": "増加", "is_correct": false, "explanation": "数や量が増えることで、拡大に近い。"}], "correct_answer": "縮小", "explanations": {"縮小": "物事が小さくなることで、拡大の反対。", "拡散": "広がり散ることで、拡大の反対ではない。", "膨張": "ふくらんで大きくなることで、拡大に近い。", "増加": "数や量が増えることで、拡大に近い。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39102, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事が大きくなること。", "primary_collocate": null, "pronunciation": "かくだい", "ipa": "kakɯdai", "syllable_count": 4, "sentences": [{"text": "絵を拡大する。", "target_word": "拡大", "complexity_tier": "T1", "furigana": "絵[え]を拡大[かくだい]する。", "sentence_source": "generated"}, {"text": "字を拡大して読む。", "target_word": "拡大", "complexity_tier": "T1", "furigana": "字[じ]を拡大[かくだい]して読[よ]む。", "sentence_source": "generated"}, {"text": "町が拡大している。", "target_word": "拡大", "complexity_tier": "T3", "furigana": "町[まち]が拡大[かくだい]している。", "sentence_source": "generated"}, {"text": "拡大した写真はぼやけていた。", "target_word": "拡大", "complexity_tier": "T3", "furigana": "拡大[かくだい]した写真[しゃしん]はぼやけていた。", "sentence_source": "generated"}, {"text": "店の拡大で、働く人が増えた。", "target_word": "拡大", "complexity_tier": "T3", "furigana": "店[みせ]の拡大[かくだい]で、働[はたら]く人[ひと]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "画面を拡大するには、二本の指を使います。", "target_word": "拡大", "complexity_tier": "T3", "furigana": "画面[がめん]を拡大[かくだい]するには、二本[にほん]の指[ゆび]を使[つか]います。", "sentence_source": "generated"}, {"text": "火事が拡大しないよう、みんなで水をかけた。", "target_word": "拡大", "complexity_tier": "T3", "furigana": "火事[かじ]が拡大[かくだい]しないよう、みんなで水[みず]をかけた。", "sentence_source": "generated"}, {"text": "工場の拡大を考えているところだ。", "target_word": "拡大", "complexity_tier": "T3", "furigana": "工場[こうじょう]の拡大[かくだい]を考[かんが]えているところだ。", "sentence_source": "generated"}, {"text": "拡大すれば、小さな文字も読めるようになる。", "target_word": "拡大", "complexity_tier": "T4", "furigana": "拡大[かくだい]すれば、小[ちい]さな文字[もじ]も読[よ]めるようになる。", "sentence_source": "generated"}, {"text": "会社は事業を拡大して、海外にも店を出した。", "target_word": "拡大", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は事業[じぎょう]を拡大[かくだい]して、海外[かいがい]にも店[みせ]を出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拡大する", "label": "活用"}, {"form": "拡大した", "label": "活用"}, {"form": "拡大鏡", "label": "派生"}, {"form": "拡大版", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事が大きくなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ac3fe2-6ce0-4a2e-b7a6-92b185db239c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39102, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拡大", "is_correct": true, "explanation": "見出し語「かくだい」。"}, {"text": "莫大", "is_correct": false, "explanation": "「ばくだい」で、か→ばの一音違い。"}, {"text": "寛大", "is_correct": false, "explanation": "「かんだい」で、く→んの一音違い。"}, {"text": "客体", "is_correct": false, "explanation": "「かくたい」で、だ→たの清濁の違い。"}], "explanations": {"拡大": "見出し語「かくだい」。", "莫大": "「ばくだい」で、か→ばの一音違い。", "寛大": "「かんだい」で、く→んの一音違い。", "客体": "「かくたい」で、だ→たの清濁の違い。"}, "sentence_index": null, "correct_answer": "拡大"}, "level_3": {"options": [{"text": "拡大", "is_correct": true, "explanation": "「絵を拡大する」で、絵を大きくすることを表す。"}, {"text": "運転", "is_correct": false, "explanation": "形は合うが意味が合わない。絵を運転するとは言わない。"}, {"text": "入院", "is_correct": false, "explanation": "形は合うが意味が合わない。絵を入院するとは言わない。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが意味が合わない。絵を結婚するとは言わない。"}], "explanations": {"拡大": "「絵を拡大する」で、絵を大きくすることを表す。", "運転": "形は合うが意味が合わない。絵を運転するとは言わない。", "入院": "形は合うが意味が合わない。絵を入院するとは言わない。", "結婚": "形は合うが意味が合わない。絵を結婚するとは言わない。"}, "sentence_index": 0, "correct_answer": "拡大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "犬が走って、足が拡大した。", "explanation": "走って足が大きくなるわけではなく、「拡大」の使い方として不自然。"}, {"text": "薬を飲んだら、熱が拡大した。", "explanation": "熱が上がることを「拡大」とは言わない。ここは意味が合わない。"}, {"text": "よく聞こえないので、テレビの音を拡大した。", "explanation": "音量を上げることは「拡大」とは言わない。「音を大きくする」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
