INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39103, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「拡大に伴う」で、「〜にともなう」という決まった言い方になる。"}, {"text": "と", "is_correct": false, "explanation": "「拡大と伴う」とは言えない。"}, {"text": "へ", "is_correct": false, "explanation": "「拡大へ伴う」は文法的に合わない。"}, {"text": "から", "is_correct": false, "explanation": "「拡大から伴う」は文法的に合わない。"}], "correct_answer": "に", "explanations": {"に": "「拡大に伴う」で、「〜にともなう」という決まった言い方になる。", "と": "「拡大と伴う」とは言えない。", "へ": "「拡大へ伴う」は文法的に合わない。", "から": "「拡大から伴う」は文法的に合わない。"}, "error_tags": {"と": "comitative", "へ": "direction", "から": "source"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "縮小", "is_correct": true, "explanation": "規模が小さくなることで、拡大の反対。"}, {"text": "拡張", "is_correct": false, "explanation": "範囲を広げることで、拡大に近い。"}, {"text": "増大", "is_correct": false, "explanation": "量が増えて大きくなることで、拡大と近い。"}, {"text": "拡充", "is_correct": false, "explanation": "内容を広げて充実させることで、拡大と近い。"}], "correct_answer": "縮小", "explanations": {"縮小": "規模が小さくなることで、拡大の反対。", "拡張": "範囲を広げることで、拡大に近い。", "増大": "量が増えて大きくなることで、拡大と近い。", "拡充": "内容を広げて充実させることで、拡大と近い。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39103, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「拡大が続けば」で、「拡大」が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「続く」は自動詞で、「拡大を続けば」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「拡大と続けば」は文法的に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「拡大へ続けば」は文法的に合わない。"}], "correct_answer": "が", "explanations": {"が": "「拡大が続けば」で、「拡大」が主語になる。", "を": "「続く」は自動詞で、「拡大を続けば」は成り立たない。", "と": "「拡大と続けば」は文法的に合わない。", "へ": "「拡大へ続けば」は文法的に合わない。"}, "error_tags": {"を": "object_marker", "と": "comitative", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "縮小", "is_correct": true, "explanation": "規模が小さくなることで、拡大の反対。"}, {"text": "増加", "is_correct": false, "explanation": "数や量が増えることで、拡大と近い。"}, {"text": "膨張", "is_correct": false, "explanation": "ふくらんで大きくなることで、拡大と近い。"}, {"text": "拡散", "is_correct": false, "explanation": "広がり散ることで、拡大の反対ではない。"}], "correct_answer": "縮小", "explanations": {"縮小": "規模が小さくなることで、拡大の反対。", "増加": "数や量が増えることで、拡大と近い。", "膨張": "ふくらんで大きくなることで、拡大と近い。", "拡散": "広がり散ることで、拡大の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39103, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある物事の範囲や規模が大きくなること。", "primary_collocate": null, "pronunciation": "かくだい", "ipa": "kakɯdai", "syllable_count": 4, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "拡大", "complexity_tier": "T6", "furigana": "近年[きんねん]、都市[とし]の無秩序[むちつじょ]な拡大[かくだい]に伴[ともな]う緑[みどり]の希薄化[きはくか]に歯止[はど]めをかけるべく、地域[ちいき]コミュニティガーデンプロジェクトが各地[かくち]で顕在化[けんざいか]している。", "sentence_source": "mined"}, {"text": "店を拡大する。", "target_word": "拡大", "complexity_tier": "T1", "furigana": "店[みせ]を拡大[かくだい]する。", "sentence_source": "generated"}, {"text": "町が拡大した。", "target_word": "拡大", "complexity_tier": "T1", "furigana": "町[まち]が拡大[かくだい]した。", "sentence_source": "generated"}, {"text": "会社の拡大は順調です。", "target_word": "拡大", "complexity_tier": "T2", "furigana": "会社[かいしゃ]の拡大[かくだい]は順調[じゅんちょう]です。", "sentence_source": "generated"}, {"text": "感染が拡大しないように注意してください。", "target_word": "拡大", "complexity_tier": "T3", "furigana": "感染[かんせん]が拡大[かくだい]しないように注意[ちゅうい]してください。", "sentence_source": "generated"}, {"text": "被害の範囲が拡大すると、多くの人が困る。", "target_word": "拡大", "complexity_tier": "T3", "furigana": "被害[ひがい]の範囲[はんい]が拡大[かくだい]すると、多[おお]くの人[ひと]が困[こま]る。", "sentence_source": "generated"}, {"text": "工場の規模を拡大するために、新しい人を雇った。", "target_word": "拡大", "complexity_tier": "T4", "furigana": "工場[こうじょう]の規模[きぼ]を拡大[かくだい]するために、新[あたら]しい人[ひと]を雇[やと]った。", "sentence_source": "generated"}, {"text": "拡大が続けば、町は住みにくくなるだろう。", "target_word": "拡大", "complexity_tier": "T4", "furigana": "拡大[かくだい]が続[つづ]けば、町[まち]は住[す]みにくくなるだろう。", "sentence_source": "generated"}, {"text": "学校の拡大により、校庭が狭くなった。", "target_word": "拡大", "complexity_tier": "T3", "furigana": "学校[がっこう]の拡大[かくだい]により、校庭[こうてい]が狭[せま]くなった。", "sentence_source": "generated"}, {"text": "この問題は拡大する一方で、解決の見通しが立たない。", "target_word": "拡大", "complexity_tier": "T4", "furigana": "この問題[もんだい]は拡大[かくだい]する一方[いっぽう]で、解決[かいけつ]の見通[みとお]しが立[た]たない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拡大する", "label": "活用"}, {"form": "拡大した", "label": "活用"}, {"form": "拡大鏡", "label": "派生"}, {"form": "拡大版", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事の範囲や規模が大きくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): 無秩序 (Zipf 2.99), 希薄 (Zipf 3.22), 歯止め (Zipf 3.18), 顕在 (Zipf 3.05)']::text[], '57ac3fe2-6ce0-4a2e-b7a6-92b185db239c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39103, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拡大", "is_correct": true, "explanation": "見出し語「かくだい」。"}, {"text": "客体", "is_correct": false, "explanation": "「かくたい」で、だ→たの清濁の違い。"}, {"text": "格段", "is_correct": false, "explanation": "「かくだん」で、最後のい→んの一音違い。"}, {"text": "寛大", "is_correct": false, "explanation": "「かんだい」で、く→んの一音違い。"}], "explanations": {"拡大": "見出し語「かくだい」。", "客体": "「かくたい」で、だ→たの清濁の違い。", "格段": "「かくだん」で、最後のい→んの一音違い。", "寛大": "「かんだい」で、く→んの一音違い。"}, "sentence_index": null, "correct_answer": "拡大"}, "level_3": {"options": [{"text": "拡大", "is_correct": true, "explanation": "「都市の無秩序な拡大」で、都市が大きくなることを表す。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが意味が合わない。都市が卒業するという意味は成り立たない。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが意味が合わない。都市の洗濯では緑の希薄化と結びつかない。"}, {"text": "読書", "is_correct": false, "explanation": "形は合うが意味が合わない。都市の読書では意味が通らない。"}], "explanations": {"拡大": "「都市の無秩序な拡大」で、都市が大きくなることを表す。", "卒業": "形は合うが意味が合わない。都市が卒業するという意味は成り立たない。", "洗濯": "形は合うが意味が合わない。都市の洗濯では緑の希薄化と結びつかない。", "読書": "形は合うが意味が合わない。都市の読書では意味が通らない。"}, "sentence_index": 0, "correct_answer": "拡大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日は寒かったので、スープの温度が拡大した。", "explanation": "「拡大」は範囲や規模が大きくなることで、温度の変化には使えない。"}, {"text": "彼は練習して、足の速さが拡大した。", "explanation": "速さの向上には「拡大」を使わない。範囲や規模の話ではない。"}, {"text": "会社の拡大が順調に小さくなっています。", "explanation": "「拡大」は大きくなることなので、「小さくなる」とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39103, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拡大", "is_correct": true, "explanation": "見出し語「かくだい」。"}, {"text": "改題", "is_correct": false, "explanation": "「かいだい」で、く→いの一音違い。"}, {"text": "閣内", "is_correct": false, "explanation": "「かくない」で、だ→なの一音違い。"}, {"text": "莫大", "is_correct": false, "explanation": "「ばくだい」で、か→ばの一音違い。"}], "explanations": {"拡大": "見出し語「かくだい」。", "改題": "「かいだい」で、く→いの一音違い。", "閣内": "「かくない」で、だ→なの一音違い。", "莫大": "「ばくだい」で、か→ばの一音違い。"}, "sentence_index": null, "correct_answer": "拡大"}, "level_3": {"options": [{"text": "拡大", "is_correct": true, "explanation": "「工場の規模を拡大する」で、規模を大きくすることを表す。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが意味が合わない。規模を散歩するとは言わない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが意味が合わない。規模を卒業するとは言わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが意味が合わない。規模を洗濯するとは言わない。"}], "explanations": {"拡大": "「工場の規模を拡大する」で、規模を大きくすることを表す。", "散歩": "形は合うが意味が合わない。規模を散歩するとは言わない。", "卒業": "形は合うが意味が合わない。規模を卒業するとは言わない。", "洗濯": "形は合うが意味が合わない。規模を洗濯するとは言わない。"}, "sentence_index": 6, "correct_answer": "拡大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎日練習して、ピアノが拡大した。", "explanation": "上達を「拡大」と言うのは誤り。「拡大」は範囲や規模が大きくなることに使う。"}, {"text": "鍋の水が冷めて、拡大する一方だ。", "explanation": "温度の変化に「拡大」は使えない。"}, {"text": "部屋の電気を拡大して、暗くした。", "explanation": "電気を消したり暗くしたりすることを「拡大」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39103, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社は事業を拡大に、利益を伸ばした。", "corrected_sentence": "会社は事業を拡大して、利益を伸ばした。", "error_description": "「拡大」の後に「して」が必要で、「に」では動作がつながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39103, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい商品で市場を拡大がしたい。", "corrected_sentence": "新しい商品で市場を拡大したい。", "error_description": "「拡大」と「したい」の間に不要な「が」が入っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39104, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高価", "is_correct": true, "explanation": "「安価」の対義語。値段が高いことを表し、意味が反対になる。"}, {"text": "手軽", "is_correct": false, "explanation": "「手軽」は簡単で扱いやすい意味で、値段の反対語ではない。"}, {"text": "丈夫", "is_correct": false, "explanation": "「丈夫」は壊れにくい意味で、対義語ではない。"}, {"text": "深刻", "is_correct": false, "explanation": "「深刻」は重大で真剣な意味で、値段の反対語ではない。"}], "correct_answer": "高価", "explanations": {"高価": "「安価」の対義語。値段が高いことを表し、意味が反対になる。", "手軽": "「手軽」は簡単で扱いやすい意味で、値段の反対語ではない。", "丈夫": "「丈夫」は壊れにくい意味で、対義語ではない。", "深刻": "「深刻」は重大で真剣な意味で、値段の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39104, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高価", "is_correct": true, "explanation": "「安価」の対義語。値段が高いことを表し、意味が反対になる。"}, {"text": "静か", "is_correct": false, "explanation": "「静か」は音や様子が穏やかな意味で、値段の反対語ではない。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気」は明るく楽しげな意味で、対義語ではない。"}, {"text": "堅実", "is_correct": false, "explanation": "「堅実」は確かで手堅い意味で、対義語ではない。"}], "correct_answer": "高価", "explanations": {"高価": "「安価」の対義語。値段が高いことを表し、意味が反対になる。", "静か": "「静か」は音や様子が穏やかな意味で、値段の反対語ではない。", "陽気": "「陽気」は明るく楽しげな意味で、対義語ではない。", "堅実": "「堅実」は確かで手堅い意味で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39104, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "値段がとても安いこと。", "primary_collocate": null, "pronunciation": "あんか", "ipa": "aŋka", "syllable_count": 3, "sentences": [{"text": "この店は安価な服をたくさん売っています。", "target_word": "安価", "complexity_tier": "T3", "furigana": "この店[みせ]は安価[あんか]な服[ふく]をたくさん売[う]っています。", "sentence_source": "generated"}, {"text": "安価なので、学生でも気軽に買えます。", "target_word": "安価", "complexity_tier": "T3", "furigana": "安価[あんか]なので、学生[がくせい]でも気軽[きがる]に買[か]えます。", "sentence_source": "generated"}, {"text": "材料が安価だから、このお弁当は三百円で売れます。", "target_word": "安価", "complexity_tier": "T3", "furigana": "材料[ざいりょう]が安価[あんか]だから、このお弁当[べんとう]は三百円[さんびゃくえん]で売[う]れます。", "sentence_source": "generated"}, {"text": "高い物より、安価な物のほうが人気があります。", "target_word": "安価", "complexity_tier": "T3", "furigana": "高[たか]い物[もの]より、安価[あんか]な物[もの]のほうが人気[にんき]があります。", "sentence_source": "generated"}, {"text": "安価なノートでも、書きやすければ十分です。", "target_word": "安価", "complexity_tier": "T3", "furigana": "安価[あんか]なノートでも、書[か]きやすければ十分[じゅうぶん]です。", "sentence_source": "generated"}, {"text": "母は安価な果物を選んで買いました。", "target_word": "安価", "complexity_tier": "T3", "furigana": "母[はは]は安価[あんか]な果物[くだもの]を選[えら]んで買[か]いました。", "sentence_source": "generated"}, {"text": "この旅館は安価で、一晩五千円です。", "target_word": "安価", "complexity_tier": "T3", "furigana": "この旅館[りょかん]は安価[あんか]で、一晩[ひとばん]五千円[ごせんえん]です。", "sentence_source": "generated"}, {"text": "安価な部品を使ったため、すぐに壊れてしまいました。", "target_word": "安価", "complexity_tier": "T3", "furigana": "安価[あんか]な部品[ぶひん]を使[つか]ったため、すぐに壊[こわ]れてしまいました。", "sentence_source": "generated"}, {"text": "安価に作れる方法を、会社で考えています。", "target_word": "安価", "complexity_tier": "T3", "furigana": "安価[あんか]に作[つく]れる方法[ほうほう]を、会社[かいしゃ]で考[かんが]えています。", "sentence_source": "generated"}, {"text": "今年は野菜が安価で、家計が助かります。", "target_word": "安価", "complexity_tier": "T3", "furigana": "今年[ことし]は野菜[やさい]が安価[あんか]で、家計[かけい]が助[たす]かります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "安価な", "label": "連体形"}, {"form": "安価で", "label": "連用形"}, {"form": "安価に", "label": "連用形"}], "register": "標準", "sense_fingerprint": "値段が非常に低いこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: やすけれ (Zipf 1.95)']::text[], '4eedbe05-f7a1-46a5-8c64-cbc0a50099f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39104, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安価", "is_correct": true, "explanation": "「安価な服」となり、値段が低い服という意味で空所に入る。"}, {"text": "平和", "is_correct": false, "explanation": "「平和な服」は意味が通らず、店で売る服の説明にならない。"}, {"text": "健康", "is_correct": false, "explanation": "「健康な服」は意味が通らない。服の性質を表す語ではない。"}, {"text": "正直", "is_correct": false, "explanation": "「正直な服」は意味が通らない。人の性格を表す語で、服には使わない。"}], "explanations": {"安価": "「安価な服」となり、値段が低い服という意味で空所に入る。", "平和": "「平和な服」は意味が通らず、店で売る服の説明にならない。", "健康": "「健康な服」は意味が通らない。服の性質を表す語ではない。", "正直": "「正直な服」は意味が通らない。人の性格を表す語で、服には使わない。"}, "sentence_index": 0, "correct_answer": "安価"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この道路は安価なので、子どもも安心して歩けます。", "explanation": "ここは〈安全〉の意味。安価は値段が低いことで、道路の安全性は指せない。"}, {"text": "この鞄は安価な大きさで、持ち歩きやすいです。", "explanation": "ここは〈手頃〉の意味（ちょうどよい大きさ）。安価は値段の低さを表すので、大きさには使えない。"}, {"text": "やっと結果がわかって、安価な気持ちになりました。", "explanation": "ここは〈安心〉の意味。安価は値段の話で、気持ちが落ち着くことは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39104, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安価", "is_correct": true, "explanation": "「安価で」と続き、値段が低いことを表して空所に入る。"}, {"text": "純粋", "is_correct": false, "explanation": "「純粋で、一晩五千円」は意味が通らず、旅館の説明にならない。"}, {"text": "頑固", "is_correct": false, "explanation": "「頑固で、一晩五千円」は意味が通らない。人の性格を表す語である。"}, {"text": "鮮烈", "is_correct": false, "explanation": "「鮮烈で、一晩五千円」は意味が通らない。印象の強さを表す語である。"}], "explanations": {"安価": "「安価で」と続き、値段が低いことを表して空所に入る。", "純粋": "「純粋で、一晩五千円」は意味が通らず、旅館の説明にならない。", "頑固": "「頑固で、一晩五千円」は意味が通らない。人の性格を表す語である。", "鮮烈": "「鮮烈で、一晩五千円」は意味が通らない。印象の強さを表す語である。"}, "sentence_index": 6, "correct_answer": "安価"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は安価な考えで試験に挑み、結局失敗した。", "explanation": "ここは〈安易〉の意味（深く考えない）。安価は値段の低さで、考えの浅さは表さない。"}, {"text": "彼女は安価な性格で、だれとでも仲良くなれる。", "explanation": "ここは〈温和〉の意味（穏やかで人当たりがよい）。安価は値段の低さで、性格は表さない。"}, {"text": "会社の将来は安価だと言われている。", "explanation": "ここは〈安泰〉の意味（心配がない）。安価は値段の低さで、将来の安心は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39104, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この市場は安価の魚を毎朝売っています。", "corrected_sentence": "この市場は安価な魚を毎朝売っています。", "error_description": "「安価」は形状詞なので、名詞の前では「な」が必要。「の」は誤りで、正しくは「安価な魚」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "安価", "is_correct": true, "explanation": "語幹。「なので」の前に置く形で、文が正しく続く。"}, {"text": "安価な", "is_correct": false, "explanation": "連体形。「安価ななので」となり、「な」が重なって不自然。"}, {"text": "安価で", "is_correct": false, "explanation": "連用形。「安価でなので」となり、文が続かない。"}, {"text": "安価に", "is_correct": false, "explanation": "連用形。「安価になので」となり、文が続かない。"}], "correct_form": "安価", "base_form": "安価", "form_label": "語幹", "sentence_index": 1, "explanations": {"安価": "語幹。「なので」の前に置く形で、文が正しく続く。", "安価な": "連体形。「安価ななので」となり、「な」が重なって不自然。", "安価で": "連用形。「安価でなので」となり、文が続かない。", "安価に": "連用形。「安価になので」となり、文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39104, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店は安価が野菜を毎朝売っています。", "corrected_sentence": "この店は安価な野菜を毎朝売っています。", "error_description": "「安価」は形状詞なので、名詞の前では「な」が必要。「が」は主語を示す助詞で誤り。正しくは「安価な野菜」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "安価", "is_correct": true, "explanation": "語幹。「部品」の前に「な」をつける形で、文が正しく続く。"}, {"text": "安価だ", "is_correct": false, "explanation": "終止形。「安価だな部品」となり、名詞を修飾できず不自然。"}, {"text": "安価である", "is_correct": false, "explanation": "「である」の形。「安価であるな部品」となり、続かない。"}, {"text": "安価だった", "is_correct": false, "explanation": "過去の形。「安価だったな部品」となり、続かない。"}], "correct_form": "安価", "base_form": "安価", "form_label": "語幹", "sentence_index": 7, "explanations": {"安価": "語幹。「部品」の前に「な」をつける形で、文が正しく続く。", "安価だ": "終止形。「安価だな部品」となり、名詞を修飾できず不自然。", "安価である": "「である」の形。「安価であるな部品」となり、続かない。", "安価だった": "過去の形。「安価だったな部品」となり、続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39105, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高価", "is_correct": true, "explanation": "「安価」の対義語。値段が高いことを表し、意味が反対になる。"}, {"text": "確実", "is_correct": false, "explanation": "「確実」は間違いないという意味で、対義語ではない。"}, {"text": "大切", "is_correct": false, "explanation": "「大切」は大事だという意味で、対義語ではない。"}, {"text": "簡単", "is_correct": false, "explanation": "「簡単」はやさしいという意味で、値段の反対語ではない。"}], "correct_answer": "高価", "explanations": {"高価": "「安価」の対義語。値段が高いことを表し、意味が反対になる。", "確実": "「確実」は間違いないという意味で、対義語ではない。", "大切": "「大切」は大事だという意味で、対義語ではない。", "簡単": "「簡単」はやさしいという意味で、値段の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
