INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39105, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "価格が低く、手軽に買えること。", "primary_collocate": null, "pronunciation": "あんか", "ipa": "aŋka", "syllable_count": 3, "sentences": [{"text": "安価で手軽な昼ごはんを探しています。", "target_word": "安価", "complexity_tier": "T3", "furigana": "安価[あんか]で手軽[てがる]な昼[ひる]ごはんを探[さが]しています。", "sentence_source": "generated"}, {"text": "この新しいスマホは安価なので、よく売れています。", "target_word": "安価", "complexity_tier": "T3", "furigana": "この新[あたら]しいスマホは安価[あんか]なので、よく売[う]れています。", "sentence_source": "generated"}, {"text": "安価な商品が増えて、誰でも買いやすくなりました。", "target_word": "安価", "complexity_tier": "T3", "furigana": "安価[あんか]な商品[しょうひん]が増[ふ]えて、誰[だれ]でも買[か]いやすくなりました。", "sentence_source": "generated"}, {"text": "安価なイヤホンなら、学生でも簡単に手に入ります。", "target_word": "安価", "complexity_tier": "T3", "furigana": "安価[あんか]なイヤホンなら、学生[がくせい]でも簡単[かんたん]に手[て]に入[はい]ります。", "sentence_source": "generated"}, {"text": "家具を安価にそろえるなら、あの店がおすすめです。", "target_word": "安価", "complexity_tier": "T3", "furigana": "家具[かぐ]を安価[あんか]にそろえるなら、あの店[みせ]がおすすめです。", "sentence_source": "generated"}, {"text": "この工具は安価で、初心者にも買いやすいです。", "target_word": "安価", "complexity_tier": "T3", "furigana": "この工具[こうぐ]は安価[あんか]で、初心者[しょしんしゃ]にも買[か]いやすいです。", "sentence_source": "generated"}, {"text": "安価なプランを選べば、毎月の通信費が減ります。", "target_word": "安価", "complexity_tier": "T3", "furigana": "安価[あんか]なプランを選[えら]べば、毎月[まいつき]の通信費[つうしんひ]が減[へ]ります。", "sentence_source": "generated"}, {"text": "以前は高かったカメラも、今は安価で手に入ります。", "target_word": "安価", "complexity_tier": "T3", "furigana": "以前[いぜん]は高[たか]かったカメラも、今[いま]は安価[あんか]で手[て]に入[はい]ります。", "sentence_source": "generated"}, {"text": "安価な傘をコンビニで買って、雨の中を帰りました。", "target_word": "安価", "complexity_tier": "T3", "furigana": "安価[あんか]な傘[かさ]をコンビニで買[か]って、雨[あめ]の中[なか]を帰[かえ]りました。", "sentence_source": "generated"}, {"text": "安価な商品ばかりでなく、品質の良い物も見てください。", "target_word": "安価", "complexity_tier": "T3", "furigana": "安価[あんか]な商品[しょうひん]ばかりでなく、品質[ひんしつ]の良[よ]い物[もの]も見[み]てください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "安価な", "label": "連体形"}, {"form": "安価で", "label": "連用形"}, {"form": "安価に", "label": "連用形"}], "register": "標準", "sense_fingerprint": "価格が低く手軽に買えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eedbe05-f7a1-46a5-8c64-cbc0a50099f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39105, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安価", "is_correct": true, "explanation": "「安価で手軽な」となり、値段が低く手軽に買えることを表して空所に入る。"}, {"text": "平和", "is_correct": false, "explanation": "「平和で手軽な昼ごはん」は意味が通らない。"}, {"text": "純粋", "is_correct": false, "explanation": "「純粋で手軽な昼ごはん」は意味が通らない。"}, {"text": "頑固", "is_correct": false, "explanation": "「頑固で手軽な昼ごはん」は意味が通らない。人の性格を表す語である。"}], "explanations": {"安価": "「安価で手軽な」となり、値段が低く手軽に買えることを表して空所に入る。", "平和": "「平和で手軽な昼ごはん」は意味が通らない。", "純粋": "「純粋で手軽な昼ごはん」は意味が通らない。", "頑固": "「頑固で手軽な昼ごはん」は意味が通らない。人の性格を表す語である。"}, "sentence_index": 0, "correct_answer": "安価"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このリュックは安価な大きさで、学校に持って行けます。", "explanation": "ここは〈手頃〉の意味（ちょうどよい大きさ）。安価は値段の低さで、大きさには使えない。"}, {"text": "この本は安価な言葉で書かれていて、子どもにも読めます。", "explanation": "ここは〈平易〉の意味（やさしくわかりやすい）。安価は値段の低さで、言葉のやさしさは表さない。"}, {"text": "試験の結果が届いて、安価な気持ちになりました。", "explanation": "ここは〈安心〉の意味。安価は値段の話で、気持ちが落ち着くことは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39105, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安価", "is_correct": true, "explanation": "「安価なプラン」となり、値段が低いプランを表して空所に入る。"}, {"text": "神聖", "is_correct": false, "explanation": "「神聖なプランを選べば」は意味が通らない。"}, {"text": "鮮烈", "is_correct": false, "explanation": "「鮮烈なプラン」は意味が通らない。印象の強さを表す語である。"}, {"text": "厳粛", "is_correct": false, "explanation": "「厳粛なプラン」は意味が通らない。儀式などの雰囲気を表す語である。"}], "explanations": {"安価": "「安価なプラン」となり、値段が低いプランを表して空所に入る。", "神聖": "「神聖なプランを選べば」は意味が通らない。", "鮮烈": "「鮮烈なプラン」は意味が通らない。印象の強さを表す語である。", "厳粛": "「厳粛なプラン」は意味が通らない。儀式などの雰囲気を表す語である。"}, "sentence_index": 6, "correct_answer": "安価"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は安価な寝顔で眠っていた。", "explanation": "ここは〈安らか〉の意味（穏やかで落ち着いている）。安価は値段の低さで、寝顔の穏やかさは表さない。"}, {"text": "彼女の気分は安価で、いつも変わらない。", "explanation": "ここは〈安定〉の意味（変わらず落ち着いている）。安価は値段の低さで、気分の安定は表さない。"}, {"text": "チームの将来は安価だと言われている。", "explanation": "ここは〈安泰〉の意味（心配がない）。安価は値段の低さで、将来の安心は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39105, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "安価のお弁当を探すなら、この店が便利です。", "corrected_sentence": "安価なお弁当を探すなら、この店が便利です。", "error_description": "「安価」は形状詞なので、名詞の前では「な」が必要。「の」は誤りで、正しくは「安価なお弁当」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "安価", "is_correct": true, "explanation": "語幹。「なので」の前に置く形で、文が正しく続く。"}, {"text": "安価な", "is_correct": false, "explanation": "連体形。「安価ななので」となり、「な」が重なって不自然。"}, {"text": "安価で", "is_correct": false, "explanation": "連用形。「安価でなので」となり、文が続かない。"}, {"text": "安価に", "is_correct": false, "explanation": "連用形。「安価になので」となり、文が続かない。"}], "correct_form": "安価", "base_form": "安価", "form_label": "語幹", "sentence_index": 1, "explanations": {"安価": "語幹。「なので」の前に置く形で、文が正しく続く。", "安価な": "連体形。「安価ななので」となり、「な」が重なって不自然。", "安価で": "連用形。「安価でなので」となり、文が続かない。", "安価に": "連用形。「安価になので」となり、文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39105, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店では、安価に魚を織っています。", "corrected_sentence": "この店では、安価に魚を売っています。", "error_description": "「安価に売る」は値段を安くして売ること。「織る」は布や糸を組む動作で、魚とは組み合わない。正しくは「売っています」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "安価", "is_correct": true, "explanation": "語幹。「安価で手に入ります」と続き、文が正しく成り立つ。"}, {"text": "安価だ", "is_correct": false, "explanation": "終止形。「安価だで手に入ります」となり、続かない。"}, {"text": "安価である", "is_correct": false, "explanation": "「である」の形。「安価であるで手に入ります」となり、続かない。"}, {"text": "安価だった", "is_correct": false, "explanation": "過去の形。「安価だったで手に入ります」となり、続かない。"}], "correct_form": "安価", "base_form": "安価", "form_label": "語幹", "sentence_index": 7, "explanations": {"安価": "語幹。「安価で手に入ります」と続き、文が正しく成り立つ。", "安価だ": "終止形。「安価だで手に入ります」となり、続かない。", "安価である": "「である」の形。「安価であるで手に入ります」となり、続かない。", "安価だった": "過去の形。「安価だったで手に入ります」となり、続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39106, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「トレンドを知るために」の目的語。知る対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すと「トレンドが知る」となり、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を表す。「トレンドに知る」は対象として不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表す。「トレンドで知る」は知る対象として不自然。"}], "correct_answer": "を", "explanations": {"を": "「トレンドを知るために」の目的語。知る対象を表す。", "が": "主語を表すと「トレンドが知る」となり、意味が通らない。", "に": "方向や相手を表す。「トレンドに知る」は対象として不自然。", "で": "手段や場所を表す。「トレンドで知る」は知る対象として不自然。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39106, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39106, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "今、人気のある考え方や流行のことです。", "primary_collocate": null, "pronunciation": "とれんど", "ipa": "toɾeɴdo", "syllable_count": 4, "sentences": [{"text": "今年の春のトレンドは、明るい黄色の服だそうです。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "今年[ことし]の春[はる]のトレンドは、明[あか]るい黄色[きいろ]の服[ふく]だそうです。", "sentence_source": "generated"}, {"text": "若い人のトレンドを知るために、毎日SNSを見ています。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "若[わか]い人[ひと]のトレンドを知[し]るために、毎日[まいにち]SNSを見[み]ています。", "sentence_source": "generated"}, {"text": "このお店は、いつも新しいトレンドを取り入れている。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "このお店[みせ]は、いつも新[あたら]しいトレンドを取[と]り入[い]れている。", "sentence_source": "generated"}, {"text": "おしゃれな妹は、トレンドの髪型をすぐに試す。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "おしゃれな妹[いもうと]は、トレンドの髪型[かみがた]をすぐに試[ため]す。", "sentence_source": "generated"}, {"text": "健康を大切にする考え方が、最近のトレンドになっている。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "健康[けんこう]を大切[たいせつ]にする考[かんが]え方[かた]が、最近[さいきん]のトレンドになっている。", "sentence_source": "generated"}, {"text": "トレンドを追いかけすぎて、自分に合う服がわからなくなった。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "トレンドを追[お]いかけすぎて、自分[じぶん]に合[あ]う服[ふく]がわからなくなった。", "sentence_source": "generated"}, {"text": "雑誌でその年のトレンドを調べてから、新しいかばんを買った。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "雑誌[ざっし]でその年[とし]のトレンドを調[しら]べてから、新[あたら]しいかばんを買[か]った。", "sentence_source": "generated"}, {"text": "去年のトレンドだった帽子は、今ではあまり見かけない。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "去年[きょねん]のトレンドだった帽子[ぼうし]は、今[いま]ではあまり見[み]かけない。", "sentence_source": "generated"}, {"text": "新しい商品を作る前に、会議で最近のトレンドについて話し合った。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "新[あたら]しい商品[しょうひん]を作[つく]る前[まえ]に、会議[かいぎ]で最近[さいきん]のトレンドについて話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "彼は音楽のトレンドにくわしく、新しい歌手をよく教えてくれる。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "彼[かれ]は音楽[おんがく]のトレンドにくわしく、新[あたら]しい歌手[かしゅ]をよく教[おし]えてくれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "トレンド", "label": "基本形"}], "register": "中立", "sense_fingerprint": "今の人気や流行の流れ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad29b17a-8ef9-4f71-bf29-c78f05e924aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39106, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "トレンド", "is_correct": true, "explanation": "「今年の春のトレンド」が主題の空所。今の人気や流行を表す語で意味が通る。"}, {"text": "電池", "is_correct": false, "explanation": "電気を蓄える装置の意味。服の流行の話題には合わない。"}, {"text": "寸法", "is_correct": false, "explanation": "大きさの数値の意味。春の流行を表さない。"}, {"text": "寝具", "is_correct": false, "explanation": "布団などの意味。服の流行には合わない。"}], "explanations": {"トレンド": "「今年の春のトレンド」が主題の空所。今の人気や流行を表す語で意味が通る。", "電池": "電気を蓄える装置の意味。服の流行の話題には合わない。", "寸法": "大きさの数値の意味。春の流行を表さない。", "寝具": "布団などの意味。服の流行には合わない。"}, "sentence_index": 0, "correct_answer": "トレンド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は約束を破るトレンドがある。", "explanation": "ここは〈個人の性格の傾向〉の意味。トレンドは今多くの人に好まれる流行で、一人の性格には使わない。"}, {"text": "このお湯のトレンドは熱すぎて、足を入れられない。", "explanation": "ここは〈温度〉の意味。トレンドは流行の傾向で、お湯の熱さを表す語ではない。"}, {"text": "この布は生地のトレンドが硬く、着にくい。", "explanation": "ここは〈生地の硬さ〉の意味。トレンドは流行の傾向で、布の質や硬さを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39106, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "トレンド", "is_correct": true, "explanation": "「その年のトレンド」を調べる、の空所。流行の傾向を指す語で意味が通る。"}, {"text": "部品", "is_correct": false, "explanation": "機械などを構成する部分の意味。流行を調べる対象ではない。"}, {"text": "寝言", "is_correct": false, "explanation": "眠っている間に出す声の意味。流行を調べる対象ではない。"}, {"text": "略歴", "is_correct": false, "explanation": "人の経歴の概要。その年の傾向を指す文脈には合わない。"}], "explanations": {"トレンド": "「その年のトレンド」を調べる、の空所。流行の傾向を指す語で意味が通る。", "部品": "機械などを構成する部分の意味。流行を調べる対象ではない。", "寝言": "眠っている間に出す声の意味。流行を調べる対象ではない。", "略歴": "人の経歴の概要。その年の傾向を指す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "トレンド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は音楽のトレンドの成績が良かった。", "explanation": "ここは〈音楽の成績〉の意味。トレンドは今人気の流行を指し、成績を表す語ではない。"}, {"text": "彼は音楽のトレンドを修理して、演奏した。", "explanation": "ここは〈修理〉の意味。トレンドは今人気の流行で、壊れた物として直す対象にはならない。"}, {"text": "彼は音楽のトレンドを玄関の鍵として使った。", "explanation": "ここは〈道具〉の意味。トレンドは今人気の流行で、鍵のように使える物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39106, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は、トレンドを服を買った。", "corrected_sentence": "妹は、トレンドの服を買った。", "error_description": "「トレンドを服」は目的語の関係が崩れる。連体修飾の「の」に直すのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39106, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年のトレンドだて服を探している。", "corrected_sentence": "去年のトレンドだった服を探している。", "error_description": "過去の断定は「だった」。「だて」は誤った活用形で、「トレンドだった服」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39107, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「トレンドの羅針盤」の連体修飾。トレンドが羅針盤と同格に並ぶ。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すと「トレンドが羅針盤」となり、名詞が続く形と合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表すが、羅針盤を取る動詞がここにはない。"}, {"text": "に", "is_correct": false, "explanation": "方向や位置を表す。「トレンドに羅針盤」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「トレンドの羅針盤」の連体修飾。トレンドが羅針盤と同格に並ぶ。", "が": "主語を表すと「トレンドが羅針盤」となり、名詞が続く形と合わない。", "を": "目的語を表すが、羅針盤を取る動詞がここにはない。", "に": "方向や位置を表す。「トレンドに羅針盤」は意味が通らない。"}, "error_tags": {"の": "連体修飾", "が": "主語", "を": "目的語", "に": "方向・位置"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39107, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「トレンドを知る」の目的語。知る対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すと「トレンドが知る」となり、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を表す。「トレンドに知る」は対象として不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表す。「トレンドと知る」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「トレンドを知る」の目的語。知る対象を表す。", "が": "主語を表すと「トレンドが知る」となり、意味が通らない。", "に": "方向や相手を表す。「トレンドに知る」は対象として不自然。", "と": "共同や引用を表す。「トレンドと知る」は意味が通らない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "方向・相手", "と": "共同・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39107, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある時期に、多くの人の間で広く好まれたり、注目されたりする考え方や様式、行動などの傾向。", "primary_collocate": null, "pronunciation": "とれんど", "ipa": "toɾeɴdo", "syllable_count": 4, "sentences": [{"text": "オートクチュールの持つ絶対的な希少性と排他性は、逆説的にマス市場におけるトレンドの源泉として機能している。", "target_word": "トレンド", "complexity_tier": "T5", "furigana": "オートクチュールのもつぜったいてきなきしょうせいとはいたせいは、ぎゃくせつてきにますしじょうにおけるトレンドのげんせんとしてきのうしている。", "sentence_source": "mined"}, {"text": "すなわち、限られた特権階級のみに奉仕することを潔しとしない独占的な美学こそが、地上に降り立つトレンドの羅針盤としての役割を担い、現代のファッション産業における生態系を永続的に循環させているのである。", "target_word": "トレンド", "complexity_tier": "T5", "furigana": "すなわち、かぎられたとっけんかいきゅうのみにほうしすることをいさぎよしとしないどくせんてきなびがくこそが、ちじょうにおりたつトレンドのらしんばんとしてのやくわりをにない、げんだいのファッションさんぎょうにおけるせいたいけいをえいぞくてきにじゅんかんさせているのである。", "sentence_source": "mined"}, {"text": "今年の春は、淡い色が洋服のトレンドになっている。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "ことしのはるは、あわいいろがようふくのトレンドになっている。", "sentence_source": "generated"}, {"text": "SNSでは、毎日新しいトレンドが生まれては消えていく。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "エスエヌエスでは、まいにちあたらしいトレンドがうまれてはきえていく。", "sentence_source": "generated"}, {"text": "トレンドを追うより、自分に似合う服を選びたい。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "トレンドをおうより、じぶんににあうふくをえらびたい。", "sentence_source": "generated"}, {"text": "この店は、若者の間のトレンドをいち早く取り入れている。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "このみせは、わかもののあいだのトレンドをいちはやくとりいれている。", "sentence_source": "generated"}, {"text": "調査によると、健康志向のトレンドが食品業界で強まっている。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "ちょうさによると、けんこうしこうのトレンドがしょくひんぎょうかいでつよまっている。", "sentence_source": "generated"}, {"text": "最新のトレンドを知るために、雑誌を毎月読んでいる。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "さいしんのトレンドをしるために、ざっしをまいつきよんでいる。", "sentence_source": "generated"}, {"text": "去年のトレンドだった形のバッグが、今は安く売られている。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "きょねんのトレンドだったかたちのバッグが、いまはやすくうられている。", "sentence_source": "generated"}, {"text": "音楽のトレンドは数年ごとに大きく変わる。", "target_word": "トレンド", "complexity_tier": "T3", "furigana": "おんがくのトレンドはすうねんごとにおおきくかわる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "トレンド", "label": "基本形"}, {"form": "トレンドの", "label": "連体形"}], "register": "標準（カタカナ語）", "sense_fingerprint": "流行や世の中の動きとして現れる時代の傾向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: 潔し (Zipf 1.9)']::text[], 'ad29b17a-8ef9-4f71-bf29-c78f05e924aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39107, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "トレンド", "is_correct": true, "explanation": "「マス市場におけるトレンドの源泉」の空所。流行の傾向を指す語で意味が通る。"}, {"text": "寝具", "is_correct": false, "explanation": "布団などの意味。源泉として機能する文脈には合わない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度の意味。市場の源泉として機能する文脈には合わない。"}, {"text": "伝票", "is_correct": false, "explanation": "取引を記録する書類の意味。源泉として機能する文脈に合わない。"}], "explanations": {"トレンド": "「マス市場におけるトレンドの源泉」の空所。流行の傾向を指す語で意味が通る。", "寝具": "布団などの意味。源泉として機能する文脈には合わない。", "体温": "体の温度の意味。市場の源泉として機能する文脈には合わない。", "伝票": "取引を記録する書類の意味。源泉として機能する文脈に合わない。"}, "sentence_index": 0, "correct_answer": "トレンド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は人の意見に流されるトレンドがある。", "explanation": "ここは〈個人の性格の傾向〉の意味。トレンドは多くの人の間で広まる流行を指し、一人の性格には使わない。"}, {"text": "庭の土のトレンドを、鍬で掘り返した。", "explanation": "ここは〈土〉の意味。トレンドは流行の傾向で、土の質や種類を表す語ではない。"}, {"text": "彼の絵は、トレンドの流派を受け継いでいる。", "explanation": "ここは〈流派〉の意味。流派は系統的な画風の継承で、移ろう流行の傾向とは別物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39107, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "トレンド", "is_correct": true, "explanation": "「健康志向のトレンド」が食品業界で強まる、の空所。流行の傾向の意味に合う。"}, {"text": "契約", "is_correct": false, "explanation": "取り決めの意味。「強まる」と結びつかず、健康志向の文脈に合わない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度の意味。食品業界で強まるという文脈に合わない。"}, {"text": "段差", "is_correct": false, "explanation": "高低差の意味。「強まる」とは言わず、意味が通らない。"}], "explanations": {"トレンド": "「健康志向のトレンド」が食品業界で強まる、の空所。流行の傾向の意味に合う。", "契約": "取り決めの意味。「強まる」と結びつかず、健康志向の文脈に合わない。", "体温": "体の温度の意味。食品業界で強まるという文脈に合わない。", "段差": "高低差の意味。「強まる」とは言わず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "トレンド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "音楽のトレンドで、耳の痛みを治療した。", "explanation": "ここは〈治療〉の手段の意味ではない。トレンドは流行の傾向で、病気を治す手段にはならない。"}, {"text": "音楽のトレンドで、鍋の湯を沸かした。", "explanation": "ここは〈燃料〉の意味。トレンドは流行の傾向で、火を起こす材料にはならない。"}, {"text": "音楽のトレンドは、歌手が歌える年齢の上限だ。", "explanation": "ここは〈上限〉の意味。トレンドは流行の傾向で、年齢や数値の上限を示さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39107, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は、トレンドに服を買う。", "corrected_sentence": "兄は、トレンドの服を買う。", "error_description": "「トレンドに」は誤り。「トレンドの服」と連体修飾の「の」にすると正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39107, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は音楽のトレンドをくわしい。", "corrected_sentence": "彼は音楽のトレンドにくわしい。", "error_description": "「くわしい」は「〜に詳しい」と相手を「に」で表す。「トレンドを」は誤りで、「トレンドに」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39108, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「整理する」の目的語を示す助詞で、「衣類を整理しました」と正しく続く。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞。衣類は整理される対象なので、「が」では文が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。「整理する」の対象には使えない。"}, {"text": "に", "is_correct": false, "explanation": "着点や相手を示す助詞。「整理する」の対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "「整理する」の目的語を示す助詞で、「衣類を整理しました」と正しく続く。", "が": "主語を示す助詞。衣類は整理される対象なので、「が」では文が合わない。", "へ": "方向を示す助詞。「整理する」の対象には使えない。", "に": "着点や相手を示す助詞。「整理する」の対象には合わない。"}, "error_tags": {"が": "主語を示す助詞", "へ": "方向を示す助詞", "に": "着点・相手を示す助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
