INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39108, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体に着るもののことです。シャツやズボンなどです。", "primary_collocate": null, "pronunciation": "いるい", "ipa": "iɾɯi", "syllable_count": 3, "sentences": [{"text": "衣類を洗濯機に入れて、スイッチを押しました。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "衣類[いるい]を洗濯機[せんたくき]に入[い]れて、スイッチを押[お]しました。", "sentence_source": "generated"}, {"text": "引っ越しの前に、いらない衣類を整理しました。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの前[まえ]に、いらない衣類[いるい]を整理[せいり]しました。", "sentence_source": "generated"}, {"text": "冬用の衣類は、箱に入れて押し入れにしまいます。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "冬用[ふゆよう]の衣類[いるい]は、箱[はこ]に入[い]れて押[お]し入[い]れにしまいます。", "sentence_source": "generated"}, {"text": "この店では、シャツやズボンなどの衣類を売っています。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "この店[みせ]では、シャツやズボンなどの衣類[いるい]を売[う]っています。", "sentence_source": "generated"}, {"text": "旅行のかばんには、三日分の衣類を入れました。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "旅行[りょこう]のかばんには、三日分[みっかぶん]の衣類[いるい]を入[い]れました。", "sentence_source": "generated"}, {"text": "雨にぬれた衣類は、早く乾かさないといけません。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれた衣類[いるい]は、早[はや]く乾[かわ]かさないといけません。", "sentence_source": "generated"}, {"text": "子ども用の衣類は、すぐに小さくなってしまいます。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "子[こ]ども用[よう]の衣類[いるい]は、すぐに小[ちい]さくなってしまいます。", "sentence_source": "generated"}, {"text": "衣類の汚れが落ちなかったので、もう一度洗いました。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "衣類[いるい]の汚[よご]れが落[お]ちなかったので、もう一度[いちど]洗[あら]いました。", "sentence_source": "generated"}, {"text": "寒い地方へ行くので、あたたかい衣類を用意しました。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "寒[さむ]い地方[ちほう]へ行[い]くので、あたたかい衣類[いるい]を用意[ようい]しました。", "sentence_source": "generated"}, {"text": "古い衣類を、必要な人に送ることにしました。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "古[ふる]い衣類[いるい]を、必要[ひつよう]な人[ひと]に送[おく]ることにしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "衣類", "label": "基本形"}, {"form": "衣類の", "label": "連体句"}], "register": "標準", "sense_fingerprint": "体に着る物、シャツやズボンなど", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eedbe05-f7a1-46a5-8c64-cbc0a50099f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39108, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "衣類", "is_correct": true, "explanation": "「衣類を洗濯機に入れて」と続き、洗える衣類を表して空所に入る。"}, {"text": "切手", "is_correct": false, "explanation": "「切手を洗濯機に入れて」は意味が通らない。"}, {"text": "果物", "is_correct": false, "explanation": "「果物を洗濯機に入れて」は意味が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓を洗濯機に入れて」は意味が通らない。"}], "explanations": {"衣類": "「衣類を洗濯機に入れて」と続き、洗える衣類を表して空所に入る。", "切手": "「切手を洗濯機に入れて」は意味が通らない。", "果物": "「果物を洗濯機に入れて」は意味が通らない。", "窓": "「窓を洗濯機に入れて」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "衣類"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このシャツは薄くて丈夫な衣類でできています。", "explanation": "ここは〈布〉の意味（材料）。衣類は着る物のことで、材料そのものは指さない。"}, {"text": "この料理は新鮮な衣類を使っています。", "explanation": "ここは〈食材〉の意味。衣類は身に着ける物で、料理の材料には使わない。"}, {"text": "この庭には衣類を植えます。", "explanation": "ここは〈植物〉の意味（育てる草木）。衣類は植えられないので、庭の植物の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39108, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衣類", "is_correct": true, "explanation": "「子ども用の衣類」となり、子どもが着る物を表して空所に入る。"}, {"text": "調味料", "is_correct": false, "explanation": "「子ども用の調味料は、すぐに小さくなる」は意味が通らない。"}, {"text": "氷山", "is_correct": false, "explanation": "「子ども用の氷山」は意味が通らない。"}, {"text": "灯台", "is_correct": false, "explanation": "「子ども用の灯台」は意味が通らない。"}], "explanations": {"衣類": "「子ども用の衣類」となり、子どもが着る物を表して空所に入る。", "調味料": "「子ども用の調味料は、すぐに小さくなる」は意味が通らない。", "氷山": "「子ども用の氷山」は意味が通らない。", "灯台": "「子ども用の灯台」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "衣類"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この車は衣類で走ります。", "explanation": "ここは〈燃料〉の意味（燃やして使う物）。衣類は燃料にはならないので、車を動かす物の意味では使わない。"}, {"text": "のどが渇いたので、冷たい衣類を飲んだ。", "explanation": "ここは〈飲料〉の意味。衣類は飲めないので、飲む物には使わない。"}, {"text": "料理に衣類を加えます。", "explanation": "ここは〈調味料〉の意味。衣類は食べ物に加えるものではないので、料理には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
