INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39109, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "衣服。身に着ける物の総称。", "primary_collocate": null, "pronunciation": "いるい", "ipa": "iɾɯi", "syllable_count": 3, "sentences": [{"text": "災害のとき、被災した人々に衣類が届けられました。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "災害[さいがい]のとき、被災[ひさい]した人々[ひとびと]に衣類[いるい]が届[とど]けられました。", "sentence_source": "generated"}, {"text": "衣類の素材には、綿や毛などがあります。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "衣類[いるい]の素材[そざい]には、綿[めん]や毛[け]などがあります。", "sentence_source": "generated"}, {"text": "衣類の売り場は、このビルの三階にあります。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "衣類[いるい]の売[う]り場[ば]は、このビルの三階[さんがい]にあります。", "sentence_source": "generated"}, {"text": "不要になった衣類は、回収箱に入れてください。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "不要[ふよう]になった衣類[いるい]は、回収箱[かいしゅうばこ]に入[い]れてください。", "sentence_source": "generated"}, {"text": "衣類のたたみ方を、動画で説明しています。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "衣類[いるい]のたたみ方[かた]を、動画[どうが]で説明[せつめい]しています。", "sentence_source": "generated"}, {"text": "衣類は水洗いできるものと、できないものがあります。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "衣類[いるい]は水洗[みずあら]いできるものと、できないものがあります。", "sentence_source": "generated"}, {"text": "荷物の中身は、本や衣類などでした。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "荷物[にもつ]の中身[なかみ]は、本[ほん]や衣類[いるい]などでした。", "sentence_source": "generated"}, {"text": "この会社は、衣類を海外から輸入して販売しています。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、衣類[いるい]を海外[かいがい]から輸入[ゆにゅう]して販売[はんばい]しています。", "sentence_source": "generated"}, {"text": "衣類の虫食いを防ぐために、防虫剤を入れます。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "衣類[いるい]の虫食[むしく]いを防[ふせ]ぐために、防虫剤[ぼうちゅうざい]を入[い]れます。", "sentence_source": "generated"}, {"text": "衣類全体の値段が上がり、家計に影響が出ています。", "target_word": "衣類", "complexity_tier": "T3", "furigana": "衣類[いるい]全体[ぜんたい]の値段[ねだん]が上[あ]がり、家計[かけい]に影響[えいきょう]が出[で]ています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "衣類", "label": "基本形"}, {"form": "衣類の", "label": "連体句"}], "register": "やや硬い", "sense_fingerprint": "衣服全般を指す総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eedbe05-f7a1-46a5-8c64-cbc0a50099f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39109, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "衣類", "is_correct": true, "explanation": "「衣類が届けられました」と続き、被災した人々に届けられる物を表して空所に入る。"}, {"text": "天気", "is_correct": false, "explanation": "「天気が届けられました」は意味が通らない。"}, {"text": "湖", "is_correct": false, "explanation": "「湖が届けられました」は意味が通らない。"}, {"text": "星", "is_correct": false, "explanation": "「星が届けられました」は意味が通らない。"}], "explanations": {"衣類": "「衣類が届けられました」と続き、被災した人々に届けられる物を表して空所に入る。", "天気": "「天気が届けられました」は意味が通らない。", "湖": "「湖が届けられました」は意味が通らない。", "星": "「星が届けられました」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "衣類"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このカバンは丈夫な衣類でできています。", "explanation": "ここは〈布〉の意味（材料）。衣類は身に着ける物で、カバンの材料としては言えない。"}, {"text": "鍋に衣類を入れて煮ます。", "explanation": "ここは〈食材〉の意味。衣類は料理の材料にならないので、鍋で煮る物には使わない。"}, {"text": "飲料を温めて、衣類を飲みます。", "explanation": "ここは〈飲み物〉の意味。衣類は飲めないので、飲み物の代わりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39109, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衣類", "is_correct": true, "explanation": "「本や衣類などでした」と続き、荷物の中身として正しく空所に入る。"}, {"text": "雲", "is_correct": false, "explanation": "「本や雲などでした」は意味が通らない。"}, {"text": "三角形", "is_correct": false, "explanation": "「本や三角形などでした」は意味が通らない。"}, {"text": "気温", "is_correct": false, "explanation": "「本や気温などでした」は意味が通らない。"}], "explanations": {"衣類": "「本や衣類などでした」と続き、荷物の中身として正しく空所に入る。", "雲": "「本や雲などでした」は意味が通らない。", "三角形": "「本や三角形などでした」は意味が通らない。", "気温": "「本や気温などでした」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "衣類"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は新鮮な衣類を、ジャムにして売っています。", "explanation": "ここは〈果物〉の意味。衣類は身に着ける物で、ジャムの材料にはならない。"}, {"text": "この衣類は水で薄めてから使います。", "explanation": "ここは〈薬品〉の意味。衣類は薄めて使うものではないので、この言葉は合わない。"}, {"text": "この料理には衣類を少し加えます。", "explanation": "ここは〈香辛料〉の意味。衣類は料理に加えるものではないので、この言葉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39109, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い地域の人に、暖かい衣類が送りました。", "corrected_sentence": "寒い地域の人に、暖かい衣類を送りました。", "error_description": "「送る」は送られる物を「を」で示す。「が」は誤りで、正しくは「衣類を送りました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39109, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この会社は、衣類が国内で作って販売しています。", "corrected_sentence": "この会社は、衣類を国内で作って販売しています。", "error_description": "「作る」は作る物を「を」で示す。「が」は誤りで、正しくは「衣類を国内で作って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
