INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39110, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す「を」。「特徴を挙げる」の対象になるので正しい。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表す「で」。「作品の特徴で、三つ挙げる」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。特徴は行き先ではないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「作品の特徴の、三つ挙げてください」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す「を」。「特徴を挙げる」の対象になるので正しい。", "で": "手段や場所を表す「で」。「作品の特徴で、三つ挙げる」では意味が通らない。", "へ": "方向を表す「へ」。特徴は行き先ではないので合わない。", "の": "連体修飾の「の」。「作品の特徴の、三つ挙げてください」では文が成り立たない。"}, "error_tags": {"で": "手段・場所を表す格", "へ": "方向を表す格", "の": "連体修飾の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39110, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "そのものやことがらを、ほかのものと区別できるようにする、目立つ点。", "primary_collocate": null, "pronunciation": "とくちょう", "ipa": "tokɯtɕoː", "syllable_count": 4, "sentences": [{"text": "この犬の特徴は、耳が大きいことです。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "この犬[いぬ]の特徴[とくちょう]は、耳[みみ]が大[おお]きいことです。", "sentence_source": "generated"}, {"text": "日本語の特徴について、先生が説明しました。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "日本語[にほんご]の特徴[とくちょう]について、先生[せんせい]が説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "犯人の特徴を、警察に詳しく伝えました。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "犯人[はんにん]の特徴[とくちょう]を、警察[けいさつ]に詳[くわ]しく伝[つた]えました。", "sentence_source": "generated"}, {"text": "この車は、小さくて燃費がよいという特徴があります。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "この車[くるま]は、小[ちい]さくて燃費[ねんぴ]がよいという特徴[とくちょう]があります。", "sentence_source": "generated"}, {"text": "双子ですが、声に特徴があるので、すぐ区別できます。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "双子[ふたご]ですが、声[こえ]に特徴[とくちょう]があるので、すぐ区別[くべつ]できます。", "sentence_source": "generated"}, {"text": "町ごとに、それぞれの特徴があって面白いです。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "町[まち]ごとに、それぞれの特徴[とくちょう]があって面白[おもしろ]いです。", "sentence_source": "generated"}, {"text": "彼の絵の特徴は、明るい色づかいです。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "彼[かれ]の絵[え]の特徴[とくちょう]は、明[あか]るい色[いろ]づかいです。", "sentence_source": "generated"}, {"text": "作品の特徴を、三つ挙げてください。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "作品[さくひん]の特徴[とくちょう]を、三[みっ]つ挙[あ]げてください。", "sentence_source": "generated"}, {"text": "北国の特徴は、冬が長いことです。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "北国[きたぐに]の特徴[とくちょう]は、冬[ふゆ]が長[なが]いことです。", "sentence_source": "generated"}, {"text": "動物ごとの特徴を、図鑑で調べました。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "動物[どうぶつ]ごとの特徴[とくちょう]を、図鑑[ずかん]で調[しら]べました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "特徴", "label": "基本形"}, {"form": "特徴の", "label": "連体句"}], "register": "標準", "sense_fingerprint": "他と区別できる目立つ点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: 色づか (Zipf 1.64)']::text[], '4eedbe05-f7a1-46a5-8c64-cbc0a50099f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39110, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特徴", "is_correct": true, "explanation": "ここは「他と区別できる目立つ点」の意味。耳が大きいことを、この犬の目立つ点として述べている。"}, {"text": "値段", "is_correct": false, "explanation": "価格を表す語だが、耳の大きさを値段として述べると意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "気象の状態を表す語で、犬の耳について述べる文には入らない。"}, {"text": "年齢", "is_correct": false, "explanation": "年数を表す語で、耳が大きいことを年齢として述べるのは合わない。"}], "explanations": {"特徴": "ここは「他と区別できる目立つ点」の意味。耳が大きいことを、この犬の目立つ点として述べている。", "値段": "価格を表す語だが、耳の大きさを値段として述べると意味が通らない。", "天気": "気象の状態を表す語で、犬の耳について述べる文には入らない。", "年齢": "年数を表す語で、耳が大きいことを年齢として述べるのは合わない。"}, "sentence_index": 0, "correct_answer": "特徴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この家の特徴は、三千万円です。", "explanation": "ここは〈価格〉の意味。特徴は性質や目立つ点を指し、金額は表さないので合わない。"}, {"text": "彼は英語の特徴が得意で、通訳の仕事もしている。", "explanation": "ここは〈特技〉の意味。特徴は見た目や性質の目立つ点を指し、得意な技能には使わないので合わない。"}, {"text": "彼は会社で大切な特徴を果たしている。", "explanation": "ここは〈役割〉の意味。特徴は性質や目立つ点で、任された働きを表す〈役割〉とは違い、「果たす」とは合わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39110, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特徴", "is_correct": true, "explanation": "ここは「他と区別できる目立つ点」の意味。絵の目立つ点として明るい色づかいを挙げている。"}, {"text": "身長", "is_correct": false, "explanation": "人や動物の背の高さを表す語で、絵の性質を述べる文には入らない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語で、絵の色づかいを述べる文には合わない。"}, {"text": "年収", "is_correct": false, "explanation": "収入を表す語で、絵の目立つ点を述べる文には入らない。"}], "explanations": {"特徴": "ここは「他と区別できる目立つ点」の意味。絵の目立つ点として明るい色づかいを挙げている。", "身長": "人や動物の背の高さを表す語で、絵の性質を述べる文には入らない。", "季節": "時期を表す語で、絵の色づかいを述べる文には合わない。", "年収": "収入を表す語で、絵の目立つ点を述べる文には入らない。"}, "sentence_index": 6, "correct_answer": "特徴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この計画の特徴を、来年までに達成しました。", "explanation": "ここは〈目標〉の意味。目標は達成するものだが、特徴は性質や目立つ点なので「達成する」とは合わないので合わない。"}, {"text": "この布の特徴を、一晩干しました。", "explanation": "ここは〈干す〉の意味。特徴は性質や目立つ点で、布のように干す対象ではないので合わない。"}, {"text": "このレポートの特徴は、来週の金曜日です。", "explanation": "ここは〈締め切り〉の意味。特徴は性質や目立つ点で、提出の期限の日付は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39110, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このアプリの特徴を、動作が軽いことです。", "corrected_sentence": "このアプリの特徴は、動作が軽いことです。", "error_description": "助詞の誤り。「特徴」に続けるのは主題を示す「は」が正しい。「を」だと、後ろの説明文「動作が軽いことです」と文がつながらないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39110, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この会社の特徴を、三つ壊してください。", "corrected_sentence": "この会社の特徴を、三つ挙げてください。", "error_description": "動詞の誤り。正しくは「挙げて」（特徴を挙げる）。「壊して」は特徴と結びつかず、意味が通らないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
