INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39112, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを買うこと。", "primary_collocate": null, "pronunciation": "こうにゅう", "ipa": "koːɲɯː", "syllable_count": 4, "sentences": [{"text": "新しいパソコンの購入を、先月決めました。", "target_word": "購入", "complexity_tier": "T3", "furigana": "新[あたら]しいパソコンの購入[こうにゅう]を、先月[せんげつ]決[き]めました。", "sentence_source": "generated"}, {"text": "本の購入は、インターネットで済ませました。", "target_word": "購入", "complexity_tier": "T3", "furigana": "本[ほん]の購入[こうにゅう]は、インターネットで済[す]ませました。", "sentence_source": "generated"}, {"text": "家を購入するために、毎月お金をためています。", "target_word": "購入", "complexity_tier": "T3", "furigana": "家[いえ]を購入[こうにゅう]するために、毎月[まいつき]お金[かね]をためています。", "sentence_source": "generated"}, {"text": "切符を購入してから、電車に乗ってください。", "target_word": "購入", "complexity_tier": "T3", "furigana": "切符[きっぷ]を購入[こうにゅう]してから、電車[でんしゃ]に乗[の]ってください。", "sentence_source": "generated"}, {"text": "購入した靴が小さかったので、店で交換しました。", "target_word": "購入", "complexity_tier": "T3", "furigana": "購入[こうにゅう]した靴[くつ]が小[ちい]さかったので、店[みせ]で交換[こうかん]しました。", "sentence_source": "generated"}, {"text": "初めての車の購入に、父がついて来てくれました。", "target_word": "購入", "complexity_tier": "T3", "furigana": "初[はじ]めての車[くるま]の購入[こうにゅう]に、父[ちち]がついて来[き]てくれました。", "sentence_source": "generated"}, {"text": "食べ物の購入は、いつも駅前のスーパーでします。", "target_word": "購入", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]の購入[こうにゅう]は、いつも駅前[えきまえ]のスーパーでします。", "sentence_source": "generated"}, {"text": "日用品を購入するとき、安さを一番に考えます。", "target_word": "購入", "complexity_tier": "T3", "furigana": "日用品[にちようひん]を購入[こうにゅう]するとき、安[やす]さを一番[いちばん]に考[かんが]えます。", "sentence_source": "generated"}, {"text": "彼は誕生日の贈り物を購入しに、デパートへ行きました。", "target_word": "購入", "complexity_tier": "T3", "furigana": "彼[かれ]は誕生日[たんじょうび]の贈[おく]り物[もの]を購入[こうにゅう]しに、デパートへ行[い]きました。", "sentence_source": "generated"}, {"text": "購入する前に、ほかの店の値段も調べました。", "target_word": "購入", "complexity_tier": "T3", "furigana": "購入[こうにゅう]する前[まえ]に、ほかの店[みせ]の値段[ねだん]も調[しら]べました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "購入する", "label": "基本形"}, {"form": "購入した", "label": "過去形"}, {"form": "購入して", "label": "て形"}], "register": "やや硬い", "sense_fingerprint": "物を買うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eedbe05-f7a1-46a5-8c64-cbc0a50099f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39112, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "購入", "is_correct": true, "explanation": "ここは「代金を払って買うこと」の意味。パソコンを買うことを先月決めたと述べている。"}, {"text": "天気", "is_correct": false, "explanation": "気象の状態を表す語で、パソコンを決める文には入らない。"}, {"text": "翻訳", "is_correct": false, "explanation": "文章を別の言語に訳すことで、パソコンを決めた文脈には合わない。"}, {"text": "出席", "is_correct": false, "explanation": "会合に加わることで、物を選ぶ文脈では意味が通らない。"}], "explanations": {"購入": "ここは「代金を払って買うこと」の意味。パソコンを買うことを先月決めたと述べている。", "天気": "気象の状態を表す語で、パソコンを決める文には入らない。", "翻訳": "文章を別の言語に訳すことで、パソコンを決めた文脈には合わない。", "出席": "会合に加わることで、物を選ぶ文脈では意味が通らない。"}, "sentence_index": 0, "correct_answer": "購入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休みの予定を購入しました。", "explanation": "ここは〈立てる〉の意味。予定は立てたり決めたりするもので、代金を払って得る購入とは合わないので合わない。"}, {"text": "友達から譲ってもらった本を購入しました。", "explanation": "ここは〈入手〉の意味。購入は代金を払って買うことで、譲り受けた物には使わないので合わない。"}, {"text": "会議では、彼の案を購入することに決まりました。", "explanation": "ここは〈採用〉の意味。購入は代金を払って物を得ることで、案や意見には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39112, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "購入", "is_correct": true, "explanation": "ここは「代金を払って買うこと」の意味。食べ物を買う場所と頻度を述べる文に合う。"}, {"text": "掃除", "is_correct": false, "explanation": "室内を清める作業で、食べ物の購入を述べる文には入らない。"}, {"text": "修理", "is_correct": false, "explanation": "壊れた物を直すことで、食べ物には使えない。"}, {"text": "散歩", "is_correct": false, "explanation": "歩き回ることで、買い物の話の文脈では意味が通らない。"}], "explanations": {"購入": "ここは「代金を払って買うこと」の意味。食べ物を買う場所と頻度を述べる文に合う。", "掃除": "室内を清める作業で、食べ物の購入を述べる文には入らない。", "修理": "壊れた物を直すことで、食べ物には使えない。", "散歩": "歩き回ることで、買い物の話の文脈では意味が通らない。"}, "sentence_index": 6, "correct_answer": "購入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "被災地のために、食料の寄付を購入しました。", "explanation": "ここは〈寄付する〉の意味。寄付は無償で贈ることで、代金を払って得る購入とは合わないので合わない。"}, {"text": "彼は明日の天気を購入しに、スタジアムへ行きます。", "explanation": "天気は代金を払って買うものではないので、購入とは合わないので合わない。"}, {"text": "図書館で、借りる手続きを購入しました。", "explanation": "ここは〈申し込む〉の意味。手続きは行ったり申し込んだりするもので、代金を払って得る購入とは合わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39112, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店での購入を、現金でもできます。", "corrected_sentence": "この店での購入は、現金でもできます。", "error_description": "助詞の誤り。正しくは主題を示す「は」。「を」では「できます」と結びつかず、文が成り立たないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39112, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この本は、書店で購入できれます。", "corrected_sentence": "この本は、書店で購入できます。", "error_description": "形の誤り。「できる」はすでに可能の形なので、さらに「れる」を重ねた「できれます」は誤り。正しくは「購入できます」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39113, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の「の」。「購入の代金」と、代金が購入に関わるものだと示すので正しい。"}, {"text": "に", "is_correct": false, "explanation": "「購入に代金は」では「に」の結びつきが不自然で、文がつながらない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表す「で」。「購入で代金は」では代金の話題と合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」。「購入を代金は」では文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の「の」。「購入の代金」と、代金が購入に関わるものだと示すので正しい。", "に": "「購入に代金は」では「に」の結びつきが不自然で、文がつながらない。", "で": "手段や場所を表す「で」。「購入で代金は」では代金の話題と合わない。", "を": "目的語を示す「を」。「購入を代金は」では文が成り立たない。"}, "error_tags": {"に": "相手・結果を表す格", "で": "手段・場所を表す格", "を": "目的語を表す格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
