INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39113, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "品物やサービスを得るために、代金を支払うこと。", "primary_collocate": null, "pronunciation": "こうにゅう", "ipa": "koːɲɯː", "syllable_count": 4, "sentences": [{"text": "商品の購入には、クレジットカードが使えます。", "target_word": "購入", "complexity_tier": "T3", "furigana": "商品[しょうひん]の購入[こうにゅう]には、クレジットカードが使[つか]えます。", "sentence_source": "generated"}, {"text": "購入の代金は、受け取りのときに払ってください。", "target_word": "購入", "complexity_tier": "T3", "furigana": "購入[こうにゅう]の代金[だいきん]は、受[う]け取[と]りのときに払[はら]ってください。", "sentence_source": "generated"}, {"text": "ネットで映画を購入して、家で見ました。", "target_word": "購入", "complexity_tier": "T3", "furigana": "ネットで映画[えいが]を購入[こうにゅう]して、家[いえ]で見[み]ました。", "sentence_source": "generated"}, {"text": "購入した品物は、三日後に家に届きます。", "target_word": "購入", "complexity_tier": "T3", "furigana": "購入[こうにゅう]した品物[しなもの]は、三日後[みっかご]に家[いえ]に届[とど]きます。", "sentence_source": "generated"}, {"text": "会員になると、購入金額に応じて割引があります。", "target_word": "購入", "complexity_tier": "T3", "furigana": "会員[かいいん]になると、購入[こうにゅう]金額[きんがく]に応[おう]じて割引[わりびき]があります。", "sentence_source": "generated"}, {"text": "年間パスの購入で、何度でも入場できます。", "target_word": "購入", "complexity_tier": "T3", "furigana": "年間[ねんかん]パスの購入[こうにゅう]で、何度[なんど]でも入場[にゅうじょう]できます。", "sentence_source": "generated"}, {"text": "購入の手続きをするため、窓口で名前を書きました。", "target_word": "購入", "complexity_tier": "T3", "furigana": "購入[こうにゅう]の手続[てつづ]きをするため、窓口[まどぐち]で名前[なまえ]を書[か]きました。", "sentence_source": "generated"}, {"text": "購入前に、レビューを読んで品質を確認します。", "target_word": "購入", "complexity_tier": "T3", "furigana": "購入前[こうにゅうまえ]に、レビューを読[よ]んで品質[ひんしつ]を確認[かくにん]します。", "sentence_source": "generated"}, {"text": "代金を払えば、アプリ内で追加のサービスを購入できます。", "target_word": "購入", "complexity_tier": "T3", "furigana": "代金[だいきん]を払[はら]えば、アプリ内[ない]で追加[ついか]のサービスを購入[こうにゅう]できます。", "sentence_source": "generated"}, {"text": "購入の領収書は、なくさないように保管してください。", "target_word": "購入", "complexity_tier": "T3", "furigana": "購入[こうにゅう]の領収書[りょうしゅうしょ]は、なくさないように保管[ほかん]してください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "購入する", "label": "基本形"}, {"form": "購入した", "label": "過去形"}, {"form": "購入できる", "label": "可能形"}], "register": "やや硬い", "sense_fingerprint": "代金を払って品物やサービスを得ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eedbe05-f7a1-46a5-8c64-cbc0a50099f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39113, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "購入", "is_correct": true, "explanation": "ここは「代金を払って物を得ること」の意味。商品を得る際にクレジットカードが使えると述べている。"}, {"text": "出席", "is_correct": false, "explanation": "会合に加わることで、商品の支払い方法の文には合わない。"}, {"text": "写真", "is_correct": false, "explanation": "撮った画像を表す語で、支払い方法の文脈には入らない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語で、支払い方法の文脈では意味が通らない。"}], "explanations": {"購入": "ここは「代金を払って物を得ること」の意味。商品を得る際にクレジットカードが使えると述べている。", "出席": "会合に加わることで、商品の支払い方法の文には合わない。", "写真": "撮った画像を表す語で、支払い方法の文脈には入らない。", "季節": "時期を表す語で、支払い方法の文脈では意味が通らない。"}, "sentence_index": 0, "correct_answer": "購入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このサービスは、無料で購入できます。", "explanation": "ここは〈入手〉の意味。購入は代金を払うことを含むので、無料のサービスには使わないので合わない。"}, {"text": "代金を購入して、店を出ました。", "explanation": "ここは〈支払う〉の意味。代金は払うもので、購入するのは品物やサービスなので合わない。"}, {"text": "庭の雑草を購入して、一日で全部抜きました。", "explanation": "ここは〈抜く〉の意味。購入は代金を払って得ることで、雑草を取り除く行為には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39113, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "購入", "is_correct": true, "explanation": "ここは「代金を払って物を得ること」の意味。購入の手続きとして名前を書いたと述べている。"}, {"text": "味", "is_correct": false, "explanation": "味覚を表す語で、手続きの話には入らない。"}, {"text": "散歩", "is_correct": false, "explanation": "歩き回ることで、手続きの文脈では意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "気象の状態を表す語で、手続きの文には入らない。"}], "explanations": {"購入": "ここは「代金を払って物を得ること」の意味。購入の手続きとして名前を書いたと述べている。", "味": "味覚を表す語で、手続きの話には入らない。", "散歩": "歩き回ることで、手続きの文脈では意味が通らない。", "天気": "気象の状態を表す語で、手続きの文には入らない。"}, "sentence_index": 6, "correct_answer": "購入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "使わなくなった家電の処分を購入しました。", "explanation": "ここは〈処分する〉の意味。処分は捨てたり片付けたりすることで、代金を払って得る購入とは合わないので合わない。"}, {"text": "この商品を、冷蔵庫に購入しました。", "explanation": "ここは〈しまう〉の意味。購入は代金を払って得る行為で、物を置く場所を指す文には使わないので合わない。"}, {"text": "空を購入して、雲を眺めました。", "explanation": "空は代金を払って得るものではないので、購入とは合わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39113, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店では、購入で身分証が必要です。", "corrected_sentence": "この店では、購入には身分証が必要です。", "error_description": "助詞の誤り。「購入」に続けるのは「には」が自然（〜には〜が必要）。「で」では「購入で身分証が必要」となり、文として成り立たないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39113, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "アプリの購入を撤去するには、設定画面を開いてください。", "corrected_sentence": "アプリの購入を取り消すには、設定画面を開いてください。", "error_description": "動詞の誤り。正しくは「取り消す」（購入を取り消す）。「撤去する」は物を取り除く意味で、購入には使わないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
