INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39114, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "ほとんど、または、たいていは。", "primary_collocate": null, "pronunciation": "おもに", "ipa": "omoɲi", "syllable_count": 3, "sentences": [{"text": "私は主に朝、図書館で勉強します。", "target_word": "主に", "complexity_tier": "T3", "furigana": "私[わたし]は主[おも]に朝[あさ]、図書館[としょかん]で勉強[べんきょう]します。", "sentence_source": "generated"}, {"text": "この店のお客さんは、主に近所に住む人です。", "target_word": "主に", "complexity_tier": "T3", "furigana": "この店[みせ]のお客[きゃく]さんは、主[おも]に近所[きんじょ]に住[す]む人[ひと]です。", "sentence_source": "generated"}, {"text": "弟は主に野菜を食べて、肉はあまり食べません。", "target_word": "主に", "complexity_tier": "T3", "furigana": "弟[おとうと]は主[おも]に野菜[やさい]を食[た]べて、肉[にく]はあまり食[た]べません。", "sentence_source": "generated"}, {"text": "夏は主に海へ行って、冬は山へ行きます。", "target_word": "主に", "complexity_tier": "T3", "furigana": "夏[なつ]は主[おも]に海[うみ]へ行[い]って、冬[ふゆ]は山[やま]へ行[い]きます。", "sentence_source": "generated"}, {"text": "彼女は主に英語の本を読んでいます。", "target_word": "主に", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は主[おも]に英語[えいご]の本[ほん]を読[よ]んでいます。", "sentence_source": "generated"}, {"text": "この辺りでは、主に米を作っています。", "target_word": "主に", "complexity_tier": "T3", "furigana": "この辺[あた]りでは、主[おも]に米[こめ]を作[つく]っています。", "sentence_source": "generated"}, {"text": "週末は主に家で過ごしますが、たまに出かけます。", "target_word": "主に", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]は主[おも]に家[いえ]で過[す]ごしますが、たまに出[で]かけます。", "sentence_source": "generated"}, {"text": "授業では主に会話の練習をしました。", "target_word": "主に", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]では主[おも]に会話[かいわ]の練習[れんしゅう]をしました。", "sentence_source": "generated"}, {"text": "私が使うのは主にこの道具で、ほかはほとんど使いません。", "target_word": "主に", "complexity_tier": "T3", "furigana": "私[わたし]が使[つか]うのは主[おも]にこの道具[どうぐ]で、ほかはほとんど使[つか]いません。", "sentence_source": "generated"}, {"text": "日本の夏の暑さは、主に湿度の高さによるものです。", "target_word": "主に", "complexity_tier": "T3", "furigana": "日本[にほん]の夏[なつ]の暑[あつ]さは、主[おも]に湿度[しつど]の高[たか]さによるものです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主に", "label": "基本形"}], "register": "標準", "sense_fingerprint": "ほとんど、たいていは", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eedbe05-f7a1-46a5-8c64-cbc0a50099f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39114, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主に", "is_correct": true, "explanation": "ここは「ほとんど、たいていは」の意味。朝に図書館で勉強するのが大体の習慣だと述べている。"}, {"text": "全然", "is_correct": false, "explanation": "打ち消しの文と結びつく副詞で、肯定の「勉強します」とは合わない。"}, {"text": "決して", "is_correct": false, "explanation": "打ち消しの表現と結びつく副詞で、肯定文では使えない。"}, {"text": "少しも", "is_correct": false, "explanation": "打ち消しと結びつく副詞で、肯定文の「勉強します」には合わない。"}], "explanations": {"主に": "ここは「ほとんど、たいていは」の意味。朝に図書館で勉強するのが大体の習慣だと述べている。", "全然": "打ち消しの文と結びつく副詞で、肯定の「勉強します」とは合わない。", "決して": "打ち消しの表現と結びつく副詞で、肯定文では使えない。", "少しも": "打ち消しと結びつく副詞で、肯定文の「勉強します」には合わない。"}, "sentence_index": 0, "correct_answer": "主に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は主に顔を出しただけで、すぐ帰りました。", "explanation": "ここは〈ただ（〜だけ）〉の意味。主には「ほとんど・たいてい」の意味で、〈ただ〉の限定の意味にはならないので合わない。"}, {"text": "彼は主に仕えて、十年になります。", "explanation": "ここは〈主君〉の読みの意味。主（あるじ）は副詞の主にとは別の語なので合わない。"}, {"text": "彼は主に一度だけ、海へ行きました。", "explanation": "ここは〈一度だけ〉の意味。主には「ほとんど・たいてい」の意味で、限られた一回の出来事とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39114, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主に", "is_correct": true, "explanation": "ここは「ほとんど、たいてい」の意味。週末は家で過ごすことが多いと述べている。"}, {"text": "全く", "is_correct": false, "explanation": "打ち消しと結びつく副詞で、肯定の「過ごします」とは合わない。"}, {"text": "一切", "is_correct": false, "explanation": "全面的な否定を表す語で、肯定文には使えない。"}, {"text": "断じて", "is_correct": false, "explanation": "強い否定を表す語で、肯定文の「過ごします」とは合わない。"}], "explanations": {"主に": "ここは「ほとんど、たいてい」の意味。週末は家で過ごすことが多いと述べている。", "全く": "打ち消しと結びつく副詞で、肯定の「過ごします」とは合わない。", "一切": "全面的な否定を表す語で、肯定文には使えない。", "断じて": "強い否定を表す語で、肯定文の「過ごします」とは合わない。"}, "sentence_index": 6, "correct_answer": "主に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は舞台の主に選ばれました。", "explanation": "ここは〈主役〉の意味。主には副詞で、役割の名前の代わりにはならないので合わない。"}, {"text": "彼は城の主に招かれ、宴に加わりました。", "explanation": "ここは〈城主〉の意味。主（あるじ）は名詞で、副詞の主にとは別の語なので合わない。"}, {"text": "彼は山の主に出会いました。", "explanation": "ここは〈ぬし〉の意味。主（ぬし）は名詞で、副詞の主にとは別の語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39114, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私の家では、主で父が料理を作ります。", "corrected_sentence": "私の家では、主に父が料理を作ります。", "error_description": "語尾の誤り。副詞「主に」の語尾は「に」が正しい。「主で」という形は存在しないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39114, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は電車で主な通勤します。", "corrected_sentence": "私は電車で主に通勤します。", "error_description": "形の誤り。副詞「主に」を形容詞「主な」に変えた誤り。「主な」は名詞を修飾する形なので、動詞「通勤します」は修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
