INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39115, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "大部分において。特に他のものと比べて、そのことが中心であることを示す。", "primary_collocate": null, "pronunciation": "おもに", "ipa": "omoɲi", "syllable_count": 3, "sentences": [{"text": "この会社の売り上げは、主に海外から来ています。", "target_word": "主に", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]の売[う]り上[あ]げは、主[おも]に海外[かいがい]から来[き]ています。", "sentence_source": "generated"}, {"text": "今回の事故は、主に不注意が原因でした。", "target_word": "主に", "complexity_tier": "T3", "furigana": "今回[こんかい]の事故[じこ]は、主[おも]に不注意[ふちゅうい]が原因[げんいん]でした。", "sentence_source": "generated"}, {"text": "参加者は主に二十代の若者で、年配の人は少なかったです。", "target_word": "主に", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]は主[おも]に二十代[にじゅうだい]の若者[わかもの]で、年配[ねんぱい]の人[ひと]は少[すく]なかったです。", "sentence_source": "generated"}, {"text": "この薬は、主に頭痛をおさえるために使われます。", "target_word": "主に", "complexity_tier": "T3", "furigana": "この薬[くすり]は、主[おも]に頭痛[ずつう]をおさえるために使[つか]われます。", "sentence_source": "generated"}, {"text": "試験では、主に文法の問題が出ました。", "target_word": "主に", "complexity_tier": "T3", "furigana": "試験[しけん]では、主[おも]に文法[ぶんぽう]の問題[もんだい]が出[で]ました。", "sentence_source": "generated"}, {"text": "この地域の収入は、主に観光に支えられています。", "target_word": "主に", "complexity_tier": "T3", "furigana": "この地域[ちいき]の収入[しゅうにゅう]は、主[おも]に観光[かんこう]に支[ささ]えられています。", "sentence_source": "generated"}, {"text": "彼の話は主に過去の失敗についてで、将来の話はありませんでした。", "target_word": "主に", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は主[おも]に過去[かこ]の失敗[しっぱい]についてで、将来[しょうらい]の話[はなし]はありませんでした。", "sentence_source": "generated"}, {"text": "会議では、主に費用の問題が話し合われました。", "target_word": "主に", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、主[おも]に費用[ひよう]の問題[もんだい]が話[はな]し合[あ]われました。", "sentence_source": "generated"}, {"text": "私の仕事は、主に新しい商品の企画です。", "target_word": "主に", "complexity_tier": "T3", "furigana": "私[わたし]の仕事[しごと]は、主[おも]に新[あたら]しい商品[しょうひん]の企画[きかく]です。", "sentence_source": "generated"}, {"text": "このサイトは、主に子ども向けの学習内容を扱っています。", "target_word": "主に", "complexity_tier": "T3", "furigana": "このサイトは、主[おも]に子[こ]ども向[む]けの学習[がくしゅう]内容[ないよう]を扱[あつか]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主に", "label": "基本形"}], "register": "やや硬い", "sense_fingerprint": "他と比べてそれが中心であること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: contains vocabulary far above tier T1: おさえる (Zipf 2.47)']::text[], '4eedbe05-f7a1-46a5-8c64-cbc0a50099f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39115, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主に", "is_correct": true, "explanation": "「主に」は大部分を表す副詞。売り上げの大半が海外からという文に合う。"}, {"text": "静かに", "is_correct": false, "explanation": "様子を表す副詞だが、売り上げの出どころを述べる文には意味が通らない。"}, {"text": "一斉に", "is_correct": false, "explanation": "同時に起こる様子を表す。売り上げが海外から来るという文脈には合わない。"}, {"text": "ゆっくりと", "is_correct": false, "explanation": "動作の速さを表す。売り上げの由来を説明する文には合わない。"}], "explanations": {"主に": "「主に」は大部分を表す副詞。売り上げの大半が海外からという文に合う。", "静かに": "様子を表す副詞だが、売り上げの出どころを述べる文には意味が通らない。", "一斉に": "同時に起こる様子を表す。売り上げが海外から来るという文脈には合わない。", "ゆっくりと": "動作の速さを表す。売り上げの由来を説明する文には合わない。"}, "sentence_index": 0, "correct_answer": "主に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の名前は主に田中です。", "explanation": "ここは〈～である〉と言い切る意味。名前は一つに決まるもので、大部分という程度の言い方はできないので「主に」は合わない。"}, {"text": "この本は主に百ページです。", "explanation": "ここは〈およそ〉の意味の「大体」が合う。「主に」は全体の大部分を指すので、数をおよそで言う文には使えない。"}, {"text": "明日は主に来ます。", "explanation": "ここは〈必ず〉の意味の「必ず」が合う。「主に」は大部分を表すだけで、確実さは示さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39115, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主に", "is_correct": true, "explanation": "「主に」は大部分・中心を表す副詞。話の内容の大部分が過去の失敗だという文に合う。"}, {"text": "次々と", "is_correct": false, "explanation": "物事が続いて起こる様子を表す。話の内容を限定する文には合わない。"}, {"text": "きっぱりと", "is_correct": false, "explanation": "断定する態度を表す。話題の範囲を述べる文には合わない。"}, {"text": "大いに", "is_correct": false, "explanation": "程度の大きさを表す。話題の中心を示す文には合わない。"}], "explanations": {"主に": "「主に」は大部分・中心を表す副詞。話の内容の大部分が過去の失敗だという文に合う。", "次々と": "物事が続いて起こる様子を表す。話の内容を限定する文には合わない。", "きっぱりと": "断定する態度を表す。話題の範囲を述べる文には合わない。", "大いに": "程度の大きさを表す。話題の中心を示す文には合わない。"}, "sentence_index": 6, "correct_answer": "主に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この鍵は主に一本しかありません。", "explanation": "ここは〈しか〜ない〉の限定の意味。「主に」は大部分を表すので、ほかを除いて一つだけという文とは噛み合わない。"}, {"text": "昨日、財布を主に落としました。", "explanation": "ここは〈一度〉（回数）の意味。「主に」は大部分の傾向を表すので、単発の出来事を言う文には使えない。"}, {"text": "あの人の年齢は主に三十歳です。", "explanation": "ここは〈ちょうど〉（数がぴったり）の意味。「主に」は大部分を表すので、年齢のように一つの値に決まるものには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39115, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもたちは公園で主な遊びます。", "corrected_sentence": "子どもたちは公園で主に遊びます。", "error_description": "形の誤り。「主に」は副詞で、動詞「遊びます」を修飾する正しい形。「主な」は名詞を修飾する形（形容動詞の連体形）なので、動詞を修飾できない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39115, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この雑誌は若い女性向けの記事を主な載せています。", "corrected_sentence": "この雑誌は若い女性向けの記事を主に載せています。", "error_description": "形の誤り。「主に」は副詞で、動詞「載せています」を修飾する正しい形。「主な」は名詞を修飾する形なので、動詞に直接続けられない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39116, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「近くに拠点がある」と存在の場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "「近くを拠点があります」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「近くで拠点があります」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「近くから拠点があります」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「近くに拠点がある」と存在の場所を表す。", "を": "「近くを拠点があります」は成り立たない。", "で": "「近くで拠点があります」は成り立たない。", "から": "「近くから拠点があります」は成り立たない。"}, "error_tags": {"を": "object", "で": "location", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
