INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39116, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かをするための中心となる場所。", "primary_collocate": null, "pronunciation": "きょてん", "ipa": "kʲoteɴ", "syllable_count": 3, "sentences": [{"text": "ここが拠点だ。", "target_word": "拠点", "complexity_tier": "T1", "furigana": "ここが拠点[きょてん]だ。", "sentence_source": "generated"}, {"text": "駅の近くに拠点があります。", "target_word": "拠点", "complexity_tier": "T2", "furigana": "駅[えき]の近[ちか]くに拠点[きょてん]があります。", "sentence_source": "generated"}, {"text": "彼らの拠点は小さな家でした。", "target_word": "拠点", "complexity_tier": "T2", "furigana": "彼[かれ]らの拠点[きょてん]は小[ちい]さな家[いえ]でした。", "sentence_source": "generated"}, {"text": "私たちは、古い倉庫を拠点にして活動した。", "target_word": "拠点", "complexity_tier": "T3", "furigana": "私[わたし]たちは、古[ふる]い倉庫[そうこ]を拠点[きょてん]にして活動[かつどう]した。", "sentence_source": "generated"}, {"text": "旅行の拠点として、駅前のホテルを選んだ。", "target_word": "拠点", "complexity_tier": "T3", "furigana": "旅行[りょこう]の拠点[きょてん]として、駅前[えきまえ]のホテルを選[えら]んだ。", "sentence_source": "generated"}, {"text": "拠点を移すことになり、みんな忙しい。", "target_word": "拠点", "complexity_tier": "T3", "furigana": "拠点[きょてん]を移[うつ]すことになり、みんな忙[いそが]しい。", "sentence_source": "generated"}, {"text": "拠点が増えれば、もっと多くの人を助けられる。", "target_word": "拠点", "complexity_tier": "T4", "furigana": "拠点[きょてん]が増[ふ]えれば、もっと多[おお]くの人[ひと]を助[たす]けられる。", "sentence_source": "generated"}, {"text": "チームの拠点として使われてきた建物が、取り壊される。", "target_word": "拠点", "complexity_tier": "T4", "furigana": "チームの拠点[きょてん]として使[つか]われてきた建物[たてもの]が、取[と]り壊[こわ]される。", "sentence_source": "generated"}, {"text": "町の拠点を守るために、住民が集まって話し合った。", "target_word": "拠点", "complexity_tier": "T4", "furigana": "町[まち]の拠点[きょてん]を守[まも]るために、住民[じゅうみん]が集[あつ]まって話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "彼は京都を拠点に仕事をしている。", "target_word": "拠点", "complexity_tier": "T3", "furigana": "彼[かれ]は京都[きょうと]を拠点[きょてん]に仕事[しごと]をしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活動拠点", "label": "派生"}, {"form": "海外拠点", "label": "派生"}, {"form": "拠点校", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 何かをする中心となる場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3446334-3278-4fc4-9bdd-c73ba1cb63db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39116, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拠点", "is_correct": true, "explanation": "「きょてん」で、聞こえた語と一致する。"}, {"text": "古典", "is_correct": false, "explanation": "「こてん」で、最初の音が違う。"}, {"text": "去年", "is_correct": false, "explanation": "「きょねん」で、真ん中の音が違う。"}, {"text": "巨人", "is_correct": false, "explanation": "「きょじん」で、真ん中の音が違う。"}], "explanations": {"拠点": "「きょてん」で、聞こえた語と一致する。", "古典": "「こてん」で、最初の音が違う。", "去年": "「きょねん」で、真ん中の音が違う。", "巨人": "「きょじん」で、真ん中の音が違う。"}, "sentence_index": null, "correct_answer": "拠点"}, "level_3": {"options": [{"text": "拠点", "is_correct": true, "explanation": "ここが活動の中心の場所だという意味に合う。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、ここが季節だという意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、ここが天気だという意味が合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "形は合うが、ここが重さだという意味が合わない。"}], "explanations": {"拠点": "ここが活動の中心の場所だという意味に合う。", "季節": "形は合うが、ここが季節だという意味が合わない。", "天気": "形は合うが、ここが天気だという意味が合わない。", "重さ": "形は合うが、ここが重さだという意味が合わない。"}, "sentence_index": 0, "correct_answer": "拠点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、私は拠点に乗って海まで行った。", "explanation": "拠点は場所で、乗り物ではない。"}, {"text": "拠点が高い人は、試験でいい点を取る。", "explanation": "拠点は場所で、高低で人を測る語ではない。"}, {"text": "彼女は拠点を弾くのが好きで、毎日練習している。", "explanation": "拠点は場所で、楽器ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
