INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39117, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "活動や組織の基盤となる場所。", "primary_collocate": null, "pronunciation": "きょてん", "ipa": "kʲoteɴ", "syllable_count": 3, "sentences": [{"text": "さらに、こうした緑の拠点が生み出す波及効果は計り知れない。", "target_word": "拠点", "complexity_tier": "T6", "furigana": "さらに、こうした緑[みどり]の拠点[きょてん]が生[う]み出[だ]す波及[はきゅう]効果[こうか]は計[はか]り知[し]れない。", "sentence_source": "mined"}, {"text": "ここが私たちの拠点です。", "target_word": "拠点", "complexity_tier": "T2", "furigana": "ここが私[わたし]たちの拠点[きょてん]です。", "sentence_source": "generated"}, {"text": "東京に新しい拠点を作りました。", "target_word": "拠点", "complexity_tier": "T2", "furigana": "東京[とうきょう]に新[あたら]しい拠点[きょてん]を作[つく]りました。", "sentence_source": "generated"}, {"text": "登山の拠点になる小屋に泊まった。", "target_word": "拠点", "complexity_tier": "T3", "furigana": "登山[とざん]の拠点[きょてん]になる小屋[こや]に泊[と]まった。", "sentence_source": "generated"}, {"text": "会社は海外にも拠点を持っている。", "target_word": "拠点", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は海外[かいがい]にも拠点[きょてん]を持[も]っている。", "sentence_source": "generated"}, {"text": "この町を拠点に、全国を旅している。", "target_word": "拠点", "complexity_tier": "T3", "furigana": "この町[まち]を拠点[きょてん]に、全国[ぜんこく]を旅[たび]している。", "sentence_source": "generated"}, {"text": "活動の拠点が決まれば、すぐに準備を始められる。", "target_word": "拠点", "complexity_tier": "T4", "furigana": "活動[かつどう]の拠点[きょてん]が決[き]まれば、すぐに準備[じゅんび]を始[はじ]められる。", "sentence_source": "generated"}, {"text": "災害のとき、学校は避難の拠点として使われる。", "target_word": "拠点", "complexity_tier": "T4", "furigana": "災害[さいがい]のとき、学校[がっこう]は避難[ひなん]の拠点[きょてん]として使[つか]われる。", "sentence_source": "generated"}, {"text": "地域の人々が集まる拠点をつくることで、新しいつながりが生まれた。", "target_word": "拠点", "complexity_tier": "T5", "furigana": "地域[ちいき]の人々[ひとびと]が集[あつ]まる拠点[きょてん]をつくることで、新[あたら]しいつながりが生[う]まれた。", "sentence_source": "generated"}, {"text": "拠点の数をもっと増やしたい。", "target_word": "拠点", "complexity_tier": "T3", "furigana": "拠点[きょてん]の数[かず]をもっと増[ふ]やしたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活動拠点", "label": "派生"}, {"form": "海外拠点", "label": "派生"}, {"form": "拠点校", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 活動や組織の基盤となる場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3446334-3278-4fc4-9bdd-c73ba1cb63db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39117, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拠点", "is_correct": true, "explanation": "「きょてん」で、聞こえた語と一致する。"}, {"text": "古典", "is_correct": false, "explanation": "「こてん」で、最初の音が違う。"}, {"text": "去年", "is_correct": false, "explanation": "「きょねん」で、真ん中の音が違う。"}, {"text": "巨人", "is_correct": false, "explanation": "「きょじん」で、真ん中の音が違う。"}], "explanations": {"拠点": "「きょてん」で、聞こえた語と一致する。", "古典": "「こてん」で、最初の音が違う。", "去年": "「きょねん」で、真ん中の音が違う。", "巨人": "「きょじん」で、真ん中の音が違う。"}, "sentence_index": null, "correct_answer": "拠点"}, "level_3": {"options": [{"text": "拠点", "is_correct": true, "explanation": "緑の拠点が波及効果を生むという意味に合う。"}, {"text": "鉛筆", "is_correct": false, "explanation": "形は合うが、鉛筆が波及効果を生み出すという意味は合わない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、意味が合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "形は合うが、意味が合わない。"}], "explanations": {"拠点": "緑の拠点が波及効果を生むという意味に合う。", "鉛筆": "形は合うが、鉛筆が波及効果を生み出すという意味は合わない。", "値段": "形は合うが、意味が合わない。", "重さ": "形は合うが、意味が合わない。"}, "sentence_index": 0, "correct_answer": "拠点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は拠点をかばんに入れて山に持っていった。", "explanation": "拠点は活動の基盤となる場所で、かばんに入れて持ち運べない。"}, {"text": "朝ごはんに拠点を食べてから出かけた。", "explanation": "拠点は場所なので、食べ物としては使えない。"}, {"text": "拠点が怒って、電話を切ってしまった。", "explanation": "拠点は場所で、人のように怒ることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39117, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拠点", "is_correct": true, "explanation": "「きょてん」で、聞こえた語と一致する。"}, {"text": "起点", "is_correct": false, "explanation": "「きてん」で、最初の音が違う。"}, {"text": "補填", "is_correct": false, "explanation": "「ほてん」で、最初の音が違う。"}, {"text": "書店", "is_correct": false, "explanation": "「しょてん」で、最初の音が違う。"}], "explanations": {"拠点": "「きょてん」で、聞こえた語と一致する。", "起点": "「きてん」で、最初の音が違う。", "補填": "「ほてん」で、最初の音が違う。", "書店": "「しょてん」で、最初の音が違う。"}, "sentence_index": null, "correct_answer": "拠点"}, "level_3": {"options": [{"text": "拠点", "is_correct": true, "explanation": "活動の拠点が決まれば準備できるという意味に合う。"}, {"text": "重さ", "is_correct": false, "explanation": "形は合うが、意味が合わない。"}, {"text": "色", "is_correct": false, "explanation": "形は合うが、意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、意味が合わない。"}], "explanations": {"拠点": "活動の拠点が決まれば準備できるという意味に合う。", "重さ": "形は合うが、意味が合わない。", "色": "形は合うが、意味が合わない。", "天気": "形は合うが、意味が合わない。"}, "sentence_index": 6, "correct_answer": "拠点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は拠点がとても上手で、みんなに褒められた。", "explanation": "拠点は場所で、上手下手を言う技能ではない。"}, {"text": "毎朝、拠点を飲んでから会社に行く。", "explanation": "拠点は場所なので、飲み物としては使えない。"}, {"text": "昨日は拠点だったので、一日中雨が降った。", "explanation": "拠点は天気を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39117, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "福岡に新しい拠点が作りました。", "corrected_sentence": "福岡に新しい拠点を作りました。", "error_description": "「拠点」は「作る」の対象なので、助詞は「が」ではなく「を」にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39117, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社員は海外の拠点を会議に出席した。", "corrected_sentence": "社員は海外の拠点で会議に出席した。", "error_description": "拠点は会議の場所なので、助詞は「を」ではなく「で」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39118, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」で、ポリエステルについて石油から作る繊維だと説明する文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示すので、「ポリエステルに石油から作る繊維」と続かず、主題にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では「ポリエステルの石油から」と続き、主題の説明として不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は主題にはならず、「ポリエステルから石油から」と不自然になる。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」で、ポリエステルについて石油から作る繊維だと説明する文に合う。", "に": "「に」は方向や相手を示すので、「ポリエステルに石油から作る繊維」と続かず、主題にならない。", "の": "連体の「の」では「ポリエステルの石油から」と続き、主題の説明として不自然。", "から": "起点を示す「から」は主題にはならず、「ポリエステルから石油から」と不自然になる。"}, "error_tags": {"に": "方向・相手", "の": "連体修飾", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39118, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「多く使われている」の主語を示す「が」で、ポリエステルが使われるという文に合う。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では主語にならず、「ポリエステルと多く使われている」と不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は主語の位置には入らず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や材料を示す「で」は主語にならず、「ポリエステルで多く使われている」が不自然になる。"}], "correct_answer": "が", "explanations": {"が": "「多く使われている」の主語を示す「が」で、ポリエステルが使われるという文に合う。", "と": "並列の「と」では主語にならず、「ポリエステルと多く使われている」と不自然になる。", "へ": "方向を示す「へ」は主語の位置には入らず、文が成り立たない。", "で": "手段や材料を示す「で」は主語にならず、「ポリエステルで多く使われている」が不自然になる。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "で": "手段・材料"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39118, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ポリエステルは、服などを作るのに使う、石油からできた繊維です。", "primary_collocate": null, "pronunciation": "ぽりえすてる", "ipa": "poɾieseɯteɾɯ", "syllable_count": 6, "sentences": [{"text": "このシャツはポリエステルでできているので、洗ってもすぐ乾く。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "このシャツはポリエステルでできているので、洗[あら]ってもすぐ乾[かわ]く。", "sentence_source": "generated"}, {"text": "ポリエステルは石油から作る繊維なので、綿とはちがう。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "ポリエステルは石油[せきゆ]から作[つく]る繊維[せんい]なので、綿[めん]とはちがう。", "sentence_source": "generated"}, {"text": "夏の運動ぶくには、ポリエステルのシャツがよく使われる。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "夏[なつ]の運動[うんどう]ぶくには、ポリエステルのシャツがよく使[つか]われる。", "sentence_source": "generated"}, {"text": "ポリエステルのスカートはしわになりにくいから、旅行に持っていく。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "ポリエステルのスカートはしわになりにくいから、旅行[りょこう]に持[も]っていく。", "sentence_source": "generated"}, {"text": "母は、アイロンがいらないポリエステルのブラウスを買った。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "母[はは]は、アイロンがいらないポリエステルのブラウスを買[か]った。", "sentence_source": "generated"}, {"text": "ポリエステルは火に近づけると溶けるので、注意が必要だ。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "ポリエステルは火[ひ]に近[ちか]づけると溶[と]けるので、注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "このセーターは、ポリエステルが半分、ウールが半分だ。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "このセーターは、ポリエステルが半分[はんぶん]、ウールが半分[はんぶん]だ。", "sentence_source": "generated"}, {"text": "安い服には、ポリエステルが多く使われている。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "安[やす]い服[ふく]には、ポリエステルが多[おお]く使[つか]われている。", "sentence_source": "generated"}, {"text": "ポリエステルの服は汗をすぐ吸わないので、夏に着るとむれる。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "ポリエステルの服[ふく]は汗[あせ]をすぐ吸[す]わないので、夏[なつ]に着[き]るとむれる。", "sentence_source": "generated"}, {"text": "ポリエステルのかばんは軽くて、雨にも強い。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "ポリエステルのかばんは軽[かる]くて、雨[あめ]にも強[つよ]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ポリエステル", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "服に使う、石油から作った化学繊維", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e41a0f0-a380-46ef-b279-79ccdfb5e191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39118, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ポリエステル", "is_correct": true, "explanation": "〈服などに使う化学繊維〉の意味で、シャツの材料として文に合う。"}, {"text": "鉄", "is_correct": false, "explanation": "金属で、洗ってもすぐ乾く衣服の材料にはならないので、文が成り立たない。"}, {"text": "ガラス", "is_correct": false, "explanation": "割れやすい素材で、シャツの材料として不自然なので合わない。"}, {"text": "段ボール", "is_correct": false, "explanation": "紙製の箱の材料で、シャツの素材としては文に合わない。"}], "explanations": {"ポリエステル": "〈服などに使う化学繊維〉の意味で、シャツの材料として文に合う。", "鉄": "金属で、洗ってもすぐ乾く衣服の材料にはならないので、文が成り立たない。", "ガラス": "割れやすい素材で、シャツの材料として不自然なので合わない。", "段ボール": "紙製の箱の材料で、シャツの素材としては文に合わない。"}, "sentence_index": 0, "correct_answer": "ポリエステル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ポリエステルは白い粉で、パンやケーキを作るときに使われる。", "explanation": "ここは〈小麦粉〉の意味。白い粉でパンやケーキに使うもので、繊維のポリエステルとは違うので合わない。"}, {"text": "ポリエステルは、木材のパルプから作られ、とろりとした光沢がある。", "explanation": "ここは〈レーヨン〉の意味。木材パルプから作る繊維の説明で、石油から作るポリエステルには合わない。"}, {"text": "ポリエステルは、薄くて水を通さない素材で、ごみ袋やラップに使われる。", "explanation": "ここは〈ポリエチレン〉の意味。ごみ袋やラップに使うプラスチックで、繊維のポリエステルとは別物なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39118, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ポリエステル", "is_correct": true, "explanation": "材料として半分を占める素材で、セーターの説明として文に合う。"}, {"text": "ボタン", "is_correct": false, "explanation": "服に付ける部品で、材料の割合を示す文には入らないので合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "食品で、服の素材にはならないので、セーターの説明として文が成り立たない。"}, {"text": "木", "is_correct": false, "explanation": "木材で、セーターの材料として文が成り立たない。"}], "explanations": {"ポリエステル": "材料として半分を占める素材で、セーターの説明として文に合う。", "ボタン": "服に付ける部品で、材料の割合を示す文には入らないので合わない。", "砂糖": "食品で、服の素材にはならないので、セーターの説明として文が成り立たない。", "木": "木材で、セーターの材料として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "ポリエステル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ポリエステルは、透明で、窓や瓶に使われる。", "explanation": "ここは〈ガラス〉の意味。透明な窓や瓶の材料の説明で、繊維のポリエステルには合わない。"}, {"text": "ポリエステルは弾力があって、タイヤや輪ゴムに使われる。", "explanation": "ここは〈ゴム〉の意味。弾力のある素材で、タイヤや輪ゴムに使われるものを指す。繊維のポリエステルには当てはまらない。"}, {"text": "ポリエステルは、かたくて重く、建物の土台に使われる。", "explanation": "ここは〈石〉の意味。かたくて重い天然の材料を指し、石油から作る繊維のポリエステルとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39118, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この服はポリエステルに作られている。", "corrected_sentence": "この服はポリエステルで作られている。", "error_description": "「作られる」で材料を示すときは「で」を使う。「ポリエステルに作られている」は助詞「に」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39118, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ポリエステルで作るった服は、汗を吸いにくい。", "corrected_sentence": "ポリエステルで作った服は、汗を吸いにくい。", "error_description": "動詞「作る」の過去形は「作った」。「作るった」は活用の誤りで、正しい形は「作った」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39119, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」で、ポリエステルは丈夫だという性質の説明に入る。"}, {"text": "を", "is_correct": false, "explanation": "「丈夫で」は性質を述べる形なので、目的語の「を」は入らず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ポリエステルに丈夫で」と続き、方向や相手を示す「に」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は性質を述べる主題にならず、文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」で、ポリエステルは丈夫だという性質の説明に入る。", "を": "「丈夫で」は性質を述べる形なので、目的語の「を」は入らず文が成り立たない。", "に": "「ポリエステルに丈夫で」と続き、方向や相手を示す「に」は不自然。", "へ": "方向を示す「へ」は性質を述べる主題にならず、文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39119, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」で、ポリエステルがしわになりにくいと説明する文の主題になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すが、「しわになりにくいため」と状態を述べる文には続かず、成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」は二つの主題を並べる形になり、理由の文として不自然になる。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は、しわになりにくい状態の主題にはならず、文が不自然になる。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」で、ポリエステルがしわになりにくいと説明する文の主題になる。", "を": "「を」は動作の対象を示すが、「しわになりにくいため」と状態を述べる文には続かず、成り立たない。", "と": "並列の「と」は二つの主題を並べる形になり、理由の文として不自然になる。", "から": "起点を示す「から」は、しわになりにくい状態の主題にはならず、文が不自然になる。"}, "error_tags": {"を": "目的語", "と": "並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
